 \subsection{DDPM for solving inverse problems}
 \label{sec:conditional_DDPM}
Let us recall some key aspects of diffusion models in the context of image restoration. We focus on solving linear inverse problems
 \begin{equation}
 	\label{eq:inverse_problem}
    \begin{aligned}
 	\V & = \A\x_0 + \sigma \n, \\
    & \quad  \x_0 \sim p_0,\sigma > 0, \n \sim \N.
    \end{aligned}
 \end{equation}
In our context, we aim at sampling $p_0(\cdot \mid \V)$  to solve it. One can use a conditional DDPM associated with the following forward process
 \begin{equation}
 \label{eq:conditional_forward_DDPM}
 \begin{aligned}
 	\tx_{t} & = \sqrt{1-\beta_t}\tx_{t-1}+\sqrt{\beta_t}\tz_t, \\
    & \quad 1 \leq t \leq T, \quad \tz_t \sim \N, \quad  \tx_0 \sim p_0(\cdot \mid \V),
\end{aligned}
 \end{equation}
 and we denote by $\tp_t$ the distribution of $\tx_t$ for $0 \leq t \leq T$. As before, the associated backward process is
 \begin{equation}
 \label{eq:conditional_backward_DDPM}
 \begin{aligned}
  \ty_T & \sim \N \\
     \ty_{t-1} & = \frac{1}{\sqrt{\alpha_t}}\left(\ty_t + \beta_t \nabla \log \tp_t(\y_t) \right) + \beta_t \z_t, \\
     & \quad \z_t\sim \N,  1 \leq t \leq T,  \z_t \sim \N
 \end{aligned}
 \end{equation}
%where $\ts_{\theta^\star}(t,\x)$ is a learning of $\nabla \log \tp_t(\x)$. 
Let us make the important following observation: Given $\x_0$, $\x_t$ is independent of $\V = \A\x_0 + \sigma \n$, so $\tp_{t \mid 0}(\tx_t\mid \tx_0) = p_{t \mid 0}(\tx_t\mid \tx_0) = p_{t \mid 0}(\tx_t\mid \tx_0,\V)$ and
 	 	\begin{align}
 		\tp_t(\tx_t)
 		& = \int \tp_{t\mid 0}(\tx_t \mid \tx_0)\tp_0(\tx_0) d\tx_0 \\
 		%& = \int \tp_{t\mid 0}(\tx_t \mid \tx_0)\frac{p_{\V\mid \x_0}(\V \mid \tx_0)\pdata(\tx_0)}{p_{\V}(\V)} d\tx_0 \text{ by Bayes' rule } \\
 		%&  = \int p_{t\mid 0}(\tx_t \mid \x_0)\frac{p_{\V\mid \x_0}(\V \mid \x_0)\pdata(\x_0)}{p_{\V}(\V)} d\x_0 \\
 		&  = \int p_{t\mid 0}(\tx_t \mid \x_0,\V)p_0(\x_0\mid \V) d\x_0 \\
 		& = p_t(\tx_t \mid \V).
 		%&  = \int p_{t\mid 0}(\tx_t \mid \x_0,\V)\pdata(\x_0\mid \V) d\x_0 \\
 		%& = p_t(\tx_t \mid \V)
 	\end{align}
 In other terms,
 \begin{equation}
 	 \tp_t = p_t(\cdot\mid \V),\quad 0 \leq t \leq T,
 \end{equation}
 that is to say that it is equivalent to condition an unconditional forward process~\eqref{eq:forward_DDPM} on $\V$ or consider a conditional forward process~\eqref{eq:conditional_forward_DDPM} to compute $\nabla_{\x} \log p_t(\x_t\mid \V)$.
Futhermore, by Bayes' rule,
 \begin{equation}
 \label{eq:Bayes_rule}
 	\nabla_{\x} \log \tp_t(\x_t) = \nabla_{\x} \log p_t(\x_t) + \nabla_{\x} \log p_t(\V \mid \x_t), 
 \end{equation}
where $p_t$ describes the unconditonal forward process (\Cref{algo:forward_DDPM}). \emile{In the following, we refer to $ p_t(\V \mid \x_t)$ as the \textbf{noisy likelihood} and to $ p_t(\x_t \mid \V)$ as the \textbf{noisy posterior}.} 


Assuming that the score function $\nabla_{\x} \log p_t(\x)$ is well known and has already been applied in image generation, the goal is now to estimate the likelihood score $\nabla_{\x} \log p_t(\V \mid \x)$.
In practice, the noisy likelihood $p_t(\V \mid \x_t)$ is generally intractable. To address this, several works \cite{Chung_DPS_ICLR_2023,Song_pseudo_inverse_guided_diffusion_2023_ICLR} assume that $p_t(\V \mid \x_t)$ follows a Gaussian distribution, which can be fully characterized by its mean and covariance matrix.
Importantly, the mean of $p_t(\V \mid \x_t)$ is given by the following expression:
\begin{equation}
	\E(\V \mid \x_t) = \E(\A\x_0 + \sigma^2 \n \mid \x_t) = \A\E(\x_0 \mid \x_t) 
\end{equation}
where $\E(\x_0 \mid \x_t) $ is the ideal MMSE denoiser. %Supposing that the unconditional score $\nabla_{\x} \log p_t(\x_t)$ is known, one have a closed expression of the conditional expectation $\E(\x_0 \mid \x_t)$  
Moreover, by Tweedie's formula,
 \begin{equation}
 \begin{aligned}
 \widehat{\x}_0(\x_t) & := \E\left[\x_0 \mid \x_t\right]  \\
 & = \frac{1}{\sqrt{\alphabar_t}}\left(\x_t + (1-\alphabar_t) \nabla_{\x}\log p_t(\x_t)\right)
 \end{aligned}
 	\label{eq:Tweedie_formula}
 \end{equation}
and the expectation $\E\left[\V \mid \x_t\right]$ is given by
 \begin{equation}
 \begin{aligned}
 \E\left[\V \mid \x_t\right] & = \A\widehat{\x}_0(\x_t) \\
 & = \frac{1}{\sqrt{\alphabar_t}}\A\left(\x_t + (1-\alphabar_t) \nabla_{\x}\log p_t(\x_t)\right).
% 	\label{eq:Tweedie_formula}
\end{aligned}
 \end{equation}
Then, it is necessary to choose a covariance matrix $\bC_{\V\mid t}$ to approximate $\Cov(\V \mid \x_t)$. 
This results in
 \begin{equation}
 	\nabla_{\x} \log p_t(\V \mid \x_t)
 	= -\frac{1}{2}\nabla_{\x} \left\|\V-\A\widehat{\x}_0(\x_t) \right\|_{\bC_{\V\mid t}^{-1}}^2
 \end{equation}
 where we introduce the notation $\|x\|_{\A} = \x^T\A\x$ for a given positive symmetric matrix $\A$. 
 Given this model, an iteration of the conditional DDPM model becomes
 {\fontsize{6pt}{7.2pt}\selectfont
 \begin{equation}
 \begin{aligned}
 	 & \ty_{t-1} \\
    & = \frac{1}{\sqrt{\alpha_t}}(\ty_t + \beta_t \nabla \log p_t(\ty_t) - \tfrac{\beta_t}{2}\nabla_{\ty_t} \|\V-\A\widehat{\ty}_0(\ty_t) \|_{\bC_{\V\mid t}^{-1}}^2 ) + \sigma_t \z_t,\\
    & \quad \z_t\sim \N,  1 \leq t \leq T,
 \end{aligned}
  \end{equation} }
  as described in \Cref{algo:backward_conditional_DDPM}.

    \begin{algorithm}
    \footnotesize
      \caption{Conditional backward DDPM process}\label{algo:backward_conditional_DDPM} 
      \begin{algorithmic}[1]
      \Require $\V, (\bC_{\V \mid t})_{0 \leq t \leq T}$
\State $\y_T \sim \N$
        \For{$t=T$ \textbf{to} 1}
        \State $\widehat{\y}_0(\x_t) = \frac{1}{\sqrt{\alphabar_t}}\left(\y_t + (1-\alphabar_t) \nabla \log p_t(y_t)\right)$
        \State {\tiny$\nabla\log p_t(\y_t\mid \V) = \nabla\log p_t(\y_t) -\frac{1}{2}\nabla_{\y_t} \left\|\V-\A\widehat{\y}_0(\y_t) \right\|_{\bC_{\V\mid t}^{-1}}^2$}
        \State $\z_t\sim \N$
    \State $\y_{t-1} = \frac{1}{\sqrt{\alpha_t}}\left(\y_t + \beta_t\nabla\log p_t(\y_t\mid \V)\right) + \beta_t \z_t$
    \EndFor      
      \end{algorithmic}
    \end{algorithm}
\noindent In the following, we concentrate on two algorithms proposed in the literature. Their respective parameterizations are detailed below and summarized in Table~\ref{tab:comparison_expression_grad_cond}. Several other approaches can be found in the comprehensive survey by \cite{Daras_diffusion_survey_inverse_problems_2024}.


\paragraph{The Diffusion Posterior Sampling (DPS).} DPS is described  in \cite{Chung_DPS_ICLR_2023} to solve linear inverse problems such as inpainting, deblurring or super-resolution or nonlinear inverse problems such as phase retrieval or non-uniform deblurring. Chung \emph{et al.} propose the following approximation
\begin{equation}
	\log p_t(\V\mid \x_t) \approx \log p(\V\mid \x_0 = \widehat{x}_0(\x_t)) 
\end{equation}
As written in Equation~\eqref{eq:inverse_problem}, 
\begin{equation}
	p(\V\mid \x_0) = \mathcal{N}\left(\A\x_0, \sigma^2\I\right).
\end{equation}
 Consequently, it is equivalent to fixing the covariance matrix of the noisy likelihood $\bC^\text{\tiny DPS}_{\V \mid t}$  to be equal to $\sigma^2\I$ and
  \begin{equation}
  \begin{aligned}
 	 	\nabla_{\x_t}\log p(\V\mid & \x_0 = \widehat{x}_0(\x_t)) \\
        & = -\frac{1}{2\sigma^2}\nabla_{\x_t}\left\|\V-\A\widehat{x}_0(\x_t)\right\|^2.
     \end{aligned}
 \end{equation}
 In practice, this method presents some instabilities. The choice of Chung \emph{et al.} is equivalent to fixing
 \begin{equation}
 	p(\x_0 \mid \x_t) \approx \delta_{\widehat{\x}_0(\x_t)}
 \end{equation}
 where $\delta$ is a Dirac distribution and this could explain these instabilities: the variance of $\x_0$ is neglected and consequently, applying the inverse of the underestimated covariance matrix $\bC_{\V \mid t}$  may cause the computations to diverge. To mitigate these instabilities, they introduce an hyperparameter $\alphaDPS > 0$ such that
  \begin{equation}
  \begin{aligned}
 	 	\nabla_{\x_t}\log p(\V\mid & \x_0 = \widehat{x}_0(\x_t)) \\
        & = -\frac{\alphaDPS}{2\sigma^2}\nabla_{\x_t}\left\|\V-\A\widehat{x}_0(\x_t)\right\|^2.
     \end{aligned}
 \end{equation}
$\alphaDPS$ is both data and problem dependent (see \cite{Chung_DPS_ICLR_2023}, \textit{Appendix D.1}). Finally, we consider $\bC^\text{\tiny DPS}_{\V \mid t} = \frac{\sigma^2}{\alphaDPS}\I$.

 \begin{rem}[Gap between theory and practical implementation of the DPS algorithm]
 \label{rem:DPS_implementation}
 	In practice, \emph{Chung et al.} make a second approximation
 \begin{equation}
 \begin{aligned}
 	 	\frac{\beta_t}{2\sqrt{\alpha_t}} &\nabla_{\x_t}\log p(\V\mid  \x_0 = \widehat{x}_0(\x_t))
 	 	\\
        & = -\frac{\alpha_{\text{\tiny DPS}}}{\|\A\widehat{\x}_0(\x_t)-\V\|} \nabla_{\x_t}\left\|\V-\A\widehat{x}_0(\x_t)\right\|^2 \\
 	 	& = -\alpha_{\text{\tiny DPS}} \nabla_{\x_t}\left\|\V-\A\widehat{x}_0(\x_t)\right\|
  \end{aligned}
 \end{equation}
 %where $\alpha_{\text{\tiny DPS}} > 0$ is an hyperparameter which is both data and problem dependent (see \cite{Chung_DPS_ICLR_2023}, \textit{Appendix D.1}). 
 This new formulation changes considerably the initial model and it amounts to put
 \begin{equation}
 \begin{aligned}
 	\log p(\V\mid & \x_0 = \widehat{x}_0(\x_t)) \\
 	& \propto -\frac{2\sqrt{\alpha_t} \alpha_{\text{\tiny DPS}}}{\beta_t}\nabla_{\x_t}\left\|\V-\A\widehat{x}_0(\x_t)\right\|.  
\end{aligned}
 \end{equation}
 It can be interpreted as modeling the distribution $p(\V\mid \x_0 = \widehat{x}_0(\x_t))$ not as a Gaussian distribution but a modified Multivariate Generalized Gaussian Distribution (MGGD) \cite{Manzano_matrix_variate_generalization_power_exponential_family_2002,Pascal_Parameter_estimation_generalized_Gaussian_IEEE_2013}.
 Another practical hint which is used in the official implementation of this method\footnote{\url{https://github.com/DPS2022/diffusion-posterior-sampling}} and that guarantees its stability is the clamping of the estimated denoised image $\widehat{\x}_0(\x_t)$ between $-1$ and $1$. To stay in the Gaussian realm, we do not consider these heuristic corrections in what follows.
 \end{rem}

\paragraph{Pseudoinverse-Guided Diffusion Models ($\Pi$GDM)}

The $\Pi$GDM algorithm \cite{Song_pseudo_inverse_guided_diffusion_2023_ICLR} is described to solve inpainting, JPEG compression or deblurring problems. Song \emph{et al.} make the following approximation
\begin{equation}
\label{eq:first_approx_Song}
	p(\x_0\mid \x_t) \approx  \mathcal{N}\left(\widehat{x}_0(\x_t),r_t^2\I\right).
\end{equation}
 Consequently, 
 \begin{equation}
p(\V\mid \x_t) \approx \mathcal{N}\left(\A\widehat{x}_0(\x_t),r_t^2\A\A^T+\sigma^2\I\right).
 \end{equation}
This is equivalent to choosing $\bC^\text{\tiny $\Pi$GDM}_{\V \mid t} = r_t^2\A\A^T + \sigma^2\I$, which now depends on the degradation operator $\A$. It is indeed natural for the degradation operator to appear, as well as a dependence on $t$. The hyperparameter $r_t$ is estimated by considering the case where $p_0$ is a standard normal distribution, which yields $r_t^2 = 1 - \alphabar_t$ in the case of DDPM. %This is a particular case of the general study we propose below.
 \begin{rem}[$\Pi$GDM algorithm for DDPM]
 \label{rem:PiGDM_implementation}
 	$\Pi$GDM was first described for the DDIM algorithm \cite{Song_pseudo_inverse_guided_diffusion_2023_ICLR}. However, the approximation of $p_t(\V\mid \x_t)$ can be extended to the DDPM one. 

 \noindent Note that $r_t^2\A\A^T + \sigma^2\I$ is invertible since $\A\A^T$ is positive semi-definite. In the noiseless setting $\sigma = 0$ (not considered here), a pseudo-inverse is applied, which is the reason this method is referred to as \emph{Pseudoinverse}-Guided Diffusion Models.
  \end{rem}


 \section{Study under Gaussian assumption}
\label{sec:study_under_Gaussian_assumption}

\emile{The different algorithms using diffusion models are evaluated by computing empirical metrics on large datasets. The intractability of the score function and their conditional forms is a main obstacle to propose a theoretical study of their accuracy. }
 \emile{In order to compare theoretically the algorithms, we will restrict to} the case where $p_0$ is a Gaussian distribution by considering the following assumption.
\begin{assumption}[Gaussian assumption]
\label{assumption:Gaussian}
	$p_0$ \textbf{is a Gaussian distribution $\mathcal{N}(\bmu,\bSigma)$} in $\R^d$.
\end{assumption}
 \noindent In this case, as developed below, we can derive all the closed-forms formulas of the distributions and precisely compare the different algorithms. \emile{Note that $\bSigma$ is not assumed to be full rank, which includes the study of distributions defined on a manifold.}


 \subsection{Exact Gaussian formulas}
\label{subsec:exact_Gaussian_formulas}
First, using a diffusion model to solve an inverse problem in the Gaussian case is generally unnecessary. In fact, we can explicitly derive the following conditional distribution
\begin{equation}
%\small
\begin{aligned}
\label{eq:conditional_Gaussian_init}
%	& p(\x_0 \mid \V) \\
%    & = \mathcal{N}\left(\bmu+\bSigma \A^T \M^{-1}\left(\V-\A\bmu\right), \bSigma - \bSigma \A^T \M^{-1} \A\bSigma\right) \\& \text{ with } \M = \A\bSigma\A^T + \sigma^2 \I
%\end{aligned}
%
%\begin{aligned}
%\label{eq:exact_cond_back_density}
p(\x_0 \mid \V)
     & = \mathcal{N}\left({\bmu}_{0\mid \V}, {\bC}_{0\mid \V}\right) \\
     \text{ with } &{\bmu}_{0\mid \V} = \bmu+\bSigma \A^T \M^{-1}\left(\V-\A\bmu\right), \\
     &{\bC}_{0\mid \V} = \bSigma - \bSigma \A^T \M^{-1} \A\bSigma, \\
       & \M = \A\bSigma\A^T + \sigma^2 \I.
\end{aligned}
\end{equation}
\emile{and the proof is provided in \Cref{appendix:x_t_mid_v}.} As done in \cite{pierret_stochastic_superresolution_gaussian_microtextures_2024} for SR of Gaussian microtextures, we can then apply a kriging reasoning to sample $\x_0$ conditionally to $\V$. 
In this context, the unconditional score $\nabla_{\x} \log p_t(\x_t)$ is explicit and is given by
\begin{equation}
\label{eq:Gaussian_score_DDPM}
	\nabla_{\x} \log p_t(\x)  = -\bSigma_t^{-1}\left(\x-\sqrt{\alphabar_t}\bmu\right),
\end{equation}
with
\begin{equation}
\bSigma_t = \alphabar_t \bSigma + (1-\alphabar_t)\I.
\end{equation}
$\bSigma_t$ is invertible for $t> 0$, as described for the continuous case in \cite{pierret_diffusion_models_gaussian_distributions_2024}. Given these closed expressions, we express exactly the conditional forward DDPM (\Cref{eq:conditional_forward_DDPM}) associated with $\tx_0 \sim p(\cdot \mid \V)$  as
\begin{equation}
%\scriptsize
\begin{aligned}
\label{eq:exact_cond_back_density}
& p_t(\tx_t \mid \V)
     = \mathcal{N}\left(\tilde{\bmu}_{t\mid \V}, \tilde{\bC}_{t\mid \V}\right) \\
    & \text{ with } \tilde{\bmu}_{t\mid \V} = \sqrt{\alphabar_t}\bmu+\sqrt{\alphabar_t}\bSigma \A^T \M^\dagger\left(\V-\A\bmu\right), \\
    & \text{ and } \tilde{\bC}_{t\mid \V} = \bSigma_t - \alphabar_t\bSigma \A^T \M^\dagger \A\bSigma.
\end{aligned}
\end{equation}
In the Gaussian setting, the different algorithms have to be compared with this forward path which they are supposed to reconstruct along the time. Another crucial derivation is the computation of the noisy likelihood $p_t(\V\mid \x_t)$ that was modeled by a Gaussian distribution by DPS and $\Pi$GDM. In this particular case, $p(\V\mid \x_t)$ is Gaussian without adding any assumption and can be expressed as
{
\begin{align}
\scriptsize
	p_t(\V \mid \x_t) 
		& \scriptsize = \mathcal{N}
		\left(
		\A \widehat{\x}_0(\x_t), (1-\alphabar_t)\A \bSigma \bSigma_t^{-1} \A^T
		+\sigma^2\I\right),  \\
	& \scriptsize \text{ with } \widehat{\x}_0(\x_t)
	 = \bmu + \sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}(\x_t - \sqrt{\alphabar}_t \bmu).
	\label{eq:Gaussian_x_0_chap}
\end{align}
}
\emile{The proofs are provided in \Cref{appendix:x_zero_chap,appendix:v_mid_x_t}}. Note that $\widehat{\x}_0(\x_t)$ follows the Tweedie's formula~\eqref{eq:Tweedie_formula}. We consider the expression in the Gaussian case as corresponding to a new algorithm: Conditional Gaussian Diffusion Model (CGDM). We fix 
 \begin{equation}
     \bC_{t\mid \V}^{\text{CGDM}} = (1-\alphabar_t)\A \bSigma \bSigma_t^{-1} \A^T
		+\sigma^2\I
\end{equation}
which is the exact expression under the Gaussian assumption. Accordingly, the various algorithms are summarized in \Cref{tab:comparison_expression_grad_cond}.

Let us observe the behavior of $\bC_{\V \mid t}$ for the different algorithms. 
%As a reminder, in this Gaussian case, CGDM is the exact theoretical distribution. 
Considering $\alphaDPS = 1$, let us observe that for $t$ close to $T$, $\bSigma_t$ is close to $\I$ and
\begin{equation}
\begin{aligned}
%\tiny
    \bC^\text{\tiny DPS}_{\V \mid t} 
	 & = \sigma^2 \I \\
  \bC^\text{\tiny $\Pi$GDM}_{\V \mid t} 
	 & \approx  (1-\alphabar_t)\A\A^T +\sigma^2 \I, \\
     \bC^\text{\tiny CGDM}_{\V \mid t} 
	 & \approx  (1-\alphabar_t)\A\bSigma\A^T + \sigma^2 \I.
\end{aligned}
\end{equation}
\noindent Consequently, $\bC^\text{\tiny $\Pi$GDM}_{\V \mid t}$ is closer to the exact theoretical expression $\bC^\text{\tiny CGDM}_{\V \mid t}$, except that the prior covariance information is missing.The DPS algorithm significantly underestimates the covariance because $1 - \alphabar_T$ is close to 1.
\noindent  For $t$ close to $0$, $\bSigma_t$ is close to $\bSigma$ and 
\begin{equation}
\begin{aligned}
    \bC^\text{\tiny DPS}_{\V \mid t} 
	 & = \sigma^2 \I, \\ 
	\bC^\text{\tiny $\Pi$GDM}_{\V \mid t} 
	 & \approx  (1-\alphabar_t)\A\A^T + \sigma^2 \I,  \\
	\bC^\text{\tiny CGDM}_{\V \mid t} 
	 & \approx  (1-\alphabar_t)\A\A^T +\sigma^2 \I.
\end{aligned}
\end{equation}
Consequently, $\bC^\text{\tiny $\Pi$GDM}_{\V \mid t}$ is really close to the exact theoretical expression $\bC^\text{\tiny CGDM}_{\V \mid t}$ for low values of $t$. Let us note that the two expressions $\bC^\text{\tiny DPS}_{\V \mid t}, \bC^\text{\tiny $\Pi$GDM}_{\V \mid t}$ are exact for $t = 0$. This is a key observation that will be important in practice.

