\subsection{Comparison of the algorithms under Gaussian assumption}
\label{sec:comp_algo_under_Gaussian_assumption}

Here, we elucidate the structure of the covariance of the noisy posterior induced by each algorithm, given their respective choice of noisy likelihood. We then verify whether these correspond to a forward process.


\paragraph{Derivation of \emile{the noisy posterior} $p_t(\x_t\mid \V)$ for each algorithm} For each algorithm, we suppose that $\nabla_{\x} \log p_t(\x)$ is perfectly known and we use a model for $\log p_t(\V \mid \x_t)$.
By using the Bayes' formula (\Cref{eq:Bayes_rule}) in a reverse sense than before, we can express a distribution $p^\text{algo}_t(\x_t\mid \V)$ verifying $\log p^\text{algo}_t(\x_t\mid \V) = \log p_t(\x) +  \log p^\text{algo}_t( \V\mid \x_t)$. 
\emile{This noisy posterior is not related to the distributions sampled by the algorithms' backward processes unless it corresponds to a forward process (as discussed below), but it can still provide an interpretation of their model.}
By denoting $p^\text{algo}_t(\x_t\mid \V) = \mathcal{N}(\bmu^\text{algo}_{t\mid \V},\bC^\text{algo}_{t\mid \V})$, these computations lead to
{\fontsize{6pt}{7.2pt}\selectfont
%\parbox{.5\linewidth}{%
\begin{align}
\tiny
	 & \bC^{\text{DPS}}_{t \mid \V} \notag \\
     & = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma \\
	 & \bC^{\text{$\Pi$GDM}}_{t \mid \V}  \notag \\
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+(1-\alphabar_t)\A\A^T+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma \\
	& \bC^{\text{CGDM}}_{t \mid \V} \notag \\
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+\A\bSigma\A^T\right)^{-1}\A\bSigma.
\end{align}
}%
%}
 All the details, with expressions of $\bmu^\text{algo}_{t\mid \V}$ are given in Appendix~\ref{appendix:proof_expression_C_v_t}. \emile{We focus our discussions on the covariance matrices $\bC^\text{algo}_{t\mid \V}$ but similar observations can be established for the mean values $\bmu^\text{algo}_{t\mid \V}$}. First, let us note that CGDM corresponds exactly to the forward distributions $\left(\tp_t\right)_{0 \leq t \leq T}$ (see \Cref{eq:exact_cond_back_density}). Then, for $t = 0$, by supposing that $\bSigma$ is invertible, $\alphabar_0 = 1$ and
 \begin{align}
	C^{\text{DPS}}_{0 \mid \V}
	& = \bSigma-\bSigma\A^T\left(\sigma^2\I+\A\bSigma\A^T\right)^{-1}\A\bSigma \\
	C^{\text{$\Pi$GDM}}_{0 \mid \V}
	& = \bSigma-\bSigma\A^T\left(\sigma^2\I+\A\bSigma\A^T\right)^{-1}\A\bSigma.
\end{align}
These expressions are the exact covariance matrix of $p(\x_0 \mid \V)$. 

\paragraph{Algorithms studied in forward time evolution} Another interesting question is: Do $p^\text{algo}_t(\x_t\mid \V)$ corresponds to a forward DDPM process' distributions ? To correspond to a forward process, $\bC_{t\mid \V}$ is expected to be in the form
\begin{equation}
	\bC_{t\mid \V} = \alphabar_t \bC_{0\mid \V} + (1-\alphabar_t)\I.
\end{equation}
As noted before, $p^\text{DPS}_t(\x_t\mid \V)$ has a covariance matrix
%\begin{equation}
%	\bC_{t\mid \V}^\text{CGDM} = \alphabar_t(\bSigma - \bSigma\A^T\left(\sigma^2\I+\A\bSigma\A^T\right)^{-1}\A\bSigma) + (1-\alphabar_t)\I
%\end{equation}
%and for the DPS algorithm,
{\fontsize{6pt}{7.2pt}\selectfont
\begin{equation}
\begin{aligned}
	& \bC_{t\mid \V}^\text{DPS} \\
    & = \alphabar_t\left[\bSigma-\bSigma\A^T\left(\sigma^2\I+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma\right] + (1-\alphabar_t)\I
\end{aligned}
\end{equation}
}
which does not correspond to a forward DDPM process in general because $\sigma^2\I+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T$ depends on $t$. The only case in which this quantity does not depend on $t$ is the trivial case where $\A = \zero$.
For the $\Pi$GDM algorithm,
{\fontsize{6pt}{7.2pt}\selectfont
\begin{equation}
\begin{aligned}
	& \bC_{t\mid \V}^\text{$\Pi$GDM} \\
    & = \alphabar_t\left[\bSigma-\bSigma\A^T\left(\sigma^2\I+(1-\alphabar_t)\A\A^T+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma\right] \\
    & \quad + (1-\alphabar_t)\I
\end{aligned}
\end{equation}
}
Similarly, this does not correspond to a standard forward DDPM process in general, since the expression
$\sigma^2 \I + (1 - \alphabar_t) \A\A^T + \alphabar_t \A \bSigma^2 \bSigma_t^{-1} \A^T$
depends on $t$. Notably, in the case where $\bSigma = \I$, we have $\bC_{t \mid \V}^\text{$\Pi$GDM} = \bC_{t \mid \V}^\text{CGDM}$. This is consistent with the fact that $r_t^2$ was chosen in \Cref{sec:conditional_DDPM} to be exact in the case where $p_0 = \mathcal{N}$.
For the CGDM algorithm, for any covariance matrix $\bSigma$,
\begin{equation}
	\bC_{t\mid \V}^\text{CGDM} = \alphabar_t \left[\bSigma - \bSigma \A^T \M^\dagger \A\bSigma\right] + (1-\alphabar_t)\I
\end{equation}
corresponds perfectly to the model forward (\Cref{eq:forward_DDPM}) applied to $p_{0\mid \V}$ (\Cref{eq:conditional_Gaussian_init}).



\subsection{Recursive computation of the backward distributions}

\label{sec:recursive_computation_backward_distributions}

Each algorithm corresponds to a backward process, as given in \Cref{algo:backward_conditional_DDPM}. We would like to characterize these at each time. In this Gaussian case, we can explicit $-\frac{1}{2}\nabla_{\x_t} \|\A\widehat{\x}_0(\x_t)-\V\|^2_{\bC_{\V \mid t}^{-1}}$. In particular, the relation between $\x_t$ and $\widehat{\x}_0(\x_t)$ is linear, as given in \Cref{eq:Gaussian_x_0_chap} and
\begin{equation}
\footnotesize
	\frac{1}{2}\nabla_{\x_t} \|\A\widehat{\x}_0(\x_t)-\V\|^2_{\bC_{\V \mid t}^{-1}}
	= \sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}(\A\widehat{\x}_0(\x_t)-\V).
\end{equation}
As a consequence, the backward process of a given algorithm can be written as
%{\small
%\begin{equation}
 %\label{eq:backward_conditional_DDPM_algo}
 %\begin{aligned}
 %	\y_{t-1} & = \frac{1}{\sqrt{\alpha_t}}(\y_t - \beta_t \bSigma_t^{-1}(\y_t-\sqrt{\alphabar_t}\bmu) -\beta_t\sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\left(\bC^\text{algo}_{\V \mid t}\right)^{-1}(\A\widehat{\x}_0(\y_t)-\V)) + \beta_t \z_t, \\
 	%&   \z_t\sim \N, \quad 1 \leq t \leq T, \quad \y_T \sim %\N.
%  \end{aligned}
% \end{equation}}
%  We can rewrite these iterations as
\begin{equation}
\label{eq:algo_A_t_b_t}
\footnotesize
	\begin{aligned}
		\y_T & \sim \N, \\
		\y_{t-1} & = \A_t^{\text{algo}}\y_{t} + \bb_t^{\text{algo}}+\beta_t \z_t, \quad 1 \leq t \leq T,  \z_t \sim \N
	\end{aligned}
\end{equation}
with
{\fontsize{7pt}{7.2pt}\selectfont
\begin{align}
\label{eq:A_t}
	&  \A_t^{\text{algo}} \notag  \\
	&   = \frac{1}{\sqrt{\alpha_t}}\left(\I -\beta_t \bSigma_t^{-1} -\beta_t \overline{\alpha}_t\bSigma_t^{-1}\bSigma \A^T\left(\bC^\text{algo}_{\V \mid t}\right)^{-1}\A\bSigma\bSigma_t^{-1}\right), \\
	&  \bb_t^{\text{algo}} \notag  \\
	& = \beta_t\sqrt{\overline{\alpha}}_{t-1}\bSigma_t^{-1}\bSigma \A^T\left(\bC^\text{algo}_{\V \mid t}\right)^{-1}(\V-\A\bmu+\alphabar_t\A\bSigma\bSigma_t^{-1}\bmu) \notag \\
    &  + \frac{\beta_t}{\sqrt{\alpha_t}}\bSigma_t^{-1}\bmu.
\end{align}
}
This formulation implies that the corresponding backward processes remain Gaussian processes because all the operations are linear. To characterize it, it is necessary to compute the means $(\bmu_t^\text{algo})_{0 \leq t \leq T}$ and  covariance matrices $(\bSigma_t^\text{algo})_{0 \leq t \leq T}$ at each time.
In this Gaussian setting, since the score operations are linear, computing the means $(\bmu_t^\text{algo})_{0 \leq t \leq T}$ simply requires running the algorithms without adding noise at each step. The corresponding iterations are provided in \Cref{algo:compute_mean_algos}.
To compute the covariance matrices $(\bSigma_t^\text{algo})_{0 \leq t \leq T}$, by using Equation~\eqref{eq:algo_A_t_b_t},
\begin{equation}
\label{eq:Sigma_t_A_t}
    	\begin{aligned}
		\bSigma_T^\text{algo} & =\I, \\
		\bSigma_{t-1}^\text{algo} & = \A_t^{\text{algo}}\bSigma_{t}^\text{algo}(\A_t^{\text{algo}})^T + \beta_t \I 
	\end{aligned}
\end{equation}
and it can be implemented by Algorithm~\ref{algo:compute_cov_algos}.
With these algorithms, we can characterize the algorithms' noisy posterior $p_t^\text{algo}(\x_t\mid \V)$ at each time and compare them to the forward process.
%These expressions provide a way to compute the corresponding distributions to the different algorithms along the time schedule.


\begin{figure*}[t]
