    \vspace*{-\baselineskip}% Vertical correction
    \begin{algorithm}[H]
      %\footnotesize
      \caption{Computation of the mean of the algorithm's backward along the time}\label{algo:compute_mean_algos}
      \begin{algorithmic}[1]
        \State $\bmu^{\text{algo}}_T  \leftarrow \zero$
        \For{t=$T$ \textbf{to} 1}
    \State $\bmu_{t-1}^{\text{algo}}\leftarrow  \frac{1}{\sqrt{\alpha_t}}\left(\bmu_t^{\text{algo}} + \beta_t\nabla \log p_t(\bmu_t^{\text{algo}} \mid \V)\right)$
    \EndFor  
