    %\footnotesize
      \caption{Computation of the covariance matrix of the algorithm's backward along the time}
      \label{algo:compute_cov_algos}
      \begin{algorithmic}[1]
            \Require $(\A_t^{\text{algo}})_{0 \leq t \leq T}$
        \State $\bSigma^{\text{algo}}_T = \I$
        \For{t=$T$ \textbf{to} 1}
        \State $\bSigma_{t-1}^\text{algo} \leftarrow \A_t^{\text{algo}}\bSigma_{t}^\text{algo}(\A_t^{\text{algo}})^T + \beta_t \I$
    \EndFor      
    \end{algorithmic}
