\section{Closed-form expressions for Gaussian diffusion models}

\emile{In this appendix, we provide closed-form expressions for Gaussian distributions in the context of diffusion models. We first present a lemma to compute conditional Gaussian distributions and gives a compact expression for the denoised estimate $\widehat{x}_0(\x_t)$ and use the first lemma to compute the theoretical $p(\x_t \mid \V)$, $p(\V\mid \x_t)$ and the theoretical discrete backward process, which sheds light on the inexactness of CGDM as observed in the Wasserstein error plots. Finally, we provide  the computation of  $p_t(\x_t \mid \V)$ given the noisy likelihood modeled by the different algorithms which is used to study them in a forward form in \Cref{sec:comp_algo_under_Gaussian_assumption}.}

\emile{
\subsection{General computation of conditional Gaussian distributions}
In the following, we derive a lemma to compute conditional Gaussian distributions in oour context. A first idea was to use the lemma from Section 2.3.3 in \cite{Bishop_pattern_recognition_and_machine_learning_2006} but it needs invertibility assumption on the covariance matrices.  For this reason, we propose a more general kriging reasoning providing the following lemma.
\begin{lem}[Conditional Gaussian distrbution computations using a kriging reasoning]
\label{lem:Gaussian_conditonal_kriging}
Given the assumptions 
\begin{align}
    p(\x) & = \mathcal{N}(\bbm,\G) \\ 
    p(\y \mid \x) & = \mathcal{N}(\B\x, \tau^2\I) \\ 
\end{align} 
the conditional distribution of $\x$ given $\y$ is given by
    \begin{align}
        p(\x\mid \y) = \mathcal{N}(\bmu_{\y\mid \x},\bSigma_{\y \mid \x})
    \end{align}
    with
    \begin{align}
        \bmu_{\y\mid \x}& = \bbm + \G \B^T \M^{-1}(\V-\B\bbm)
        \\
        \bSigma_{\y \mid \x} & = \G - \G \B^T\M^{-1}\B\G \\
        \M & = \B\G\B^T + \tau^2\I.
    \end{align}
\end{lem}

\noindent Note that $\M$ is invertible because $\B\G\B^T$ is a positive symmetric matrix.
\begin{proof}
    In the case $\bbm = \zero$, as shown by a kriging reasoning in Appendix E of \cite{pierret_stochastic_superresolution_gaussian_microtextures_2024},
    by denoting $\M = \B\G\B + \tau^2\I$, 
\begin{equation}
    \La^T\y + \tx - \La^T(\B\tx + \tau\boldsymbol{\tilde{n}})
\end{equation}
where $\tx$ is a sample from $p_0$ independent of $\y$ and $\n$ is an independent sample following $\mathcal{N}(\zero,\I)$ follows the posterior distribution $p(\x\mid\y)$ with $\La = \M^{-1}\B\G$ is solution of a kriging equation. Consequently, the posterior covariance matrix is the covariance matrix of this expression with respect to $\x$ which is
\begin{align}
    \bSigma_{\y\mid \x} & = (\I - \La^T\B)\G(\I - \La^T\B)^T + \tau^2\La^T\La \\
    & = \G  - \La^T\B\G + \La^T\B\G \B^T\La^T - \G\B^T\La^T + \tau^2\La^T\La\\
    & = \G  - \La^T\B\G + \La^T(\B\G \B^T + \G\B^T + \tau^2\I)\La - \G\B^T\La^T\\
    & = \G  - \La^T\B\G + \La^T\B\G - \G\B^T\La^T\\
    & = \G  -\G \B^T \M^{-1}\B\G
\end{align}
and the conditional expectation
\begin{align}
    \bmu_{\y\mid\x} 
    & = \G\B^T\M^{-1}\y.
\end{align}

In the general case $\bbm \neq \zero$, the covariance matrix is not affected and the conditional expectation becomes
    \begin{align}
    \bmu_{\y\mid\x} 
    & = \mu+\G\B^T\M^{-1}(\y-\B\bbm).
\end{align}
which is equivalent to rescale the quantity to ensure a null expectation.
\end{proof}


}
\subsection{Computation of \texorpdfstring{$\widehat{\x}_0(\x_t)$}{}}
\label{appendix:x_zero_chap}
\emile{In the Gaussian setting $p_0 = \mathcal{N}(\bmu,\bSigma)$, the expression for $\widehat{\x}_0(\x_t)$ is given by Tweedie’s formula (see \Cref{eq:Tweedie_formula}), which, when combined with the explicit form of the score function (see \Cref{eq:Gaussian_score_DDPM}), yields the closed-form expression}
\begin{align}
	\widehat{\x}_0(\x_t)
	& = \frac{1}{\sqrt{\alphabar_t}}\left(\x_t + (1-\alphabar_t) \nabla_{\x}\log p_t(\x_t)\right) \\
	& = \frac{1}{\sqrt{\alphabar_t}}\left(\x_t - (1-\alphabar_t) \bSigma_t^{-1}(\x_t - \sqrt{\alphabar}_t \bmu)\right) \\
	& = (1-\alphabar_t)\bSigma_t^{-1}\bmu +\frac{1}{\sqrt{\alphabar_t}}\left(\x_t - (1-\alphabar_t) \bSigma_t^{-1}\x_t \right) \\
	& = (1-\alphabar_t)\bSigma_t^{-1}\bmu +\frac{\bSigma_t^{-1}}{\sqrt{\alphabar_t}}\left(\bSigma_t \x_t - (1-\alphabar_t) \x_t \right) \\
	& = (1-\alphabar_t)\bSigma_t^{-1}\bmu +\frac{\bSigma_t^{-1}}{\sqrt{\alphabar_t}}\left(\alphabar_t\bSigma\x_t\right) \\
	& = (1-\alphabar_t)\bSigma_t^{-1}\bmu +\sqrt{\alphabar_t}\bSigma_t^{-1}\bSigma\x_t.
\end{align}

\noindent Then, one can also derive
\begin{align}
(1-\alphabar_t)\bSigma_t^{-1}\bmu +\sqrt{\alphabar_t}\bSigma_t^{-1}\bSigma\x_t
& = \bSigma_t^{-1}((1-\alphabar_t)\I)\bmu+\sqrt{\alphabar_t}\bSigma_t^{-1}\bSigma\x_t \\
& = \bSigma_t^{-1}(\bSigma_t-\alphabar_t\bSigma)\bmu+\sqrt{\alphabar_t}\bSigma_t^{-1}\bSigma\x_t \\
& =  \bmu + \sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}(\x_t - \sqrt{\alphabar}_t \bmu).
\end{align}



\emile{\subsection{Computation of \texorpdfstring{$p(\x_t \mid \V)$}{}}

\label{appendix:x_t_mid_v}
In this section, we compute $p(\x_0 \mid \V)$ and $p(\x_t \mid \V)$ in the Gaussian setting $p_0 = \mathcal{N}(\bmu,\bSigma)$.
We apply \Cref{lem:Gaussian_conditonal_kriging} with
\begin{align}
    \x & = \x_0 \\
    \y & = \V \\
    \bbm & = \bmu \\
    \G & = \bSigma \\
    \B & = \A \\
    \tau & = \sigma.
\end{align}
 By denoting $\M = \A\bSigma\A + \sigma^2\I$, it ensures that 
 \begin{equation}
     p(\x_0\mid \V) = \mathcal{N}(\bmu_{0\mid \V},\bSigma_{0\mid \V})
 \end{equation}
 with
\begin{align}
    \bSigma_{\x_0 \mid \V}
    & = \bSigma  -\bSigma \A^T \M^{-1}\A\bSigma \\
    \bmu_{0\mid \V} & = \bmu +\bSigma\A^T\M^{-1}(\V-\A\bmu) \\
    \M & = \A\bSigma\A^T+\sigma^2\I.
\end{align}

Then, because $p(\x_t\mid \x_0) = \mathcal{N}(\sqrt{\alphabar}_t\x_0, (1-\alphabar_t)\I)$,

\begin{equation}
    p(\x_t\mid\V) = \mathcal{N}(\sqrt{\alphabar}_t\E[\x_0\mid \V], \alphabar_t\bSigma_{\x_0 \mid \V}+(1-\alphabar_t)\I )
\end{equation}
}

\emile{
\subsection{Computation of \texorpdfstring{$p(\V \mid \x_t)$}{}}
\label{appendix:v_mid_x_t}
Let us first compute $p(\x_0\mid \x_t)$. 
We apply \Cref{lem:Gaussian_conditonal_kriging} with
\begin{align}
    \x & = \x_0 \\
    \y & = \x_t \\
    \bbm & = \bmu \\
    \G & = \bSigma \\
    \B & = \sqrt{\alphabar}_t\I \\
    \tau & = (1-\alphabar_t).
\end{align}
We obtain the covariance matrix is
\begin{align}
    \bSigma_{0\mid t}
    & =
    \bSigma  - \alphabar_t\bSigma (\alphabar_t\bSigma +(1-\alphabar_t) \I))^{-1}\bSigma
    & = \bSigma  - \alphabar_t\bSigma^2 \bSigma_t^{-1} \\
    & = \bSigma\bSigma_t^{-1}(\bSigma_t - \alphabar_t\bSigma) \\
    & = (1-\alphabar_t)\bSigma\bSigma_t^{-1},
\end{align}

and the expectation is $\widehat{\x}_0(\x_t)$.

Then, $\V = \A\x_0 + \sigma^2\I$ and consequently,

\begin{equation}
    p(\V \mid \x_t) = \mathcal{N}(\A\widehat{\x}_0(\x_t),(1-\alphabar_t)\A\bSigma\bSigma_t^{-1} \A^T + \sigma^2\I).
\end{equation}
}

