\subsection{Computation of \texorpdfstring{$p(\x_t \mid \V)$}{} for the different algorithms}

\label{appendix:proof_expression_C_v_t}
\emile{In the Gaussian setting where $p_0 = \mathcal{N}(\bmu,\bSigma)$, the forward process defined in \Cref{eq:forward_DDPM} yields}  $p_t(\x_t) = \mathcal{N}(\sqrt{\alphabar}_t \bmu,\bSigma_t)$ with $\bSigma_t = \alphabar_t\bSigma + (1-\alphabar_t)\I$ and $p(\V \mid \x_t) = \mathcal{N}(\A\widehat{\x}_0(\x_t),\bC_{\V \mid t})$, as developed in \Cref{sec:conditional_DDPM}. By Bayes' rule,
\begin{equation}
	\nabla_{\x} \log p_t(\x_t \mid \V) 
	= \nabla_{\x} \log p_t( \x_t) +\nabla_{\x} \log p_t( \V\mid \x_t) 
\end{equation}
\noindent Consequently,
\begin{equation}
	\nabla_{\x} \log p_t(\x_t \mid \V) 
	= -\bSigma_t^{-1}(\x_t-\sqrt{\alphabar}_t\bmu)-\sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}(\A\widehat{\x}_0(\x_t)-\V)  
\end{equation}
\noindent By denoting $p_t(\x_t\mid \V) = \mathcal{N}(\bmu_{t \mid \V},\bC_{t\mid \V})$, $\nabla_{\x} \log p_t(\x_t\mid \V) = -\bC_{\V \mid t}^{-1}(\x_t - \bmu_{\V \mid \x_t})$ and by identifying the terms in $\x_t$,
\begin{align}
	C_{t \mid \V}^{-1}
	& = \bSigma_t^{-1}+\alphabar_t\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\A\bSigma\bSigma_t^{-1}
\end{align}
Furthermore, by Woodburry matrix identity \cite{Higham_accuracy_stability_Woodburry_2002},
\begin{equation}
	\left(B + UDV \right)^{-1} = B^{-1} - B^{-1}U \left(D^{-1} + VB^{-1}U \right)^{-1} VB^{-1}
\end{equation}
\noindent Consequently, with $B = \bSigma_t, U = -\sqrt{\alphabar}_t\bSigma\A^T, V = \sqrt{\alphabar}_t\A\bSigma,$ and $D$ such that $D^{-1} + VB^{-1}U = \bC_{\V \mid t}$ ie $D = \left(\bC_{\V \mid t}+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}$,
\begin{align}
	\bC_{t \mid \V}
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\bC_{\V \mid t}-\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma
\end{align}
and finally,
{\small
\begin{align}
	C^{\text{DPS}}_{t \mid \V}
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma \\
	C^{\text{$\Pi$GDM}}_{t \mid \V}
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+(1-\alphabar_t)\A\A^T+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma \\
	C^{\text{CGDM}}_{t \mid \V}
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+(1-\alphabar_t)\A\bSigma\bSigma_t^{-1}\A^T+\alphabar_t \A\bSigma^2\bSigma_t^{-1}\A^T\right)^{-1}\A\bSigma \\
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+\A\bSigma\bSigma_t^{-1}((1-\alphabar_t)\I+\alphabar_t \bSigma)\A^T\right)^{-1}\A\bSigma \\
	& = \bSigma_t-\alphabar_t\bSigma\A^T\left(\sigma^2\I+\A\bSigma\A^T\right)^{-1}\A\bSigma
\end{align}}
By identifying the other terms,
\begin{align}
	\bC_{t \mid \V}^{-1}\bmu_{t \mid \V}
	& =  \sqrt{\alphabar}_t\bSigma_t^{-1}\bmu+\sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\left(\V +\alphabar_t \A\bSigma\bSigma_t^{-1}\bmu-\A\bmu \right) \\
	& = \sqrt{\alphabar}_t\left(\bSigma_t^{-1}+\alphabar_t\bSigma\bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\A\bSigma\bSigma_t^{-1}\right)\bmu +\sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\left(\V -\A\bmu \right)\\
	& = \sqrt{\alphabar}_t\bC_{t \mid \V}^{-1}\bmu+\sqrt{\alphabar_t}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\left(\V -\A\bmu \right),
\end{align}
\noindent and
\begin{equation}
	\bmu_{t \mid \V}
	=  \sqrt{\alphabar}_t\bmu+\sqrt{\alphabar_t}\bC_{t \mid \V}\bSigma \bSigma_t^{-1}\A^T\bC_{\V \mid t}^{-1}\left(\V -\A\bmu \right).
\end{equation}


