\section{Analytical derivations for diffusion models on Gaussian microtextures}

\label{appendix:ADSN_computations}


\subsection{Application of the exact score function}

\label{appendix:ADSN_score_application}

The ADSN model \cite{Galerne_Gousseau_Morel_random_phase_textures_2011_IEEE} allows for the exact computation of the score function associated with the iterations of diffusion models.
The inverse of the matrix $\bSigma_t = \alphabar_t \bSigma + (1 - \alphabar_t)\I$ appears in the score function, as given in Equation~\eqref{eq:Gaussian_score_DDPM}.
Let us now describe why this inversion is feasible.

\noindent First, we recall \Cref{eq:score_matrix_3d}: for $\xi \in \OMN$,
\begin{equation}
\widehat{\bSigma}_t(\xi) = \alphabar_t \widehat{\bt}(\xi)\left[\widehat{\bt}(\xi)\right]^T + (1 - \alphabar_t)\I_3. \tag{{\color{black}\ref{eq:score_matrix_3d}}}
\end{equation}
In a certain sense, the action of $\bSigma_t$ is separable across all frequencies.
We can invert it using the following lemma.
\begin{lem}
\label{lem:inverse_1_rank_3d}
	Let $\y \in \C^3$, $a,b \in \R^+$,
	\begin{equation}
		\left(a\y\overline{\y}^T + b\I_3\right)^{-1} = \frac{1}{b}I_3 -  \frac{a\|y\|^2}{b(a\|y\|^2+b)}\y\y^T.
	\end{equation}
\end{lem}
\begin{proof}
    It is well-known that $\frac{\y\overline{\y}^T}{\|y\|^2}$ is the orthogonal projection on $\Span(\y)$ (see for example \cite{golub_matrix_computations_2013}).

\noindent Consequently, by completing $\frac{\y}{\|y\|^2}$ in an orthogonal basis and considering its matrix $\bP$,
	\begin{equation}
		\y\overline{\y}^T 
		= \bP^T\begin{pmatrix}
			\|y\|^2 & 0 & 0 \\
			0 & 0 & 0 \\
			0 & 0 & 0
		\end{pmatrix}\bP.
	\end{equation}
	Then,
	\begin{equation}
		\bP (a\y\overline{\y}^T+bI_3) 
		= \bP^T\begin{pmatrix}
			a\|y\|^2+b & 0 & 0 \\
			0 &  b& 0 \\
			0 & 0 & b
		\end{pmatrix}\bP
	\end{equation}
	and
	\begin{align}
		 (a\y\overline{\y}^T+bI_3)^{-1}
		& = \bP^T\begin{pmatrix}
			\frac{1}{a\|y\|^2+b} & 0 & 0 \\
			0 &  \frac{1}{b}& 0 \\
			0 & 0 & \frac{1}{b}
		\end{pmatrix}\bP  \\
		& = \frac{1}{b}I_3 + \left(\frac{1}{a\|y\|^2+b}-\frac{1}{b}\right)\y\overline{\y}^T \\
		& = \frac{1}{b}I_3-  \frac{a\|y\|^2}{b(a\|y\|^2+b)}.
	\end{align}
\end{proof}
\noindent This lemma follows from the fact that the symmetric rank-one matrix $\frac{\y \overline{\y}^T}{|\y|^2}$ is the orthogonal projection onto $\Span(\y)$.
It can be applied to the matrix $\bSigma_t$ separately at each frequency, following \Cref{eq:score_matrix_3d}. To be complete, for $\x \in \R^{3\OMN}$ and $ \xi \in \OMN$,

\begin{equation}
    \widehat{\bSigma_t^{-1}\x}(\xi)
    = \frac{1}{1-\alphabar_t}\widehat{\x}(\xi) - \frac{\alphabar_t\|\widehat{\bt}(\xi)\|^2}{(1-\alphabar_t)(\alphabar_t\|\widehat{\bt}(\xi)\|^2 + \alphabar_t) } \widehat{\bSigma}(\xi)\widehat{\x}(\xi)
\end{equation}
where $\widehat{\x}(\xi) = (\begin{smallmatrix}
    \widehat{\x}_1(\xi) & \widehat{\x}_2(\xi) & \widehat{\x}_3(\xi)
\end{smallmatrix})^T \in \R^3$

\subsection{Proof of \Cref{prop:simult_diago_cov_backwards}}

\label{appendix:proof_proposition_simultaneous_diagonalizable}

We recall here \Cref{prop:simult_diago_cov_backwards} that we prove.
\setcounter{prop}{0}
\begin{prop}[Simultaneous diagonalizability of the Gaussian backward processes associated with the different algorithms]
For the deblurring problem involving ADSN microtextures, the covariance matrices associated with the backward processes of the different algorithms—$(\bSigma_t^\text{CGDM})_{0 \leq t \leq T}$, $(\bSigma_t^\text{DPS})_{0 \leq t \leq T}$, and $(\bSigma_t^\text{$\Pi$GDM})_{0 \leq t \leq T}$—are diagonalizable in the same orthogonal basis as $\bSigma$.
\end{prop}
\begin{proof}

As proved in Appendix I.2 of \cite{pierret_diffusion_models_gaussian_distributions_2024}, it is sufficient to study the 3D structure of the covariance matrix of ADSN to determine its eigenvectors and associated eigenvalues. In a certain sense, the matrix is block-diagonalizable with respect to 3D blocks. We will show that its eigenvectors are preserved over time. For a given frequency $\xi \in \OMN$, we denote 
\begin{equation}
    \widehat{\V}_1(\xi) = \widehat{\bt}(\xi) =  \begin{pmatrix}
        \widehat{\bt}_1(\xi) \\
        \widehat{\bt}_2(\xi) \\
        \widehat{\bt}_3(\xi) \\
    \end{pmatrix}, \widehat{\V}_2(\xi)  =  \begin{pmatrix}
        -\overline{\widehat{\bt}}_3(\xi) \\
        0 \\
        \overline{\widehat{\bt}}_1(\xi) \\
    \end{pmatrix}, \widehat{\V}_2(\xi)  =  \begin{pmatrix}
       0 \\
         -\overline{\widehat{\bt}}_3(\xi)\\
        \overline{\widehat{\bt}}_2(\xi). \\
    \end{pmatrix}
\end{equation}
It is an orthogonal basis of eigenvectors of $\widehat{\bSigma}(\xi)$ because
\begin{align}
    \overline{\widehat{\V}}_k(\xi)^T\widehat{\V}_\ell(\xi) & = 0 \text{ for $1\leq k< \ell \leq 3$} \\
    \widehat{\bSigma}(\xi)\widehat{\V}_1(\xi) 
    & = [\overline{\widehat{\bt}}(\xi)^T\widehat{\bt}(\xi)]\widehat{\V}_1(\xi) \\
    \widehat{\bSigma}(\xi)\widehat{\V}_2(\xi) 
    & =\zero \\
    \widehat{\bSigma}(\xi)\widehat{\V}_3(\xi) 
    & = \zero .
\end{align}
We denote $\lambda_k(\xi)$ the eigenvalues associated with $\widehat{\V}_k(\xi)$ (respectively $[\overline{\widehat{\bt}}(\xi)^T\widehat{\bt}(\xi)]$, $0$ and $0$). Furthermore, $\widehat{\bC}(\xi)$ conserves the same eigenvectros because
\begin{equation}
\label{eq:c_preserves_structure}
     \widehat{\bC}(\xi)\widehat{\V}_k(\xi) 
     = \bc(\xi)\widehat{\V}_k(\xi) \text{ for $1\leq k \leq 3$}
\end{equation}
\noindent and $\widehat{\bSigma}_t^{-1}(\xi)$ also by the previous subection.
This ensures that the matrix $\A_t^\text{algo}$ given in \Cref{eq:A_t} and recalled here
\begin{equation}
	\A_t^{\text{algo}}
	 = \frac{1}{\sqrt{\alpha_t}}\left(\I -\beta_t \bSigma_t^{-1} -\beta_t \overline{\alpha}_t\bSigma_t^{-1}\bSigma \A^T\left(\bC^\text{algo}_{\V \mid t}\right)^{-1}\A\bSigma\bSigma_t^{-1}\right)
\end{equation}
\noindent preserves the eigenvectors of $\widehat{\bSigma}(\xi)$. Finally, the application of \Cref{algo:compute_cov_algos} ensures that the covariance matrices associated with the algorithms' backward processes preserve the eigenvector basis.

\begin{rem}
    \Cref{eq:c_preserves_structure} shows that our method cannot be extended to cases where different kernels are applied to different image channels, highlighting the crucial role of the specific structure of the deblurring problem degradation operator.
\end{rem}
\end{proof}
}
