\section{On Lossless Multiple Release Sampling}\label{appendix:sampling}
\Cref{lemma:additive_noise_means_lossless} makes no claim about how easy it is to sample noise from the conditional noise distribution, but guarantees its existence.
We will use this section for discussing this sampling in greater detail.
Consider the joint distribution of the releases defined by \cref{eq:multiple-release} from the proof of \Cref{lemma:additive_noise_means_lossless}, re-stated below for convenience:
\begin{equation}\tag{1}
     Y_{\rho_k} = f(\X) + Z_{\rho_m} + \sum_{j=k}^{m-1} W_{\rho_{j+1}, \rho_j}\,,\qquad k=1, \dots, m\,,
\end{equation}
where $Y_{\rho_k}$ is the $\rho_k$-private release, $Z_{\rho_m}\sim \mathcal{D}(\rho_m)$ and $W_{\rho_{j+1}, \rho_j}\sim\mathcal{C}(\rho_{j+1}, \rho_j)$.
Recall that $\mathcal{C}(\rho', \rho)$ is the unique distribution where for any $0 < \rho < \rho' : \mathcal{D}(\rho) = \mathcal{D}(\rho') * \mathcal{C}(\rho', \rho)$.
As argued for in the proof of \Cref{lemma:additive_noise_means_lossless}, to make a new $\rho$-private release, we consider the joint distribution, and sample the new releases conditioned on all past releases.

Formally, for a set of privacy parameters $\rho_1 < \dots < \rho_m$, we are interested in releasing $\rho_k$ for a single $k\in[m]$, conditioned on the set of past releases $M=\{(\rho_i, Y_{\rho_i}) : i\in[m]\setminus\{k\}\}$.
We give pseudocode for this in \Cref{alg:generic-sampling}, and a lemma for its correctness.
\begin{algorithm}[t]
\caption{$\releaseGeneric$}\label{alg:generic-sampling}
\begin{algorithmic}[1]
\PARAMETERS Noise distribution family $\mathcal{D}(\rho)$ satisfying a convolution preorder,\\
bridging noise distribution $\mathcal{C}(\rho, \rho')$ where $\mathcal{D}(\rho') * \mathcal{C}(\rho', \rho) = \mathcal{D}(\rho)$ for $0 < \rho < \rho'$.
\INPUTS Sensitive value $f(\X)$, new privacy parameter $\rho_k$, set of past releases $M = \{ (\rho_i, Y_{\rho_i}) : i\in[m]\setminus\{ k \} \}$
\IF{$M = \emptyset$}
\STATE Sample $Z_{\rho_k}$ from $\mathcal{D}(\rho_{\rho_k})$
\STATE Set $Y_{\rho_k} = f(\X) + Z_{\rho_k}$
\ELSIF{$k = 1$}
\STATE Sample $W_{\rho_{k+1}, \rho_{k}}$ from $\mathcal{C}(\rho_{k+1}, \rho_{k})$
\STATE Set $Y_{\rho_k} = Y_{\rho_{k+1}} + W_{\rho_{k+1}, \rho_{k}}$
\ELSIF{$k\in (1, m)$} \label{case3.sample}
\STATE Sample $W_{\rho_{k+1}, \rho_k}$ from $\mathcal{C}(\rho_{k+1}, \rho_k)$ conditioned on $W_{\rho_{k+1}, \rho_k} + W_{\rho_k, \rho_{k-1}} = Y_{\rho_{k-1}} - Y_{\rho_{k+1}}$ 
\STATE Set $Y_{\rho_k} = Y_{\rho_{k+1}} + W_{\rho_{k+1}, \rho_k}$
\ELSIF{$k=m$}
\STATE Sample $Z_{\rho_k}$ from $\mathcal{D}(\rho_k)$ conditioned on $Z_{\rho_k} + W_{\rho_{k}, \rho_{k-1}} = Y_{\rho_{k-1}} - f(\X)$
\STATE Set $Y_{\rho_k} = f(\X) + Z_{\rho_k}$
\ENDIF
\STATE Set $M = M \cup \{(\rho_k, Y_{\rho_k})\}$
\STATE \textbf{Return} $Y_{\rho_k}$
\end{algorithmic}
\end{algorithm}
\begin{lemma}\label{lemma:generic_sampling}
    Initializing $M=\emptyset$ and then running \Cref{alg:generic-sampling} for a set of privacy parameters $\{\rho_i : i\in[m]\}$ (processed in arbitrary order), will produce a set of outputs $\{ Y_{\rho_i} : i\in[m]\}$ with distribution given by \cref{eq:multiple-release}.
\end{lemma}

\begin{proof}
    For $M=\emptyset$, we have that $Y_{\rho_k} = f(\X) + \cD(\rho_k) =\mathcal{A}_{f,\rho_k}(\X)$ on lines 2-3, as expected, where $\cA$ is our \IAN noise mechanism releasing $f$ with $\rho$-privacy.
    For the remaining cases, assume $M$ contains $m-1$ releases with the correct joint distribution, and we are generating a new release at privacy level $\rho_k$.
    We will argue that \Cref{alg:generic-sampling} produces a $Y_{\rho_k}$ whose joint distribution with the releases in $M$ matches \eqref{eq:multiple-release}.
    For $k=1$, observe that $Y_{\rho_1} = Y_{\rho_2} + W_{\rho_{2}, \rho_{1}}$, and so lines 5-6 are correct.
    For $1 < k < m$, note that $Y_{\rho_k} = Y_{\rho_{k+1}} + W_{\rho_{k+1}, \rho_{k}}$ and ${Y_{\rho_{k-1}} = Y_{\rho_k} + W_{\rho_{k}, \rho_{k-1}}}$, which combined allows us to identify the correct conditional distribution.
    $Y_{\rho_k}$ is given by $Y_{\rho_{k+1}} + W_{\rho_{k+1}, \rho_{k}}$, conditioned on $W_{\rho_{k+1}, \rho_{k}} + W_{\rho_{k}, \rho_{k-1}} = Y_{\rho_{k-1}} - Y_{\rho_{k+1}}$, matching lines 8-9.
    For the final case of $k=m$, then $Y_{\rho_m} = f(\X) + Z_{\rho_m}$ and we have that $Y_{\rho_{m-1}} = Y_{\rho_m} + W_{\rho_{m}, \rho_{m-1}}$.
    It follows that the correct noise distribution is $Y_{\rho_m} = f(\X) + Z_{\rho_{m}}$, conditioned on $Z_{\rho_m} + W_{\rho_{m}, \rho_{m-1}} = Y_{\rho_{m-1}} - f(\X)$, matching lines 11-12.
    An inductive argument identical to that given in the proof of \Cref{lemma:additive_noise_means_lossless} completes the proof.
\end{proof}

\subsection{Simplification and Removing Dependency on the Dataset}
Note that $f(\X)$ is only used in \Cref{alg:generic-sampling} when a more accurate release is generated (lines 1 and 10).
In the remaining cases we are only adding noise to past releases.
This already allows us to simplify the algorithm, and argue for not having to store $f(\X)$ in memory indefinitely.
The algorithm reduces to the case (see line~7 of \cref{alg:generic-sampling}) where only the two closest releases are combined into a new one.
Such an algorithm is given in \Cref{alg:generic-sampling-simpler}, together with \Cref{lemma:generic_sampling_simplified}.

\begin{algorithm}[t]
\caption{$\releaseGenericS$}
\label{alg:generic-sampling-simpler}
\begin{algorithmic}[1]
\PARAMETERS Noise distribution family $\mathcal{D}(\rho)$ satisfying a convolution preorder,\\
bridging noise distribution $\mathcal{C}(\rho, \rho')$ where $\mathcal{D}(\rho') * \mathcal{C}(\rho', \rho) = \mathcal{D}(\rho)$ for $0 < \rho < \rho'$
\INPUTS Privacy parameter $\rho$, set of releases $M$
\STATE Find ${(\rho_k, Y_{\rho_k}), (\rho_{k+1}, Y_{\rho_{k+1}})\in M}$ such that $\rho\in [\rho_k, \rho_{k+1})$ and $\forall (\rho', \cdot)\in M: \rho' \notin (\rho_k, \rho_{k+1})$\label{line:closest-rhos}
\STATE Sample $W_{\rho_{k+1}, \rho}$ from $\mathcal{C}(\rho_{k+1}, \rho)$ conditioned on $W_{\rho_{k+1}, \rho} + W_{\rho, \rho_{k}} = Y_{\rho_{k}} - Y_{\rho_{k+1}}$
\STATE Set $Y_\rho = Y_{\rho_{k+1}} + W_{\rho_{k+1}, \rho}$
\STATE Set $M = M \cup \{(\rho, Y_\rho)\}$
\STATE \textbf{Return} $Y_\rho$
\end{algorithmic}
\end{algorithm}

\begin{lemma}\label{lemma:generic_sampling_simplified}
     Let $M=\{(\rho_0, Y_{\rho_0}), (\rho_\infty, Y_{\rho_\infty})\}$ for $Y_{\rho_\infty} = \mathcal{A}_{\rho_\infty, f}(x)$, and $Y_{\rho_0} = Y_{\rho_\infty} + W_{\rho_\infty, \rho_0}$.
     Then running \Cref{alg:generic-sampling-simpler} with input $M$ and a set of privacy parameters $\{\rho_i : i\in[m]\}\subset (\rho_0, \rho_\infty)$ (processed in arbitrary order), will produce a set of outputs $\{Y_{\rho_i} : i\in[m]\}$ with distribution given by \cref{eq:multiple-release}.
     Moreover, the set $M$ will at all times satisfy $\rho_\infty$-privacy.
\end{lemma}
\begin{proof}
    The statement follows from carefully comparing to \Cref{alg:generic-sampling}.
    Let $S=(\rho_1, \dots, \rho_m)$ be a sequence of noise values from the lemma statement, and let $O=(Y_{\rho_1}, \dots, Y_{\rho_m})$ be the outputs.
    Consider a second sequence $S'=(\rho_\infty, \rho_0, \rho_1, \dots, \rho_m)$, and consider the corresponding sequence of outputs $O'=(Y_{\rho_\infty}', Y_{\rho_0}', Y_{\rho_1}', \dots, Y_{\rho_m}')$ from inputting $S'$ and $M'=\emptyset$ to \Cref{alg:generic-sampling}.
    We can directly check that $Y_{\rho_0}\stackrel{d}{=}Y_{\rho_0}'$ and $Y_{\rho_\infty}\stackrel{d}{=} Y_{\rho_\infty}'$.
    For the remaining outputs, note that just before each algorithm is called, their internal states $M$ and $M'$ are also identically distributed.
    Now, the fact that each $\rho_i\in(\rho_0, \rho_\infty)$ implies that the remaining outputs $Y_{\rho_1}', \dots, Y_{\rho_m}'$ are generated from lines 10-12 in \Cref{alg:generic-sampling}.
    Checking carefully, lines 1-3 in \Cref{alg:generic-sampling-simpler} are implementing the same routine, and since $M \stackrel{d}{=} M'$, it follows that $(Y_{\rho_1}, \dots, Y_{\rho_m}) \stackrel{d}{=} (Y_{\rho_1}', \dots, Y_{\rho_m}')$, and so the statement follows from \Cref{lemma:generic_sampling}.
    The last statement on the $\rho_\infty$-privacy of $M$ follows from \Cref{alg:generic-sampling-simpler} implements \Cref{eq:multiple-release}, and so each release in $M$ can at any time during execution be viewed as randomized post-processing of $Y_\infty$.
\end{proof}
Essentially, if we commit to supporting a bounded range of privacy parameters then we get a simpler algorithm.
\Cref{lemma:generic_sampling_simplified} also says something more:
If we commit to supporting a lowest level of privacy $\rho_\infty$, then \Cref{alg:generic-sampling-simpler} can be implemented in such a way that its internal state is $\rho_\infty$-private.
After initializing $M$ using the sensitive function $f(\X)$, we can erase $f(\X)$ from memory and $Y_\infty$ will contain enough private information to generate all future releases.
This could prove useful in settings where the time between releases is large, and we want to limit the private information leaked if the state of the algorithm were to be compromised.
This can be compared with the gradual release setting, where natural implementations would require consistent access to $f(\X)$.

\section{Omitted Proof for Gaussian Lossless Multiple Release}\label{appendix:omitted-proofs}

\begin{proof}[Proof of \Cref{lemma:gaussian_seq_ooo}]
    Throughout the proof we will ignore the factor $2$ in the denominator of the variance.
To argue that the values generated by the process match the distribution \Cref{lemma:gaussian_seq}, we will argue for increasing subsets of releases.
    Let $S_n = \{ \rho_k : k\in [n-1]\}$ where $0 < \rho_1 < \dots < \rho_n < \rho_\infty$ be the set of values in $S$ for which we have generated Gaussians at the start of the $n$\textsuperscript{th} round of the process.
    Note that we re-label the $\rho$'s between the rounds such that $\rho_k\in S_n$ always is the $k$\textsuperscript{th} smallest value in $S_n$.
    Our argument will proceed by induction: assume that all the Gaussians $\{Y_{\rho_k} : k\in [n]\}$ generated after $n$ rounds have the distribution given by \Cref{lemma:gaussian_seq}.
    Then we will show that $\{Y_{\rho_k} : k\in[n-1]\}\cup \{ Y_\rho \}$ has the same distribution as predicted by $S_{n}\cup\{\rho\}$ from invoking \Cref{lemma:gaussian_seq}.

    We begin with our base case.
    For $n=1$, we have that $\rho_l = 0$ and $\rho_r=\rho_\infty$, and so $Y_\rho = Y_{\rho_\infty} + \NN(0, 1/\rho - 1/\rho_\infty)$.
    Since $Y_{\rho_\infty}\sim\NN(\beta, 1/\rho_\infty)$, we have that $Y_\rho\sim\NN(\beta, 1/\rho)$, as expected, and so the base case passes.

    For $n\geq 2$, we first consider the following cases.

    \emph{Case 1}: $\rho_l = 0, \rho_r=\rho_1\in S_n$.
    In this case, $Y_\rho = Y_{\rho_1} + \NN(1/\rho - 1/\rho_1)$, and so $Y_\rho\sim\NN(\beta, 1/\rho)$.
    Since $\rho < \rho_1$, we have that $\forall i\in[n-1] : \mathrm{Cov}(Y_\rho, Y_{\rho_i}) = \mathrm{Cov}(Y_{\rho_1}, Y_{\rho_i}) = 1/\rho_i$, as expected for the release with the smallest value in $\{\rho\}\cup S_n$, and so the case is complete.

    \emph{Case 2}: $\rho_l = \rho_{n-1}, \rho_r = \rho_\infty = \infty$.
    We have to deal with the case where we have set $\rho_\infty=\infty$ separately, as it is a bit of a trick.
    Note that we get $Y_\rho = \frac{(1-\rho_{n-1})\beta + \rho_{n-1}Y_{\rho_{n-1}}}{\rho}  + \NN(0, \frac{1-\rho_{n-1}/\rho}{\rho})$, since $Y_{\rho_\infty} = \beta$ in this case.
    The end result is once more a sum of Gaussians, with mean $\beta$, and for the variance we can explicitly compute that $\var[Y_\rho] = \frac{\rho_{n-1}^2}{\rho_{n-1}\rho^2} - \frac{\rho - \rho_{n-1}}{\rho^2} = 1/\rho$, as expected.
    For the covariance, for $i\in[n-1] : \mathrm{Cov}(Y_\rho, Y_{\rho_i}) = \frac{\rho_{n-1}}{\rho}\mathrm{Cov}(Y_{\rho_{n-1}}, Y_{\rho_i}) = 1/\rho$, as expected for the largest value in $\{\rho\}\cup S_n$, and so we are done.
    Now we consider the most general case.

    \emph{Case 3}: $\rho_l\in S_{n-1}$ and $\rho_r \neq \infty$.
We begin with computing the variance of $Y$ using the hypothesis $\var[Y_{\rho_r}] = 1/\rho_r$ and $\var[Y_{\rho_l}] = 1/\rho_l$
    \begin{align*}
        \var[Y_\rho] &=  \frac{(\rho_l^{-1} -\rho^{-1})(\rho^{-1} - \rho_{r}^{-1})}{\rho_l^{-1} - \rho_{r}^{-1}}
        + \frac{(\rho_l^{-1} - \rho^{-1})^2\var[Y_{\rho_r}] + (\rho^{-1} -\rho_{r}^{-1})^2\var[Y_{\rho_l}]}{(\rho_l^{-1} - \rho_{r}^{-1})^2}\\
        &= \frac{1}{(\rho_l^{-1} - \rho_{r}^{-1})^2}\bigg[(\rho_l^{-1} - \rho^{-1})(\rho^{-1} - \rho_{r}^{-1})(\rho_l^{-1} - \rho_{r}^{-1}) +\rho_{r}^{-1}(\rho_l^{-1} - \rho^{-1})^2 + \rho_l^{-1}(\rho^{-1} - \rho_{r}^{-1})^2 \bigg]\\
        &= \frac{1}{(\rho_l^{-1} - \rho_{r}^{-1})^2}\cdot\rho^{-1}(\rho_l^{-1} - \rho_{r}^{-1})^2 = \frac{1}{\rho}\,,
    \end{align*}
    where the third equality follows from applying the identity
    \begin{align*}
        (a-b)(b-c)(a-c) + c(a-b)^2 + a(b-c)^2 = b(a-c)^2\,,
    \end{align*}
    to the expression in the brackets for $a = \rho_l^{-1}, b = \rho^{-1}$ and $c = \rho_{r}^{-1}$, 
    proving the correctness of the variance.
    Furthermore, $Y_\rho$ is a sum of Gaussians and a convex combination of two Gaussians with mean $\beta$, so $Y_\rho\sim\NN(\beta, 1/\rho)$.
    What remains to show is that the covariances match up, which we do next.

    We start with the case where $\rho_r \neq \rho_\infty$, and so there exists $\rho_k, \rho_{k+1}\in S_n$ such that $\rho\in (\rho_k, \rho_k+1)$
    For $j\in[n-1]$, we therefore have that
    \begin{align*}
        \mathrm{Cov}(Y_\rho, Y_{\rho_j}) &=
        \mathrm{Cov}\bigg(\frac{(\rho_l^{-1} - \rho^{-1})Y_{\rho_r} + (\rho^{-1} - \rho_{r}^{-1})Y_{\rho_l}}{\rho_l^{-1} - \rho_{r}^{-1}}, Y_{\rho_j}\bigg)\\
        &= \frac{1}{\rho_l^{-1} - \rho_{r}^{-1}}\bigg[(\rho_l^{-1} - \rho^{-1})\mathrm{Cov}(Y_{\rho_r}, Y_{\rho_j}) + (\rho^{-1} - \rho_{r}^{-1})\mathrm{Cov}(Y_{\rho_l}, Y_{\rho_j})\bigg]\\
        &= \frac{1}{\rho_l^{-1} - \rho_{r}^{-1}}\bigg[(\rho_l^{-1} - \rho^{-1})\min(\rho_{r}^{-1}, \rho_j^{-1}) + (\rho^{-1} - \rho_{r}^{-1})\min(\rho_{l}^{-1}, \rho_j^{-1})\bigg]\,.
\end{align*}
    We consider the cases of $j\leq k$ and $j > k$ separately.
    For $j\leq k$, we have that
    \begin{equation*}
        \mathrm{Cov}(Y_\rho, Y_{\rho_j}) = \frac{1}{\rho_l^{-1} - \rho_{r}^{-1}}\bigg[(\rho_l^{-1} - \rho^{-1})\rho_{r}^{-1} + (\rho^{-1} - \rho_{r}^{-1})\rho_{l}^{-1}\bigg]\enspace = \frac{1}{\rho}\,,
    \end{equation*}
    and similarly for $j \geq k+1$ we get
    \begin{equation*}
        \mathrm{Cov}(Y_\rho, Y_{\rho_j}) = \frac{1}{\rho_k^{-1} - \rho_{k+1}^{-1}}\bigg[(\rho_k^{-1} - \rho^{-1})\rho_{j}^{-1} + (\rho^{-1} - \rho_{k+1}^{-1})\rho_{j}^{-1}\bigg]\enspace = \frac{1}{\rho_j}\,.
    \end{equation*}
    It follows that $\mathrm{Cov}(Y_\rho, Y_{\rho_j}) = \frac{\Delta_2^2}{2\max(\rho, \rho_j)}$ for $j\in[m]$, and so we are done with this part of the covariances.

    For the last step, we consider what happens when $\rho_r=\rho_\infty < \infty$.
    In this case, $\rho_l = \rho_{n-1}$ and so for $j\in[n-1]$:
    \begin{align*}
        \mathrm{Cov}(Y_\rho, Y_{\rho_j}) &= \mathrm{Cov}\left(\frac{(1-\rho_{n-1}/\rho)Y_{\rho_\infty} + (\rho_{n-1}/\rho - \rho_{n-1}/\rho_\infty)Y_{\rho_{n-1}}}{1-\rho_{n-1}/\rho_\infty}, Y_{\rho_j}\right)\\
        &= \frac{1-\rho_{n-1}/\rho}{1-\rho_{n-1}/\rho_\infty}\mathrm{Cov}(Y_{\rho_\infty}, Y_{\rho_j}) + \frac{\rho_{n-1}/\rho - \rho_{n-1}/\rho_\infty}{1-\rho_{n-1}/\rho_\infty}\mathrm{Cov}(Y_{\rho_{n-1}}, Y_{\rho_j})\\
        &= \frac{1-\rho_{n-1}/\rho}{\rho_\infty-\rho_{n-1}} + \frac{1/\rho - 1/\rho_\infty}{1-\rho_{n-1}/\rho_\infty} = \frac{1 - \rho_{n-1}/\rho + \rho_\infty/\rho - 1}{\rho_\infty - \rho_{n-1}} = 1/\rho\,,
    \end{align*}
    and now we are done.
\end{proof}


\section{Details on (Efficient) Weakly Lossless Gradual Release of Sparse Gaussian Histograms}\label{sec:efficient-sparse}
\Cref{alg:gradual-release-histogram} implements \emph{weakly lossless gradual release} of private histograms.
We prove this next.
\begin{proof}[Proof of \Cref{lemma:gradual_histograms}]
    Observe that for any increasing sequence $(\rho_k)_{k\in m}$, the corresponding sequence of variables $Z$ on line~3 produced by the algorithm, have the same distribution as in \Cref{lemma:inverse-variance-weighting-is-nice} for $\beta=0$.
    The $Y$ that is ultimately returned, however, is a post-processing of $H(\X) + Z$, which has the same distribution as \Cref{lemma:inverse-variance-weighting-is-nice} for $\beta=H(\X)$.
    Therefore \Cref{alg:gradual-release-histogram} is implementing lossless gradual release for the Gaussian mechanism applied to $H(\X)$, combined with a non-invertible post-processing.
    The lemma statement follows from \Cref{cor:noninv_postproc_meta}.
\end{proof}
Note that one \emph{only} has to store the noisy terms from the preceding round to implement \cref{alg:gradual-release-histogram}.
Nevertheless, it might be infeasible, say, when the domain is really large, to sample the noise for the zero coordinates.
\Cref{alg:efficient-gradual-release} uses the computational trick in \Cref{lemma:smart-histogram-sampling} to speed up this computation.
The algorithm is static, where the privacy budgets are fixed upfront but can easily be converted to an online algorithm.
Recall that $U(H(\X)) = \{i \in [d]: H(\X)_i \neq 0\}$ is the support of the histogram.
\begin{algorithm}[t]
\caption{\EGLSGH}
\label{alg:efficient-gradual-release}
\begin{algorithmic}[1]
\PARAMETERS $\ell_2$-sensitivity $\Delta_2$
\INPUTS Private histogram $H(\X)$,
privacy budgets $\rho_1 < \dots < \rho_m$,
thresholds $\tau_1,\dots,\tau_m$
\STATE Let $S^{(0)} = U(H(\X))$ {\bf \color{blueish} // Tracking counts that have already been released}
\STATE Also let $Z^{(0)} = \{0\}^d$ and $\rho_0 = 0$.
\STATE $\forall r\in [m]:$ let distribution $\mathcal{D}^{(r)} =\NN\left(0, \frac{1}{2}\Delta_2^2 (\rho_r - \rho_{r-1})\right)$
\FOR{each round $r \in[m]$} 
    \STATE Initialize $Y^{(r)} = \{0\}^d$
    \FOR{each tracked count in preceding round $j\in S^{(r-1)}$}
        \STATE Draw fresh noise $\tilde{Z}^{(r)}_j\sim\mathcal{D}^{(r)}$\label{eff:fresh}
        \STATE Update aggregate noise $Z^{(r)}_j = \frac{\rho_{r-1}}{\rho_{r}}Z^{(r-1)}_j + \frac{1}{\rho_r}\tilde{Z}^{(r)}_j$
        \IF{$H(\X)_j + Z^{(r)}_j > \tau_r$}
            \STATE $Y^{(r)}_j = H(\X)_j + Z^{(r)}_j$
        \ENDIF
    \ENDFOR
    \\ {\bf \color{blueish} // Simulating Noise for zero counts}
    \STATE Let $\tilde{Z}^{(k)}\sim\mathcal{D}^{(k)}$ for $k\in[r]$ be random variables.
    \STATE Compute $p^{(r)} = \Pr\left[\sum_{k=1}^r \tilde{Z}^{(k)} > \tau_r \rho_r\ |\ \{\forall \ell\in[r-1] : \sum_{k=1}^\ell \tilde{Z}^{(k)} \leq \rho_\ell\tau_\ell \} \right]$
    \STATE Draw $q\sim\operatorname{Binomial}\left(d - \lvert S^{(r-1)}\rvert, p^{(r)}\right)$.
    \STATE Select a subset $Q\subseteq [d]\setminus S^{(r-1)}$ uniformly at random of size $q$.
    \FOR{each index $j \in Q$}\label{eff:bin}
        \STATE Initialize $Z^{(r)}_j =0$
        \FOR{$k\in[r-1]$}
            \STATE Draw fresh noise $\tilde{Z}^{(k)}_j \sim \mathcal{D}^{(k)}$ conditioned on $\tilde{Z}^{(k)}_j \leq \rho_k\tau_k - Z^{(r)}_j$
            \STATE Update aggregate noise $Z^{(r)}_j = Z^{(r)}_j + \tilde{Z}^{(k)}_j$
        \ENDFOR
        \STATE Draw fresh noise $\tilde{Z}^{(k)}_j \sim \mathcal{D}^{(k)}$ conditioned on $\tilde{Z}^{(k)}_j > \rho_k\tau_k - Z^{(r)}_j$
        \STATE Update aggregate noise $Z^{(r)}_j = Z^{(r)}_j + \tilde{Z}^{(k)}_j$
        \STATE $Y^{(r)}_j = H(\X)_j + Z^{(r)}_j$ {\color{blueish}\bf //  Guaranteed to be above the threshold.}
    \ENDFOR
    \STATE Set $S^{(r)} = S^{(r-1)}\cup Q$
    \STATE\textbf{output} private histogram $Y^{(r)}$
\ENDFOR
\end{algorithmic}
\end{algorithm}

We proceed to give proofs for \Cref{lemma:efficient-histogram-id}~and~\ref{lemma:sampled_gaussians}.
\begin{proof}[Proof sketch for \Cref{lemma:efficient-histogram-id}.]
    The claim directly follows an inductive argument.
    For the base case, note that the first iteration of \Cref{alg:efficient-gradual-release} is running the same routine as described by \Cref{lemma:smart-histogram-sampling}, and so $\hat{Y}^{(1)}$ must be identically distributed to $Y^{(1)}$.
    For our inductive hypothesis, assume that the subsequences $(Y^{(1)}, \dots, Y^{(k)})$ and $(\hat{Y}^{(1)}, \dots, \hat{Y}^{(k)})$ are identically distributed.
    Note that for the $(k+1)$\textsuperscript{st} release, \Cref{alg:efficient-gradual-release} handles all the true nonzero counts and every zero count that has ever exceeded the threshold in a past round in the same way.
    These counts in $\hat{Y}^{(k+1)}$ and $Y^{(k+1)}$ clearly have the same distribution.

    Now, note that each of the remaining zero counts have up to and including the $k$\textsuperscript{th} round been reported as zero in each round, and so their probability of exceeding the threshold, $p^{(k+1)}$, should be equal across all of them.

    The sampling performed by \Cref{alg:efficient-gradual-release} is structured in the same manner as \Cref{lemma:smart-histogram-sampling}, but with sampling probability $p^{(k+1)}$, and the noise terms added for any zero count exceeding the threshold, are different.
    For the distributions to match, the probability of exceeding the threshold and the noise distribution for an element chosen to exceed the threshold are more complex.
    The probability of exceeding the threshold is conditioned on prefixes of Gaussians, which correctly simulates the probability of not exceeding the threshold at any prior round until first doing so in the $(k+1)$\textsuperscript{st} one.
    The noise added once selected to exceed the threshold is a sum of truncated Gaussians, which simulate the same event.
    As the principle is built on the same logic as \Cref{lemma:smart-histogram-sampling}, we have that $(Y^{(1)}, \dots, Y^{(k+1)})$ and $(\hat{Y}^{(1)}, \dots, \hat{Y}^{(k+1)})$ are identically distributed, and so the claim is true by induction.
\end{proof}
\begin{proof}[Proof of \Cref{lemma:sampled_gaussians}]
    Note that each of the $k$ non-zero true counts will, in each round, have fresh noise added on line~7.
    If a non-zero count is selected by the binomial sampling in the $k$\textsuperscript{th} round, the for-loop starting on line~17 will result in sampling $k$ noise terms, after which for future rounds it will get treated as a non-zero count.
    It follows that non-zero entries contribute $km$ samples, and zero counts exceeding the threshold contribute $cm$ samples.\end{proof}

\section{Definitions}\label{sec:preliminaries}

We begin with the most common version of differential privacy.
\begin{definition}[$(\epsilon, \delta)$-Differential Privacy~\cite{dwork2014algorithmic}]
    A randomized algorithm $\cM : \mathcal{X}\to\mathcal{Y}$ is ($\varepsilon, \delta)$-differentially private if for all
    $S\subseteq\mathsf{Range}(\cM)$ and all pairs of neighboring inputs $\X, \X' \in \cX$, it holds that
    \begin{equation*}
        \Pr[\cM(\X)\in S] \leq \exp(\epsilon)\Pr[\cM(\X')\in S] + \delta\,,
    \end{equation*}
    where $(\epsilon, 0)$-DP is referred to as $\varepsilon$-DP.
\end{definition}

Zero-Concentrated Differential Privacy (zCDP) is a notion of differential privacy that provides a simple but accurate analysis of privacy loss, particularly under composition.
\begin{definition}[\citet{bun_steinke_2016}, $\rho$-zCDP]
Let $\rho > 0$.
An algorithm ${\cM : \cX \rightarrow \cY}$ satisfies $\rho$-zCDP, 
if for all $\alpha > 1$ and all pairs of neighboring inputs $\X, \X' \in \cX$, it holds that 
\begin{equation*}
    \begin{array}{c}
        D_\alpha \left( 
            \cM \left( \X \right) || \cM \left( \X' \right) 
        \right)
        \le \rho \alpha, 
    \end{array}
\end{equation*}
where 
$
    D_\alpha \left( 
        \cM \left( \X \right) || \cM \left(\X' \right)\right)
$ 
denotes the $\alpha$-Rényi divergence between two output distributions of $\cM(\X)$ and $\cM(\X')$.
\end{definition}

\begin{lemma}[\citet{bun_steinke_2016}, Composition]\label{fact:composition-zdp}
    If $\cM_1(\X)$ and $\cM_2(\X)$ satisfy $\rho_1$-zCDP and $\rho_2$-zCDP, respectively,
    then $(\cM_1(\X), \cM_2(\X))$ satisfies $(\rho_1 + \rho_2)$-zCDP.
\end{lemma}

\begin{lemma}[\citet{bun_steinke_2016}, Gaussian Mechanism]
Let $f : \mathcal{X} \to \R^d$ be a query with $\ell_2$-sensitivity $\Delta_2$.
Consider the mechanism $\mathcal{G}_{f, \rho} : \mathcal{X} \to \R^d$ that, on private input $\X$, releases a sample from $f(\X) + \NN\left(0, \frac{\Delta_2^2}{2\rho}\right)^d$.
Then $\mathcal{G}_{f, \rho}$ satisfies $\rho$-zCDP.
\end{lemma}

One way to uniquely describe probability distributions is via their \emph{Characteristic Functions}. 
\begin{definition}[Characteristic Function]\label{def:CF}
The characteristic function of a random variable $X$ is defined as $\varphi_X(t) = \EX[e^{itX}]$.
\end{definition}

For proving \cref{lem:lap-conv,lem:exp-conv}, we will use a nice property of CFs for the convolution of two random variables:
\begin{lemma}[Convolution of Characteristic Functions]
Let $X,Y$ be two independent RVs with CFs $\varphi_X(t)$ and $\varphi_Y(t)$ respectively, then $\varphi_{X+Y}(t) = \varphi_X(t) \cdot \varphi_Y(t)$.
\end{lemma}
\begin{proof}
Furthermore, by linearity of expectation, we have for the sum of $X+Y$:
\begin{equation*}
    \varphi_{X+Y}(t) = \EX[e^{it(X+Y)}] = \EX[e^{itX}] + \EX[e^{itY}] =\varphi_X(t)\cdot \varphi_X(t)\,.\qedhere
\end{equation*}
\end{proof}

\section{The Poisson Mechanism}\label{sec:poisson}

We are not aware of any explicit statements in the literature on the privacy guarantees obtained by adding Poisson distributed noise to a $d$-dimensional vector of integers.
However, since the Poisson distribution is the limiting distribution of binomial distributions with the same mean $\lambda = N p$, where $N$ is the number of trials, such bounds can be derived from existing bounds on the binomial mechanism.
For the sake of completeness, we include such statements based on the following theorem from~\cite{agarwal2018cpsgd}:

\begin{theorem}[\citet{agarwal2018cpsgd}]
For any \(\delta\), parameters \(N, p\) and sensitivity bounds \(\Delta_1, \Delta_2, \Delta_\infty\) such that
\[
Np(1 - p) \geq \max \left( 23 \log \left( \frac{10d}{\delta} \right), \, 2\Delta_\infty \right),
\]
the $d$-dimensional Binomial mechanism is \((\varepsilon, \delta)\)-differentially private for
\[
\varepsilon =
\frac{\Delta_2 \sqrt{2 \log \frac{1.25}{\delta}}}{\sqrt{N p (1 - p)}}
+ \frac{\Delta_2 c_p \sqrt{\log \frac{10}{\delta}} + \Delta_1 b_p}{N p (1 - p) (1 - \delta/10)}
+ \frac{\frac{2}{3} \Delta_\infty \log \frac{1.25}{\delta} + \Delta_\infty d_p \log \frac{20d}{\delta} \log \frac{10}{\delta}}{N p (1 - p)}.
\]
where
\[
d_p \triangleq \frac{4}{3} \cdot \left( p^2 + (1 - p)^2 \right), \quad
b_p \triangleq \frac{2(p^2 + (1 - p)^2)}{3} + (1 - 2p), \quad
c_p \triangleq \sqrt{2} \left( 3p^3 + 3(1 - p)^3 + 2p^2 + 2(1 - p)^2 \right).
\]
\end{theorem}

Setting $p = \lambda/N$ and considering the limiting bound when $N\rightarrow\infty$ we get:

\begin{theorem}[Privacy guarantees of the Poisson Mechanism]
The $d$-dimensional Poisson mechanism with parameter
\( \lambda > \max( 23 \log(10d/\delta),\, 2\Delta_\infty) \),
is \((\varepsilon, \delta)\)-differentially private with
\[
\varepsilon =
\frac{\Delta_2 \sqrt{2 \log \frac{1.25}{\delta}}}{\sqrt{\lambda}}
+ \frac{5\sqrt{2}\,\Delta_2 \sqrt{\log \frac{10}{\delta}} + \frac{5}{3}\Delta_1}{\lambda (1-\delta/10)}
+ \frac{\frac{2}{3}\Delta_\infty \log \frac{1.25}{\delta} + \frac{4}{3}\Delta_\infty \log \frac{20d}{\delta}\,\log \frac{10}{\delta}}{\lambda} \,.
\]
\end{theorem}

A simpler expression can be derived for unit sensitivities by relaxing the constants and assuming that \(\delta\) is not too large:

\begin{corollary}[Simplified upper bound with unit sensitivities]
    Assume that \(\Delta_1=\Delta_2=\Delta_\infty=1\). Then for \(\delta < 1/100\), the $d$-dimensional Poisson mechanism with parameter \(\lambda > 23 \log(10d/\delta)\) is \((\varepsilon, \delta)\)-differentially private for
    \[
    \varepsilon = \frac{\sqrt{2\log\frac{1.25}{\delta}}}{\sqrt{\lambda}} 
    + \frac{2\,\log\frac{20d}{\delta}\,\log\frac{10}{\delta}}{\lambda}\,.
    \]
    \end{corollary}

We will need the following lemma that determines the sampling step of private lossless multiple release for the Poisson mechanism:

\begin{lemma}\label{lemma:conditional-poisson}
    Let $X_1 \sim \operatorname{Poi}(\lambda_1)$ and $X_2 \sim \operatorname{Poi}(\lambda_2)$ be independent Poisson random variables. 
    Then, for any nonnegative integer $k$, the conditional distribution of $X_1$ given $X_1+X_2 = k$ is
    \begin{align*}
        X_1\mid (X_1+X_2=k) \sim \operatorname{Binomial}\left(k, \frac{\lambda_1}{\lambda_1+\lambda_2}\right)\,.
    \end{align*}
    \end{lemma}

    \begin{proof}
    Since \( X_1 \) and \( X_2 \) are independent, their joint probability mass function is for all $x = 0,1, \cdots, k$
    \begin{align*}
    P[X_1=x,\,X_2=k-x] = e^{-(\lambda_1+\lambda_2)}\frac{\lambda_1^x}{x!}\frac{\lambda_2^{\,k-x}}{(k-x)!}\,.
    \end{align*}
    Moreover, the sum \( X_1+X_2 \) is Poisson with parameter \( \lambda_1+\lambda_2 \), so that
    \[
    \Pr[X_1+X_2=k] = e^{-(\lambda_1+\lambda_2)}\frac{(\lambda_1+\lambda_2)^k}{k!}\,.
    \]
    Thus, by the definition of conditional probability,
    \begin{align*}
    \Pr[X_1=x \mid X_1+X_2=k] &= \frac{\Pr[X_1=x,\,X_2=k-x]}{\Pr[X_1+X_2=k]} \\
    &= \dfrac{e^{-(\lambda_1+\lambda_2)}\dfrac{\lambda_1^x}{x!}\dfrac{\lambda_2^{\,k-x}}{(k-x)!}}{e^{-(\lambda_1+\lambda_2)}\dfrac{(\lambda_1+\lambda_2)^k}{k!}} \\
    &= \binom{k}{x}\left(\dfrac{\lambda_1}{\lambda_1+\lambda_2}\right)^x \left(\dfrac{\lambda_2}{\lambda_1+\lambda_2}\right)^{k-x}.
    \end{align*}
    This is precisely the probability mass function of a Binomial random variable with parameters \( k \) and \( \frac{\lambda_1}{\lambda_1+\lambda_2} \). 
    \end{proof}

 \section{The Laplace Mechanism}\label{sec:laplace}

\citet{koufogiannis_2016} showed how to do lossless \emph{gradual} releases for the Laplace mechanism and supports either tightening the privacy guarantees or loosening them. 
We will now strengthen this result by exactly showing how to do them in arbitrary order, similar to what was done in \cref{sec:lossless-multiple-release} for the Gaussian mechanism.
We will first show that the Laplace distribution satisfies \cref{def:decomposable}.
This already implies the existence of an algorithm supporting gradual lossless release via \cref{lemma:additive_noise_means_lossless}.
After, we will derive how to sample a new release with scale parameter $b$ given two distinct releases with scaling $b_2 < b$ and $b < b_1$.

\begin{definition}[Laplace distribution]\label{def:lap}
The \emph{zero-centered Laplace distribution} $\lap(0, b)$ with scale parameter $b > 0$ has probability density function $f_b(x) = \frac{1}{2b} \exp( -|x|/b )$ for all $x \in \mathbb{R}$.
\end{definition}

\begin{lemma}[{\citet{kotzLaplaceDistributionGeneralizations2001}} Characteristic function of Laplace]\label{lem:CFLap}
Let $X$ be Laplace random variable with probability density function as in \cref{def:lap}, then for all $t\in \R$, the characteristic function of $X$ is
\[ 
\varphi_X(t) = \EX[e^{itX}] = \int\limits_{-\infty}^{\infty}e^{i t x}\frac{1}{2b}e^{-|x|/b} dx = \frac{1}{1+b^2t^2}\,.
\]
\end{lemma}
\begin{proof}
    By a simple integration:
    \begin{align*}
        \EX[e^{itX}] &= \frac{1}{2b} \int\limits_{-\infty}^{\infty}e^{itx -|x|/b} dx
        = \frac{1}{2b}\left(\int\limits_{-\infty}^{0}e^{(1/b + ti)x} dx
        + \int\limits_{0}^\infty e^{(-1/b + ti)x}dx \right)\\
        &= \dfrac{1}{2b}\left(\dfrac{1}{1/b + ti}+ \dfrac{1}{1/b - ti}\right) = \dfrac{1}{1+b^2t^2}\,.\qedhere
    \end{align*}
\end{proof}
We will now show that the zero-centered Laplace distribution with scale parameter $b$ satisfies convolution preorder (\cref{def:decomposable}).
Note that a larger value of $b$ corresponds to a more private release by definition.
Building on this, we will condition on the two closest releases to create a new one in the middle, as done in \cref{lemma:gaussian_seq_ooo} for the Gaussian.
The following fact was already shown in~\cite{koufogiannis_2016}, but we give a proof here for completeness.
\begin{claim}[Convolution preorder: Laplace]\label{lem:lap-cpo}
    Fix $b_2 < b_1 \in \R^+$ let $X \sim \lap(0, b_2)$ and draw 
    \begin{align*}
        W = \begin{cases}
        0 & \text{with probability } b_2^2/b_1^2\\
        \lap(0, b_1) & \text{otherwise}
    \end{cases},  \quad \text{then~} X + W \sim \lap(0, b_1)\,.
    \end{align*}
\end{claim}
\begin{proof}
We know that the characteristic function of $X$ is $\varphi_{X}(t) = \frac{1}{1+b_2^2t^2}$ and for the convolution $\varphi_{X+W} = \frac{1}{1+b_1^2t^2}$.
Because of independence, the convolution is defined for all $t$ as:
\begin{align*}
\varphi_{X}(t)\varphi_{W}(t) &= \varphi_{X+W}(t)\\
\Leftrightarrow \varphi_{W}(t) &= \frac{1+b_2^2t^2}{1+b_1^2t^2} = \frac{b_1^2 + b_1^2b_2^2t^2}{b_1^2(1+b_1^2t^2)}
= \frac{b_2^2(1+b_1^2t^2) + b_1^2-b_2^2}{b_1^2(1+b_1^2t^2)}
= \frac{b_2^2}{b_1^2}+ \left(1 - \frac{b_2^2}{b_1^2}\right) \cdot \frac{1}{1+b_1^2t^2}\,.
\end{align*}

The last expression encodes the convex combination of the claimed mixture distribution because $\frac{1}{1+b_1^2t^2}$ is again the characteristic function of a zero-centered Laplace distribution with scaling parameter $b_1$.
\end{proof}

We next prove a simple result about the convolution of two Laplace distributions (compare also eq., 2.3.23 of \citet{kotzLaplaceDistributionGeneralizations2001}).
\begin{lemma}[Convolution]\label{lem:lap-conv}
    For two fixed scaling parameters $b_1 \neq b_2 \in \R^+$, let $X_1 \sim \lap(0, b_1)$ and $X_2 \sim \lap(0, b_2)$. Then the density of $X_1 + X_2$ is given by
    \begin{align*}
        (f_{b_1} \ast f_{b_2})(t)
        = \dfrac{1}{2(b_1^2 - b_2^2)}\left( b_1 e^{-|t|/b_1} - b_2 e^{-|t|/b_2}\right)\,.
    \end{align*}
\end{lemma}
\begin{proof}
Assume $t\geq 0$ and note that the other case follows by symmetry.
We compute the density of the convolution by a straightforward integration:
\begin{align*}
    (f_{b_1} \ast f_{b_2})(t)  &= \int_{-\infty}^{\infty}f_{b_1}(x)f_{b_2}(t-x)dx = \dfrac{1}{4b_1b_2}\int_{-\infty}^{\infty}\exp\left(-\frac{|x|}{b_1} - \frac{|t-x|}{b_2}\right)dx\\
    &= \dfrac{1}{4b_1b_2}\cdot \left(\int_{-\infty}^{0} e^{\frac{x}{b_1} - \frac{t-x}{b_2}} dx
    + \int_{0}^{t} e^{-\frac{x}{b_1} - \frac{t-x}{b_2}} dx
    + \int_{t}^{\infty}e^{-\frac{x}{b_1} - \frac{x-t}{b_2}} dx\right)\\
    &=\dfrac{1}{4b_1b_2}\cdot \bigg(\left[\dfrac{\exp\left(x/b_1 - (t-x)/b_2\right)}{b_1^{-1} +b_2^{-1}}\right]_{-\infty}^{0}\\
    &\qquad+ \left[\dfrac{\exp(-x/b_1 - (t-x)/b_2)}{b_2^{-1} - b_1^{-1}}\right]_{0}^{t}
    + \left[\dfrac{\exp(-x/b_1 - (x-t)/b_2)}{-b_2^{-1} - b_1^{-1}}\right]_{t}^{\infty}\bigg)\\
    &= \dfrac{1}{4} \cdot \left(\dfrac{\exp(-t/b_2)}{b_1 + b_2}
    + \dfrac{\exp(-t/b_1) - \exp(-t/b_2)}{b_1 - b_2}
    + \dfrac{\exp(-t/b_1)}{b_1 + b_2}\right)\\
    &= \frac{1}{2(b_1^2 - b_2^2)}\left( b_1 e^{-t/b_1} - b_2 e^{-t/b_2}\right)\,.\qedhere
\end{align*}
\end{proof}

Now, we are ready to show that the Laplace mechanism can be implemented with multiple releases.
\begin{lemma}[Multiple release Laplace]\label{lem:lap-mult}
For fixed $0 < b_2 < b < b_1$, let $\mu_1 = b^2/b_1^2$ and $\mu_2 = b_2^2/b^2$ and $D_1 \sim \ber(\mu_1)$ and $D_2 \sim \ber(\mu_2)$.
Furthermore, let
\begin{align*}
X_1 =
\begin{cases}0 & \text{if} \quad D_1 = 1 \\ 
\lap(0, b) & \text{otherwise }\end{cases}
\quad \text{and} \quad  
X_2 = 
\begin{cases}0 & \text{if} \quad D_2 = 1 \\ \lap(0, b_2) & \text{otherwise } \end{cases}.
\end{align*}
Then we have that $\Pr[X_1 = 0 \mid X_1 + X_2 = 0] = 1$, and
for every real number $k\neq 0$ the distribution of $X_1$ conditioned on $X_1 + X_2 = k$ is:
\begin{align}\label{alg:sample}
X_1\mid{(X_1 + X_2 = k)} \sim \begin{cases}
    0 & \text{with probability } \mu_1\cdot(1-\mu_2)\cdot \dfrac{\exp(-|k|/b_2)}{2b_2\cdot f_{X_1+X_2}(k)} \\[2ex]
    k & \text{with probability } (1-\mu_1)\cdot \mu_2\cdot\dfrac{\exp(-|k|/b)}{2b\cdot f_{X_1+X_2}(k)}\\[2ex]
    H(b, b_2, k) & \text{with probability } (1-\mu_1)\cdot (1- \mu_2)\cdot \dfrac{(f_b \ast f_{b_2})(k)}{f_{X_1+X_2}(k)}\\
    \end{cases} 
\end{align}    
where $0$ and $k$ denote the constant distributions, $H(b, b_2, k)$ is the probability distribution with probability density function $h(x) = \dfrac{f_b(x)f_{b_2}(k-x)}{(f_b \ast f_{b_2})(k)}$, 
\begin{align*}
f_{X_1 + X_2}(k) &= \frac{\mu_1(1-\mu_2}{2b_2} e^{-|k|/b_2} + \frac{(1-\mu_1)\mu_2}{2b} e^{-|k|/b}
  \frac{(1-\mu_1)(1-\mu_2)}{2(b^2-b_2^2)} \left(be^{-|k|/b}- b_2 e^{-|k|/b_2}\right) + \mu_1\mu_2\delta_0(x) ,\text{ and}\\
(f_b \ast f_{b_2})(k) &= \frac{1}{2(b_1^2 - b_2^2)}\left( b_1 e^{-t/b_1} - b_2 e^{-t/b_2}\right)\,,\end{align*}
where $\delta_0$ is the Dirac delta function.
\end{lemma}

\begin{proof}
First we consider $\Pr[X_1 = 0| X_1 + X_2 = 0]$, arguing that
\begin{align*}
    \Pr[X_1 = 0| X_1 + X_2 = 0]
    = \frac{\Pr[X_1 = 0]\Pr[X_2=0]}{\Pr[X_1 + X_2 = 0]} = \frac{\mu_1\mu_2}{\mu_1\mu_2 + 0}= 1 \,.
\end{align*}
To see why the first equality holds split $\Pr[X_1 + X_2 = 0]$ into each of the four combinations of discrete/continuous for $X_1, X_2$.
The only non-zero contribution to the probability mass comes from the discrete/discrete case, as the remaining cases contribute mass proportional to the probability that a continuous distribution assumes an exact value, which is zero.


Next we turn to the distribution of $X_1$ conditioned on $X_1 + X_2 = k$ where $k\neq 0$.
Denote by $f_b$ the probability density function of $\lap(0, b)$.
Note that the mixture densities become
\begin{align*}
    f_{X_1}(x) &= \mu_1 \delta_0(x) + (1-\mu_1) f_b(x)\,,\\
    f_{X_2}(x) &= \mu_2 \delta_0(x) + (1-\mu_2)f_{b_2}(x)\,.
\end{align*}
Before analyzing the different cases separately, we compute the convolution $X_1 + X_2$.

\allbold{Convolution $f_{X_1 + X_2}$.}

Note that have to take care of a subtle technicality: The case that both $X_1$ and $X_2$ are zero from the discrete part can only happen when we condition on $X_1 + X_2 = 0$.
We can now give the density of the convolution $X_1 + X_2$ at any real point $x$:
\begin{align*}
f_{X_1 + X_2}(x) &=  \sum_{(d_1,d_2) \in \{0,1\}^2} f_{X_1+X_2|D_1 = d_1, D_2 = d_2}(x) \cdot \Pr[D_1 = d_1 \wedge D_2 = d_2]\\
&=\mu_1 (1-\mu_2) \cdot  f_{b_2}(x) + (1-\mu_1) \mu_2 \cdot f_{b}(x)
+ (1-\mu_1)(1-\mu_2) \cdot (f_{b} \ast f_{b_2})(x)
+ \mu_1\mu_2\delta_0(x)\\
&=\dfrac{\mu_1(1-\mu_2)}{2b_2}e^{-|x|/b_2}
+ \frac{(1-\mu_1)\mu_2}{2b}e^{-|x|/b}
+ (1-\mu_1)(1-\mu_2) \frac{1}{2(b^2-b_2^2)}\left(b e^{-|x|/b}
- b_2 e^{-|x|/b_2}\right)\\
&\qquad + \mu_1\mu_2\delta_0(x)\,,
\end{align*}
where the third term follows from \Cref{lem:lap-conv}. 
Note that the last term only contributes when $x=0$.

We can now show how the sampling procedure in the claim is justified. 
We first assume $k \neq 0$ and analyze three possible cases how $X_1 + X_2$ is built up: 
Either both of them are drawn from the (continuous) Laplace distribution or exactly one.
(The case where both are from their respective discrete parts can only happen if $k = 0$, analyzed above.)
\begin{caseof}
\case{$X_1 = 0$ and $X_2 = k$.}
$X_2 = k$ is necessarily from its continuous part.
By the definition of conditional probability, we have for $k \neq 0$:
\begin{align*}
    \Pr[X_1 = 0 | X_1 + X_2 = k, k \neq 0] 
    &= \frac{\Pr[X_1 = 0 \wedge X_1+X_2=k]}{\Pr[X_1 + X_2 = k]} 
    = \frac{\Pr[X_1 = 0]\Pr[X_2=k]}{\Pr[X_1 + X_2 = k]}\\
    &= \mu_1\frac{f_{X_2}(k) }{f_{X_1 + X_2}(k)}
    = \frac{\mu_1(1-\mu_2)}{2b_2 f_{X_1+X_2}(k)} \cdot e^{-|k| / b_2} \coloneqq p_1\,.
\end{align*}
For the third equality, we simply used definition of a probability density function via its limit:
\[
\lim_{\Delta\to 0^+} \frac{\Pr\left[X_2\in[k-\Delta, k+\Delta]\right]}{\Pr\left[X_1+X_2\in[k-\Delta, k+\Delta]\right]}
= \frac{f_{X_2}(k)}{f_{X_1+X_2}(k)}\,.
\]

\case{$X_1 = k$ and $X_2 = 0$}
Now assume the flipped case.
By a similar argument:
\[
\Pr[X_1 = k | X_1 + X_2 = k] = \frac{\Pr[X_1 = k, X_1 + X_2 = k]}{\Pr[X_1 + X_2 = k]}  = \frac{\Pr[X_1 = k]\Pr[X_2 = 0]}{\Pr[X_1 + X_2 = k]}
=\frac{(1-\mu_1)\mu_2}{2bf_{X_1+X_2}(k)} \cdot e^{-|k|/b} \coloneqq p_2 \,.
\]


\case{$X_1 \neq 0, X_2 \neq 0, X_1 + X_2 = k$} 
In the remaining case, both $X_1$ and $X_2$ are independently sampled from continuous Laplace distributions with probability density functions $f_b(x)$ and $f_{b_2}(x)$.
Therefore, with the remaining probability $1-(p_1 + p_2)$, we know that $X_1$ is sampled according to the following conditional probability density function:
\[
f_{X_1}(x)\vert_{X_1 + X_2 = k} =
\frac{f_{X_1, X_1+X_2}(x,k)}{(f_b \ast f_{b_2})(k)}
=\frac{f_b(x)f_{b_2}(k-x)}{(f_{b}\ast f_{b_2})(k)}\,,
\]
where the last line follows from the trivial identity $X_1 + X_2 = k \Leftrightarrow X_2 = k - X_1$.
This is a valid probability density function because $f$ is trivially non-negative due to its parts being non-negative and furthermore
\begin{align*}
\int_{-\infty}^{\infty}\frac{f_b(x)f_{b_2}(x-k)}{(f_{b} \ast f_{b_2})(k)} dx
= \frac{1}{(f_b \ast f_{b_2})(k)}\int_{-\infty}^{\infty}f_b(x)f_{b_2}(k-x) dx
= \frac{(f_b \ast f_{b_2})(k)}{(f_{b}\ast f_{b_2})(k)} = 1\,.
\end{align*}

\end{caseof}
What is left is to verify that the probabilities in \cref{alg:sample} indeed add up to one for $k\ne 0$:
\begin{align*}
      &\frac{(1-\mu_1)(1- \mu_2) (f_b \ast f_{b_2})(k)}{f_{X_1+X_2}(k)} + \frac{  
     (1-\mu_1)\mu_2\exp(-|k|/b)}{2b f_{X_1+X_2}(k)}  +\frac{\mu_1(1-\mu_2) \exp(-|k|/b_2)}{2b_2 f_{X_1+X_2}(k)} \\
    &  = \frac{1}{f_{X_1+X_2}(k)}
    \underbrace{\left((1-\mu_1) (1- \mu_2) (f_b \ast f_{b_2})(k) + \frac{(1-\mu_1)\mu_2 \exp(-|k|/b)}{2b} + \frac{\mu_1(1-\mu_2) \exp(-|k|/b_2)}{2b_2}e^{-\lambda_2 |k|} \right)}_{f_{X_1 + X_2}(k) \ \text{for} \ k \neq 0} = 1
    \end{align*}
\end{proof}


\subsection{Showing Convolution Preorder for Exponential Noise}\label{sec:exponential}

The exponential distribution is closely related to the Laplace distribution, but gives poor differential privacy guarantees.
Nevertheless, it still serves as a building block for some private mechanisms, e.g., Report-Noisy-Max~\cite{Ding2021}.
We show next that it also satisfies a convolution preorder.


\begin{definition}[Exponential distribution]\label{def:Exp}
The \emph{exponential distribution} $\operatorname{Exp}(\lambda)$ with rate parameter $\lambda > 0$ has probability density function $f_\lambda(x) = \lambda \exp( -\lambda x)$ for all $x \in \mathbb{R}_+$.
Furthermore, its characteristic function is given by $\varphi_X(t) = \EX[e^{itX}] = \frac{\lambda}{\lambda- it}$
\end{definition}

\begin{claim}[Convolution preorder: Exponential distribution]\label{lem:exp-conv}
    Fix $\lambda_1 < \lambda_2  \in \R_+$, let $X \sim \operatorname{Exp}(\lambda_2)$ and draw 
    \begin{align*}
    W = \begin{cases}
        0 & \text{with probability } \lambda_1/\lambda_2 \\
        \operatorname{Exp}( \lambda_1) & \text{otherwise} 
    \end{cases},  \quad \text{then~} X + W \sim \operatorname{Exp}(\lambda_1)\,.
    \end{align*}
\end{claim}
\begin{proof}
    Using the same trick as in the proof of \Cref{lem:lap-cpo}, we have that
\begin{align*}
    \varphi_{W}(t) &= \frac{\varphi_{X + W}(t)}{\varphi_{X}(t)}
    = \frac{\lambda_1}{\lambda_2}\cdot\frac{\lambda_2 - it}{\lambda_1 - it}
    = \frac{\lambda_1}{\lambda_2}\left( 1 + \frac{\lambda_2 - \lambda_1}{\lambda_1 - it}\right)
    = \frac{\lambda_1}{\lambda_2} + \left( 1 - \frac{\lambda_1}{\lambda_2} \right) \varphi_{X+W}(t)
\end{align*}
where the final expression is the characteristic function of the claimed mixture distribution.\end{proof} 

