\subsection{Triangulations}
We let $\bar \Gamma_h$ be a polyhedral surface approximation of $\gamma$
with simplicial faces such that $d$ is well defined on $\bar \Gamma_h$ with
$d(x) = \calO(h^2)$ for $x\in \Gamma_h$.  Let $\bar \calT_h$
 be the set of faces, and denote by $\bar \bnu_h$ the outward unit normal
of $\bar \Gamma_h$. The tangential projection operator with respect to $\bar \Gamma$ is given by
$\bar \bPi_h = {\bf I}-\bar \bnu_h\otimes \bar \bnu_h$.

Let $\hat K\subset \bbR^2$ be the reference triangle
with vertices $(1,0),(0,1),(0,0)$, and let $F_{\bar K}:\hat K\to \bar K$
be an affine diffeomorphism. We assume that $\bar \calT_h$ is shape-regular
in the sense that the following estimates are satisfied
\begin{subequations}
\label{eqn:FbarEst}
\begin{equation}
\|\nab F_{\bar K}\|_{L_\infty(\hat K)}\lesssim h_{\bar K},\qquad \det(\nab F_{\bar K}^\intercal \nab F_{\bar K}) \approx h_{\bar K}^4,
\end{equation}
where $h_{\bar K} = {\rm diam}(\bar K)$, and $\nab F_{\bar K}\in \bbR^{3\times 2}$ is the Jacobian of $F_{\bar K}$.
Here, we use
$a \lesssim b$ (resp., $a\gtrsim b$) to mean  there exists a generic constant $C>0$ independent
of the discretization parameter $h$ such that $a\le C b$ (resp., $a\ge C b$). 
The statement $a\approx b$ means $a\lesssim b$ and $a\gtrsim b$.

Since $(\nab F_{\bar K}^\intercal \nab F_{\bar K})^{-1} 
= {\rm det}(\nab F_{\bar K}^\intercal \nab F_{\bar K})^{-1}{\rm adj}(\nab F_{\bar K}^\intercal \nab F_{\bar K})$,
where ${\rm adj}(\cdot)$ denotes the matrix adjugate,
the above estimates yield
\begin{equation}
 \|(\nab F_{\bar K}^\intercal \nab F_{\bar K})^{-1}\|_{L_\infty(\hat K)}\lesssim h^{-2}_{\bar K}.
\end{equation}
\end{subequations}

We now define a family of high-order discrete surfaces $\Gamma_{h,k}$, $k \in \bbN$.  For $k=1$ we take 
$\Gamma_{h,1}=\bar \Gamma_h$ to be the affine surface approximation defined previously.  We assume
there exists  a continuous map $\bPsi: \bar \Gamma_h \rightarrow \mathbb{R}^3$ such that 
$\bPsi_{\bar K}:=\bPsi |_{\bar K} \in [\mathbb{P}_k(\bar K)]^3$, $\bar K \in \calT_h$ and satisfies
%
\begin{equation}\label{eqn:HighOrderGeometry}
|\bPsi(x)-\bp(x)|\lesssim h^{k+1},\quad \text{and}\quad |\nab \bPsi(x)-\nab \bp(x)|\lesssim h^k.
\end{equation}  
%
Let $\Gamma_{h,k}=\bPsi(\bar \Gamma_h)$ be the high-order surface approximation to $\gamma$,
and set $\calT_{h,k}= \{\bPsi(\bar{K}): \bar{K} \in \bar{\calT}_h\}$ to be the associated
triangulation of $\Gamma_{h,k}$.  The set of edges of $\bar \calT_h$ is denoted by $\bar \calE_h$,
and the set of edges of $\calT_{h,k}$ is $\calE_{h,k} = \{\Psi(\bar e):\ \bar e\in \bar \calE_h\}$.
We denote by $\bnu_h$ the outward unit normal
of $\Gamma_{h,k}$, and use the notation $\bnu_K = \bnu_h|_K$ for $K\in \calT_{h,k}$.
%
It follows from \eqref{eqn:HighOrderGeometry} that
%In addition to \eqref{eqn:HighOrderGeometry}, we assume
\begin{equation}\label{eqn:normalApprox}
|\bnu- \bnu_h|\lesssim h^k.
\end{equation}
Similar to above, we set the tangential projection operator
with respect to $\Gamma_{h,k}$ as $\bPi_h = {\bf I}-\bnu_h\otimes \bnu_h$.
For a point on the discrete surface $a\in \Gamma_{h,k}$, we denote
by $\calT_a\subset \calT_{h,k}$ the set of faces containing $a$, i.e.,
$\calT_a = \{K\in \calT_{h,k}:\ a\in {\rm cl}(K)\}$.  We further define
\[
\calT_K = \{K'\in \calT_{h,k}:\ {\rm cl}(K')\cap {\rm cl}(K)\neq \emptyset\},\qquad \omega_K = \bigcup_{K\in \calT_K} K.
\]
Set $h_K = h_{\bar K}$, where $K = \bPsi(\bar K)$, and set $h = \max_{K\in \calT_{h,k}} h_K$.  We assume $\bar \calT_h$ is quasi-uniform in the sense that $h_K = h_{\bar K}\approx h$
for all $\bar {K}\in \bar \calT_h$.


The mapping $\bPsi$ may be viewed as an elementwise degree-$k$ polynomial mapping over $\bar \Gamma_h$, but concretely it is realized as a polynomial 
mapping from the reference element $\hat{K} \subset \mathbb{R}^2$.  In particular, we have
%given $\bar{K} \in \bar{\calT}_h$, let $F_{\bar K}: \hat{K} \rightarrow \bar{K}$ be the standard affine reference map.  Then we have
\[ 
\bPsi_{\bar{K}}= \ba_K \circ F_{\bar K}^{-1},
\]
where $\ba_K: \hat{K} \rightarrow K$ is a tri-degree $k$ diffeomorphism with $K = \bPsi(\bar K)\in \calT_{h,k}$.
We assume this polynomial mapping satisfies the following estimates.
\begin{equation}\label{eqn:akGood}
|\ba_K|_{W^{m}_\infty(\hat K)}\lesssim h^m,\qquad
{|\ba_K^{-1}|_{W^m_\infty( K)}\lesssim h^{-1}}\text{ ($1\le m\le (k+1))$},\quad
%
\det(\nab \ba_K^\intercal \nab \ba_K) \approx h^4,
\end{equation}
%
and note  these
 estimates imply  $L_\infty$ Sobolev norms of $\bPsi$ are bounded:
\begin{align}\label{eqn:bPsiHSBound}
|\bPsi|_{W^{m}_\infty(\bar K)} \lesssim |F_{\bar K}^{-1}|_{W^1_\infty(\bar K)}^{m} |\ba_K|_{W^{m}_\infty(\hat K)}\lesssim 1
\qquad \forall \bar K\in \bar \calT_h,\ \forall m\in \bbN.
\end{align}



We further assume that $F_{\bar K}(\hat a) = \ba_K(\hat a)$ for all vertices $\hat a$ of $\hat K$, i.e.,
$F_{\bar K}$ is the linear interpolant of $\ba_K$. It then follows
from the Bramble-Hilbert lemma and \eqref{eqn:akGood} that
\begin{equation}\label{eqn:baPert}
\|\ba_K - F_{\bar K}\|_{W^m_\infty(\hat K)}\lesssim h^2\quad \forall m\in \bbN_0:=\bbN\cup \{0\}.
\end{equation}

