\begin{lemma}
For an edge $e\in \calE_{h,k}$ (resp., $\bar e\in \bar \calE_h$), 
let $\bt_e$ (resp., $\bt_{\bar e}$) denote a unit tangent to $e$.
Then there holds for $h$ sufficiently small
\begin{equation}\label{eqn:Ptang}
\begin{split}
&|\nab \bp \bt_e|\gtrsim 1\text{ on every curved edge $e\in \calE_{h,k}$, and }\\
&|\nab \bPsi \bt_{\bar e}|\gtrsim 1\text{ on every affine edge $\bar e \in \bar \calE_h$.}
\end{split}
\end{equation}
\end{lemma}
\begin{proof}
Fix $e\in \calE_{h,k}$, and 
let $\bp(e)$ be the projected edge on $\gamma$
with unit tangent vector $\bt_{\bp(e)}$. We extend $\bt_{\bp(e)}$
to a neighborhood of $\gamma$ in the normal direction, 
and note that $|\bt_{\bp(e)}-\bt_e|\lesssim h^k$ on $e$.
Since $\nab \bp \bt_{\bp(e)} = ({\bf P}-d{\bf H})\bt_{\bp(e)} = \bt_{\bp(e)} +\calO(h^{k+1}),$
we have
\[
|\nab \bp \bt_e| \ge |\nab \bp \bt_{\bp(e)}|-|\nab \bp| |\bt_{\bp(e)} - \bt_e| \ge 1 - C h^k \gtrsim 1
\]
for $h$ sufficiently small.

Likewise, for a fixed $\bar e\in \bar \calE_h$, let $\bp(\bar e)$ be the projected edge
on $\gamma$ with unit tangent $\bt_{\bp(\bar e)}$. Then by \eqref{eqn:HighOrderGeometry} and $|\bt_{\bar e}-\bt_{\bp(\bar e)}|\lesssim h$, we have
\[
|\nab \bPsi \bt_{\bar e}| 
\ge |\nab \bp \bt_{\bp(\bar e)}| - |\nab \bp| |\bt_{\bp(\bar e)}-\bt_{\bar e}| - |\nab \bPsi-\nab \bp| |\bt_{\bar e}| \ge 1-C h \gtrsim 1.
\]
\end{proof}


