\subsection{Extensions and Lifts}

For a (scalar or vector-valued)  function $w$ defined on the exact surface $\gamma$,
its extension $w^e$ is given by $w^e(x) = w^e(\bp(x))$ for $x\in U_\delta$.
On the other hand, for a function $w$ defined on either $\bar \Gamma_h$
or $\Gamma_{h,k}$, we let $\tilde w$ satisfy $\tilde w(x) = w(\bq(x))$ for all $x\in \gamma$,
where $\bq$ satisfies $\bp(\bq(x)) = x$. We then define the lift $w^\ell(x) = \tilde w( \bp(x))$ 
for $x\in U_\delta$.

Setting $\mu_h:\Gamma_{h,k}\to \bbR$ and $\bar \mu_h:\bar \Gamma_h\to \bbR$ as
\[
\mu_h  = \bnu\cdot \bnu_h(1-d \kappa_1)(1-d\kappa_2),\qquad \bar \mu_h  = \bnu\cdot \bar \bnu_h(1-d \kappa_1)(1-d\kappa_2),
\]
we have \cite{Demlow09}
\[
\int_{\Gamma_{h,k}} w^e \mu_h =  \int_{\bar \Gamma_h} w^e \bar \mu_h = \int_{\gamma} w,\qquad \forall w\in L_1(\gamma).
\]
We also have the following change of variables
result with respect to integration across edges. 
Its proof is given in the appendix.
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:ChangeVarE}
Let edge $\bar e$ and $e$ be edges in $\bar \calT_h$ and $\calT_{h,k}$, respectively, with $e = \bPsi(\bar e)$,
and let $ \bt_{\bar e}$ denote a unit tangent vector to $\bar e$.
There holds
\begin{align*}
\int_e q 
%
& = \int_{\bar e} \mu_e q\circ \bPsi\qquad \forall q\in L_1(e),
\end{align*}
where $\mu_e = |\nab \bPsi \bt_{\bar e}|.$
\end{lemma}




