\subsection{Piola Transforms}
We follow the setup and notation in \cite{Steinmann08,CD16,SurfaceStokes1,DemlowNeilan23}
to describe the Piola transform between two surfaces in $\bbR^3$.
Let $\bPhi:\calS_0\to \calS_1$ be a diffeomorphism 
between two surfaces $\calS_0$ and $\calS_1$.
 Let $d\sigma_i$ be
the surface measure of $\calS_i$,
and let $\mu$  satisfy $\mu d\sigma_0 = d\sigma_1$.
The Piola transform of a vectorfield $\bv:\calS_0\to \bbR^3$ 
with respect to $\bPhi$
is given by 
\[
(\calP_{\bPhi} \bv)\circ \bPhi= \mu^{-1} \nab\bPhi \bv,
\]
whereas the Piola transform for a vectorfield $\bv:\calS_1\to \bbR^3$
with respect to the inverse mapping $\bPhi^{-1}$ is given by 
%
\[
(\calP_{\bPhi^{-1}} \bv)\circ \bPhi^{-1} = (\mu\circ \bPhi^{-1}) \nab \bPhi^{-1} \bv.
\]
The mappings $\calP_{\bPhi}:\bH({\rm div}_{\calS_0};\calS_0)\to \bH({\rm div}_{\calS_1};\calS_1)$
and $\calP_{\bPhi^{-1}}:\bH({\rm div}_{\calS_1};\calS_1)\to \bH({\rm div}_{\calS_0};\calS_0)$
are bounded, and in particular, satisfy
${\rm div}_{\calS_0} \bv = \mu {\rm div}_{\calS_1} \calP_{\bPhi}  \bv$ for all $\bv\in \bH({\rm div};\calS_0).$

%%%%%%%%%%%%%%
%%%%%%%%%%%%%%
%%%%%%%%%%%%%%
{\begin{remark}
In what follows, we make a slight abuse of notation
and treat the symbol of the Piola transform $\calP_{(\cdot)}$ as both an operator 
and a matrix. For example, we write $(\calP_{\bPhi} \bv)\circ \bPhi(x) = \calP_{\bPhi}(x) \bv(x)$,
where on the left-hand side $\calP_{\bPhi} \bv:\calS_1\to \bbR^3$, whereas on 
the right-hand side, both $\calP_{\bPhi}= \mu^{-1}\nab \bPhi$ and $\bv$ are functions defined on $\calS_0$.
This leads to (admittedly unusual) statements such as $\|\calP_{\bPhi}\bv\|_{L_p(\calS_1)} = \|\mu^{1/p} \calP_{\bPhi} \bv\|_{L_p(\calS_0)}$.
\end{remark}}


In the case $\bPhi = \bp$, $\calS_0 = \Gamma_{h,k}$,
and $\calS_1 = \gamma$,
the Piola transform of $\bv:\Gamma_{h,k}\to \bbR^3$ with $\bPi_h \bv= \bv$
is  \cite{CD16,SurfaceStokes1,DemlowNeilan23}
%
\begin{equation}\label{eqn:Piola}
\pt \bv \circ \bp := \calP_{\bp}  \bv =  \frac1{\mu_h} \big[\bPi - d {\bf H}\big]  \bv,
\end{equation}
%
whereas the Piola transform of $\bv:\gamma\to \bbR^3$
with respect to the inverse $\bp^{-1}$ is given by
%
\begin{equation}\label{eqn:invPiola}
\ipt \bv := \calP_{\bp^{-1}}\bv = \mu_h \Big[{\bf I}- \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\Big][{\bf I}-d {\bf H}]^{-1} (\bv \circ \bp). 
\end{equation}

Due to the smoothness of $\bp$ and local smoothness of $\bnu_h$, 
the function $\mu_h = \bnu\cdot \bnu_h \det({\bm I}-d {\bf H})$ is smooth
on each $K\in \calT_{h,k}$, and so is its reciprocal. In particular $|\mu_h^{-1}|_{W^m_\infty(K)}\lesssim 1$ 
and $\|\mu\|_{W^m_\infty(K)}\lesssim 1$ for $m\in \bbN_0$.
It thus follows that
\begin{equation}
\label{eqn:PiolaPBounds}
\|\calP_{\bp}\|_{W^m_\infty(K)}\lesssim 1,\quad \text{and}\quad \|\calP_{\bp^{-1}}\|_{W^m_\infty(K^\gamma)}\lesssim 1
\end{equation}
on each $K\in \calT_{h,k}$ and $K\in \calT_{h,k}^\gamma$, and so
%
\begin{align}\label{eqn:ugh}
\|\pt{\bv}\|_{W^{m}_p(K^\gamma)}\approx  \|\bv\|_{W^{m}_p(K)}\qquad \forall \bv\in {\bm W}_p^m(K),\ \forall K\in \calT_{h,k},\ m\in \mathbb{N}_0,\ p\in [1,\infty],
\end{align}
with $\pt{\bv} = \calP_{\bp} \bv$.


The proofs of the following three lemmas are found in the appendix.
%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:xPert}
Assume \eqref{eqn:FbarEst}--\eqref{eqn:baPert}, and let $\bar K\in \calT_h,\ K\in \calT_{h,k}$.
Then there holds
\begin{equation}
\begin{aligned}
|\calP_{\bPsi_{\bar K}} \bx - \bx|\lesssim h |\bx|\qquad &&\text{for all $\bx$ tangent to $\bar K$,}\\
|\calP_{\bPsi^{-1}_{K}} \bx - \bx|\lesssim h |\bx|\qquad &&\text{for all $\bx$ tangent to $K$.}
\end{aligned}
\end{equation}
\end{lemma}


%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:PiolaOfa}
There holds for all $K\in \calT_{h,k}$, $\bar K\in \bar \calT_h$, and $m \in \mathbb{N}_0$
\begin{alignat}{2}
\label{eqn:PiolaOfa}
|\calP_{\ba_K}|_{W^m_\infty(\hat K)}&\lesssim h^{m-1},\qquad
&&
|(\calP_{\ba_K})^\dagger|_{W^m_\infty(\hat K)}\lesssim h^{1+m},\\
%
\label{eqn:PiolaBounds}
\|\calP_{\bPsi}\|_{W^m_\infty(\bar K)}&\lesssim 1, \qquad &&\|\calP_{\bPsi^{-1}}\|_{W^m_\infty(K)}\lesssim 1,
\end{alignat}
where $(\calP_{\ba_K})^\dagger$ is the pseudo-inverse of $\calP_{\ba_K}$. Consequently 
if $\bw\in \bH^m(K)$ and $\hat \bw\in \bH^m(\hat K)$ are related via $\bw = \calP_{\ba_K} \hat \bw$, then there holds
\begin{align}\label{eqn:ScalingOfPiolaA}
 |{\bw}|_{H^m(K)}\lesssim \sum_{\ell=0}^m h^{-\ell} |\hat \bw|_{H^\ell(\hat K)},\qquad |\hat \bw|_{H^m(\hat K)}\lesssim h^m\|{\bw}\|_{H^m(K)}.
\end{align}
%
Moreover, for all $\bar \bv\in \bH^m(\bar K)$ there holds
\begin{align}
\label{eqn:PhiPiolaNormEquiv}
\|\calP_{\bPsi} \bar \bv\|_{H^m(K)}\approx \|\bar \bv\|_{H^m(\bar K)},\quad K = \bPsi(\bar K).
\end{align}
\end{lemma}



%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:DefCons}
There holds  for $\bv\in \bH^1_T(K)$
\begin{equation}\label{eqn:DefChain}
|{\rm Def}_\gamma \pt{\bv} - ({\rm Def}_{\Gamma_{h,k}} \bv)\circ \bp^{-1}|\lesssim h^{k} \left(|(\nab_{\Gamma_{h,k}} \bv)\circ \bp^{-1}| +
|\bv\circ \bp^{-1}|\right) \quad \text{on }K^\gamma.
\end{equation}
\end{lemma}


