\section{Finite Element Spaces}\label{sec-3}
Recall in the Euclidean case, the Taylor--Hood pair takes the 
velocity space to be the vector-valued  Lagrange space of degree $r\ge 2$,
whereas the pressure space is the (scalar)  Lagrange space of degree $(r-1)$.
Analogously, on the affine surface $\bar \Gamma_h$ we let  $\bar Q_h$ be the space of continuous, piecewise  polynomials of degree $(r-1)$.
On the high-order surface approximation, we define the pressure space via standard composition:
%
\begin{equation}\label{eqn:THQhDef}
Q_h = \{q\in H^1(\Gamma_{h,k})\cap \mathring{L}_2(\Gamma_{h,k}):\ q\circ \bPsi|_{\bar K}\in \mathbb{P}_{r-1}(\bar K)\ \forall \bar K\in \bar \calT_h\},
\end{equation}
where $\mathbb{P}_{r-1}(\bar K)$ denotes the space of polynomials of degree $\le (r-1)$
with domain $\bar K$, and $\mathring{L}_2(\Gamma_{h,k})$ is the space of square-integrable
functions on $\Gamma_{h,k}$ with vanishing mean.
Note that $Q_h$ is equivalent
to the space of functions $q$ in $H^1(\Gamma_{h,k})\cap \mathring{L}_2(\Gamma_{h,k})$
such that $q\circ \ba_K|_{\hat K}\in \mathbb{P}_{r-1}(\hat K)$ for each $K\in \calT_{h,k}$.

Let $\bar \calN_h$ denote the set of degrees of freedom (DOFs) of the $r$th-degree Lagrange finite element
space on $\bar \calT_h$, i.e., $\bar \calN_h$ consists of (i) the vertices in $\bar \calT_h$;
(ii) $(r-1)$ points on each (open) edge $\bar e\in \bar \calE_h$; (iii) $\frac12(r-1)(r-2)$ points
in the interior of each $\bar K\in \bar \calT_h$, chosen such that they uniquely determine
a polynomial of degree $(r-3)$. The corresponding set of points are mapped to $\Gamma_{h,k}$ via $\bPsi$:
\[
\calN_{h,k} = \{\bPsi(\bar a):\ \bar a\in \calN_h\}.
\]
We also set for each $K\in \calT_{h,k}$, 
\[
\calN_K = \{a\in \calN_{h,k}:\ a\in {\rm cl}(K)\}
\]
to be the location of these degrees of freedom on $K$.
We make the mild assumption that these degrees
of freedom are the image of a set of reference DOFs under $\ba_K$, 
i.e., there exists a set $\calN_{\hat K}\subset {\rm cl}(\hat K)$
such that $\calN_K = \{\ba_K(\hat a):\ \hat a\in \calN_{\hat K}\}$.


For each $K\in \calT_{h,k}$, we define the local velocity space,
which is the space of  Piola-mapped polynomials of degree $r$:
\[
\bV(K) = \{\calP_{\ba_K} \hat \bv:\ \hat \bv\in [\mathbb{P}_r(\hat K)]^2\}.
\]
%
To piece together these local spaces and to define
the global velocity space, we require a definition along with a technical result.
%%%%%%%%%
%%%%%%%%%
%%%%%%%%%
\begin{definition}\label{def:MaK}
For each DOF $a\in \calN_{h,k}$ in the triangulation, 
we arbitrarily choose a single (fixed) face $K_a\in \calT_a$.
For $K\in \calT_a$, we define
$\calM_a^K:\bbR^3\to \bbR^3$ by
%
\begin{equation}\label{eqn:calMDef}
\calM_a^K \bx= \Big(\bnu_{K_a}(a) \cdot \bnu_K(a) \Big[ {\bf I} - \frac{\bnu_{K_a}(a) \otimes \bnu_{K}(a)}{\bnu_{K_a}(a)\cdot \bnu_{K}(a)}\Big]\Big) \bx,
\end{equation}
where we recall $\bnu_{K_a}$ and $\bnu_{K}$ are the outward unit normals of $K_a$ and $K$, respectively.
In particular, $\calM_a^K \bx$ is the Piola transform of $\bx$ with respect
to the inverse of the closest point projection onto the plane tangent to $K_a$ at $a$ \cite{DemlowNeilan23}.
\end{definition}

\begin{remark} While our algorithm functions by choosing a master element $K_a$ at each node $a$, 
it is more appropriately interpreted as assigning an approximate tangent plane at each node.
%conceptually this procedure may more appropriately be seen as fixing a reference approximate tangent plane at each node.  
The algorithm does not have access to the continuous normal $\bnu$ or equivalently the tangent plane to $\gamma$.  In essence, our algorithm functions by choosing a reasonable but somewhat arbitrary approximation to $\bnu$ at each node and then computing degrees of freedom based on this choice.  
In the absence of the actual tangent plane of $\gamma$,
%Absent knowledge of the actual tangent plane, 
there does not appear to be a canonical or ``best'' choice of approximate tangent plane for this purpose.  
\end{remark}



%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:PiolaD} 
Fix $a\in \calN_{h,k}$ and let $\bu$ lie in the tangent plane of $\gamma$ at 
$\bp(a)$.  For $K\in \calT_a$, let $\ipt{\bu}_K = \calP_{\bp^{-1}} \bu|_K$ be the Piola transform of $\bu$ to $K$ via the inverse of the closest point projection.
Then 
\begin{align}
\label{piola_defect}
|\ipt{\bu}_K-\mathcal{M}_a^K \ipt \bu_{K_a}|
\lesssim h^{2k} |\ipt \bu_{K_a}| \le h^{2k} |\bu|.
\end{align} 
\end{lemma}
\begin{proof}
The proof for the case $k=1$ is found in \cite[Lemma 2.5]{DemlowNeilan23}. The arguments
given there generalize to arbitrary $k\ge 1$ to yield \eqref{piola_defect}; see \cite[Remark 2.6]{DemlowNeilan23}.
\end{proof}



%
Motivated by Lemma  \ref{lem:PiolaD},
we define the global velocity space as
\begin{equation}\label{eqn:THVhDef}
\bV_h = \{\bv\in \bL_2(\Gamma_{h,k}):\ \bv_K\in \bV(K),\ \forall K\in \calT_{h,k}; \bv_K(a) = \calM_a^K(\bv_{K_a}(a))\ \forall K\in \calT_a,\ \forall a\in \calN_{h,k}\}.
\end{equation}

%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:vn3Points}
Let $\bv\in \bV_h$, and 
for an edge $e$ with $e = \p K_1\cap \p K_2$ ($K_1,K_2\in \calT_{h,k}$),
set $\bv_j = \bv|_{K_j}$.  Let $\bn_j$ be the outward unit co-normal
of $\p K_j$ restricted to $e$. 
Then there holds
\[
(\bv_1\cdot \bn_1 + \bv_2 \cdot \bn_2)(a) = 0\qquad \forall {\rm cl}(e) \ni a\in \calN_{h,k}.
\]
\end{lemma}
\begin{proof}
This result  follows from the (in-plane) normal-preserving properties
of the Piola transform. See \cite[Proposition 3.1]{DemlowNeilan23} for details.
\end{proof}


%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{lemma}
There holds $\bV_h\subset \bH({\rm div}_{\Gamma_{h,k}};\Gamma_{h,k})$.
\end{lemma}
\begin{proof}
It suffices to show that co-normal components functions in $\bV_h$
are single-valued on the edges in $\calT_{h,k}$.

Let $\bv\in \bV_h$, set $\bar \bv = \calP_{\bPsi^{-1}} \bv$,
and let $\bar K\in \bar \calT_h$ and $K\in \calT_{h,k}$ be related
via $K = \bPsi(\bar K)$.
Writing $\bv_K :=\bv|_K =  \calP_{\ba_K} \hat \bv$ for some $\hat \bv\in [\mathbb{P}_r(\hat K)]^2$,
we have $\bar \bv_{\bar K} :=\bar \bv|_{\bar K} =  \calP_{\bPsi^{-1}} \calP_{\ba_K} \hat \bv = \calP_{F_{\bar K} \circ \ba_K^{-1}} \calP_{\ba_K} \hat \bv= \calP_{F_{\bar K}} \hat \bv$.
Thus $\bar \bv_K$ is a polynomial of degree $\le r$.

Let $e$ be an edge of $\calT_{h,k}$ and $\bar e$ an edge of $\bar \calT_h$
with $e = \bPsi(\bar e)$.  Write $e = \p K_1\cap \p K_2$ with $K_1,K_2\in \calT_{h,k}$,
and let $\bar K_1,\bar K_2\in \bar \calT_h$ be the corresponding
affine elements.  The normal-preserving properties
of the Piola transform read
%
\begin{align*}
\int_{e}  (\bv_j \cdot \bn_j)q = \int_{\bar e} (\bar \bv_j\cdot \bar \bn_j)\bar q\qquad \forall q\in L_2(e),
%
\end{align*} 
%
where $\bv_j = \bv|_{K_j},\ \bar\bv_j = \bar\bv|_{\bar K_j}$, and  $\bar q = q\circ \bPsi$.  
An application of Lemma \ref{lem:ChangeVarE} yields
%
\begin{align*}
\int_{\bar e} (\bar \bv_j\cdot \bar \bn_j) \bar q = \int_e (\bv_j \cdot \bn_j)q = \int_{\bar e} \mu_e (\bv_j \cdot \bn_j)\circ \bPsi \bar q\qquad \forall q\in L_2(e).
\end{align*}
%
Thus, $\bar \bv_j\cdot \bar \bn_j = \mu_e ( \bv_j\cdot  \bn_j)\circ \bPsi$ and so
\begin{align*}
\bv_1 \cdot \bn_1 + \bv_2 \cdot \bn_2 = \Big(\mu_e \big(\bar \bv_1\cdot \bar \bn_1+\bar \bv_2\cdot \bar \bn_2)\Big)\circ \bPsi^{-1}\qquad \text{on }e.
\end{align*}
Lemma \ref{lem:vn3Points} shows  that the left-hand side vanishes at $(r+1)$ distinct points on ${\rm cl}(e)$,
and therefore $\bar \bv_1\cdot \bar \bn_1+\bar \bv_2\cdot \bar \bn_2$ vanishes at $(r+1)$ points on $\bar e$.
Since $\bar \bv\cdot \bar \bn_j$ is a   polynomial of degree $\le r$ on $\bar e$,
we conclude $\bar \bv_1 \cdot \bar \bn_1 + \bar \bv_2 \cdot \bar \bn_2=0$ on $\bar e$.
Therefore $ \bv_1 \cdot  \bn_1 +  \bv_2 \cdot  \bn_2=0$ on $ e$, and
so $\bv\in \bH({\rm div}_{\Gamma_{h,k}};\Gamma_{h,k})$. 
\end{proof}



