%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Scaling and Approximation Properties of $\bV_h$}

In this section, we gather some scaling and approximation results
of the velocity space $\bV_h$, showing that it has similar
properties as the (isoparametric) Lagrange finite element space.
For example, we have the following inverse estimate.
%%%%%%%%%%%%
%%%%%%%%%%%%
%%%%%%%%%%%%
\begin{lemma}
There holds for all $\bv\in \bV(K)$ and $m,s\in \mathbb{N}_0$ with $s\le \min\{r,m\}$,
\begin{align}\label{eqn:HOIE}
\|\bv\|_{W^{m}_\infty(K)}\lesssim h^{-1+s-\min\{r,m\}} \|\bv\|_{H^s(K)}\qquad \forall \bv\in \bV(K),\ \forall K\in \calT_{h,k}.
\end{align}
\end{lemma}
\begin{proof}
Write $\bv = \calP_{\ba_K} \hat \bv$ for some $\hat \bv\in [\mathbb{P}_r(\hat K)]^2$.
By similar arguments as in the proof of Lemma \ref{lem:PiolaOfa} (cf. \eqref{eqn:wbound}), we have for any $m\in \mathbb{N}$
\[
|\bv|_{W^{m}_\infty(K)}\lesssim h^{-1} \sum_{\ell=0}^{m}  h^{-\ell} |\hat \bv|_{W^\ell_\infty(\hat K)} = h^{-1} \sum_{\ell=0}^{\min\{r,m\}}  h^{-\ell} |\hat \bv|_{W^\ell_\infty(\hat K)}
\lesssim  \sum_{\ell=0}^{s-1} h^{-\ell-1} |\hat \bv|_{H^\ell(\hat K)}+h^{-\min\{r,m\}-1}|\hat \bv|_{H^s(\hat K)},
\]
where we used the fact that $\hat \bv$ is a polynomial of degree at most $r$ and equivalence of norms in the last two steps.
We then map back to $K$, using Lemma \ref{lem:PiolaOfa},
\[
|\bv|_{W^{m}_\infty(K)}\lesssim  h^{-1} \| \bv\|_{H^{s-1}(\hat K)}+h^{-1+s-\min\{r,m\}} \| \bv\|_{H^s(K)}\lesssim h^{-1+s-\min\{r,m\}}\|\bv\|_{H^s(K)}.
\]
\end{proof}



%%%%%%%%%%%%
%%%%%%%%%%%%
%%%%%%%%%%%%
\begin{lemma}\label{lem:Scaling}
There holds
\begin{equation}
h^{m-1}\|\bv\|_{H^m(K)} \lesssim \sum_{a\in \calN_K} |\bv(a)|\qquad \forall \bv\in \bV(K),\ \forall K\in \calT_{h,k}\qquad m=0,1,\ldots,r.
\end{equation}
\end{lemma}
\begin{proof}
Write $\bv = \calP_{\ba_K} \hat \bv$ with $\hat \bv\in [\mathbb{P}_k(\hat K)]^2$.
Applying Lemma \ref{lem:PiolaOfa} and equivalence of norms we have
\begin{align*}
|\bv|^2_{H^m( K)}\lesssim h^{-2m}\|\hat \bv\|^2_{H^m(\hat K)}\lesssim h^{-2m} \sum_{\hat a\in \calN_{\hat K}} |\hat \bv(\hat a)|^2.
\end{align*}
We then apply the estimate \eqref{eqn:PiolaOfa} to obtain
%
\begin{align*}
|\bv|^2_{H^m( K)}
\lesssim h^{-2m} \sum_{\hat a\in \calN_{\hat K}} |(\calP_{\ba_K})^\dagger \calP_{\ba_K} \hat \bv(\hat a)|^2
\lesssim h^{-2m} \|(\calP_{\ba_K})^\dagger\|_{L_\infty(\hat K)}^2  \sum_{\hat a\in \calN_{\hat K}}|\bv(a)|^2\le h^{-2m+2}
\sum_{\hat a\in \calN_{\hat K}}|\bv(a)|^2.
\end{align*}
\end{proof}



%%%%%%%%%%%%
%%%%%%%%%%%%
%%%%%%%%%%%%
\begin{lemma}\label{lem:ApproxProps}
For each $\bw\in \bC(\gamma)\cap \bH^1_T(\gamma)\cap \bH^s_h(\gamma)\ (2\le s\le r+1)$, 
there exists $\bI_h \ipt{\bw}\in \bV_h$ such that
\begin{align}\label{eqn:InterpolantEstimate}
h^m \|\ipt{\bw}-\bI_h \ipt{\bw}\|_{H^m(K)}\lesssim h^s \|\bw\|_{H^s(K^\gamma)}+h^{2k}\|\bw\|_{H^2(\omega_{K^\gamma})},\quad m=0,1,\ldots,r \hbox{ and } m \le s.
\end{align}
\end{lemma}
\begin{proof}
This result essentially follows from the arguments in 
\cite[Lemma 3.2]{DemlowNeilan23}, so we only sketch
the main ideas.

Given $\bw\in \bC(\gamma)\cap \bH^1_T(\gamma)\cap \bH^s_h(\gamma)$,
we uniquely define  $\bv =\bI_h \ipt{\bw} \in \bV_h$ such that
\[
\bv_{K_a}(a) = \ipt{\bw}_{K_a}(a)\qquad \forall a\in \calN_{h,k},
\]
where $\ipt{\bw} = \calP_{\bp^{-1}} \bw$, with $\bp^{-1}:\gamma \to \Gamma_{h,k}$.

Define $\ipt \bw_I$ such that $(\ipt \bw_I)_K\in \bV(K)$ for each $K\in \calT_{h,k}$
and $(\ipt \bw_I)_K(a) = \ipt{\bw}_K(a)$ for all nodes $a\in \calN_{h,k}$
and elements $K\in \calT_{h,k}$.
Then the arguments in \cite[Lemma 3.2]{DemlowNeilan23} and \eqref{piola_defect} yield
\[
|(\bv-\ipt\bw_I)_K(a)|\lesssim h^{2k} |\ipt{\bw}_{K_a}(a)|.
\]
Thus by
Lemma \ref{lem:Scaling} and a scaled Sobolev embedding we obtain
%
\begin{align*}
h^m \|\ipt{\bw}_I - \bv\|_{H^m(K)}
&\lesssim h \max_{a\in \calN_K} |(\ipt{\bw}_I-\bv)_K(a)|\lesssim h^{2k+1}\max_{a\in \calN_K} |\ipt{\bw}_{K_a}(a)|\lesssim h^{2k}\|\ipt \bw\|_{H^2_h({\omega_{K}})}.
\end{align*}
%
A scaling argument and the Bramble-Hilbert lemma
yields $h^m \|\ipt{\bw}-\ipt{\bw}_I\|_{H^m(K)}\lesssim h^s \|\ipt\bw\|_{H^s(K)}$.
Therefore by the triangle inequality and \eqref{eqn:ugh},
we obtain
\[
h^m \|\ipt\bw - \bv\|_{H^m(K)}\lesssim h^s \|\ipt \bw\|_{H^s(K)} + h^{2k} \|\ipt \bw\|_{H^2_h(\omega_K)}{\lesssim h^s \|\bw\|_{H^s(K^\gamma)}+h^{2k} \|\bw\|_{H^2_h(\omega_{K^\gamma})}.}
\] \end{proof}

%%%%%%%%%%%%
%%%%%%%%%%%%
%%%%%%%%%%%%
\begin{lemma}
Given $\bw\in \bH^1_T(\gamma)$,
there exists ${\bI_{h,1}} \bw\in \bV_h$ such that
\begin{equation}\label{eqn:IhwProp}
\|{\bI_{h,1}} \bw\|_{H^1_h(\Gamma_{h,k})}\lesssim \|\bw\|_{H^1(\gamma)}\quad \text{and}\quad 
\left(\sum_{K\in \calT_{h,k}} h_K^{-2} \|\bw-\pt{\bI_{h,1} \bw}\|^2_{L_2(K^\gamma)}\right)^{1/2}\lesssim \|\bw\|_{H^1(\gamma)}.
\end{equation}
\end{lemma}
\begin{proof}
Let $\bar{\bw}_h$ be the componentwise Scott-Zhang interpolant of $\bar{\bw}:=\bw \circ \bp \circ \bPsi$ on $\bar \Gamma_h$ into the continuous piecewise tri-linear Lagrange space \cite{ScottZhang90}.  Then $\bw_h := \bPi (\bar{\bw}_h\circ \bPsi^{-1} \circ \bp^{-1}) \in \bC(\gamma) \cap \bH_T^1(\gamma) \cap \bH_h^2(\gamma)$.  Let also $\bI_{h,1} \bw= \bI_h \ipt{ \bw}_h \in \bV_h$.  Given $K \subset \Gamma_{h,k}$, applying norm equivalences, \eqref{eqn:InterpolantEstimate}, the fact that second-order
derivatives of $\bar \bw_h$ vanish on $\bar \Gamma_h$, %$D_h^2 \overline{\bw}_h =0$ on $\bar\Gamma_h$, 
and standard properties of the Scott-Zhang interpolant yields
$$\begin{aligned}
\|\bI_{h,1} \bw \|_{H^1(K)} & \le  \|\bI_h \ipt{\bw}_h-\ipt{\bw}_h\|_{H^1(K)} + \|\ipt{\bw}_h\|_{H^1(K)}
\\ & \lesssim h \|\bw_h \|_{H^2_h(\omega_{K^\gamma})} + \|{\bw}_h\|_{H^1( K^\gamma)}
\\ &\lesssim h \|\overline{\bw}_h\|_{H^2_h(\omega_{\bar K})} + \|\bar \bw_h\|_{H^1(\bar K)}
%
\\ &\lesssim \|\overline{\bw}_h\|_{H^1(\omega_{\bar K})}
%\\ & \lesssim h \|(\Pi\circ \bp \circ \psi)  \overline{\bw}_h\|_{H^2(\omega_{\bar K})} + \|\overline{\bw}\|_{H^1(\omega_{\bar K})}
%\\ & \lesssim h \|\overline{\bw}_h \|_{H^1(\omega_{\bar K})}+\|\overline{\bw}\|_{H^1(\omega_{\bar K})}
\\ & \lesssim \|\bar{\bw}\|_{H^1(\omega'_{\bar K})} \lesssim \|\bw\|_{H^1(\omega'_{K^\gamma})},
\end{aligned} $$
%
where
\[
\omega'_{\bar K} = \mathop{\bigcup_{\bar K\in \bar \calT_h}}_{{\rm cl}(\bar K)\cap {\rm cl}(\omega_{\bar K})\neq \emptyset} K,
\]
and an analogous definition for $\omega'_{K^\gamma}$.

By similar arguments, we have
\begin{align*}
\|\bw-\pt{\bI_{h,1} \bw}\|_{L_2(K^\gamma)}
&\le \|\bw-\bw_h\|_{L_2(K^\gamma)}+\|\bw_h-\pt{\bI_{h,1}\bw}\|_{L_2(K^\gamma)}\\
&\lesssim \|\bar \bw-\bar \bw_h\|_{L_2(\bar K)} + \|\ipt{\bw}_h-\bI_{h}\ipt{\bw}_h\|_{L_2(K)}\\
%
&\lesssim h \|\bar \bw\|_{H^1(\omega_{\bar K})} + h^2 \| \bar \bw_h\|_{H^2_h(\omega_{K^\gamma})}
\lesssim h\|\bw\|_{H^1(\omega'_{K^\gamma})}.
\end{align*}
The desired result \eqref{eqn:IhwProp} now follows after summing over $K\in \calT_{h,k}$.
\end{proof}






