%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Inf-Sup stability}
In this section we establish that $\bV_h\times Q_h$ is an inf-sup stable
 pair for the surface Stokes problem. The proof relies
 on a variant of Verf\"urth's trick, analogous to the standard
 stability argument for the Euclidean Taylor--Hood pair.
We begin by showing 
a stability result with respect to a weighted $H^1$-norm.

%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%
\begin{lemma} 
There holds 
\begin{equation}\label{eqn:THKMInfSup}
\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k} } ({\rm div}_{\Gamma_{h,k}} \bv)q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}} \ge c_1 \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}\qquad \forall q\in Q_h,
\end{equation}
where $c_1>0$ is independent of $h$.
\end{lemma}
\begin{proof}
Let $\calN_{h,k}^{\calE}\subset \calN_{h,k}$ denote the set of DOFs that lie
in the interior of edges, and let $\calN_{h,k}^{\calT}\subset \calN_{h,k}$ denote
the set of DOFs that lie in the interior of a (curved) simplex. The corresponding sets
defined on $\bar \calT_h$ are denoted by $\bar \calN_h^{\bar \calE}$ and $\bar \calN_h^{\bar \calT}$.

For given $q \in Q_h$, let $\bar{q}=q \circ \bPsi \in \bar{Q}_h$ and define $\bv \in \bV_h$ as follows.  

\noindent(i) {\em Vertex DOFs:} We set $\bv(a)=0$ at all vertices $a$ in $\calT_{h,k}$.  



\noindent(ii) {\em Edge DOFs:} If $a\in \calN_{h,k}^{\calE}$ lies in the interior of an edge $e$, 
then we set $\bar e = \bPsi^{-1}(e)$, let  $\bt_{\bar e}$ be a unit tangent vector to $\bar e$,
 and set $\bar a = \bPsi^{-1}(a)$ to be the corresponding point on $\bar e$.
Let $\phi_{\bar e}$ be the continuous, piecewise quadratic polynomial (bubble) that takes the value 
$1$ at the edge midpoint of $\bar e$ and vanishes at the vertices and other edges of $\bar \calT_h$.  
%
We set
\[
\bv_{K_a}(a) =-h_e^2 \phi_{\bar e}(\bar a)({\bt}_{\bar e}\cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a))  (\calP_{\bPsi_{\bar K_{ a}}} \bar{\bt}_e)(a)\qquad a\in \calN_{h,k}^{\calE},
\]
where $\bar K_{a} = \bPsi^{-1}(K_{a})$, and we note $ \bt_{\bar e} \cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a)$ is single-valued 
because $\bar q$ is continuous. 
We see  that $(\calP_{\bPsi_{\bar K_{a}}}\bar{\bt}_e)(a)$ is tangent to $\Gamma_{h,k}$
by properties of the Piola transform. Moreover, for
any co-normal vector $\bn_e$, we have 
 $0 = \big(\mu_e(\bar a)\big)^{-1}( \bt_{\bar e} \cdot \bar \bn_e)(\bar a) =(\calP_{\bPsi_{\bar K_{a}}} \bt_{\bar e})(a)\cdot \bn_e(a)$.
 Thus, $(\calP_{\bPsi_{\bar K_{a}}}{\bt}_{\bar e})(a)$ is parallel to the edge unit tangent $\bt_e(a)$.

For both $K \ni a$, we then have using \eqref{eqn:calMDef} and $\bnu_K(a) \cdot \bt_e(a)=0$ that 
\[
\bv_{K}(a) = \calM_a^K \bv_{K_a}(a)=-h_e^2 \phi_{\bar e}(\bar a)  (\bnu_{K_a}(a) \cdot \bnu_{K}(a) ) ({\bt}_{\bar e}\cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a)) (\calP_{\bPsi_{\bar K_a}} {\bt}_{\bar e})(a),
\quad K\in \calT_a,\ \ a\in \calN_{h,k}^{\calE}.
\]

\noindent(iii) {\em Interior DOFs:} If $a\in \calN_{h,k}^{\calT}$ is a DOF that lies in the interior of $K\in \calT_{h,k}$ (so that $K_a = K$), then we set
\[
\bv_{K_a}(a) =  -\sum_{e\subset \p K} h_e^2 \phi_{\bar e}(\bar a)( \bt_{\bar e}\cdot \nab_{\bar \Gamma_h} \bar q(\bar a))(\calP_{{\bPsi}_{\bar K_a}}  \bt_{\bar e})(a)\qquad a\in \calN_{h,k}^{\calT}.
\]


Letting $\bar{\bv}=\calP_{\bPsi^{-1}}\bv\in \bH({\rm div}_{\bar \Gamma_h};\bar \Gamma_h)$, we  have 
\[
\bar{\bv}_{\bar{K}}(\bar a)=(\calP_{\bPsi_K^{-1}} \bv_{K})(\bar a) =
\left\{
\begin{array}{ll}
-h_e^2\phi_{\bar e}(\bar a)  (\bnu_{K_a}(a) \cdot \bnu_{K}(a) ) ({\bt}_{\bar e}\cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a)) \calP_{\bPsi_K^{-1}}(a) (\calP_{\bPsi_{\bar K_a}} {\bt}_{\bar e})(a) 
& a\in \calN_{h,k}^{\calE},\\
%
-\sum_{e\subset \p K} h_e^2 \phi_{\bar e}(\bar a)( \bt_{\bar e}\cdot \nab_{\bar \Gamma_h} \bar q(\bar a)) \bt_{\bar e}& a\in \calN_{h,k}^{\calT},
\end{array}\right.
\]
and $\bar \bv$ vanishes at the vertices of $\bar \Gamma_h$.

Recall that, for $a\in \calN_{h,k}^{\calE}$, $(\calP_{\bPsi_{\bar K_a}} {\bt}_{\bar e})(a) = \calP_{\bPsi_{\bar K_{a}}}(\bar{a}) {\bt}_{\bar e}$ is parallel to $\bt_e(a)$,
and so $\calP_{\bPsi_K^{-1}}(a) \calP_{\bPsi_{K_{a}}}(\bar{a}) {\bt}_{\bar e}$ is parallel to $ \bt_{\bar e}$.
Thus we can write
%
\begin{equation}\label{eqn:LineA}
(\bnu_{K_{a}}(a)  \cdot \bnu_K(a)) \calP_{\bPsi_K^{-1}}(a) \calP_{\bPsi_{K_{a}}}(\bar{a}) {\bt}_{\bar e}= C_{K, e,a} {\bt}_{\bar e}
\end{equation}
for some $C_{K,e,a}\in \bbR$.
An application of Lemma \ref{lem:xPert} yields
%
\begin{equation*}
\begin{split}
\left|\calP_{\bPsi_K^{-1}}(a) \calP_{\bPsi_{\bar K_{a}}}(\bar a)  \bt_{\bar e}- \bt_{\bar e}\right|
&\le \left|\calP_{\bPsi_K^{-1}}(a) \calP_{\bPsi_{\bar K_{a}}}(\bar a)  \bt_{\bar e}- \calP_{\bPsi_{\bar K_{a}}}(\bar a)  \bt_{\bar e}\right|\\
&\qquad+\left|\calP_{\bPsi_{\bar K_{a}}}(\bar a)  \bt_{\bar e}- \bt_{\bar e}\right|\\
%
&\lesssim h | \bt_{\bar e}| = h.
\end{split}
\end{equation*}
This estimate along with $\bnu_K(a)\cdot \bnu_{K_a}(a) = 1+O(h^{2k})$ and \eqref{eqn:LineA}
shows $C_{K,e,a} = 1+\calO(h)$ and
\[
\bar{\bv}_{\bar{K}}(\bar a)=
\left\{
\begin{array}{ll}
-h_e^2 C_{K,e,a}  \phi_{\bar e}(\bar a)  ({\bt}_{\bar e}\cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a))  {\bt}_{\bar e}(a) 
& a\in \bar \calN_{h}^{\bar \calE},\\
%
-\sum_{e\subset \p K} h_e^2 \phi_{\bar e}(\bar a)(\bt_{\bar e}\cdot \nab_{\bar \Gamma_h} \bar q(\bar a)) \bt_{\bar e}& a\in \bar \calN_{h}^{\bar \calT}.
\end{array}\right.
\]
We see from a simple scaling argument that $\|\bar \bv\|_{H^1_h(\bar \Gamma_h)}\lesssim \|h \nab_{\bar \Gamma_h} \bar q\|_{L_2(\bar \Gamma_h)}$.

Now define $\tilde \bv:\bar \Gamma_h\to \bbR^3$ as
\[
\tilde{\bv} (\bar x)= -\sum_{\bar e \in \bar \calE_h}  h_e^2 \phi_{\bar e}(\bar x)(\bar{\bt}_e \cdot \nab_{\Gamma_h} \bar{q}(\bar x)) \bar{\bt}_e
\]
and note that both $\tilde \bv$ and $\bar \bv$ are  polynomials of degree $r$ on each $\bar K\in \bar \calT_h$ with
\[
(\tilde \bv -\bar{\bv})_{\bar{K}}(\bar a)=
\left\{
\begin{array}{ll}
-h_e^2 (1-C_{K,e,a})  \phi_{\bar e}(\bar a)  (\bar{\bt}_e\cdot \nabla_{\bar \Gamma_h} \bar{q}(\bar a))  \bar{\bt}_e(a) 
& a\in \bar \calN_{h}^{\bar \calE},\\
%
0& a\in \bar \calN_{h}^{\bar \calT}.
\end{array}\right.
\]
A scaling argument and the inequality $|1-C_{K,e,a}|\lesssim h$ then yields
\begin{align*}
\|h^{-1}(\tilde \bv-\bar \bv)\|_{L_2(\bar \Gamma_h)}^2 
&\lesssim \sum_{\bar a\in \bar \calN_h^{\bar \calE}}  |(\tilde \bv-\bar \bv)(\bar a)|^2\lesssim 
 \sum_{\bar a\in \bar \calN_h} h^6 |\nab_{\bar \Gamma_h} \bar q(\bar a)|^2\lesssim h^2 \|h \nab_{\bar \Gamma_h} \bar q\|_{L_2(\bar \Gamma_h)}^2.
\end{align*}


Using properties of the Piola transform and integrating by parts, rearranging the sum, and using norm equivalence, we then obtain 
for $h$ sufficiently small
\begin{align*}
\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q & = \int_{\bar \Gamma_h} ({\rm div}_{\bar \Gamma_h} \bar{\bv}) \bar{q}  = -\int_{\bar \Gamma_h} \tilde{\bv} \cdot \nabla_{\bar \Gamma_h} \bar{q}
-\int_{\bar \Gamma_h} (\bar \bv-\tilde \bv)\cdot \nab_{\bar \Gamma_h} \bar q
 \\ & \ge \sum_{\bar{K} \in \bar{\calT}_h} \sum_{\bar e \in \bar \calE_h: \bar{e} \subset \partial \bar{K}} \int_{\bar{K}}  h_e^2 \phi_{\bar e} (\bar{\bt}_e \cdot \nab_{\bar \Gamma_h} \bar{q})^2
 - \|h^{-1}(\bar \bv-\tilde \bv)\|_{L_2(\bar\Gamma_h)}  \|h \nab_{\bar \Gamma_h} \bar q\|_{L_2(\bar \Gamma_h)}
\\ & \gtrsim \sum_{e\in \calE_h} h^2_e \sum_{K\in \calT_{h,k}: e\subset \p K} \int_{K} |\nab_{\Gamma_h} \bar{q}\cdot \bar{\bt}_e|^2-  h\|h \nab_{\bar \Gamma_h} \bar q\|_{L_2(\bar \Gamma_h)}^2
\gtrsim \|h \nab_{\Gamma_h} \bar{q}\|_{L_2(\bar \Gamma_h)}^2
\\ & \gtrsim \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}^2.
\end{align*}
The proof is complete upon using this estimate
and
\[
\|\bv\|_{H^1_h(\Gamma_{h,k})}\lesssim \|\bar \bv\|_{H^1_h(\bar \Gamma_h)}\lesssim \|h \nab_{\bar \Gamma_h} \bar q\|_{L_2(\bar \Gamma_h)}\lesssim \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}.
\]
\end{proof}







%%%%%%%%%%%%
%%%%%%%%%%%%
%%%%%%%%%%%%
\begin{theorem}
There holds
\begin{align}\label{eqn:THInfSup}
\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}
\ge \beta \|q\|_{L_2(\Gamma_{h,k})}\qquad \forall q\in Q_h.
\end{align}
\end{theorem}
\begin{proof}
For a fixed $q\in Q_h$,
let $\bw\in \bH_T^1(\gamma)$ satisfy \cite{JankuhnEtal18}
\[
{\rm div}_\gamma \bw = (\mu_{h}^{-1} q)^\ell,\qquad \|\bw\|_{H^1(\gamma)}\lesssim \|(\mu_{h}^{-1} q)^\ell\|_{L_2(\gamma)}\lesssim \|q\|_{L_2(\Gamma_{h,k})}.
\]
Let $\bI_{h,1} \bw\in \bV_h$ be the approximation of $\bw$ satisfying \eqref{eqn:IhwProp}.
Then
\begin{align*}
\frac{\int_{\Gamma_h} ({\rm div}_{\Gamma_h} (\bI_{h,1} \bw)) q}{\|\bI_{h,1} \bw\|_{H^1_h(\Gamma_h)}} = 
\frac{\int_{\gamma} ({\rm div}_\gamma \pt{\bI_{h,1} \bw})q^\ell}{\|\bI_{h,1} \bw\|_{H^1_h(\Gamma_h)}}
\gtrsim  \frac{\int_{\gamma} ({\rm div}_\gamma \pt{\bI_{h,1} \bw})q^\ell}{\|\bw\|_{H^1(\gamma)}}.
\end{align*}
%
We then add and subtract $\bw$, integrate by parts, and use \eqref{eqn:IhwProp}:
\begin{equation}\label{eqn:ASw}
\begin{split}
\frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} (\bI_{h,1} \bw)) q}{\|\bI_h \bw\|_{H^1_h(\Gamma_{h,k})}} 
&\gtrsim  \frac{\int_{\gamma} ({\rm div}_\gamma \bw)q^\ell}{\|\bw\|_{H^1(\gamma)}}
-\frac{\int_\gamma ({\rm div}_\gamma (\bw-\pt{\bI_{h,1} \bw})) q^\ell}{\|\bw\|_{H^1(\gamma)}}\\
%
&\geq c_2\|q\|_{L_2(\Gamma_{h,k})}
+\frac{\int_\gamma  (\bw-\pt{\bI_{h,1} \bw}) \cdot \nab_\gamma q^\ell}{\|\bw\|_{H^1(\gamma)}}\\
%
&{\geq c_2} \|q\|_{L_2(\Gamma_{h,k})} 
- { c_3} \left(\sum_{K\in \calT_{h,k}} h_K^2 \|\nab_\gamma q^\ell\|_{L_2(K^\gamma)}^2\right)^{1/2}.
\end{split}
\end{equation}
for some $c_2,c_3>0$ independent of $h$.
%
%Note that $\|\nab_{\Gamma_h} q\|_{L_2(K)}\approx \|\nab_\gamma q\|_{
Note that $\|\nab_\gamma q^\ell\|_{L^2(K^\gamma )}\approx \|\nab_{\Gamma_h} q\|_{L_2(K)}$ on each $K\in \calT_{h,k}$. % (cf.~Dziuk (1988), Lemma 3).
Consequently,
\begin{align*}
\left(\sum_{K\in \calT_{h,k}} h_K^2 \|\nab_\gamma q^\ell\|_{L_2(K^\gamma)}^2\right)^{1/2}\lesssim \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}.
\end{align*}
%
Thus we conclude from \eqref{eqn:ASw},
\begin{equation}\label{eqn:Verf}
\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}
\ge \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} (\bI_{h,1} \bw)) q}{\|\bI_{h,1} \bw\|_{H^1_h(\Gamma_{h,k})}} 
\ge  c_2 \|q\|_{L_2(\Gamma_{h,k})} - c_4 \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}
\end{equation}
with $c_4>0$ independent of $h$.
%
Finally, we combine \eqref{eqn:THKMInfSup} 
and \eqref{eqn:Verf} to obtain 
\begin{align*}
c_2  \|q\|_{L_2(\Gamma_{h,k})} 
&\le \sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}
+c_4 \|h \nab_{\Gamma_{h,k}} q\|_{L_2(\Gamma_{h,k})}\\
%
&\le \left(\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}\right)
+\frac{c_4}{c_1} \left(\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}\right)\\
%
& = (1+ \frac{c_4}{c_1})  \left(\sup_{\bv\in \bV_h} \frac{\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv) q}{\|\bv\|_{H^1_h(\Gamma_{h,k})}}\right).
\end{align*}
Thus, we obtain  the inf-sup condition \eqref{eqn:THInfSup}
with $\beta = c_2 (1+ \frac{c_4}{c_1})^{-1}$.
\end{proof}






