\section{Consistency Estimates}\label{sec-Consistency}
In this section, we derive several
estimates that deal with the lack of $\bH^1$-conformity
of the finite element space $\bV_h$.
These results show that, while functions in this space
are not globally continuous on $\Gamma_{h,k}$
they possess sufficient ``weak continuity'' properties
to ensure the finite element method presented in the subsequent section
converges with optimal order.
To derive such estimates, we make the following assumption
on the location of the edge degrees of freedom.
\begin{assumption}
We assume that the location of the edge DOFs of $\bV_h$
correspond to the $\bPsi$-mapped $(r+1)$-point Gauss-Lobatto rule.
%
We further assume  the surface $\gamma$ (and hence $\bp$) is smooth with 
\begin{equation}
\label{eqn:GammaPsmooth}
\|\bp\|_{W^{2r+1}_\infty(\Gamma_{h,k})}\lesssim 1.
\end{equation}
\end{assumption}


We define the jump of a given elementwise-smooth (with respect to $\calT_{h,k}^\gamma$) vector-valued function $\bv$ across $e^\gamma$
as
\begin{align*}
\jump{\bv}|_{e^\gamma} = \bv_+\otimes \bn^\gamma_+ + \bv_- \otimes \bn^\gamma_-,
\end{align*}
where $e^\gamma = \p K^\gamma_+\cap \p K^\gamma_-\ (K^\gamma_{\pm}\in \calT_{h,k}^\gamma)$, $\bv_{\pm} = \bv|_{K^\gamma_\pm}$, and $\bnu^\gamma_{\pm}$
is the outward unit co-normal with respect to $\p K_{\pm}^\gamma$.
Likewise, given an elementwise-smooth quantity $v$, let $\{v \}|_e = \frac12(v_++v_-)$ denote the average value of $v$ on the mesh skeleton.







Recall $\bV(K)$ is the space of functions in $\bV_h$ restricted to $K\in \calT_{h,k}$.
%
For a given $\bv\in \bV_h$, we define
$\bv_I$ such that $\bv_I|_K\in \bV(K)$ for all $K\in \calT_{h,k}$ and 
\begin{equation}\label{eqn:bvcConstruction}
\bv_I|_K (a) = \calP_{\bp|_K^{-1}} \calP_{\bp} \bv_{K_a}(a)\qquad \forall K\in \calT_a,\ \forall a\in \calN_{h,k}.
\end{equation}
In further detail, we have
\begin{align*}
\bv_I|_K(a) 
%&=  \calP_{\bp^{-1}}|_{K} \calP_{\bp} \bv_{K_a}(a) = \mu_K(a)\left[
% {\bf I}- \frac{\bnu_K(a)\otimes \bnu(a)}{\bnu_K(a)\cdot \bnu(a)}\right]
%  [{\bf I}-d(a) {\bf H}(a)]^{-1}( \calP_{\bp} \bv_{K_a}(a))\\
%  %
%& = \frac{\mu_K(a)}{\mu_{K_a}(a)} \left[
% {\bf I}- \frac{\bnu_K(a)\otimes \bnu(a)}{\bnu_K(a)\cdot \bnu(a)}\right]\bPi(a) \bv_{K_a}(a)\\
% %
 & = \frac{(\bnu\cdot \bnu_K)(a)}{(\bnu\cdot \bnu_{K_a})(a)} \left[
 {\bf I}- { \frac{ \bnu(a) \otimes \bnu_K(a)}{\bnu(a) \cdot \bnu_K(a)} } \right]\bPi(a) \bv_{K_a}(a)\qquad \forall K\in \calT_a,\ \forall a\in \calN_{h,k}.
\end{align*}
%
By co-normal-preserving properties
of the Piola transform, there holds $\bv_I\in \bH({\rm div}_{\Gamma_{h,k}};\Gamma_{h,k})$.
Furthermore, using Lemma \ref{lem:PiolaD}, we have $|(\bv-\bv_I)_K(a)|\lesssim h^{2k} |\bv_{K_a}(a)|$. Because $\bv,\bv_I|_K\in \bV(K)$, 
a scaling estimate yields the following result.
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:NTS1}
For a given $\bv\in \bV_h$, let $\bv_I$ be uniquely determined by \eqref{eqn:bvcConstruction}.
Then there holds
\begin{equation}
\label{eqn:NTS1}
\|\pt \bv-\pt \bv_I\|_{L_2(\gamma)}+h \|\pt \bv - \pt \bv_I\|_{H^1(\gamma)}\lesssim h^{2k} \|\pt \bv\|_{L_2(\gamma)}.
\end{equation}
\end{lemma}
\begin{proof} 
By a change of variables and \eqref{eqn:PiolaBounds}, we have ($m=0,1$) 
\begin{align*}
\|\pt \bv - \pt \bv_I\|_{H^m(K^\gamma)}
&\lesssim \|\bv -\bv_I\|_{H^m(K)} = \|\calP_{\bPsi} (\bar \bv- \bar \bv_I)\|_{H^m(K)}\\
&\lesssim \|\calP_{\bPsi}\|_{W^m_\infty(\bar K)} \|\bar \bv-\bar \bv_I\|_{H^m(\bar K)}\lesssim \|\bar \bv-\bar \bv_I\|_{H^m(\bar K)},
\end{align*}
where $\bar \bv = \bv \circ \bPsi$ and $\bar \bv_I = \bv_I \circ \bPsi$.
Both $\bar \bv$ and $\bar \bv_I$ are polynomials of degree $r$ on $\bar K$, so a simple scaling argument and \eqref{eqn:PiolaBounds} yields
\begin{align*}
\|\bar \bv-\bar \bv_I\|_{H^m(\bar K)}^2
&\lesssim \sum_{\bar a\in \bar \calN_{\bar K}} h^{2-2m} |(\bar \bv-\bar \bv_I)(\bar a)|^2\\
%
& = \sum_{\bar a\in \bar \calN_{\bar K}} h^{2-2m} |\calP_{\bPsi^{-1}} \calP_{\bPsi} (\bar \bv-\bar \bv_I)(\bar a)|^2\\
%
&\le \|\calP_{\bPsi^{-1}}\|^2_{L_\infty(K)} \sum_{a\in \calN_K} h^{2-2m} |(\bv-\bv_I)(a)|^2\lesssim   \sum_{a\in \calN_K} h^{2-2m+4k}|\bv_{K_a}(a)|^2.
\end{align*}
A similar scaling argument shows $h^2 \sum_{a\in \calN_K} |\bv_{K_a}(a)|^2\lesssim  \|\bv\|_{L_2(\omega_K)}^2$.
%where $\omega_K$ 
%is the patch of curved simplices abutting $K$.
Therefore
\[
\|\pt \bv - \pt \bv_I\|_{H^m(K^\gamma)}\lesssim h^{2k-m} \|\bv\|_{L_2(\omega_K)}\lesssim h^{2k-m} \|\pt{\bv}\|_{L_2(\omega_{K^\gamma})},
\]
and the result \eqref{eqn:NTS1} follows by summing over $K^\gamma\in \calT^\gamma_{h,k}$.
\end{proof}

Note that $\pt \bv_I$ is {not} continuous on $\gamma$, but is single-valued at the 
(projected) nodal points on $\gamma$.  We  exploit this fact
to derive estimates of the jump across edges of 
the mesh $\calT_{h,k}^\gamma$ % = \{\bp(K):\ K\in \calT_{h,k}\}$ 
using error estimates of Gauss-Lobatto
integration rules.  




%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lem:JUMP}
For given $\bv\in \bV_h$, let $\bv_I$ be defined by \eqref{eqn:bvcConstruction}, 
and let ${\bf G}$ be a piecewise smooth matrix-valued function on $\gamma$.
Then there holds on all $e\in \calE_{h,k}$,
\begin{equation}
\label{eqn:JumpEst}
\left|\int_{e^\gamma} \{{\bf G}\} :\jump{\pt \bv_I}\right| \lesssim h^{r+s}  \big(\|{\bf G}\|_{W^{2r}_\infty(K_+^\gamma)}+\|{\bf G}\|_{W^{2r}_\infty(K_-^\gamma)}\big) \big( \| \bv_I \|_{H^s( K_+)}+\|\bv_I\|_{H^s(K_-)}\big)\quad s=0,1,2,\ldots,r,
\end{equation}
%
where $e = \p K_+\cap \p K_-$ and $e^\gamma = \bp(e)= {\p K^\gamma_+\cap \p K^\gamma_-}$.
\end{lemma}
\begin{proof}
Let $e$ be an edge of $\calT_{h,k}$, and let $\bar e$ be an edge of $\bar \calT_h$
with $e = \bPsi(\bar e)$. %We also let $e^\gamma = \bp(e)$ be the corresponding edge
%on $\calT_{h,k}^\gamma$. 
By a change of variables, we have
\begin{align*}
\int_{e^\gamma}  \{{\bf G}\} :\jump{\pt \bv_I} = \int_e ( \{{\bf G}\} :\jump{\pt \bv_I})\circ \bp |\nab \bp \bt_e| = \int_{\bar e} \big((\{{\bf G}\}  :\jump{\pt \bv_I}) \circ \bp |\nab\bp \bt_e|\big)\circ \bPsi  |\nab \bPsi \bt_{\bar e}|.
\end{align*}
%
Set $\bar{\pt \bv}_I = \pt{\bv}_I \circ \bp \circ \bPsi$, $\bar {\bf G} = {\bf G}\circ \bp \circ \bPsi$, and $\sigma_{\bar e} =  |\nab\bp \bt_e|\circ \bPsi  |\nab \bPsi \bt_{\bar e}|$ so that
\begin{align*}
\int_{e^\gamma}  \{{\bf G}\} :\jump{\pt \bv_I} = \int_{\bar e}  \{ \bar {\bf G}\}  :\big[{\bar{\pt\bv}_I}\big] \sigma_{\bar e},
\end{align*}
where $\big[{\bar{\pt\bv}_I}\big] = \bar{\pt \bv}_I\big|_{\bar K_+} \otimes (\bn_{K^\gamma_+}\circ \bp\circ \bPsi)+
\bar{\pt \bv}_I\big|_{\bar K_-} \otimes (\bn_{K^\gamma_-}\circ \bp\circ \bPsi)$.

%
Because  ${\bar{\pt\bv}_I}$ is single valued at the Gauss-Lobatto nodes and $(\bn_{K^\gamma_+}\circ \bp\circ \bPsi) = -(\bn_{K^\gamma_-}\circ \bp\circ \bPsi)$ on $\bar e$,
we conclude  $ \{{\bf G}\}  :\big[{\bar{\pt\bv}_I}\big]$ vanishes at the Gauss-Lobatto points of $\bar e$. By the error estimate of the $(r+1)$-point Gauss-Lobatto rules, we have
%
\begin{align}\label{eqn:GLEstimate}
\left|\int_{e^\gamma}  \{ {\bf G}\}  :\jump{\pt \bv_I}\right|\lesssim h^{2r+1} \big(\|\bar {\bf G}\|_{W^{2r}_\infty(\bar K_+)}+\|\bar {\bf G}\|_{W^{2r}_\infty(\bar K_-)}\big)\big( \| \bar {\pt\bv}_I\|_{W^{2r}_\infty(\bar K_+)}+
\|\bar{\pt\bv}_I\|_{W^{2r}_\infty(\bar K_-)}\big) \|\sigma_{\bar e}\|_{W^{2r}_{\infty}(\bar e)},
\end{align}
where $\bar K_{\pm}\in \bar \calT_h$ with $\bar e = \p \bar K_+\cap  \p \bar K_-$. 

By \eqref{eqn:bPsiHSBound} and \eqref{eqn:Ptang}, there holds $\| |\nab \bPsi \bt_{\bar e}|\|_{W^{2r}_\infty(\bar e)} \lesssim 1$.
Likewise, since $\bt_e\circ \bPsi = \nab \bPsi \bt_{\bar e}/|\nab \bPsi \bt_{\bar e}|$, we have $\|\bt_e\|_{W^{2r}_\infty(e)}\lesssim 1$
by \eqref{eqn:bPsiHSBound} and \eqref{eqn:Ptang}. It then follows 
from the chain rule, \eqref{eqn:bPsiHSBound}, \eqref{eqn:GammaPsmooth},  \eqref{eqn:Ptang} , and a change of variables (cf.~Lemma \ref{lem:ChangeVarE}), 
that $\||\nab \bp \bt_e|\circ \bPsi\|_{W^{2r}_\infty(\bar e)}\lesssim \||\nab \bp \bt_e|\|_{W^{2r}_\infty(e)}\lesssim 1$.
Consequently, we have
%
\begin{align}\label{eqn:SigmaBound}
\|\sigma_{\bar e}\|_{W^{2r}_{\infty}(\bar e)}\lesssim 1.
\end{align}
%
By \eqref{eqn:GammaPsmooth}, \eqref{eqn:bPsiHSBound} and a change of variables, we have 
\begin{equation}
\label{eqn:ptbvcBound}
\begin{split}
\|\bar {\pt \bv}_I \|_{W^{2r}_\infty(\bar K_+)} + \|\bar {\pt\bv}_I \|_{W^{2r}_{\infty}(\bar K_-)}&\lesssim \| {\pt\bv}_I \|_{W^{2r}_{\infty}( K^\gamma_+)}+\|\pt\bv_I\|_{W^{2r}_\infty(K^\gamma_-)},\\
 \|\bar  {\bf G} \|_{W^{2r}_{\infty}(\bar K_+)}+ \|\bar  {\bf G} \|_{W^{2r}_{\infty}(\bar K_-)}&\lesssim  \| {\bf G} \|_{W^{2r}_{\infty}( K^\gamma_+)}+\|{\bf G}\|_{W^{2r}_\infty(K^\gamma_-)} .
 \end{split}
 \end{equation}
 %
  We use \eqref{eqn:GLEstimate}, \eqref{eqn:SigmaBound}, and \eqref{eqn:ptbvcBound} along with \eqref{eqn:ugh} to conclude
\begin{align}\label{eqn:GLEstimate2}
\left|\int_{e^\gamma}  \{{\bf G}\} :\jump{\pt \bv_I}\right|\lesssim h^{2r+1} \big(\| {\bf G} \|_{W^{2r}_{\infty}( K^\gamma_+)} +\|{\bf G}\|_{W^{2r}_\infty(K^\gamma_-)}\big)\big(  \| \bv_I \|_{W^{2r}_{\infty}( K_+)}
+\| \bv_I \|_{W^{2r}_{\infty}( K_-)}\big),
\end{align}
and the desired result now follows from the inverse estimate \eqref{eqn:HOIE}. 
 \end{proof}


