\begin{lemma}
\label{lem:edgejumpest}
For given $\bv\in \bV_h$, let $\bv_I$ be defined by \eqref{eqn:bvcConstruction}.  Then for $0 \le s \le r$, 
%Then there exists $\pt{\bv}_c\in C^0(\gamma)$ such that
\begin{align}\label{eqn:NTS3}
\sum_{e\in \calE_{h,k}} h^{-1}  \|\jump{\pt{\bv}_I}\|_{L_2(e^\gamma)}^2 \lesssim h^{2s} \|\pt\bv_I\|_{H_{h}^s(\gamma)}^2.
%\|\pt{\bv}_c-\pt{\bw}\|_{L_2(\gamma)}+ h \|\pt{\bv}_c-\pt{\bw}\|_{H^1(\gamma)}\lesssim h^2 \|\pt \bv_c\|_{H^1(\gamma)}.
\end{align}
\end{lemma}
\begin{proof}
We construct $\bv_c \approx \bv_I$ such that $\pt{\bv}_c \in {\bm C}(\gamma)$.
%The construction of such a  $\bv_c$ follows from the arguments in \cite[Lemma 3.4]{DemlowNeilan23}.
Let $\bar \bw$ be the continuous, {tri}-piecewise polynomial of degree $r$ (w.r.t. $\bar \calT_h$) such that $\bar \bw(\bar a) = \pt \bv_{K_a}(\bp(a))= \pt \bv_I(\bp(a))$ for $a\in \calN_{h,k}$, where $a = \bPsi(\bar a)$.  We then set 
\begin{align}
\label{vcdef}
\pt{\bv}_c = \bPi \bar \bw \circ \bPsi^{-1} \circ \bp^{-1}, 
\end{align}
and $\bar \bv_I = \calP_{\bPsi^{-1}} \bv_I$.
Using norm equivalence, we then have for $m=0,1$ and all $K^\gamma$
\[
\begin{aligned} 
\|\pt \bv_c-\pt \bv_I\|_{H^m(K^\gamma)} 
& = \|\bPi( \bar \bw \circ \bPsi^{-1} \circ \bp^{-1}- \calP_{\bp} \calP_{\bPsi} \bar \bv_I)\|_{H^m(K^\gamma)} 
\\ & \lesssim \|\bar \bw \circ \bPsi^{-1} \circ \bp^{-1}- \calP_{\bp} \calP_{\bPsi} \bar \bv_I\|_{H^m(K^\gamma)} \lesssim \|\bar \bw-(\calP_{\bp} \circ \bPsi) \calP_{\bPsi} \bar \bv_I\|_{H^m(\bar K)}.
\end{aligned} 
\]
Because $\pt \bv_I$ is single-valued at nodes and $\bar\bw$ coincides with $\pt \bv_I$ at nodes, we have that $\bar \bw$ is the elementwise degree-$r$ Lagrange interpolant of  $\pt \bv_I=\calP_{\bp} \calP_{\bPsi} \bar \bv_I$.  
We thus have 
\begin{align}
\label{vcest}
 \begin{aligned} 
h^m  \|\pt \bv_c-\pt \bv_I\|_{H^m(K^\gamma)} &  \lesssim h^{r+1} |(\calP_{\bp} \circ \bPsi) \calP_{\bPsi} \bar \bv_I|_{H^{r+1}(\bar K)}
\\ & \lesssim h^{r+1} \sum_{j=0}^{r} |(\calP_{\bp} \circ \bPsi) \calP_{\bPsi} |_{W_\infty^{r+1-j}(\bar K)} |\bar \bv_I|_{H^j(\bar K)} 
\\ & \lesssim h^{s+1} \|\bar \bv_I\|_{H^s(\bar K)} \lesssim h^{s+1} \|\pt \bv_I\|_{H^s(K^\gamma)}.
\end{aligned} \end{align}
In the last line we have used the inverse estimate $|\bar \bv_I|_{H^j(\bar K)} \lesssim h^{s-j} \|\bar \bv_I\|_{H^s(\bar K)}$, $s \le j \le r$, along with \eqref{eqn:bPsiHSBound}, \eqref{eqn:PiolaBounds}, and \eqref{eqn:PiolaPBounds}.
%and $\|\calP_{\bPsi}\|_{W_\infty^m(K)} \lesssim 1$ (the latter being an easily proved extension of \eqref{eqn:PiolaBounds}).}  
The desired estimate then follows by noting that $\|\jump{\pt{\bv}_I}\|_{L_2(e^\gamma)}=  \|\jump{\pt{\bv}_I-\pt \bv_c}\|_{L_2(e^\gamma)}$ and then applying a standard scaled trace inequality followed by the above approximation bound.  
\end{proof}


