\begin{lemma}
Given $\bv \in \bV_h$, there holds
\begin{align}
\label{korn:contsurf}
\|\pt{\bv}\|_{H_h^1(\gamma)} \lesssim \|\pt{\bv} \|_{L_2(\gamma)} + \|{\rm Def}_{\gamma, h} \pt{\bv} \|_{L_2(\gamma)}
\end{align}
and
\begin{align}
\label{korn:discsurf}
\|\bv\|_{H_h^1(\Gamma_{h,k})} \lesssim \|\bv \|_{L_2(\Gamma_{h,k})} + \|{\rm Def}_{\Gamma_{h,k},h}\bv\|_{L_2(\Gamma_{h,k})}.
\end{align}
\end{lemma}
\begin{proof}
Let $\pt{\bv}_c\in {\bm C} (\gamma) \cap {\bm H}_T^1(\gamma)$ be as defined in \eqref{vcdef}.  Combining \eqref{eqn:NTS1} and \eqref{vcest} with $m=1$ and $s=0$ yields
$$\|\pt{\bv}-\pt{\bv}_c\|_{H_h^1(\gamma)} \lesssim \|\pt{\bv}\|_{L_2(\gamma)}.$$
With this relationship and \eqref{eqn:DefChain} in hand, the proofs of \eqref{korn:contsurf} and \eqref{korn:discsurf} are completed essentially as in \cite[Lemma 3.5]{DemlowNeilan23} and \cite[Lemma 3.6]{DemlowNeilan23}, respectively. 
\end{proof}

