\section{Finite element method and convergence analysis}\label{sec-FEM}
We define the bilinear forms
\begin{align*}
a(\bv,\bw) 
&= \int_{\gamma} \left(({\rm Def}_{\gamma,h}\bv):
 ({\rm Def}_{\gamma,h}\bw)+ \bv\cdot \bw\right),\\
 b(\bv,q)
 & = -\int_{\gamma} ({\rm div}_\gamma \bv)q,
 \end{align*}
 where ${\rm Def}_{\gamma,h}\bv|_{K^\gamma} = {\rm Def}_{\gamma}\bv|_{K^\gamma}\ \forall K^\gamma\in \calT_{h,k}^\gamma$
 is the piecewise defined deformation operator.
The variational formulation of the surface Stokes problem then reads:
 find $(\bu,p)\in \bH^1_T(\gamma)\times \mathring{L}_2(\gamma)$ such that
\begin{equation}
\label{eqn:StokesVariational}
 \begin{aligned}
 a(\bu,\bv) + b(\bv,p) & = \int_\gamma {\bm f}\cdot \bv\qquad &&\forall \bv\in \bH^1_T(\gamma),\\
 %
 b(\bu,q)& = 0\qquad &&\forall q\in \mathring{L}_2(\gamma).
 \end{aligned}
 \end{equation}
The relevant continuous inf-sup condition for this problem is found in \cite{JankuhnEtal18}; well-posedness follows.  Here the mass term is added to the standard Stokes equations in order to avoid possible degeneracies due to the presence of Killing fields \cite{SurfaceStokes1}.  Finally, $H^2$ regularity results for surface Stokes equations posed are contained in \cite{ORZ21}, while higher-order regularity is proved in \cite{BNSPP}.  Below we assume these results without direct citation.

 The analogous bilinear forms defined on $\Gamma_{h,k}$ are given by
\begin{align*}
a_h(\bv,\bw) 
&= %\sum_{K \in \calT_{h,k}} \int_{K} 
\int_{\Gamma_{h,k}}\left(({\rm Def}_{\Gamma_{h,k},h}\bv):
 ({\rm Def}_{\Gamma_{h,k},h}\bw)+ \bv\cdot \bw\right),\\
 b_h(\bv,q)
 & = -\int_{\Gamma_{h,k}} ({\rm div}_{\Gamma_{h,k}} \bv)q,
 \end{align*}
 where $ {\rm Def}_{\Gamma_{h,k},h}\bv|_K =  {\rm Def}_{\Gamma_{h,k}} \bv|_K\ \forall K\in \calT_{h,k}$.
 The finite element method seeks $(\bu_h,p_h)\in \bV_h \times Q_h$ such that 
 %
 \begin{equation}
\label{eqn:FEM}
 \begin{aligned}
 a_h(\bu_h,\bv) + b_h(\bv,p_h) & = \int_{\Gamma_{h,k}} {\bm f}_h \cdot \bv\qquad &&\forall \bv\in \bV_h,\\
 %
 b_h(\bu_h,q)& = 0\qquad &&\forall q\in Q_h.
 \end{aligned}
 \end{equation}
 The existence and uniqueness of a solution to \eqref{eqn:FEM} follows
from the inf-sup condition \eqref{eqn:THInfSup} and the discrete Korn inequality \eqref{korn:discsurf}.
Furthermore, there holds $\|\bu_h\|_{H^1_h(\Gamma_{h,k})}+\|p_h\|_{L_2(\Gamma_{h,k})}\lesssim \|{\bm f}_h\|_{L_2(\Gamma_{h,k})}$.


