 \begin{lemma}
 \label{lem:consist1}
 Define the bilinear form
 $G_h:\bH^1_h(\Gamma_{h,k})\times \bH_h^1(\Gamma_{h,k}) \rightarrow \mathbb{R}$ by
 \begin{align}
 \label{eqn:GhDef}
 G_h(\bw,\bv) = a(\pt{\bw},\pt{\bv}) - a_h(\bw,\bv).
 \end{align}
 There holds
 \begin{align}\label{eqn:GhEstimate}
 |G_h(\bv,\bw)|\lesssim h^k \|\pt{\bv}\|_{H^1_h(\gamma)} \|\pt{\bw}\|_{H^1_h(\gamma)}.
 \end{align}
 \end{lemma}
 \begin{proof}
The arguments in \cite[(4.8)]{DemlowNeilan23} and surrounding may be easily adapted to the current case of higher-order surface approximations to yield
\begin{align}
\label{l2geo}
\int_{\Gamma_{h,k}} \bw\cdot \bv -\int_\gamma \pt{\bw} \cdot \pt{\bv} \lesssim h^{k+1}\|\bw\|_{L_2(\Gamma_{h,k})} \|\bv \|_{L_2(\Gamma_{h,k})}.
\end{align} 
 The desired result then directly follows from \eqref{l2geo}, \eqref{eqn:DefChain}, and the arguments in \cite[Lemma 4.2]{DemlowNeilan23}.   Therefore its proof is omitted.
 \end{proof}


 The following lemma improves the geometric consistency error, provided
