\subsection{Convergence Analysis}
We start the convergence analysis by introducing
the discretely divergence-free subspace of $\bV_h$:
\[
\bX_h = \{\bv\in \bV_h:\ b_h(\bv,q)=0\ \forall q\in Q_h\}.
\]
%For $\bv\in \bV_h$, let $\bv_I$ be defined by \eqref{eqn:bvcConstruction}.  
We also set
\[
{\bm F}_h = \big[{\bf I}-d {\bf H}]^{-1} \left[ {\bf I} - \frac{\bnu_h\otimes \bnu}{\bnu_h\cdot \bnu}\right] \bPi_h {\bm f}_h,
\]
so that (cf.~\cite{DemlowNeilan23})
\begin{equation}\label{eqn:CapF}
\int_{\Gamma_{h,k}} {\bm f}_h \cdot \bv = \int_{\Gamma_{h,k}} (\bPi_h {\bm f}_h) \cdot \bv = \int_{\gamma} {\bm F}^\ell_h \cdot \pt{\bv}\qquad \forall \bv\in \bL_2(\Gamma_{h,k}),\ \bv\cdot \bnu_h = 0.
\end{equation}
\begin{remark}[Choice of ${\bm f}_h$]
Using $[{\bf I}-d {\bf H}]^{-1} \bnu = \bnu$ and $\bnu \otimes \bnu \frac{\bnu_h \otimes \bnu}{\bnu\cdot \bnu_h} = \bnu \otimes \bnu$, we have
\begin{align*}
{\bm F}_h 
&= \left(\big[{\bf I}-d {\bf H}\big]^{-1} \left[ {\bf I} - \frac{\bPi \bnu_h\otimes  \bnu}{\bnu\cdot \bnu_h}\right] {-} \bnu\otimes \bnu\right)\bPi_h{\bm f}_h\\
%
&= \big[{\bf I}-d {\bf H}\big]^{-1} \left[ {\bf I} - \frac{\bPi \bnu_h\otimes  \bPi_h \bnu}{\bnu\cdot  \bnu_h}\right] {\bm f}_h - ((\bPi_h {\bm f}_h)\cdot \bnu)\bnu
\end{align*}
Consequently, using {$\pt{\bv} \cdot \bnu=0$,} $|\bPi \bnu_h|\lesssim h^k$, $|\bPi_h \bnu|\lesssim h^k$, and $|d|\lesssim h^{k+1}$, we conclude
\begin{align}\label{eqn:FsDiff}
\int_\gamma ({\bm f}-{\bm F}_h^\ell)\cdot \pt{\bv}\lesssim \left(\|{\bm f}-\bPi {\bm f}_h^\ell\|_{L_2(\gamma)} + h^{k+1} \|{\bm f}_h^\ell\|_{L_2(\gamma)}\right)\|\pt{\bv}\|_{L_2(\gamma)}\qquad \forall \bv\in \bV_h.
\end{align}
Choosing for example either ${\bm f}_h = {\bm f}^\ell$ or ${\bm f}_h = \ipt{\bm f}$, we obtain $\|{\bm f}-\bPi {\bm f}_h^\ell\|_{L_2(\gamma)} \lesssim h^{k+1} \|{\bm f}\|_{L_2(\gamma)}$.  Thus
\begin{align}
\label{fhest}
\int_\gamma ({\bm f}-{\bm F}_h^\ell)\cdot \pt{\bv} \lesssim h^{k+1} \|{\bm f}\|_{L_2(\Gamma)} \hbox{ and } \|{\bm f}_h\|_{L_2(\Gamma_{h,k})} \lesssim \|{\bm f}\|_{L_2(\gamma)}.
\end{align}
It is possible to obtain optimal-order convergence under more general assumptions on the choice of ${\bm f}_h$, but we assume \eqref{fhest} below in order to simplify our presentation.

\end{remark}


