\begin{theorem}\label{thm:EnergyConv}
Let $(\bu_h,p)\in \bV_h \times Q_h$ satisfy the finite element
method \eqref{eqn:FEM} and assume the exact solution satisfies $(\bu,p)\in \bH^{r+1}(\gamma)\times H^{r}(\gamma)$.  Assume also that ${\bm f}_h$ is chosen so that \eqref{fhest} is satisfied. 
Then there holds
\begin{align}\label{eqn:EnergyError}
%\begin{aligned} 
\|\bu-\pt{\bu}_h\|_{H^1_h(\gamma)}  +\|p-p^\ell\|_{L_2(\gamma)}  &\lesssim h^{r} (\|\bu\|_{H^{r+1}(\gamma)}+\|p\|_{H^r(\gamma)}) + h^k \|{\bm f}\|_{L_2(\gamma)}. 
% \\
%&\qquad+ }. %+ h^k \|{\bm f}_h\|_{L_2(\Gamma_{h,k})}+\|{\bm f}-{\bm F}^\ell_h\|_{L_2(\gamma)}.
%\end{aligned}
\end{align}
\end{theorem}
\begin{proof}
Given $\bv \in \bX_h$, we add and subtract terms and use \eqref{eqn:GhEstimate} to obtain
\begin{equation}
\label{eqn:ConstStart}
\begin{split}
a(\bu-\pt{\bu}_h,\pt{\bv}) 
&= \Big[a(\bu,\pt{\bv}) - \int_\gamma {\bm f}\cdot \pt{\bv}\Big] + \int_\gamma ({\bm f}-{\bm F}^\ell_h)\cdot \pt{\bv} + G_h(\bu_h,\bv)\\
%
&\lesssim \Big[a(\bu,\pt{\bv}) - \int_\gamma {\bm f}\cdot \pt{\bv}\Big] +\big(\|{\bm f}-{\bm F}^\ell_h\|_{L_2(\gamma)} +h^k \|\pt{\bu}_h\|_{H^1_h(\gamma)}\big)\|\pt{\bv}\|_{H^1_h(\gamma)}.
%
%&\quad = \Big[a(\bu,\pt{\bv}_I) - \int_\gamma {\bm f}\cdot \pt{\bv}_I\Big] +\Big[a(\bu,\pt\bv-\pt\bv_I)-\int_\gamma {\bm f} \cdot (\pt \bv-\pt\bv_I)\Big]+ \int_\gamma ({\bm f}-{\bm F}^\ell_h)\cdot \pt{\bv} + G_h(\bu_h,\bv).
\end{split}
\end{equation}
%
%Applying the estimates \eqref{eqn:NTS1} and \eqref{eqn:GhEstimate} yields
%%
%\begin{equation}
%\label{eqn:ConstStart2}
%\begin{split}
%&a(\bu-\pt{\bu}_h,\pt{\bv})
%%&\lesssim  \Big[a_\gamma(\bu,\pt{\bv}_I) - \int_\gamma {\bm f}\cdot \pt{\bv}_I\Big]  +\left(h^{2k-1} \|\bu\|_{H^1(\gamma)}+h^{2k} \|{\bm f}\|_{L_2(\gamma)}+\|{\bm f}-{\bm F}_h^\ell\|_{L_2(\gamma)}\right)\|\pt{\bv}\|_{L_2(\gamma)}\\
%%&\qquad+ h^k \|\pt{\bu}_h\|_{H^1_h(\gamma)} \|\pt{\bv}\|_{H^1_h(\gamma)}\\
%%
%\lesssim  \Big[a(\bu,\pt{\bv}_I) - \int_\gamma {\bm f}\cdot \pt{\bv}_I\Big]\\
%&\quad  +\left(h^{2k-1} \|\bu\|_{H^1(\gamma)}+h^{2k} \|{\bm f}\|_{L_2(\gamma)}
%+\|{\bm f}-{\bm F}_h^\ell\|_{L_2(\gamma)}
%%+\|{\bm f}-{\bm f}_h^\ell\|_{L_2(\gamma)}
%%+h^{k+1}\|{\bm f}^\ell_h\|_{L_2(\gamma)}
%+h^k \|\pt{\bu}_h\|_{H^1_h(\gamma)}\right)\|\pt{\bv}\|_{H_h^1(\gamma)}.
%%&\qquad+ h^k \|\pt{\bu}_h\|_{H^1_h(\gamma)} \|\pt{\bv}\|_{H^1_h(\gamma)} 
%\end{split}
%\end{equation}
%for all $\bv\in \bX_h$.
%

Using integration by parts, we find
\begin{equation}\label{eqn:aIBP}
\begin{split}
a(\bu,\pt{\bv}) 
&= \sum_{K\in \calT_{h,k}} \int_{K^\gamma} {\rm Def}_{\gamma} \bu:{\rm Def}_\gamma \pt{\bv} + \int_\gamma \bu\cdot \pt{\bv}\\
%
&= -\int_{\gamma} {\rm div}_\gamma ({\rm Def}_{\gamma} \bu ) \cdot \pt{\bv}
+  \sum_{K\in \calT_{h,k}} \int_{\p K^\gamma} ({\rm Def}_{\gamma} \bu) \bn_{\p K^\gamma} \cdot {\pt{\bv}} + 
\int_\gamma \bu\cdot \pt{\bv}\\
%
%& = \int_{\gamma} {\bm f}\cdot \pt{\bv}_I - \int_{\gamma} \nab_\gamma p \cdot \pt{\bv}_I
%+  \sum_{K\in \calT_{h,k}} \int_{\p K^\gamma} ({\rm Def}_{\gamma} \bu) : (\pt{\bv}_I\otimes \bn_{\p K^\gamma})\\
%
& = \int_{\gamma} {\bm f}\cdot \pt{\bv} - b(\pt{\bv},p)
+  \sum_{e\in \calE_{h,k}} \int_{e^\gamma} ({\rm Def}_{\gamma} \bu) : \jump{\pt{\bv}}.
\end{split}
\end{equation}


Therefore by the divergence-preserving properties of the Piola transform {and since $\bv$ is discretely divergence-free},
{
\begin{align*}
a(\bu,\pt{\bv}) & = \int_{\gamma} {\bm f}\cdot \pt{\bv} - b(\pt{\bv},p-q^\ell)%-b(\pt{\bv}_I-\pt{\bv},p)
+  \sum_{e\in \calE_{h,k}} \int_{e^\gamma} ({\rm Def}_{\gamma} \bu) : \jump{\pt{\bv}}\quad \forall \bv\in \bX_h,\ \forall q\in Q_h.
\end{align*}
}
%
We then find using Lemma \ref{lem:JumpDef} with $t=r-1$ and $s=1$ that 
\begin{align*}
a(\bu,\pt{\bv}) - \int_\gamma {\bm f}\cdot \pt{\bv}
&\lesssim \|p-q^\ell\|_{L_2(\gamma)} \|\pt\bv\|_{H^1_h(\gamma)} + h^{2k-1} \|\bu\|_{H^2(\gamma)} \|\pt{\bv}\|_{L_2(\gamma)} + h^{r} \|\bu\|_{H^{r}(\gamma)} \|\pt \bv\|_{H^1_h(\gamma)}\\
%
&\lesssim \big(\|p-q^\ell\|_{L_2(\gamma)}+ h^{2k-1} \|\bu\|_{H^2(\gamma)}  + h^{r} \|\bu\|_{H^{r}(\gamma)}\big) \|\pt\bv\|_{H^1_h(\gamma)} .
\end{align*}
We apply this estimate to \eqref{eqn:ConstStart} along with   
$\|\pt{\bu}_h\|_{H^1_h(\gamma)}\lesssim \|\bu_h\|_{H^1_h(\Gamma_{h,k})}\lesssim \|{\bm f}_h\|_{L_2(\Gamma_{h,k})}$, $\|\bu\|_{H^2(\gamma)}\lesssim \|{\bm f}\|_{L_2(\gamma)}$,  \eqref{fhest}, and $k \le 2k-1$
to conclude
\begin{align*}
a(\bu-\pt{\bu}_h,\pt{\bv}) 
&\lesssim 
\Big(\|p-q^\ell\|_{L_2(\gamma)}  + h^{r} \|\bu\|_{H^{r}(\gamma)}+ h^k \|{\bm f}\|_{L_2(\gamma)} \Big) \|\pt\bv\|_{H_h^1(\gamma)}
%&\qquad 
%+  h^{2k-1} \|{\bm f}\|_{L_2(\gamma)}+ h^k \|{\bm f}_h\|_{L_2(\Gamma_{h,k})}+\|{\bm f}-{\bm F}^\ell_h\|_{L_2(\gamma)}\Big)
\end{align*}
for all $q\in Q_h$ and $\bv\in \bX_h$. We then take $q\in Q_h$ to satisfy $\|p-q^\ell\|_{L_2(\gamma)}\lesssim h^{r} \|p\|_{H^{r}(\gamma)}$, apply
Strang's lemma, and use the approximation properties of the finite element space $\bV_h$ (cf.~Lemma \ref{lem:ApproxProps})
 to obtain
\begin{align}\label{eqn:velocityH1Error}
\|\bu-\pt{\bu}_h\|_{H^1_h(\gamma)}\lesssim h^{r} (\|\bu\|_{H^{r+1}(\gamma)}+\|p\|_{H^{r}(\gamma)})
+ h^k \|{\bm f}\|_{L_2(\gamma)}% + h^k \|{\bm f}_h\|_{L_2(\Gamma_{h,k})}+\|{\bm f}-{\bm F}^\ell_h\|_{L_2(\gamma)}.
\end{align}

Next, we use \eqref{eqn:FEM}, \eqref{eqn:CapF} and \eqref{eqn:GhDef},
along with the divergence-preserving properties of the Piola transform to write
\begin{align*}
b_h(\bv,p_h - q)
& = \int_\gamma {\bm F}_h^\ell \cdot \pt{\bv} - a(\pt{\bu}_h,\pt{\bv}) -b(\pt{\bv},q^\ell) + G_h(\bu_h,\bv)\\
%
& = 
\left[ \int_\gamma {\bm f}\cdot \pt{\bv} - a(\bu,\pt{\bv})-b(\pt{\bv},p)\right] 
+\int_\gamma ({\bm F}_h^\ell-{\bm f})\cdot \pt{\bv} +a(\bu-\pt{\bu}_h,\pt{\bv}) -b(\pt{\bv},q^\ell-p)+G_h(\bu_h,\bv)
\end{align*}
for all $\bv\in \bV_h$ and $q\in Q_h$. 

We let $q\in Q_h$ satisfy $\|p-q^\ell\|_{L_2(\gamma)}\lesssim h^{r}\|p\|_{H^{r}(\gamma)}$,
and apply % \eqref{eqn:NTS1}
 %\eqref{eqn:FsDiff}, 
 %and 
 \eqref{eqn:GhEstimate} and \eqref{fhest} to obtain
\begin{align*}
&b_h(\bv,p_h - q)\lesssim {\left[ \int_\gamma {\bm f}\cdot \pt{\bv} - a(\bu,\pt{\bv})-b(\pt{\bv},p)\right]}\\
&\qquad+ \left(h^{k+1} \|{\bm f}\|_{L_2(\gamma)}%+h^{2k-1}\|{\bm f}\|_{L_2(\gamma)}
+\|\bu-\pt{\bu}_h\|_{H^1_h(\gamma)} + h^{r}\|p\|_{H^{r}(\gamma)}+h^{k}\|{\bm f}_h\|_{L_2(\Gamma_{h,k})}\right)\|\pt{\bv}\|_{H^1_h(\gamma)}.
%& = -\sum_{e\in \calE_{h,k}} \int_{e^\gamma} ({\rm Def}_\gamma \bu): \jump{\pt{\bv}_I}\\
%&\qquad+ \left(\|{\bm f}-{\bm f}_h^\ell\|_{L_2(\gamma)} +h^{k}\|{\bm f}_h^\ell\|_{L_2(\gamma)}+h^{2k-1}\|{\bm f}\|_{L_2(\gamma)}
%+\|\bu-\pt{\bu}_h\|_{H^1_h(\gamma)} + h^r\|p\|_{H^r(\gamma)}\right)\|\pt{\bv}\|_{H^1_h(\gamma)}.
\end{align*}
Using \eqref{eqn:aIBP} and Lemma \ref{lem:JumpDef}, we have
\begin{align*}
{ \int_\gamma {\bm f}\cdot \pt{\bv} - a(\bu,\pt{\bv})-b(\pt{\bv},p) }
&= 
 -\sum_{e\in \calE_{h,k}} \int_{e^\gamma} ({\rm Def}_\gamma \bu): \jump{\pt{\bv}}\\
 &\lesssim h^{r} \|\bu\|_{H^{r}(\gamma)} \|\pt{\bv}\|_{H_h^1(\gamma)}+h^{2k-1}\|\bu\|_{H^2(\gamma)}\|\pt{\bv}\|_{L_2(\gamma)}.
 \end{align*}
{Thus by \eqref{eqn:velocityH1Error}, \eqref{fhest}, and $\|\bu\|_{H^2(\gamma)}\lesssim \|{\bm f}\|_{L_2(\gamma)}$,
\begin{align*}
%\begin{aligned}
b_h(\bv,p_h -q)  \lesssim   \left ( h^{r} (\|\bu\|_{H^{r+1}(\gamma)}+\|p\|_{H^{r}(\gamma)})
+ h^k\|{\bm f}\|_{L_2(\gamma)} \right ) \|\pt{\bv}\|_{H_h^1(\gamma)}.
%+h^k \|{\bm f}_h\|_{L_2(\Gamma_{h,k})} + \|{\bm f}-{\bm F}_h^\ell\|_{L_2(\gamma)}\right) \|\pt{\bv}\|_{H_h^1(\gamma)}.
%\end{aligned}
\end{align*}
} 

Applying a triangle inequality, norm equivalence, and the discrete inf-sup condition \eqref{eqn:THKMInfSup} then yields for properly chosen 
$\bv \in \bV_h$ with $\|\bv\|_{H_h^1(\Gamma_{h,k})}=1$ that
$$
\begin{aligned}
\|p-p_h^\ell\|_{L_2(\gamma)} & \lesssim \|p-q^\ell\|_{L_2(\gamma)} + b_h(\bv, p_h-q)
\\ & \lesssim h^{r} (\|\bu\|_{H^{r+1}(\gamma)}+\|p\|_{H^{r}(\gamma)}) + h^{k} \|{\bm f}\|_{L_2(\gamma)}. %+h^k \|{\bm f}_h\|_{L_2(\Gamma_{h,k})} + \|{\bm f}-{\bm F}_h^\ell\|_{L_2(\gamma)}.
\end{aligned} $$
This estimate combined with \eqref{eqn:velocityH1Error}  yields the desired result \eqref{eqn:EnergyError}.
\end{proof}



