\section{Proof of Lemma \ref{lem:xPert}}
First, we write
\begin{align}\label{calPPsi}
\calP_{\bPsi_{\bar{K}}}=\calP_{\ba_k} \calP_{F^{-1}_{\bar K}} = 
\frac{\sqrt{ {\rm det} \nabla F_{\bar K}^\top \nabla F_{\bar K}}}{\sqrt{{\rm det} \nabla \ba_k^\top \nabla \ba_k}} \nabla \ba_k (\nabla F_{\bar K}^\top \nabla F_{\bar K})^{-1} \nabla F_{\bar K}^{\top}.
\end{align}
Therefore, for $\bx$ tangent to $\bar K$, and by writing $\ba_k = F_{\bar K}+\ell_k$, we have 
\begin{align*}
\calP_{\bPsi_{\bar{K}}} \bx  
&= \frac{\sqrt{ {\rm det} \nabla F_K^\top \nabla F_{\bar K}}}{\sqrt{{\rm det} \nabla \ba_k^\top \nabla \ba_k}} (\nabla F_{\bar K}+\nab \bell_k) (\nabla F_{\bar K}^\top \nabla F_K)^{-1} \nabla F_{\bar K}^{\top}\bx\\
%
%&= \frac{\sqrt{ {\rm det} \nabla F_K^\top \nabla F_{\bar K}}}{\sqrt{{\rm det} \nabla \ba_k^\top \nabla \ba_k}} \left(\nabla F_{\bar K}\balpha +\nab \bell_k (\nabla F_{\bar K}^\top \nabla F_K)^{-1} \nabla F_{\bar K}^{\top}\bx\right)\\
%
&= \bx + \left(\frac{\sqrt{ {\rm det} \nabla F_K^\top \nabla F_{\bar K}}}{\sqrt{{\rm det} \nabla \ba_k^\top \nabla \ba_k}}-1\right)\bx 
+ \frac{\sqrt{ {\rm det} \nabla F_K^\top \nabla F_{\bar K}}}{\sqrt{{\rm det} \nabla \ba_k^\top \nabla \ba_k}} \nab \bell_k (\nab F_{\bar K}^\top \nab F_{\bar K})^{-1} \nab F_{\bar K}^\top \bx.
\end{align*}
Now $(\nab F_{\bar K}^\top \nab F_{\bar K})(\nab \ba_k^\top \nab \ba_k)^{-1} = {\bf I} + {\bf B}(\nab \ba_k^\top \nab \ba_k)^{-1}$ for some ${\bf B}$ satisfying 
$\|{\bf B}\|_{L_\infty(\hat K)}\lesssim \|\nab \bell\|_{L_\infty(\hat K)}\|\nab \ba_k\|_{L_\infty(\bar K)}+\|\nab \bell\|_{L_\infty(\hat K)}^2$.
Using the estimates \eqref{eqn:FbarEst}--\eqref{eqn:baPert}, we have
%
\[
\det\left((\nab F_{\bar K}^\top \nab F_{\bar K})(\nab \ba_k^\top \nab \ba_k)^{-1}\right) = 1+O(h),
\]
and 
\[
\|\nab \bell_k (\nab F_{\bar K}^\top \nab F_{\bar K})^{-1} \nab F_{\bar K}^\top\|_{L_\infty(\hat K)}\lesssim h.
\]
Combining these two estimates then yields
\begin{align*}
\left|\calP_{\bPsi_{\bar{K}}} \bx -\bx\right| \lesssim h |\bx|
\end{align*}
for all vectors $\bx$ tangent to $\bar K$, and so
\begin{align*}
\left|\calP_{\bPsi^{-1}_{{K}}} \bx -\bx\right| \lesssim h |\calP_{\bPsi^{-1}_K} \bx|\lesssim h |\bx|
\end{align*}
for all vectors $\bx$ tangent to $K$.




