We follow the arguments given in \cite[Lemma 2.3]{NeilanOtus21}.
Set $g = (\det(\nab \ba_K^\intercal \nab \ba_K))^{1/2}:\hat K\to \bbR$.  
Letting $E(m,j) = \{\alpha\in \bbN_0^m:\ |\alpha|=j\text{ and } \sum_{j=1}^m j \alpha_j = m\}$,
there holds the  chain rule \cite{Bernardi89}
\begin{align}
\label{chain_rule}
D^m (f_1\circ f_2) = \sum_{j=1}^m (D^j f_1)\circ f_2 \sum_{\alpha\in E(m,j)} c_\alpha \prod_{i=1}^m (D^i f_2)^{\alpha_i}
\end{align}
for some constants $c_\alpha\in \bbR$.

Now set $f =  \det(\nab \ba_K^\intercal \nab \ba_K)$, so that $g = f^{1/2}=f_1 \circ f_2$ with $f_1(x)=x^{1/2}$ and $f_2=f$.  A simple induction argument and \eqref{eqn:akGood} shows $|f|_{W^m_\infty(\hat K)}\lesssim h^{4+m}$.  Applying \eqref{chain_rule} and recalling \eqref{eqn:akGood} then yields for any multi-index $\beta$ with $|\beta|=m$,
\begin{align*}
\left|\frac{\p^m }{\p \hat x^\beta}g \right|
& =\left|\frac{\p^m }{\p \hat x^\beta}\left(f^{1/2}\right)\right| \lesssim \sum_{j=1}^m |f^{1/2-j}| \sum_{\alpha \in E(m,j)} \prod_{i=1}^m |(D^i f)|^{\alpha_i}
\\ & \lesssim \sum_{j=1}^m h^{4(1/2-j)} \sum_{\alpha \in E(m,j)} \prod_{i=1}^m h^{(4+i)\alpha_i}
 \lesssim \sum_{j=1}^m h^{2-4j} \sum_{\alpha \in E(m,j)} h^{4j+m}
\\ & \lesssim h^{m+2}.
\end{align*}
%
Applying \eqref{chain_rule} now with $f_1(x) = x^{-1}$ and $f_2=g$ and recalling that $g \approx h^2$ from \eqref{eqn:akGood}, we have for any multi-index $\alpha = (\alpha_1,\alpha_2)$ with $|\alpha|=m$
\begin{align*}
\left|\frac{\p^m }{\p \hat x^\alpha}\left(\frac1{g}\right)\right| 
& \lesssim \sum_{j=1}^m |g|^{-(j+1)} \sum_{\alpha \in E(m,j)} \prod_{i=1}^m |(D^i g)|^{\alpha_i}
\\ & \lesssim \sum_{j=1}^m h^{-2(j+1)} \sum_{\alpha \in E({m,j})} \prod_{i=1}^m h^{(i+2)\alpha_i}
\\ & \lesssim \sum_{j=1}^m h^{-2(j+1)} \cdot h^{m+2j}  \lesssim h^{m-2}.
\end{align*}
We then conclude
\begin{align*}
|g^{-1}|_{W^m_\infty(\hat K)} \lesssim h^{m-2}.
%\frac{\p^m }{\p \hat x^\alpha}\left(\frac1{g}\right) 
%\lesssim h^{-2(m+1)}  \sum_{|\beta^{(1)}|+\cdots+|\beta^{(m)}|=m} h^{|\beta^{(1)}|+2} \cdots h^{|\beta^{(m)}|+2}\lesssim h^{m-2}.
