\section{Proof of Lemma \ref{lem:DefCons}}
The proof of the estimate \eqref{eqn:DefChain}
mostly follows from the arguments in \cite[Lemma 2.2]{DemlowNeilan23}, so we only
present the main points.

First, by the chain rule (cf.~(A.1) in \cite{DemlowNeilan23})
we have
\begin{align*}
\nab (\bv\circ \bp^{-1}) \bPi 
&= \left(\nab \bv \bPi_h \big[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\big]\big[{\bf I}- d {\bf H}\big]^{-1}\right)\circ \bp^{-1}.
\end{align*}
Next, set ${\bf H}_h = \nab \bnu_h$ on $K$ (where $\bnu_h$ is extended to $U_\delta$).
Then since $\bPi_h \bv = \bv$, there holds
\[
\nab \bv \bPi_h = \nab (\bPi_h \bv)\bPi_h = \left(\bPi_h \nab \bv- \bnu_h \otimes ({\bf H}_h \bv)\right)\bPi_h = \nab_{\Gamma_{h,k}} \bv - \bnu_h\otimes ({\bf H}_h \bv).
\]
Setting ${\bf L} = \mu_h^{-1} \big[\bPi - d {\bf H}\big]$, we have
\begin{equation}
\label{eqn:ChainRuleFun}
\begin{split}
\nab_\gamma \pt{\bv} 
& = {\bf L} \left( \big(\nab_{\Gamma_{h,k}}\bv )\big) \left[ {\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]
\left[{\bf I}-d {\bf H}\right]^{-1}\right)\circ \bp^{-1}\\
&\qquad  - \left(({\bf L}\bnu_h) \otimes ({\bf H}_h \bv) \left[ {\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]
\left[{\bf I}-d {\bf H}\right]^{-1}\right)\circ \bp^{-1}
%%
%&\qquad 
+ \bPi \nab ({\bf L}\circ \bp^{-1}) \bv\circ \bp^{-1} \bPi.
\end{split}
\end{equation}
Using the estimates $|{\bf L} \bnu_h|\lesssim h^k$
and $|{\bf L}- \bPi_h|\lesssim h^k$
and applying
the same arguments as in \cite[Lemma 2.2]{DemlowNeilan23},
we obtain 
\begin{equation}\label{eqn:DefProof1}
\left|{\rm Def}_{\gamma} \pt{\bv} - ({\rm Def}_{\Gamma_{h,k}} \bv)\circ \bp^{-1}\right|\lesssim 
h^k \big(|(\nab_{\Gamma_{h,k}} \bv)\circ \bp^{-1}| + |\bv\circ \bp^{-1}|\big) + \left|\bPi \nab ({\bf L}\circ \bp^{-1}) \bv\circ \bp^{-1} \bPi\right|.
\end{equation}

Next, we have (cf.~\cite[(A.5)--(A.6)]{DemlowNeilan23})
\begin{align*}
 \left|\bPi \nab ({\bf L}\circ \bp^{-1}) \bv\circ \bp^{-1} \bPi\right|
 &\lesssim \left|\bPi \big(\nab {\bf L} \bv \bPi_h\big)\circ \bp^{-1}\right|,
\end{align*}
%
and 
\begin{align*}
\bPi \nab {\bf L} \bv \bPi_h
& = -\mu_h^{-1} \bPi\left[ ({\bf L}\bv)\otimes \nab \mu_h + \bnu \otimes ({\bf H} \bv)+({\bf H}\bv)\otimes \bnu + (\bnu\cdot \bv) {\bf H} + d \nab {\bf H}\bv\right]\bPi_h\\
%
& = -\mu_h^{-1} \left[ ({\bf L}\bv)\otimes (\bPi_h \nab \mu_h) +({\bf H}\bv)\otimes (\bPi_h \bnu) + (\bnu\cdot \bv) {\bf H}\bPi_h  + d \bPi \nab {\bf H}\bv\bPi_h\right]\\
%
& = -  ({\bf L}\bv)\otimes (\bPi_h \nab \mu_h)+O(h^k |\bv|)
\end{align*}
We write $\mu_h = \bnu\cdot \bnu_h \det({\bf I}-d {\bf H})$
and note that $\nab \det({\bf I}-d {\bf H}) = -\bnu {\rm tr}({\bf H}) +O(h^{k+1})$.
Consequently,
\begin{equation}
\label{eqn:JacobiFun}
\begin{split}
\nab \mu_h 
&= \nab (\bnu\cdot \bnu_h) \det({\bf I}-d {\bf H}) + (\bnu\cdot \bnu_h) \nab \det({\bf I}-d {\bf H})\\
%
& = \big({\bf H}\bnu_h + {\bf H}_h \bnu\big)\det({\bf I}-d {\bf H}) -  {\rm tr}({\bf H})(\bnu\cdot \bnu_h) \bnu +O(h^{k+1})\\
%
& = - {\rm tr}({\bf H}) \bnu + O(h^k).
\end{split}
\end{equation}
Thus using $|\bPi_h \bnu|\lesssim h^k$, we obtain
\begin{align*}
\big|\bPi \nab {\bf L} \bv \bPi_h\big|\lesssim h^k |\bv|,
\end{align*}
and so
\begin{align}\label{eqn:DefProof2}
 \left|\bPi \nab ({\bf L}\circ \bp^{-1}) \bv\circ \bp^{-1} \bPi\right|\lesssim h^k|\bv\circ \bp^{-1}|.
\end{align}
The estimate \eqref{eqn:DefChain} is then obtained by combining \eqref{eqn:DefProof1} and \eqref{eqn:DefProof2}.


