 = \int_\gamma \big(\nab_\gamma {\bv}-(\nab_{\Gamma_{h,k}} \ipt \bv)^\ell\big): {\rm Def}_\gamma {\bw}
\end{align}
for $\bw,\bv\in \bH^2_T(\gamma)$; in the last equality we employ ${\bf A}^\intercal:{\bf B}= {\bf A}:{\bf B}$ when ${\bf B}^\intercal={\bf B}$.




Our starting point is \eqref{eqn:ChainRuleFun}, which we rephrase here for convenience:
\begin{equation*}
\begin{split}
\nab_\gamma {\bv} 
& = {\bf L} \left( \big(\nab_{\Gamma_{h,k}}\ipt \bv )\big) \left[ {\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]
\left[{\bf I}-d {\bf H}\right]^{-1}\right)^\ell\\
&\qquad  - \left(({\bf L}\bnu_h) \otimes ({\bf H}_h \ipt \bv) \left[ {\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]
\left[{\bf I}-d {\bf H}\right]^{-1}\right)^\ell
%%
%&\qquad 
+ \bPi \nab ({\bf L}^\ell) \ipt \bv^\ell \bPi.
\end{split}
\end{equation*}
%
We then add and subtract terms to get
\begin{equation}
\label{eqn:JsExpand}
\begin{split}
\nab_\gamma {\bv} 
& = (\nab_{\Gamma_{h,k}} \ipt \bv)^\ell + \left(\big[{\bf L}-{\bf I}\big] \nab_{\Gamma_{h,k}} \ipt \bv\left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h} \right]\big[{\bf I}-d {\bf H}\big]^{-1}\right)^\ell\\
%
&\qquad +\left(\nab_{\Gamma_{h,k}} \ipt \bv\left(\left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h} \right] \big[{\bf I}-d {\bf H}\big]^{-1} - \bPi_h\right)\right)^\ell\\
%
&\qquad\qquad  - \left(({\bf L}\bnu_h) \otimes ({\bf H}_h \ipt \bv) \left[ {\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]
\left[{\bf I}-d {\bf H}\right]^{-1}\right)^\ell+ \bPi \nab {\bf L}^\ell \ipt \bv^\ell\bPi\\
%
& =:(\nab_{\Gamma_{h,k}} \ipt \bv)^\ell  + J_1+J_2+J_3+J_4.
\end{split}
\end{equation}
We now bound each $J_i$.

We use $|{\bf L}- \bPi|\lesssim h^{k+1}$ and $|d|\lesssim h^{k+1}$ to obtain
\begin{align*}
\int_\gamma J_1: {\rm Def}_\gamma {\bw}
& \lesssim \int_\gamma \left(\big[\bPi - {\bf I}\big] \nab_{\Gamma_{h,k}} \ipt \bv \left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]\right)^\ell: {\rm Def}_\gamma {\bw} + h^{k+1}\|{\bw}\|_{H^1(\gamma)} \|{\bv}\|_{H^1(\gamma)}.
\end{align*}
We then use the algebraic relation $({\bf A}{\bf B}):{\bf C} = ({\bf A}^\intercal {\bf C}):{\bf B}$ and $(\bPi-{\bf I}){\rm Def}_\gamma \pt{\bw} = 0$
to get
\begin{align}\label{eqn:J1Bound}
\left|\int_\gamma J_1: {\rm Def}_\gamma {\bw}\right| \lesssim h^{k+1} \|{\bw}\|_{H^1(\gamma)} \|{\bv}\|_{H^1(\gamma)}.
\end{align}

For $J_2$, we first use $|d|\lesssim h^{k+1}$ to obtain
\begin{align*}
\left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h} \right] \big[{\bf I}-d {\bf H}\big]^{-1} - \bPi_h
&\lesssim \left(\left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h} \right] - \bPi_h\right)+h^{k+1}\\
%
&= \bnu_h\otimes \bnu_h -\frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h} +h^{k+1}.
\end{align*}
Therefore, using $\nab_{\Gamma_{h,k}} \ipt \bv (\bnu_h\otimes \bnu_h) = 0$, $|\nab_{\Gamma_{h,k}} \ipt \bv \bnu|\lesssim h^k$, 
the algebraic identity $({\bf A} \ba \otimes \bb) : {\bf B}= ({\bf A}\ba) \cdot ({\bf B} \bb)$, 
and $|\bnu_h^\intercal {\rm Def}_{\gamma} {\bw}|\lesssim h^k$, we have
%
\begin{align}\label{eqn:J2Bound}
\left|\int_\gamma J_2: {\rm Def}_\gamma {\bw}\right|\lesssim (h^{2k}+h^{k+1})\|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}\lesssim h^{k+1}\|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}.
\end{align}

Next, using $|{\bf L}-\bPi|\lesssim h^{k+1}$, $|d|\lesssim h^{k+1}$, 
and the algebraic relation $((\ba\otimes \bb) {\bf A}):{\bf B} = ({\bf B} {\bf A}^\intercal \bb)\cdot \ba$,
we obtain
%
\begin{equation}
\label{eqn:J3Start}
\begin{split}
\left|\int_{\gamma} J_3: {\rm Def}_\gamma \pt{\bw}\right|
&\lesssim \left|\int_{\gamma} \left((\bPi \bnu_h)\otimes ({\bf H}_h \ipt \bv)\left[{\bf I}- \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]\right)^\ell : {\rm Def}_\gamma {\bw}\right|+h^{k+1} \|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}\\
%
&= \left|\int_{\gamma} \left({\rm Def}_\gamma {\bw} \left(\left[{\bf I} - \frac{\bnu_h\otimes \bnu}{\bnu\cdot \bnu_h}\right]{\bf H}_h \ipt \bv\right)^\ell\right)\cdot (\bPi \bnu^\ell_h)\right|
+h^{k+1} \|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}.
\end{split}
\end{equation}
The desired bound for $\int_{\gamma} J_3: {\rm Def}_\gamma \pt{\bw}$ is completed in the case $k=1$ by using ${\bf H}_h=0$.
When $k \ge 2$, we recall that $\bnu^\intercal {\bf H}=0$, $|{\bf H}_h - {\bf H}| \lesssim h^{k-1}$,   $|\bPi\bnu_h^\ell| \lesssim h^k$,
and $|\ipt{\bv}^\ell-\bv|\lesssim h^k |\bv|$.  
%$|\ipt{\bv}-\bv| +|\bnu-\bnu_h| +|1-\bnu \cdot \bnu_h |+ |\Pi\bnu_h^\ell| \lesssim h^k$.  
These relationships yield after noting that $2k-1 \ge k+1$ when $k \ge 2$
%
\begin{equation}
\label{eqn:J3Start2}
\begin{split}
\left|\int_{\gamma} J_3: {\rm Def}_\gamma \pt{\bw}\right|
&\lesssim 
 \left|\int_{\gamma} \left({\rm Def}_\gamma {\bw} \left(\left[{\bf I} - \frac{\bnu_h\otimes \bnu}{\bnu\cdot \bnu_h}\right]({\bf H}_h-{\bf H}) \ipt \bv\right)^\ell\right)\cdot (\bPi \bnu^\ell_h)\right|\\
&\qquad+ \left |  \int_\gamma \left ({\rm Def}_\gamma \bw {\bf H} \ipt \bv^\ell \right ) \cdot (\bPi \bnu_h^\ell) \right | 
+ h^{k+1} \|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}\\
&\lesssim  \left |  \int_\gamma \left ({\rm Def}_\gamma \bw {\bf H} \bv \right ) \cdot (\bPi \bnu_h^\ell) \right | + h^{k+1} \|{\bv}\|_{H^1(\gamma)} \|{\bw}\|_{H^1(\gamma)}.
\end{split}
\end{equation}



Next, following arguments from \cite{HansboLarsonLarsson20}, we have for any $\bz\in \bW^1_1(\Gamma_{h,k})$,
\begin{equation}
\label{eqn:HLTrick}
\begin{split}
\int_{\Gamma_{h,k}} \bz \cdot (\bPi_h \bnu) 
&= \int_{\Gamma_{h,k}} \bz \cdot \nab_{\Gamma_{h,k}} d = -\int_{\Gamma_{h,k}}  d({\rm div}_{\Gamma_{h,k}} \bz) 
%
\lesssim h^{k+1} \|\bz\|_{W^1_1(\Gamma_{h,k})},
\end{split}
\end{equation}
%
and, for $\bz\in \bW^1_1(\gamma)$,
\begin{align*}
\int_{\gamma} \bz\cdot \bPi \bnu_h^\ell 
&= -\int_{\gamma} \bz\cdot \bPi_h^\ell  \bnu-\int_{\gamma}\bz\cdot  (\bPi-\bPi^\ell_h)(\bnu-\bnu^\ell_h)\\
%
& \lesssim  -\int_{\gamma} \bz \cdot (\nab_{\Gamma_{h,k}} d)^\ell + h^{2k}\|\bz\|_{L_1(\gamma)}\\
%
&\lesssim -\int_{\Gamma_{h,k}} \bz^e \cdot \nab_{\Gamma_{h,k}} d + h^{k+1}\|\bz\|_{L_1(\gamma)}\\
%
& = \int_K d({\rm div}_{\Gamma_{h,k}} \bz^e)  +h^{k+1} \|\bz\|_{L_1(\gamma)}\\
%
&\lesssim h^{k+1}\|\bz\|_{W^1_1(\gamma)}. 
\end{align*}
Taking  $\bz = {\rm Def}_\gamma \bw {\bf H} \bv $
and applying the estimate to \eqref{eqn:J3Start2} yields
%
\begin{align}\label{eqn:J3Bound}
\left|\int_{\gamma} J_3: {\rm Def}_\gamma {\bw}\right|
&\lesssim  
h^{k+1}\|{\bv}\|_{H^1(\gamma)}\|{\bw}\|_{H^2(\gamma)}.
\end{align}

To estimate $J_4$, we first use (cf.~\cite{DemlowNeilan23})
\begin{align*}
\bPi \nab {\bf L}^\ell \ipt \bv^\ell \bPi = \bPi \left(\nab {\bf L} \ipt \bv \bPi_h \left[{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}\right]\big[{\bf I} - d {\bf H}\big]^{-1}\right)^\ell,
\end{align*}
%
and
\begin{align*}
\bPi \nab {\bf L} \ipt \bv \bPi_h
&= -\mu_h^{-1} \bPi\Big( ({\bf L} \ipt \bv)\otimes \nab \mu_h + \bnu\otimes ({\bf H}\ipt \bv)+({\bf H}\bv)\otimes \bnu + (\bnu\cdot \ipt \bv) {\bf H}+d \nab {\bf H }\ipt \bv\Big)\bPi_h\\
%
&= -\mu_h^{-1} \Big( ({\bf L} \ipt \bv)\otimes \nab \mu_h\bPi_h  +({\bf H}\ipt \bv)\otimes (\bPi_h \bnu) + (\bnu\cdot \ipt \bv) {\bf H}\bPi_h+d \bPi \nab {\bf H }\ipt \bv \bPi_h \Big).
\end{align*}
%
Therefore, by setting ${\bf N} = [{\bf I} - \frac{\bnu\otimes \bnu_h}{\bnu\cdot \bnu_h}]$, 
and noting $\bPi_h {\bf N} = {\bf N}$, ${\bf H} {\bf N}^\ell = {\bf H}$, $((\ba\otimes \bb){\bf A}):{\bf B} = ({\bf A} {\bf B}^\intercal \ba)\cdot \bb$,
and $\ipt\bv\cdot \bnu_h=0$, we have
%
\begin{align*}
\left|\int_\gamma J_4:{\rm Def}_\gamma {\bw}\right|
& \lesssim \left|\int_\gamma \left(\Big( ({\bf L} \ipt \bv)\otimes \nab \mu_h   +({\bf H}\ipt \bv)\otimes (\bPi_h \bnu) + ((\bPi_h \bnu)\cdot \ipt \bv) {\bf H}\Big) 
{\bf N}\right)^\ell : {\rm Def}_\gamma {\bw}  \right|\\
&\qquad + h^{k+1} \|{\bv}\|_{L_2(\gamma)}\|{\bw}\|_{H^1(\gamma)}\\
%
&=\Big|\int_\gamma \left( ({\bf L} \ipt \bv)\otimes ({\bf N}^\intercal \nab \mu_h)\right)^\ell:{\rm Def}_\gamma {\bw}
+\int_\gamma ({\bf N}^\ell {\rm Def}_\gamma {\bw} {\bf H} \ipt \bv^\ell)\cdot (\bPi_h \bnu)^\ell\\
%
&\qquad + \int_\gamma \left((\bPi_h \bnu)\cdot \ipt \bv\right)^\ell \bf H : {\rm Def}_\gamma {\bw}))\Big|+h^{k+1} \|{\bv}\|_{L_2(\gamma)}\|{\bw}\|_{H^1(\gamma)}\\
%
&\lesssim \Big|\int_\gamma \left( ({\bf L} \ipt \bv)\otimes ({\bf N}^\intercal \nab \mu_h)\right)^\ell:{\rm Def}_\gamma {\bw}
+\int_\gamma ({\rm Def}_\gamma {\bw} {\bf H} \bv)\cdot (\bPi_h \bnu)^\ell\\
%
&\qquad + \int_\gamma \left(\bPi_h \bnu\right)^\ell  \cdot (\bv ({\bf H} : {\rm Def}_\gamma {\bw}))\Big|+h^{k+1} \|{\bv}\|_{L_2(\gamma)}\|{\bw}\|_{H^1(\gamma)},
\end{align*}
where we used $|\bnu_h^\intercal {\rm Def}_\gamma\bw| +|\bPi_h \bnu| \lesssim h^{k}$
and $|\ipt{\bv}^\ell-\bv|\lesssim h^k|\bv|$ in the last inequality.
%\ARD{Note next that $|\bnu_h^\top  {\rm Def}_\gamma\bw| + |\ipt{\bv}-\bv| + |\Pi_h \bnu| \lesssim h^{k}$.  
 Applying \eqref{eqn:HLTrick} 
 %to appropriate $O(h^{2k})$ perturbations 
 to  the second term with $\bz={\rm Def}_\gamma \bw {\bf H} \bv$ and to the third term with $\bz = \bv ({\bf H}^\ell : {\rm Def}_\gamma \bw)$ then yields
 %
\begin{align*}
\left|\int_\gamma J_4:{\rm Def}_\gamma {\bw}\right|
&\lesssim \left|\int_\gamma \left( ({\bf L} \ipt \bv)\otimes ({\bf N}^\intercal \nab \mu_h)\right)^\ell:{\rm Def}_\gamma {\bw}\right| + h^{k+1}\|{\bv}\|_{H^1(\gamma)}\|{\bw}\|_{H^2(\gamma)}.
%
%&\MJN{= \left|\int_\gamma ({\bf N} {\rm Def}_\gamma \bw {\bf L} \ipt{\bv})\cdot \nab \mu_h\right| + h^{k+1}\|{\bv}\|_{H^1(\gamma)}\|{\bw}\|_{H^2(\gamma)}}
\end{align*}
Using (cf.~\eqref{eqn:JacobiFun})
\[
\nab \mu_h = {\bf H}\bnu_h + {\bf H}_h \bnu - {\rm tr}({\bf H})\bnu+O(h^{k+1}) = {\bf H}\bPi\bnu_h + {\bf H}_h \bPi_h \bnu - {\rm tr}({\bf H})\bnu+O(h^{k+1}),
\]
%where ${\bf H}_h$ is the elementwise Jacobian of $\bnu_h$, 
applying some algebraic identities, and applying \eqref{eqn:HLTrick} {after appropriate $O(h^{k+1})$ perturbations as above to ensure $\bz \in \bW_1^1(\gamma)$ as required}, we have
\begin{align*}
\left|\int_\gamma \left( ({\bf L} \ipt \bv)\otimes ({\bf N}^\intercal \nab \mu_h)\right)^\ell:{\rm Def}_\gamma {\bw}\right|
& \lesssim \left|\int_\gamma ({\bf H} {\bf N} {\rm Def}_\gamma \bw {\bf L} \ipt{\bv})\cdot (\bPi\bnu_h)\right|
 + \left|\int_\gamma ({\bf H}_h {\bf N} {\rm Def}_\gamma \bw {\bf L} \ipt{\bv})\cdot (\bPi_h\bnu)\right|\\
 &\qquad + \left|\int_\gamma {\rm tr}({\bf H}) ({\bf N} {\rm Def}_\gamma \bw {\bf L} \ipt{\bv})\cdot (\bPi_h \bnu)\right| + h^{k+1}\|\bv\|_{L_2(\gamma)}\|\bw\|_{H^1(\gamma)}\\
 %
 &\lesssim h^{k+1}\|\bv\|_{H^1(\gamma)}\|\bw\|_{H^2(\gamma)}.
\end{align*}
%\ARD{[ARD: I believe $ ({\bf H}) ({\bf N} {\rm Def}_\gamma \bw {\bf L} \ipt{\bv})\cdot \bnu =0$, since $\bnu^\top {\bf N}= \bnu^\top$ and $\bnu {\rm Def}_\gamma \bw=0$, so this could be simplified a little.]}  \MJN{[I'm getting $\bnu^\intercal {\bf N} = \bnu^\intercal - \bnu_h^\intercal/(\bnu\cdot \bnu_h)$.]}
Thus, we have the following bound for $J_4$:
\begin{align}\label{eqn:J4Bound}
\left|\int_\gamma J_4:{\rm Def}_\gamma {\bw}\right|\lesssim h^{k+1}\|\bw\|_{H^2(\gamma)}\|\bv\|_{H^1(\gamma)}.
\end{align}

We combine \eqref{eqn:GEStarting} and \eqref{eqn:JsExpand},
along with the estimates \eqref{eqn:J1Bound}, \eqref{eqn:J2Bound}, \eqref{eqn:J3Bound}, and \eqref{eqn:J4Bound}
to get
\begin{align}
 \left|\int_\gamma \big({\rm Def}_\gamma {\bv} - ({\rm Def}_{\Gamma_{h,k}} \ipt \bv)^\ell\big): {\rm Def}_\gamma {\bw} \right|
&\lesssim h^{k+1}\|\bv\|_{H^1(\gamma)}\|\bw\|_{H^2(\gamma)}.
\end{align}
Applying this estimate to \eqref{eqn:StartOfLong} twice then yields
\begin{align*}
|G(\ipt \bv,\ipt \bw)|\lesssim h^{k+1}\|\bv\|_{H^2(\gamma)}\|\bw\|_{H^2(\gamma)}.
\end{align*}

