	\infer{\Gamma \vdash \set_a(V,M) : \sigma \ar \kappa}{\Gamma \vdash V : \delta && \Gamma \vdash M : (\langle a:\delta \rangle\wedge\sigma)\ar \kappa}
&	\infer{\term{G+D |- a<\_>.[V]a.M : a([])\,!!m => !!n}}{\infer{\term{G+D |- [V]a.M : !!m => !!n}}{\term{G |- V:i} && \term{D |- M : a(i)\,!!m => !!n}}}
\end{array}
\]
