\section{Proofs for Section~\ref{sec:FMC}: The Functional Machine Calculus}

%--------------- Prop: small-step big-step agree
\smallStepBigStep*

\begin{proof}
The machine transitions correspond to the big-step evaluation rules as follows. From left to right the proof is by (strong) induction on $n$, and from right to left by induction on the derivation for $\evalarrow_n$.

\begin{itemize}
\item\case{Application:}
A successful run starting with a \emph{push} transition and the evaluation rule for application correspond as follows.
\[
\begin{array}{@{(~}l@{~,~}r@{~,~}r@{~)}}
          S_A               & \term{[N]a.M} & \e
\\ \hline S_A\msep\term N_a &      \term{M} & \e
\\ \dline T_A               &      \term{*} & \e
\end{array}
\,\raisebox{-4pt}{$\scriptstyle n$}
\qquad
\evalAlign 
  [n]   {S_A\msep\term N_a}       M  {T_A}
  [n+1] {S_A}               {[N]a.M} {T_A}
\]

\item\case{Abstraction:}
A successful run starting with a \emph{pop} transition and the evaluation rule for abstraction correspond as follows.
\[
\begin{array}{@{(~}l@{~,~}r@{~,~}r@{~)}}
          S_A\msep\term N_a & \term{a<x>.M} & \e
\\ \hline S_A               &      \term{M} & \e
\\ \dline T_A               &      \term{*} & \e
\end{array}
\,\raisebox{-4pt}{$\scriptstyle n$}
\qquad  
\evalAlign 
  [n]   {S_A}             {\{N/x\}M} {T_A}
  [n+1] {S_A\msep\term N_a} {a<x>.M} {T_A}
\]

\item\case{Unit:}
The unit run for a single state corresponds to the unit evaluation rule.
\[
	(S_A,\term *,\e) \qquad \evalRule {} {\eval[1]{S_A}*{S_A}}
\]

\item\case{Sequence:}
A successful run for $\term{M;N}$ consists of a transition pushing $\term N$ to the continuation stack, a successful run for $\term M$ (ignoring $\term N$ on the continuation stack), a transition popping $\term N$, and a run for $\term N$. The correspondence is then as follows, where the total length of the run is that of both constituting runs for $\term M$ and $\term N$ plus the initial state for $\term{M;N}$.
\[
\begin{array}{@{(~}l@{~,~}r@{~,~}r@{~)}l@{}}
          R_A & \term{M;N} & \e       
\\ \hline R_A & \term{M}   & \term{N} 
\\ \dline S_A & \term{*}   & \term{N} 
\\ \hline S_A & \term{N}   & \e       
\\ \dline T_A & \term{*}   & \e       
\end{array}
\,\raisebox{11pt}{\makebox[0pt][l]{$\scriptstyle m$}}
  \raisebox{-20pt}{$\scriptstyle n$}
\qquad
\evalRule {\eval[m]{R_A}M{S_A} \qquad \eval[n]{S_A}N{T_A}} {\eval[m+n+1]{R_A}{M;N}{T_A}}
\]
\end{itemize}
\end{proof}




%------------------------------------------------------------ MACHINE TERMINATION
\section{Proofs for Section~\ref{sec:machine termination}: Machine Termination}

%--------------- LEMMA: weak substitution
\substitutionWeak*

\begin{proof}
The proof is by induction on $\term M$, except that the \emph{collection} case is treated separately from the \emph{application} case. Each case is demonstrated by two derivations, representing a permutation of the substitution typing rule, where one derivation exists if and only if the other does.

\begin{itemize}

% Variable
\item\case{Variable case:}
In the case $\term M=\term x$ we have the following two derivations. In both directions it is immedate that given one derivation, we may construct the other.
\[
\infer-[\rr s]{\term{G |- \{N/x\}x:t}}{\infer[\rr c]{\term{G |- N:[t]}}{\term{G |- N:t}} && \infer[\rr x]{\term{x:[t] |- x:t}}{}}
\qquad\qquad
\term{G |- N:t}
\]
In the case $\term M=\term y\neq\term x$ we have the following two derivations.
\[
\infer-[\rr s]{\term{y:[t] |- \{N/x\}y:t}}{\infer[\rr c]{\term{|- N:[]}}{} && \infer[\rr x]{\term{y:[t], x:[] |- y:t}}{}}
\qquad\qquad
\infer[\rr x]{\term{y:[t] |- y:t}}{}
\]

% Abstraction
\item\case{Abstraction case:}
In the case $\term M=\term{a<y>.P}$ we have the following two derivations. In both directions, given one derivation we may construct the other, where by $\alpha$-conversion we may assume $\term y\notin\fv N$.
\[
\infer-[\rr s]{\term{G+D |- \{N/x\}a<y>.P: a(i)\,!!k => !!m }}{\term{G |- N:n} && \infer[\rr l]{\term{D , x:n |- <y>.P: a(i)\,!!k => !!m}}{\term{D , x:n , y:i , |- P: !!k => !!m }}}
\]
\[
\infer[\rr l]{\term{G+D |- a<y>.\{N/x\}P: a(i)\,!!k => !!m}}{\infer-[\rr s]{\term{G+D, y:i |- \{N/x\}P: !!k => !!m}}{\term{G |- N:n} && \term{D , x:n , y:i , |- P: !!k => !!m }}}
\]

% Weak application
\item\case{Weak application case:}
In the case $\term M=\term{[Q]a.P}$ we have the following two derivations, where $\type n =\type{n_1+n_2}$ and $\term D=\term{D_1+D_2}$. Given the former derivation, since $\term{G |- N:n}$ must be introduced by a collection rule, we have $\term{G_i |- N:n_i}$ for $i=1,2$ with $\term G=\term{G_1+G_2}$, so that we may construct the latter derivation. The other direction is immediate.
\[
\infer-[\rr s]{\term{G+D |- \{N/x\}[Q]a.P: !!k => !!m}}{
   \term{G |- N:n}
&& \infer[\rr a]{\term{D , x:n |w [Q]a.P}}{
      \term{D_1 , x:n_1 |- Q:i}
   && \term{D_2 , x:n_2 |- P:a(i)\,!!k => m}
   }
}
\]
\[
\infer[\rr a]{\term{G+D |w [\{N/x\}Q]a.\{N/x\}P: !!k => !!m}}{
   \infer-[\rr s]{\term{G_1+D_1 |- \{N/x\}Q : i}}{
      \term{G_1 |- N:n_1}
   && \term{D_1 , x:n_1 |- Q:i}
   }
&& \infer-[\rr s]{\term{G_2+D_2 |- \{N/x\}P : a(i)\,!!k => !!m}}{
      \term{G_2 |- N:n_2}
   && \term{D_2 , x:n_2 |- P:a(i)\,!!k => !!m}
   }
}
\]

% Unit
\item\case{Unit case:} We have the following two derivations.
\[
\infer-[\rr s]{\term{|- \{N/x\}* : !!i => !!i}}{\infer[\rr c]{\term{|- N:[]}}{} && \infer[\rr *]{\term{|- *: !!i => !!i}}{}}
\qquad\qquad
\infer[\rr *]{\term{|- *: !!i => !!i}}{}
\]

% Sequencing
\item\case{Sequencing case:} The case is similar to the weak application case, with the following two derivations. Given the former derivation, since $\type n=\type{n_1+n_2}$ and $\term{G |- N:n}$ is introduced by an \emph{intersection} rule, we have the two derivations $\term{G_i |- N:n_i}$ for $i=1,2$, and may construct the latter derivation. The reverse is again immediate, noting that $\term G=\term{G_1+G_2}$ and $\term D=\term{D_1+D_2}$.
\[
\infer-[\rr s]{\term{G+D |- \{N/x\}(P;Q) : !!i => !!m}}{
   \term{G |- N:n}
&& \infer[\rr ;]{\term{D , x:n |- P;Q : !!i => !!m}}{
      \term{D_1 , x:n_1 |- P : !!i => !!k}
   && \term{D_2 , x:n_2 |- Q : !!k => !!m}
   }
}  
\]
\[
\infer[\rr ;]{\term{G+D |- \{N/x\}(P;Q) : !!i => !!m}}{
   \infer-[\rr s]{\term{G_1+D_1 |- \{N/x\}P : !!i => !!k}}{
      \term{G_1 |- N:n_1}
   && \term{D_1 , x:n_1 |- P: !!i => !!k}
   }
&& \infer-[\rr s]{\term{G_2+D_2 |- \{N/x\}Q : !!k => !!m}}{
      \term{G_2 |- N:n_2}
   && \term{D_2 , x:n_2 |- Q: !!k => !!m}
   }
}
\]

% Collection
\item\case{Collection case:} The case is similar to the weak application case. The two derivations are as follows, where $\type n=\type{n_1++n_n}$ and $\term D=\term{D_1++D_n}$. Given the former derivation, since $\term{G |- N:n}$ is introduced by an intersection rule, we have the derivations $\term{G_i |- N:n_i}$ for $1\leq i\leq n$ needed to construct the latter derivation, where $\term G=\term{G_1++G_n}$. The reverse direction is immediate.
\[
\infer-[\rr s]{\term{G+D |- \{N/x\}M : [t_1,,t_n]}}{
   \term{G |- N:n}
&& \infer[\rr c]{\term{D , x:n |- M: [t_1,,t_n]}}{
      (\term{D_i , x:n_i |- M: t_i})_{1\leq i\leq n}
   }
}
\]
\[
\infer[\rr c]{\term{G+D |- \{N/x\}M : [t_1,,t_n]}}{
   \hspace{22pt}\left(\vc{
   \infer-[\rr s]{\term{G_i+D_i |- \{N/x\}M : t_i}}{
      \term{G_i |- N:n_i}
   && \term{D_i , x:n_i |- M:t_i}
   }
   }\right)_{1\leq i\leq n}
   \hspace{34pt}
}
\qedhere
\]
\end{itemize}
\end{proof}


%--------------- LEMMA: machine evaluation reduces typing weights
\evaluationReducesWeights*

\begin{proof}
For each of the four machine transitions the two typing derivations will be given. In each case, given one derivation the other may be constructed, while the first has weight exactly one greater than the second, as it has exactly one additional rule instance contributing to the weight of a derivation (an \emph{application}, \emph{abstraction}, \emph{unit}, or \emph{sequencing} rule).

\begin{itemize}

% Application	
\item\case{Application case:}
\[
	\step {S_A}{[N]a.M}K {S_A\msep\term N_a}MK
\]
The two typing derivations are as follows.
\[
	\infer[\rr ?]{\term{|- ??{S_A}{[N]a.M}K : \e => !!m }}{
	   \term{|- S_A : !!i}
	&& \infer[\rr a]{\term{|- [N]a.M : !!i => !!k}}{\term{|- N : n} && \term{|- M : a(n)\,!!i => !!k}}
	&& \term{|- K : !!k => !!m}
	}
\]
\[
	\infer[\rr ?]{\term{|- ??{S_A\msep\term N_a}MK : \e => !!m }}{
	   \infer[\rr o]{\term{|- ?{S_A\msep\term N_a} : !!i\,a(n)}}{\term{|- ?{S_A} : !!i} && \term{|- N : n}}
	&& \term{|- M : a(n)\,!!i => !!k}
	&& \term{|- K : !!k => !!m}
	}
\]

% Abstraction
\item\case{Abstraction case:}
\[
	\step{S_A\msep\term N_a}{a<x>.M}K {S_A}{\{N/x\}M}K
\]
The two typing derivations are as follows. In both directions, the use of the \emph{substitution} typing rule is justified by Lemma~\ref{lem:substitutionWeak}.
\[
	\infer[\rr ?]{\term{|- ??{S_A\msep\term N_a}{a<x>.M}K : \e => !!m}}{
	   \infer[\rr o]{\term{|- ?{S_A\msep\term N_a} : !!i\,a(n)}}{\term{|- ?{S_A} : !!i} && \term{|- N : n}}
	&& \infer[\rr l]{\term{|- a<x>.M : a(n)\,!!i => !!k}}{\term{x:n |- M : !!i => !!k}}
	&& \term{|- K : !!k => !!m}
	}
\]
\[
	\infer[\rr ?]{\term{|- ??{S_A}{\{N/x\}M}K : \e => !!m}}{
	   \term{|- ?{S_A} : !!i}
	&& \infer-[\rr s]{\term{|- \{N/x\}M : !!i => !!k}}{\term{|- N : n} && \term{ x:n |- M : !!i => !!k}}
	&& \term{|- K : !!k => !!m}
	}
\]

% Sequencing
\item\case{Sequencing case:}
\[
	\step {S_A}{M;N}K {S_A}M{\term N\,K} 
\]
The two derivations are as follows.
\[
	\infer[\rr ?]{\term{|- ??{S_A}{M;N}K : \e => !!n}}{
	   \term{|- ?{S_A} : !!i}
	&& \infer[\rr ;]{\term{|- M;N : !!i => !!m}}{\term{|- M : !!i => !!k} && \term{|- N : !!k => !!m}}
	&& \term{|- ?K : !!m => !!n}
	}
\]
\[
	\infer[\rr ?]{\term{|- ??{S_A}M{\term N\,K} : \e => !!n}}{
	   \term{|- ?{S_A} : !!i}
	&& \term{|- M : !!i => !!k}
	&& \infer[\rr k]{\term{|- ?{\term N\,K} : !!k => !!n}}{ 
	       \term{|- N : !!k => !!m} 
	   &&  \term{|- ?K : !!m => !!n}
	   }
	}
\]

% Unit
\item\case{Unit case:}
\[
	\step {S_A}*{\term M\,K} {S_A}MK
\]
The two derivations are as follows.
\[
    \infer[\rr ?]{\term{|- ??{S_A}*{\term M\,K} : \e => !!m}}{
    	\term{|- ?{S_A} : !!i}
    &&	\infer[\rr *]{\term{|- * : !!i => !!i}}{}
    &&	\infer[\rr k]{\term{|- ?{\term M\,K} : !!i => !!m}}{ 
			\term{|- M : !!i => !!k} 
		&&	\term{|- ?K : !!k => !!m } 
		}
	}
\]
\[
	\infer[\rr ?]{\term{|- ??{S_A}MK : \e => !!m}}{
		\term{|- ?{S_A} : !!i}
	&&	\term{|- M : !!i => !!k}
	&&	\term{|- ?K : !!k => !!m}
	}
\qedhere
\]
\end{itemize}
\end{proof}



%------------------------------------------------------------ SPINE REDUCTION
\section{Proofs for Section~\ref{sec:spine}: Spine Normalization}


%--------------- PROPOSITION: spine normal forms
\spineNF*

\begin{proof}
By induction on terms, it is shown that $\term{\WW}$ are the spine normal terms, and $\term{\VV}$ those that are not abstractions. A variable $\term x$ and a unit $\term *$ are spine normal, and a composition $\term{M;N}$ is normal if and only if $\term M$ is a variable and $\term N$ is spine normal, since if $\term M$ is a unit, application, abstraction, or sequencing, a reduction step applies. An application $\term{[N]a.M}$ is spine-normal if and only if $\term M$ is spine-normal and not an abstraction, since otherwise a beta-step or passage-step would apply. An abstraction $\term{a<x>.M}$ is spine-normal if and ony if $\term M$ is. 
\end{proof}




%--------------- LEMMA: spine normal forms typeable
\spineNFTyped*


\begin{proof}
By induction on $\term{\WW}$ the following are proved.
\begin{enumerate}
	\item\label{case:N0} For any $\term{\WW}$ there is a type derivation $\term{G |w \WW: !!i => []^f}$.
	\item\label{case:N1} For any $\term{\VV}$ and any $f:A\to\mathbb N$ there is a type derivation $\term{G |w \VV: []^f => []^g}$.
\end{enumerate}
Note that~\ref{case:N1} implies~\ref{case:N0}.

\begin{itemize}

% Unit
\item\case{Unit case:}
For a term $\term *$, we prove case~\ref{case:N1}. For any $f$ we have $\term{|- *:[]^f => []^f}$.

% Variable
\item\case{Variable case:}
For a variable $\term x$, we prove case~\ref{case:N1}. For any $f$ we have $\term{x:[[]^f=>\e] |- x: []^f => \e}$.

% Sequencing
\item\case{Sequencing case:}
For a term $\term{x;\WW}$ we prove case~\ref{case:N1}. By induction, let $\term{G |- \WW: !!i => []^g}$. For any $f$ we get $\term{G + `{\black(}x:[]^f=>!!i`{\black)} |- x;\WW : []^f => []^g}$.

% Application
\item\case{Application case:}
For a term $\term{[M]a.\VV}$, we prove case~\ref{case:N1}. Given $f$, define $f'$ by $f'(a)=f(a)+1$ and $f'(b)=f(b)$ for $a\neq b$. We apply the inductive hypothesis for case~\ref{case:N1} to $\term{\VV}$ and $f'$ to get $\term{G |- \VV: []^{f'} => []^g}$. The following \emph{weak application} rule instance then gives the required type.
\[
\infer[\rr a]{\term{G |w [M]a.\VV : []^f => []^g}}{
   \infer[\rr c]{\term{|- M: []}}{}
&& \term{G |- \VV: []^{f'} => []^g}
}
\]

% Abstraction
\item\case{Abstraction case:}
For a term $\term{a<x>.\WW}$ we prove case~\ref{case:N0}. By induction, there is a judgement $\term{G , x:i |- \WW : !!k => []^f}$. Then by the \emph{abstraction} typing rule we get the required type $\term{G |- a<x>.\WW : a(i)\,!!k => []^f}$.
\qedhere
\end{itemize}
\end{proof}


%--------------- LEMMA: spine reduction
\weightedSpine*

\begin{proof}
By induction on spine contexts. The cases for a top-level reduction step are as follows.

\begin{itemize}

% Beta
\item\case{Beta case:} For a reduction $\term{[N]a.a<x>.M}\rw\term{\{N/x\}M}$, by Lemma~\ref{lem:substitutionWeak} a derivation for $\term{\{N/x\}M}$ is given by a substitution rule, as below right. Then we have the derivation below left if and only if we have that below right, with weight $n+2$ respectively $n$.
\[
\infer[\rr a]{\term{G+D |w [N]a.a<x>.M : !!k => !!m}}{
   \term{G |- N:i}
&& \infer[\rr l]{\term{D |- a<x>.M: a(i)\,!!k => !!m}}{
      \term{D , x:i |- M: !!k => !!m}
   }
}
\qquad
\infer-[\rr s]{\term{G+D |- \{N/x\}M : !!k => !!m}}{
   \term{G |- N:i}
&& \term{D , x:i |- M: !!k => !!m}
}
\]

% Passage
\item\case{Passage case:} For a reduction $\term{[N]b.a<x>.M}\rw\term{a<x>.[N]b.M}$ where $a\neq b$ and $x\notin\fv N$, we have the derivation below left if and only if we have that below right, with equal weights. Note that $\type{a(i)\,b(n)\,!!k}=\type{b(n)\,a(i)\,!!k}$.
\[
\infer[\rr a]{\term{G+D |w [N]b.a<x>.M : a(i)\,!!k => !!m}}{
   \term{G |- N:i}
&& \infer[\rr l]{\term{D |- a<x>.M: a(i)\,b(n)\,!!k => !!m}}{
      \term{D , x:i |- M: b(n)\,!!k => !!m}
   }
}
\qquad
\infer[\rr a]{\term{G+D |w a<x>.[N]b.M : a(i)\,!!k => !!m}}{
   \infer[\rr l]{\term{G+D , x:i |- [N]b.M: !!k => !!m}}{
      \term{G |- N:i}
   && \term{D , x:i |- M: b(n)\,!!k => !!m}
   }
}
\]

% Next
\item\case{Next case:} For a reduction $\term{*;M}\rw\term M$, we have the derivation for $\term{G |_{n+2} *;M : !!i => !!k}$ below if and only if we have a derivation for $\term{G |_n M: !!i => !!k}$.
\[
\infer[\rr ;]{\term{G |- *;M : !!i => !!k}}{
   \infer[\rr *]{\term{|- *: !!i => !!i}}{}
&& \term{G |- M: !!i => !!k}
}
\]

% Prefix (pop)
\item\case{Prefix (pop) case:} For a reduction $\term{a<x>.N;M}\rw\term{a<x>.(N;M)}$ where $x\notin\fv M$, given the derivation below left we may construct that below right, and vice versa.
\[
\infer[\rr ;]{\term{G+D |- a<x>.N;M : a(i)\,!!k => !!n }}{
   \infer[\rr l]{\term{G |- a<x>.N : a(i)\,!!k => !!m}}{\term{G , x:i |- N: !!k => !!m}}
&& \term{D |- M : !!m => !!n}   
}
\quad~
\infer[\rr l]{\term{G+D |- a<x>.(N;M) : a(i)\,!!k => !!n }}{
   \infer[\rr ;]{\term{G+D , x:i |- N;M : !!k => !!n }}{
      \term{G , x:i |- N: !!k => !!m}
   && \term{D |- M : !!m => !!n}   
}}
\]

% Prefix (push)
\item\case{Prefix (push) case:} For a reduction $\term{[P]a.N;M}\rw\term{[P]a.(N;M)}$, given the first derivation below we may construct the second, and vice versa.
\[
\infer[\rr ;]{\term{G+D+E |- [P]a.N;M : !!k => !!n }}{
   \infer[\rr a]{\term{G+D |w [P]a.N : !!k => !!m}}{
      \term{G |- P: i}
   && \term{D |- N: a(i)\,!!k => !!m}
   }
&& \term{E |- M : !!m => !!n}   
}
\]
\[
\infer[\rr a]{\term{G+D+E |w [P]a.(N;M) : !!k => !!n }}{
   \term{G |- P: i}
&& \infer[\rr ;]{\term{D+E |- N;M : a(i)\,!!k => !!n}}{
      \term{D |- N: a(i)\,!!k => !!m}
   && \term{E |- M : !!m => !!n}   
}}
\]

% Associativity
\item\case{Associate case:} For a reduction $\term{(P;N);M}\rw\term{P;(N;M)}$, given the first derivation below we may construct the second, and vice versa.
\[
\infer[\rr ;]{\term{G+D+E |- (P;N);M : !!i => !!n }}{
   \infer[\rr ;]{\term{G+D |- P;N : !!i => !!k}}{
      \term{G |- P: !!i => !!k}
   && \term{D |- N: !!k => !!m}
   }
&& \term{E |- M : !!m => !!n}   
}
\]
\[
\infer[\rr ;]{\term{G+D+E |- P;(N;M) : !!i => !!n }}{
   \term{G |- P: !!i => !!k}
&& \infer[\rr ;]{\term{D+E |- N;M : !!k => !!n}}{
      \term{D |- N: !!k => !!m}
   && \term{E |- M : !!m => !!n}   
}}
\]
\end{itemize}

For reduction in a spine context, $\term{W\{M\}}\rw_\spine\term{W\{N\}}$, it is sufficient to observe from the derivation rules that the  derivation for $\term M$ occurs exactly once in $\term{W\{M\}}$; then the effect of replacing the derivation for $\term{G |w M:t}$ with $\term{G |w N:t}$, or vice versa, reflects directly on the derivations for $\term{W\{M\}}$ and $\term{W\{N\}}$.
