\end{proof}


%--------------- LEMMA: spine normal => termination
\spineNFterminate*

\begin{proof}
By induction on $\term\WW$ it will be shown that there is a dimension $d$ such that for any memory $S_A$ and substitution map $\sigma$ of dimension $d$, the following hold.
\begin{enumerate}

\item\label{case:spine eval 1} 
There is a memory $T_A$ such that $\eval{S_A}{\sigma\WW}{T_A}$.

\item\label{case:spine eval 2}
For a term $\term\VV$, there is a memory $T_A$ such that $\eval\e{\sigma\VV}{T_A}$.

\end{enumerate}
Observe that case~\ref{case:spine eval 1} implies case~\ref{case:spine eval 2} by expanding the memory $\e$ to $S_A$.

\begin{itemize}

\item\case{Unit case:}
We prove statement~\ref{case:spine eval 2}. Let $d=0$. We have $\term{\sigma(*)}=\term*$ and $\eval\e*\e$.

\item\case{Variable case:}
We prove statement~\ref{case:spine eval 2}. Let $d=0$. Given $\sigma$, since $\term{\sigma x}$ is a term of dimension $d$, we have $\eval\e{\sigma x}{T_A}$ for some memory $T_A$ of dimension $d$.

\item\case{Sequencing case:}
We prove statement~\ref{case:spine eval 2}. Given $\term{x;\WW}$, by induction we get a dimension $d$ such that statement~\ref{case:spine eval 1} holds for $\term\WW$. Let $\sigma$ be a substitution map of dimension $d$. As in the previous case, we have $\eval\e{\sigma x}{S_A}$ where $S_A$ is a memory of dimension $d$. Then by the inductive hypothesis, we have $\eval {S_A}{\sigma\WW}{T_A}$, and by the evaluation rule for sequencing, $\eval\e{\sigma(x;\WW)}{T_A}$.
\[
\evalRule
    {\eval\e{\sigma x}{S_A} \qquad \eval{S_A}{\sigma\WW}{T_A}}
	{\eval\e{\sigma(x;\WW)}{T_A}} 
\]

\item\case{Application case:}
We prove statement~\ref{case:spine eval 2}. Given $\term{[M]a.\VV}$, by induction we get a dimension $d$ such that $\eval\e{\sigma\VV}{T_A}$ given any $\sigma$ of dimension $d$. Then by expansion and the evaluation rule for application, statement~\ref{case:spine eval 2} follows for $\term{[M]a.\VV}$ with dimension $d$ and return memory $\term{\sigma M}_a\msep T_A$ (abusing notation to prepend $\term{\sigma M}$ to the stack $a$ in $T_A$).
\[
	\evalAlign
	  {\term{\sigma M}_a}       {\sigma\VV}  {\term{\sigma M}_a\msep T_A}
	  {\e}                {\sigma([M]a.\VV)} {\term{\sigma M}_a\msep T_A} 
\]

\item\case{Abstraction case:}
Given $\term{a<x>.\WW}$, by induction there is a dimension $d$ such that statement~\ref{case:spine eval 1} holds for $\term\WW$. We prove statement~\ref{case:spine eval 1} for dimension $d+1$. A memory of dimension $d+1$ is of the form $S_A\msep\term M_a$ where both $\term{M}$ and $S_A$ are of dimension $d$, in the latter case since every stack is of length at least $d$ (and holding terms of dimenstion at least $d$). A substitution map $\sigma$ of dimension $d+1$ is also of dimension $d$. Then so is $\sigma\{\term M/x\}$ (which assigns $\term M$ to $\term x$ and behaves as $\sigma$ everywhere else). The inductive hypothesis then gives $\eval{S_A}{\sigma\{M/x\}\WW}{T_A}$. By the evaluation rule for abstraction, from this we get $\eval{S_A\msep\term M_a}{\sigma(a<x>.\WW)}{T_A}$ for dimension $d+1$.
\[
	\evalAlign
	   {S_A}              {\sigma\{M/x\}\WW} {T_A}
	   {S_A\msep\term M_a} {\sigma(a<x>.\WW)}{T_A}
\qedhere
\]
\end{itemize}
\end{proof}

%--------------- LEMMA: evaluation invariant under spine reduction
\spineTermination*

\begin{proof}
By induction on the spine context for the reduction step. The first six cases cover reduction at top level, and the last four reduction in context.

\begin{itemize}

% Beta
\item\case{Beta case:} Let $\term{[N]a.a<x>.M}\rw\term{\{N/x\}M}$. Noting that $\term{\sigma(\{N/x\}M)}=\term{(\sigma\{\sigma N/x\})M}$, the left hand term evaluates as below if and only if the right hand term evaluates as $\eval{S_A}{\sigma(\{N/x\}M)}{T_A}$.
\[
\begin{array}{@{}r@{}l@{}}
	      \strut S_A                         ,\,    \term{\sigma(\{N/x\}M)} & {}\evalarrow T_A
\\ \hline \strut S_A \msep \term{\sigma N}_a ,\,      \term{\sigma(a<x>.M)} & {}\evalarrow T_A
\\ \hline \strut S_A                         ,\, \term{\sigma([N]a.a<x>.M)} & {}\evalarrow T_A
\end{array}
\]

% Passage
\item\case{Passage case:} Let $\term{[N]b.a<x>.M}\rw\term{a<x>.[N]b.M}$ where $x$ is not free in $\term N$. Assuming by alpha-conversion that $\sigma$ does not bind in $\term P$, we have the first derivation if and only if we have the second.
\[
\begin{array}{@{}r@{}l@{}}
	      \strut S_A \msep \term{\sigma N}_b                  ,\,    \term{\sigma(\{P/x\}M)} & {}\evalarrow T_A
\\ \hline \strut S_A \msep \term{P}_a \msep \term{\sigma N}_b ,\,      \term{\sigma(a<x>.M)} & {}\evalarrow T_A
\\ \hline \strut S_A \msep \term{P}_a                         ,\, \term{\sigma([N]b.a<x>.M)} & {}\evalarrow T_A
\end{array}
\qquad
\begin{array}{@{}r@{}l@{}}
	      \strut S_A \msep \term{\sigma N}_b  ,\,      \term{\sigma(\{P/x\}M)} & {}\evalarrow T_A
\\ \hline \strut S_A                          ,\, \term{\sigma([N]b.\{P/x\}M)} & {}\evalarrow T_A
\\ \hline \strut S_A \msep \term{P}_a         ,\,   \term{\sigma(a<x>.[N]b.M)} & {}\evalarrow T_A
\end{array}
\]

% Next
\item\case{Next case:} Let $\term{*;M}\rw\term M$. Since $\term{\sigma(*)}=\term*$, we have $\eval{S_A}{\sigma M}{T_A}$ if and only if we have the folowing.
\[
\infer{ \eval{S_A}{\sigma(*;M)}{T_A} }{ \eval{S_A}*{S_A} && \eval{S_A}{\sigma M}{T_A} }
\]


% Prefix (pop)
\item\case{Prefix (pop) case:} Let $\term{a<x>.N;M}\rw\term{a<x>.(N;M)}$ where $\term x$ is not free in $\term M$. Assuming by alpha-conversion that $\sigma$ does not bind in $\term P$, we have the first derivation if and only if we have the second.
\[
\infer{ \eval{R_A\msep\term{P}_a}{\sigma(a<x>.N;M)}{T_A} }{
 \infer{ \eval{R_A\msep\term{P}_a}{\sigma(a<x>.N)}{S_A} }{
  \eval{R_A}{\sigma(\{P/x\}N)}{S_A}
 } &&
 \eval{S_A}{\sigma M}{T_A}
}
\qquad
\infer{ \eval{R_A\msep\term{P}_a}{\sigma(a<x>.(N;M))}{T_A} }{
 \infer{ \eval{R_A}{\sigma(\{P/x\}N;M)}{T_A} }{
  \eval{R_A}{\sigma(\{P/x\}N)}{S_A}
  &&
  \eval{S_A}{\sigma M}{T_A}
}}
\]


% Prefix (push)
\item\case{Prefix (push) case:} For a reduction $\term{[P].N;M}\rw\term{[P].(N;M)}$, we have the first derivation if and only if we have the second.
\[
\infer{ \eval{R_A}{\sigma([P].N;M)}{T_A} }{
 \infer{ \eval{R_A}{\sigma([P].N)}{S_A} }{
  \eval{R_A\msep\term{\sigma P}_a}{\sigma N}{S_A}
 } &&
 \eval {S_A}{\sigma M}{T_A}
}
\qquad
\infer{ \eval{R_A}{\sigma([P].(N;M))}{T_A} }{
 \infer{ \eval{R_A\msep\term{\sigma P}_a}{\sigma(N;M)}{T_A} }{
  \eval{R_A\msep\term{\sigma P}_a}{\sigma N}{S_A}
  &&
  \eval {S_A}{\sigma M}{T_A}
}}
\]

% Associativity
\item\case{Associativity case:} For a reduction $\term{(P;N);M}\rw\term{P;(N;M)}$, we have the first derivation if and only if we have the second.
\[
\infer{ \eval{R_A}{\sigma((P;N);M)}{U_A} }{
 \infer{ \eval{R_A}{\sigma(P;N)}{T_A} }{
  \eval {R_A}{\sigma P}{S_A}
  &&
  \eval {S_A}{\sigma N}{T_A}
 } &&
 \eval {T_A}{\sigma M}{U_A}
}
\]
\[
\infer{ \eval{R_A}{\sigma(P;(N;M))}{U_A} }{
 \eval {R_A}{\sigma P}{S_A}
 &&
 \infer{ \eval{S_A}{\sigma(N;M)}{U_A} }{
  \eval {S_A}{\sigma N}{T_A}
  &&
  \eval {T_A}{\sigma M}{U_A}
}}
\]

\item\case{Application case:} Let $\term{[P]a.M}\rw\term{[P]a.N}$ where $\term M\rw\term N$. Given $S_A$ and $\sigma$, by induction we have $\eval{S_A\msep\term{\sigma P}_a}{\sigma M}{T_A}$ if and only if $\eval{S_A\msep\term{\sigma P}_a}{\sigma N}{T_A}$, and hence $\eval{S_A}{\sigma([P]a.M)}{T_A}$ if and only if $\eval{S_A}{\sigma([P]a.N)}{T_A}$.

\item\case{Abstraction case:} Let $\term{a<x>.M}\rw\term{a<x>.N}$ where $\term M\rw\term N$. Given $S_A\msep\term{\sigma P}_a$ and $\sigma$, assuming $\sigma$ does not bind in $\term P$, by induction we have $\eval{S_A}{\sigma(\{P/x\}M)}{T_A}$ if and only if $\eval{S_A}{\sigma(\{P/x\}N)}{T_A}$, and hence $\eval{S_A\msep\term{\sigma P}_a}{\sigma(a<x>.M)}{T_A}$ if and only if $\eval{S_A\msep\term{\sigma P}_a}{\sigma(a<x>.N)}{T_A}$.

\item\case{Prefix case:} Let $\term{M;P}\rw\term{N;P}$ where $\term M\rw\term N$. Given $S$, by induction we have $\eval{R_A}{\sigma M}{S_A}$ if and only if $\eval{R_A}{\sigma N}{S_A}$, so given $\eval{S_A}{\sigma P}{T_A}$ we have $\eval{R_A}{\sigma(M;P)}{T_A}$ if and only if $\eval{S_A}{\sigma(N;P)}{T_A}$.

\item\case{Postfix case:} Let $\term{P;M}\rw\term{P;N}$ where $\term M\rw\term N$. By induction we have $\eval{S_A}{\sigma M}{T_A}$ if and only if $\eval{S_A}{\sigma N}{T_A}$, so given $\eval{R_A}{\sigma P}{S_A}$ we have $\eval{R_A}{\sigma(P;M)}{T_A}$ if and only if $\eval{R_A}{\sigma(P;N)}{T_A}$. 
%
\qedhere
\end{itemize}
\end{proof}



%------------------------------------------------------------ STRONG NORMALIZATION
\section{Proofs for section~\ref{sec:SN}: Strong Normalization}


%--------------- LEMMA: strong substitution
\substitutionStrong*

\begin{proof}
The proof is similar to the substitution lemma for the weak type system, Lemma~\ref{lem:substitutionWeak}. We cover the new cases: \emph{strong application} and \emph{weakening}.

\begin{itemize}

	% Strong application
	\item\case{Strong application case:} 
For a term $\term M=\term{[Q]a.P}$ we have the following derivations, both of the same weight, where $\type{n = n_1+n_2+n_3}$,  $\term{G = G_1+G_2+G_3}$ and $\term{D = D_1+D_2+D_3}$. In the second derivation, the premises of the top rules are stacked for space and readability. The argument is as follows. Given the first derivation, where $\term{G |- N:n}$ is introduced by a collection typing rule $\RR c$, we may partition its premisses along the decomposition $\type{n = n_1+n_2+n_3}$ to get $\term{G_i |- N:n_i}$ for $i=1,2,3$. Then we may construct the second derivation. In the reverse direction, given the second derivation, we may construct the first.
\[
\infer-[\rr s]{\term{G+D |- \{N/x\}[Q]a.P: !!k => !!m}}{
   \term{G |- N:n}
&& \infer[\rr A]{\term{x:n , D |s [Q]a.P : !!k => !!m}}{
     \term{x:n_1, D_1  |- Q : i}
   & \term{x:n_2, D_2  |- P : a(i)\,!!k => !!m}
   & \term{x:n_3, D_3  |- Q : t}
%   \begin{array}{@{}l@{}}
%      \term{x:n_1, D_1  |- Q : i}
%   \\ \term{x:n_2, D_2  |- P : a(i)\,!!k => !!m}
%   \\ \term{x:n_3, D_3  |- Q : t}
%   \end{array}
   }
}
\]
\[
\infer[\rr A]{\term{G+D |s [\{N/x\}Q].\{N/x\}P: !k => !m}}{
   \infer-[\rr s]{\term{G_1+D_1 |- \{N/x\}Q : i}}{
   \begin{array}{@{}r@{}l@{}}  
   	          \term{G_1} & \term{|- N:n_1}
   \\ \term{x:n_1 , D_1} & \term{|- Q:i}
   \end{array}
   }
&  \infer-[\rr s]{\term{G_2+D_2 |- \{N/x\}P : a(i)\,!!k => !!m}}{
   \begin{array}{@{}r@{}l@{}}  
   	          \term{G_2} & \term{|- N:n_2}
   \\ \term{x:n_2 , D_2} & \term{|- P : a(i)\,!!k => !!m}
   \end{array}
   }
&  \infer-[\rr s]{\term{G_3+D_3 |- \{N/x\}Q : t}}{
   \begin{array}{@{}r@{}l@{}}  
   	          \term{G_3} & \term{|- N:n_3}
   \\ \term{x:n_3 , D_3} & \term{|- Q:t}
   \end{array}
   }
}
\]

	% Weakening
	\item\case{Weakening case:} 
From left to right, assume the derivation below left with sub-derivations of weights $i$ and $k$. The derivation for $\term N$, ending in a collection typing rule, may be partitioned along $\type{n+m}$ to give $\term{G_1 |_n N:n}$ and $\term{G_2 |_m N:m}$ where $n+m=i$. Then we may construct the derivation below right, which by induction has a weight $j\leq n+k$.
\[
\infer-[\rr s]{\term{G+D+E |- \{N/x\}M : t}}{
   \term{G |_i N:n+m}
&& \infer[\rr W]{\term{x:n+m , D + E |s M : t}}{
     \term{x:n , D |_k M : t}
}}
\qquad
\infer[\rr W]{\term{G_1+G_2+D+E |- \{N/x\}M : t}}{
  \infer-[\rr s]{\term{G_1+D+E |- \{N/x\}M : t}}{
     \term{G_1 |_n N:n}
  && \term{x:n , D |_k M : t}    
}}
\]
From right to left, given the derivation below left we may construct that below right of the same weight $n+m$, where by alpha-conversion we may assume $x$ does not occur in the context $\term{E}$.
\[
\infer[\rr W]{\term{G+D+E |- \{N/x\}M : t}}{
  \infer-[\rr s]{\term{G+D |- \{N/x\}M : t}}{
     \term{G |_n N:n}
  && \term{x:n , D |_m M : t}
}}
\qquad
\infer-[\rr s]{\term{G+D+E |- \{N/x\}M : t}}{
   \term{G |_n N:n}
&& \infer[\rr W]{\term{x:n , D+E |- M : t}}{
     \term{x:n , D |_m M : t}
}}
\qedhere
\]
\end{itemize}
\end{proof}



%--------------- LEMMA: subject reduction, beta
\subjectReductionBeta*

\begin{proof}
By induction on the reduction context. We give the case for a beta-redex and that for the \emph{argument} context $\term{[C]a.M}$ of the strong application rule. For the other cases, the derivation for $\term{C\{M\}}$ contains exactly one subderivation for $\term{M}$, so that a change in weight is reflected directly.

\begin{itemize}

	% Beta
	\item\case{Beta case:} 
For a reduction $\term{[N]a.a<x>.M}\rw\term{\{N/x\}M}$, given the first derivation below we may construct the second. Where the first derivation has weight $n+m+k+2$, by Lemma~\ref{lem:strong substitution} the second has weight $i\leq n+m$.
\[
\infer[\rr A]{\term{G+D+E |s [N]a.a<x>.M : !!k => !!m}}{
   \term{G |_n N:i}
&& \infer[\rr l]{\term{D |- a<x>.M: a(i)\,!!k => !!m}}{
      \term{D , x:i |_m M: !!k => !!m}
   }
&& \term{E |_k N:t}
}
\]
\[
\infer[\rr W]{\term{G+D+E |s \{N/x\}M : !!k => !!m}}{
   \infer-[\rr s]{\term{G+D |- \{N/x\}M : !!k => !!m}}{
      \term{G |_n N:i}
   && \term{D , x:i |_m M: !!k => !!m}
   }
}
\]

	% Argument
	\item\case{Argument case:} 
For a reduction $\term{[M]a.P}\rw\term{[N]a.P}$ given $\term M\rw\term N$, consider the strong application inference below, where $\term{G=G_1++G_n}$ and $\type{i=[t_1..t_n]}$ Observe that there is at least one sub-derivation for $\term M$, given by $\term{E |- M:t}$, in the derivation for $\term{[M]a.P}$. Replacing every sub-derivation for $\term M$ with one for $\term N$ of strictly smaller weight then gives a strictly smaller weight for the derivation for $\term{[N]a.P}$.
\[
\infer[\rr A]{\term{G+D |s [M]a.P : !!k => !!m}}{
   \infer[\rr c]{\term{G |- M: i}}{(\term{G_i|- M:t_i})_{1\leq i\leq n}}
&& \term{D |- P: a(i)\,!!k => !!m}
&& \term{E |- M: t}
}
\qedhere
\]
\end{itemize}
\end{proof}



%--------------- LEMMA: non-beta reduction
\strongNonBeta*

\begin{proof}
The proof is similar to Lemma~\ref{lem:spine reduction}. The one new case for top-level reduction is the following.
\begin{itemize}

	% Strong application/sequence
	\item\case{Strong application/sequence case:} 
For a reduction $\term{[P]a.N;M}\rw\term{[P]a.(N;M)}$, given the first derivation below we may construct the second, of equal weight.
\[
\infer[\rr ;]{\term{G+D+E+F |- [P]a.N;M : !!k => !!n }}{
   \infer[\rr A]{\term{G+D+E |s [P]a.N : !!k => !!m}}{
      \term{G |- P: i}
   && \term{D |- N: a(i)\,!!k => !!m}
   && \term{E |- P: t}
   }
&& \term{F |- M : !!m => !!n}   
}
\]
\[
\infer[\rr A]{\term{G+D+E+F |s [P]a.(N;M) : !!k => !!n }}{
   \term{G |- P: i}
&& \infer[\rr ;]{\term{D+F |- N;M : a(i)\,!!k => !!n}}{
      \term{D |- N: a(i)\,!!k => !!m}
   && \term{F |- M : !!m => !!n}  
   } 
&& \term{E |- P: t}
}
\]
\end{itemize}
For reduction in context, $\term{C\{M\}}\rw\term{C\{N\}}$, the new case is the argument position, where there may be any (non-zero) number of sub-derivations for $\term M$ in $\term{C\{M\}}$. Replacing a sub-derivation with one of equal or lower weight then results in an overall weight that is equal or lower.
\end{proof}



