%--------------- LEMMA: SN => perpetual
\SNperpetual*

\begin{proof}
The proof is by induction on the following pair of measures: first, the sum length of reduction paths from $\term M$, and second, the size of $\term M$. Let $\term M$ be of the form $\term{[S_A].M'}$, with $\term{M'}$ not an application and proceed by case analysis on the structure of $\term{M'}$.
\begin{itemize}

	% Unit
	\item\case{Unit case:} if $\term M$ is of the form $\term{[S_A].*}$ then we have the case \emph{Normal (unit)} of the definition of $\rp$ as below. The premisses are given by the inductive hypothesis: each term $\term{N_i}$ has equal or fewer reductions than $\term M$, and is smaller. The reduction $\term M\rwn\term\MM$ follows from the reductions $\term{N_i}\rwn\term{\MM_i}$.
\[
\infer{\term{[N_1]a_1..[N_n]a_n.*} \rp \term{[\MM_1]a_1..[\MM_n]a_n.*}}{(\term{N_i}\rp\term{\MM_i})_{i\leq n}}
\]

	% Variable
	\item\case{Variable case:} if $\term M$ is of the form $\term{[S_A].x}$ then we have the case \emph{Normal (variable)} as below. It resolves as the previous case.
\[
\infer{\term{[N_1]a_1..[N_n]a_n.x} \rp \term{[\MM_1]a_1..[\MM_n]a_n.x}}{(\term{N_i}\rp\term{\MM_i})_{i\leq n}}
\]

	% Abstraction
	\item\case{Abstraction case:} if $\term{M'}$ an abstraction $\term{a<x>.N}$ there are three sub-cases. If $\term{[S_A]}$ is empty, we have the case \emph{Normal (abstraction)} as below.
\[
\infer{\term{a<x>.N}\rp\term{a<x>.\MM}}{\term{N}\rp\term \MM}
\]
If $\term{[S_A]}$ is of the form $\term{[T_A].[P]a}$, ending in a push on location $a$, we have the case \emph{Beta} as below, with the reduction $\term{[T_A].[P]a.a<x>.N}\rw\term{[T_A].\{P/x\}N}\rw\term\MM$.
\[
\infer{\term{[T_A].[P]a.a<x>.N}\rp\term\MM}{\term{[T_A].\{P/x\}N}\rp\term\MM}
\]
If $\term{[S_A]}$ is of the form $\term{[T_A].[P]b}$, ending in a push on location $b\neq a$, we have the case \emph{Passage} as below, with the reduction $\term{[T_A].[P]b.a<x>.N}\rw\term{[T_A].a<x>.[P]b.N}\rw\term\MM$.
\[
\infer{\term{[T_A].[P]b.a<x>.N}\rp\term\MM}{\term{[T_A].a<x>.[P]b.N}\rp\term\MM}
\]
	% Sequence (unit)	
	\item\case{Unit/sequence case:}
If $\term M$ is of the form $\term{[S_A].(*;P)}$ we have the case \emph{Next} below, with the reduction $\term{[S_A].(*;P)}\rw\term{[S_A].P}\rwn\term\MM$. 
\[
\infer{\term{[S_A].(*;P)} \rp \term\MM}{\term{[S_A].P}\rp \term\MM}
\]

	% Sequence (variable)
	\item\case{Variable/sequence case:}
If $\term M$ is of the form $\term{[S_A].(x;P)}$ we have the case \emph{Normal (sequence)} as below. The inductive hypothesis gives the premisses, which each have a smaller measure. The reduction from $\term M$ follows by that for each $\term{N_i}$ and $\term P$.
\[
\infer{\term{[N_1]a_1..[N_n]a_n.(x;P)} \rp \term{[\MM_1]a_1..[\MM_n]a_n.(x;\MM)}}{(\term{N_i}\rp\term{\MM_i})_{i\leq n} && \term P\rp\term\MM}
\]

	% Sequence (abstraction)
	\item\case{Abstraction/sequence case:}
If $\term M$ is of the form $\term{[S_A].(a<x>.N;P)}$ we have the case \emph{Prefix (pop)} as below, with the reduction $\term{[S_A].(a<x>.N ; P)} \rw \term{[S_A].a<x>.(N ; P)}\rwn\term\MM$.
\[
