\toprule
Configuration & LCS Sim. & Missing & Extra & Order \\
\midrule
Full System & \textbf{0.183} & \textbf{10.17} & 8.32 & \textbf{9.47} \\
No LTL Translation & 0.178 & 10.25 & \textbf{8.25} & 9.80 \\
No LLM Verification & 0.0717 & 10.28 & 9.14 & 16.48 \\
\bottomrule
