	%	where $k$ indicates the iteration index. If the optimization problem \eqref{eq:ADMM} is convex, the ADMM algorithm \eqref{eq:ADMM-updates} is guaranteed to converge to the minimum of \eqref{eq:ADMM} \cite{boyd2011distributed}.

	%	\subsection{Verification as Distributed Optimization}
	We duplicate local variables $X_i$ and obtain an equivalent form of \eqref{eq:coupling condition} as follows.
	\begin{equation}\label{eq:general-admm}
		\begin{aligned}
			\min_{X_i}\; & 1\\
			\text{s.t.}\;\;\;\;\; & X_i\in\mathcal{L}_i,\;\; \forall i\in\mathcal{V}  \\
			& l^c(Z_1,\dots,Z_N)\preceq0 \\
			& X_i=Z_i,\; \forall i\in\mathcal{V}  
		\end{aligned}
	\end{equation}

	The optimization problem \eqref{eq:general-admm} can be solved by ADMM with convergence guarantee as long as the local constraint sets $\mathcal{L}_i$ is convex \cite{boyd2011distributed}. In the following, we focus on the special case that considers the Krasovskii's storage function for local dissipativity. Note, however, that the proposed algorithm can readily adapt to different local optimization sub-problems as long as $\mathcal{L}_i$ is convex.

	Now consider Proposition \ref{pro:c5-lmi} for constructing local constraints. Define a matrix-valued function $l_i^d$ for each dynamic bus
	\begin{equation*}
		l_i^d(X_i,\mathcal{P}_i):=
		\begin{bmatrix}
			\mathcal{P}_iA_i+A_i^\T \mathcal{P}_i+\epsilon I & *\\
			B_i^\T\mathcal{P}_i&0
		\end{bmatrix}-
		*^\text{T}
		X_i
		\begin{bmatrix}
			0&I\\
			C_i&D_i
		\end{bmatrix},
	\end{equation*}
	and $l_i^s$ for each static bus
	\begin{equation*}
		l_i^s(X_i):=
		-
		\begin{bmatrix}
			I\\
			D_i
		\end{bmatrix}^\text{T}
		X_i
		\begin{bmatrix}
			I\\
			D_i
		\end{bmatrix},
	\end{equation*}
	where $*$ stands for the symmetric part, $A_i$, $B_i$, $C_i$, and $D_i$ are state-input-dependent Jacobian matrices as defined in \eqref{eq:c5-lmi} and \eqref{eq:c5-Ps}.
	Then \eqref{eq:general-admm} becomes

	\begin{equation}\label{eq:ADMM-ps}
		\begin{aligned}
			\min_{\mathcal{P}_i,X_i,Z_i}\; & 1\\
			\text{s.t.}\;\;\;\;\; & l^d_i(X_i,\mathcal{P}_i)\preceq0,\;\mathcal{P}_i\succ0,\;\; \forall i\in\mathcal{V}_1  \\
			& l^s_i(X_i)\preceq0,\;\; \forall i\in\mathcal{V}_2  \\
			& l^c(Z_1,\dots,Z_N)\preceq0 \\
			& X_i=Z_i,\; \forall i\in\mathcal{V}  
		\end{aligned}
	\end{equation}

	To improve the convergence, we introduce a relaxation variable $t_i$ for each local constraint and consider
	\begin{equation}\label{eq:ADMM-ps-relax}
		\begin{aligned}
			\min_{\mathcal{P}_i,X_i,Z_i,t_i}\; & \sum_{i\in\mathcal{V}}-t_i\\
			\text{s.t.}\;\;\;\;\; & l^d_i(X_i,\mathcal{P}_i)\preceq-t_iI,\;\mathcal{P}_i\succ0,\;t_i\leq\bar{t}\;\; \forall i\in\mathcal{V}_1  \\
			& l^s_i(X_i)\preceq-t_iI,\;t_i\leq\bar{t}\;\; \forall i\in\mathcal{V}_2  \\
			& l^c(Z_1,\dots,Z_N)\preceq0 \\
			& X_i=Z_i,\; \forall i\in\mathcal{V}  
		\end{aligned}
	\end{equation}

	Here, $\bar{t}>0$ serves as a uniform upper bound for $t_i$, preventing excessive values of $t_i$ while ensuring numerical stability. A practical choice is $\bar{t}=100\epsilon$ where $\epsilon>0$ corresponds to the error tolerance for LMI constraint satisfaction.
	An optimal solution of \eqref{eq:ADMM-ps-relax} with all $t_i>0$ guarantees feasibility in the original problem \eqref{eq:ADMM-ps}. Ideally, the solution achieves $t_i^*=\bar{t}$, balancing constraint relaxation across subsystems. This relaxation significantly enhances convergence, especially when the original problem \eqref{eq:ADMM-ps} is infeasible.

	%	\begin{remark}
		For nonlinear subsystems, \eqref{eq:ADMM-ps-relax} involve infinitely many local constraints since $l_i^d$ and $l_i^s$ depend on $x_i$ and $u_i$. It should be verified at every point in the required dissipative region $\mathcal{D}_i$. To this end, one can transform the local constraints into a robust optimization program and leverage advanced robust optimization techniques\cite{ben2002robust}. One can also adapt a scenario optimization program by sampling points in $\mathcal{D}_i$. After solving \eqref{eq:ADMM-ps-relax} and obtaining feasible $X_i$, one can re-characterize the accurate dissipative region $\mathcal{D}_i$ by the dissipation inequality. We adopt the latter approach in the case studies in Sec \ref{sec:case}.
		%	\end{remark}
	\subsection{Distributed Algorithm Based on ADMM}
	Define the local Lagrangian for \eqref{eq:ADMM-ps-relax} as
	\begin{equation*}
		L_\rho^i(X_i,Z_i,Y_i):=-t_i+\text{Tr}(Y_i^\T(X_i-Z_i)) +\frac{\rho}{2}\|X_i-Z_i\|_{F}^2,
	\end{equation*}
	where Tr denotes the trace of a matrix and $\|\cdot\|_{F}$ denotes the Frobenius norm. Then the augmented Lagrangian of \eqref{eq:ADMM-ps-relax} is
	\begin{equation*}
		L_\rho(X,Z,Y):=\sum_{i\in\mathcal{V}}L_\rho^i(X_i,Z_i,Y_i), 
	\end{equation*}
	where with a little abuse of notation we let $X$, $Z$, and $Y$ denote the collection of $X_i$, $Z_i$, and $Y_i$, respectively. Based on the augmented Lagrangian, at the $k$-th iteration, our algorithm performs the following six steps.

	\subsubsection{X-update}
	Each dynamic bus $i\in\mathcal{V}_1$ solves the following problem
	\begin{equation}\label{eq:X-update-1}
		\begin{aligned}
			\min_{\mathcal{P}_i,X_i,t_i}\; & L_{\rho^k}^i(X_i,Z_i^k,Y_i^k)\\
			\text{s.t.}\;\;\;\; & l^d_i(X_i,\mathcal{P}_i)\preceq-t_iI,\;\mathcal{P}_i\succ0,\;t_i\leq\bar{t}  
		\end{aligned}
	\end{equation}
	Each static bus $i\in\mathcal{V}_2$ solves the following problem
	\begin{equation}\label{eq:X-update-2}
		\begin{aligned}
			\min_{X_i,t_i}\; & L_{\rho^k}^i(X_i,Z_i^k,Y_i^k)\\
			\text{s.t.}\;\; & l^s_i(X_i)\preceq-t_iI,\;t_i\leq\bar{t}  
		\end{aligned}
	\end{equation}
	The optimal solution yields $X^{k+1}$.
	\subsubsection{p-check}
	If for some error tolerance $\epsilon>0$, we have $t_i>\epsilon$ for all $i\in\mathcal{V}$, then we perform the p-check step by solving the following problem.
	\begin{equation}\label{eq:p-check}
		\begin{aligned}
			\min_{p_i,t_z}\;\; & t_z\\
			\text{s.t.}\;\; & l^c(p_1X_1^{k+1},\dots,p_NX_N^{k+1})\preceq t_zI \\
			& p_1+\cdots+p_N=N,\;\; p_i>0, \forall i\in\mathcal{V}
		\end{aligned}
	\end{equation}
	Here, we use a 1-norm constraint to bound $p_i$. If the optimal $t_z<-\epsilon$, then the p-check passes and justifies the coupling condition and the iteration terminates.

	\subsubsection{Z-update}
	If p-check fails or is not performed, we do Z-update. The system coordinator solves the following problem.
	\begin{equation}\label{eq:Z-update}
		\begin{aligned}
			\min_{Z_i}\; & L_{\rho^k}(X^{k+1},Z,Y^k)\\
			\text{s.t.}\;\; & l^c(Z_1,\dots,Z_N)\preceq0 
		\end{aligned}
	\end{equation}
	The optimal solution yields $Z^{k+1}$.

	\subsubsection{Y-update}
	We update the dual variable by
	\begin{equation}\label{eq:Y-update}
		Y_i^{k+1}:=Y_i^k+\rho^k(X_i^{k+1}-Z_i^{k+1}),\;\;\forall i\in\mathcal{V}
	\end{equation}

	\subsubsection{Residuals update}
	We calculate the primal residual in the $k$-th iteration by
	\begin{equation}\label{eq:r-update}
		r^{k}=\left[X_1^{k+1},\dots,X_N^{k+1}\right]-\left[Z_1^{k+1},\dots,Z_N^{k+1}\right]
	\end{equation}
	And calculate the dual residual in the $k$-th iteration by
	\begin{equation}\label{eq:s-update}
		s^{k}=\rho^k\left(\left[Z_1^{k+1},\dots,Z_N^{k+1}\right]-\left[Z_1^{k},\dots,Z_N^{k}\right]\right)
	\end{equation}
	If $\|r^{k}\|_F<\epsilon_{pri}$ and $\|s^{k}\|_F<\epsilon_{dual}$, then we terminate the iteration. Here, $\epsilon_{pri}>0$ and $\epsilon_{dual}>0$ are the error tolerances for the primal and dual residuals, respectively. Guidelines for choosing these tolerances can be found in \cite{boyd2011distributed}.

	\subsubsection{$\rho$-update}
	We use the following adaptive penalty parameter $\rho^k$ for each iteration to improve the convergence. 
	\begin{equation}\label{eq:rho-update}
		\rho^{k+1}=\left\lbrace 
		\begin{aligned}
			\tau^{\text{incr}}\rho^k \;\;\;\; &\text{if} \left\|r^k\right\|_{F}>\mu\left\|s^k\right\|_{F}\\
			\rho^k/\tau^{\text{decr}} \;\;\;\; &\text{if} \left\|s^k\right\|_{F}>\mu\left\|r^k\right\|_{F}\\
			\rho^k \;\;\;\; &\text{otherwise,}
		\end{aligned}\right.
	\end{equation}
	where $\mu>1$, $\tau^{\text{incr}}>1$, and $\tau^{\text{decr}}>1$ are parameters.

	The pseudo code of our algorithm is summarized below, together with the flow chart as shown in Fig. \ref{fig:algorithm}.
	\begin{algorithm}[htb]
		\caption{Distributed verification of the coupling condition}
		\label{al:1}
		\KwIn{Error tolerance $\epsilon>0$, $\epsilon_{pri}>0$, and $\epsilon_{dual}>0$. Adaptive penalty parameters $\mu>1$, $\tau^{\text{incr}}>1$, and $\tau^{\text{decr}}>1$. Upper bound $\bar{t}>0$ in the X-update. Maximum iteration number $M$. Initial values $X_i^1$, $Z_i^1$, $Y_i^1$, and $\rho^1$.}
		\KwOut{$X_i^*$ that verifies the local and coupling conditions.}
		\BlankLine
		Initialize $X_i^1$, $Z_i^1$, $Y_i^1$, and $\rho^1$. Set $k=1$;

		\For{$k=1$ \textnormal{to} $M$}
		{
			\ForEach{$i\in\mathcal{V}$}{
				$X$-\textit{update}: Solve \eqref{eq:X-update-1} or \eqref{eq:X-update-2} and obtain $X_i^{k+1}$ and $t_i$;
			} 
			\If{$t_i>\epsilon$, $\forall i\in\mathcal{V}$}{
				$p$-\textit{check}: Solve \eqref{eq:p-check} and obtain $t_z$;

				\If{$t_z<-\epsilon$}{
					\Return{$X_i^*=X_i^{k+1}$ and $t_i$}
				}
			}
			$Z$-\textit{update}: Solve \eqref{eq:Z-update} and obtain $Z^{k+1}$;

			$Y$-\textit{update}: Update the dual variable by \eqref{eq:Y-update};

			\textit{Residuals update}: Update the primal and the dual residuals by \eqref{eq:r-update} and \eqref{eq:s-update}, respectively;

			\If{$\|r^{k}\|_F<\epsilon_{pri}$ and $\|s^{k}\|_F<\epsilon_{dual}$}{
				\Return{$X_i^*=X_i^{k+1}$ and $t_i$}
			}

			$\rho$-\textit{update}: Update the penalty by \eqref{eq:rho-update} and obtain $\rho^{k+1}$.
		}
	\end{algorithm}
	\begin{figure}[htb]
		\centering
		\includegraphics[width=.9\hsize]{algorithm}
		\caption{The flow chart of Algorithm \ref{al:1}.}
		\label{fig:algorithm}
	\end{figure}
