\subsection{Upper and lower skins}
\label{section:upper-and-lower-skins}

Assume that $X \subseteq \Rspace^d$ is vertically convex relative to \M and let $m \in
\pi_\M(X)$.  The endpoints (possibly equal) of the segment $\Normal m
\M \cap B(m,\rtube) \cap X$ are denoted by $\low X m$ and $\up X m$,
with $\up X m$ being above $\low X m$ along the direction of the unit
normal vector $\normal m$. With this notation, $X$ can be expressed as
a union of disjoint normal segments:
\[
X  = \dot{\bigcup}_{m \in \pi_\M(X)} [\low X m, \up X m].
\]
The {\em upper skin} and {\em lower
  skin} of $X$ are, respectively:
\begin{align*}
  \UpperSkin X &= \{ \up X m \mid m \in \pi_\M(X) \},\\
  \LowerSkin X &= \{ \low X m \mid m \in \pi_\M(X) \}.
\end{align*}
Figure~\ref{figure:upper-lower-skins} displays an example.
Our goal is to study the skins of $\US{K}$, for which we need two extra definitions.


\begin{definition}[Vertical simplex]
  A simplex $\sigma \subseteq \Rspace^d$ such that $\Conv\sigma
    \subseteq \Rspace^d \setminus \MA{\M}$ is {\em vertical} relative
  to \M if there exists a pair of distinct points in $\Conv \sigma$
  sharing the same projection onto \M.
\end{definition}


\begin{definition}[Non-vertical skeleton]
  Assume that $\US{K}  \subseteq \Rspace^d \setminus \MA{\M}$.  We say that $K$ has a {\em non-vertical skeleton} relative to \M if $K$ contains no vertical $i$-simplices relative to \M for all integers $0 < i <d$.
\end{definition}

The next lemma is a key property of vertically convex
simplicial complexes:

\begin{restatable}{lemmma}{SkinsHomeomorphicToManifold}
  \label{lemma:upper-and-lower-skins-homeomorphic-to-manifold}
  Suppose that $K$ is vertically convex and has a non-vertical
  skeleton relative to \M. Then, the upper and lower skins of
  $\US{K}$ are closed sets, each homeomorphic to $\pi_\M(\US{K})$.
  The homeomorphism is realized in both cases by $\pi_\M$. In addition,
  \begin{equation}
    \label{eq:boundary-equals-upper-and-lower}
  \partial \US{K} = \UpperSkin {\US{K}} \cup \LowerSkin {\US{K}}.
  \end{equation}
\end{restatable}

A simple consequence follows:

\begin{restatable}{lemma}{UpperEqualsLowerConsequence}
  \label{lemma:upper-equals-lower-consequence}
  Let $K$ be vertically convex and with non-vertical skeleton
  relative to $\M$. If $\UpperSkin {\US{K}} = \LowerSkin {\US{K}}$,
  then $K = \partial K$.
\end{restatable}

Aiming for a simplicial version of Equation
\eqref{eq:boundary-equals-upper-and-lower}, we define the {\em upper
  complex} of $K$ and the {\em lower complex} of $K$ relative to \M
as follows:
\begin{align*}
  \UpperC K &= \{ \nu \subseteq \partial K \mid  \Conv{\nu} \subseteq \UpperSkin{\US{K}} \}, \\
  \LowerC K &= \{ \nu \subseteq \partial K \mid  \Conv{\nu} \subseteq \LowerSkin{\US{K}} \}.
\end{align*}
By construction, both are subcomplexes of $\partial K$.  A
combinatorial equivalent of
Lemma~\ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold} is:

\begin{restatable}{lemmma}{uppLowComplex}
  \label{lemma:upper-and-lower-complex-equal-boundary}
  Let $K$ be vertically convex with non-vertical skeleton relative to $\M$. Then,
  \begin{align*}
    &\US{\UpperC K} = \UpperSkin{\US{K}},\\
    &\US{\LowerC K} = \LowerSkin{\US{K}} \,\,\, \text{ and } \\
    &\partial K = \UpperC K \, \cup \, \LowerC K.
  \end{align*}
  Moreover, if $\pi_\M(\US{K}) = \M$, both $\UpperC K$ and $\LowerC K$ are triangulations of $\M$.
\end{restatable}


\subsection{Upper and lower facets of a $d$-simplex}
\label{section:upper-and-lower-facets}


Let $\sigma$ be a non-degenerate $d$-simplex of $\Rspace^d$ such that $\Conv \sigma \subseteq \Offset \M \rtube$ for some $\rtube < \Reach{\M}$. In that case,  $\Cl \sigma$ is embedded and
vertically convex relative to $\M$. The facets of $\sigma$ can be partitioned into \emph{upper facets} and \emph{lower facets} of $\sigma$ relative to $\M$ as follows:
\begin{align*}
  \Above \sigma &= \{ \nu \text{ facet of } \sigma \mid \nu \in \UpperC{\Cl \sigma} \} \\
  \Below \sigma &= \{ \nu \text{ facet of } \sigma \mid \nu \in \LowerC{\Cl \sigma} \}.
\end{align*}
An example can be seen in Figure~\ref{figure:simplex}, where one can also observe the following property:

\begin{figure}[htb]
  \def\svgwidth{.6\linewidth}
  \centering\input{Figures/simplex-modified.pdf_tex}
  \caption{Upper (smooth green edges) and lower (dotted pink edge) facets of a $2$-simplex $\sigma\subseteq\Rspace^2$.}
  \label{figure:simplex}
\end{figure}

\begin{restatable}{lemmma}{facetsLem}
  \label{lemma:facets}
  Consider a non-degenerate $d$-simplex $\sigma \subseteq \Rspace^d$ such
  that $\Conv \sigma \subseteq \Offset \M \rtube$ for some $\rtube <
  \Reach{\M}$. If $\sigma$ has no vertical facets relative to \M,
  then $\Above \sigma$ and $\Below \sigma$ are non-empty sets that
  partition the facets of $\sigma$.
\end{restatable}


\section{Vertically collapsing simplicial complexes}
\label{section:vertical-collapses}

In this section, assuming that $\US{K} \subseteq \Offset \M \rtube$
for some $\rtube < \Reach{\M}$, we introduce an algorithm for
simplifying $K$ using vertical collapses relative to $\M$
(Section~\ref{section:algorithm}) and establish conditions for when it
outputs a triangulation of $\M$
(Section~\ref{section:correctness}). We first present a naive version
that requires the knowledge of $\M$ and then present a practical
version (Section~\ref{section:in-practice}).



\subsection{Naive algorithm}
\label{section:algorithm}

\begin{definition}[Vertically free simplices]
\label{definition:vertically-free-simplex}
  A simplex $\tau$ is said to be {\em free from
    above (resp., free from below)} in $K$ relative to \M if
  \begin{itemize}
  \item $\tau$ is a free simplex of $K$;
  \item the unique inclusion-maximal simplex $\sigma$ in $\Star \tau K$ has dimension $d$;
  \item the set of $(d-1)$-simplices in $\Star \tau K$ is exactly the set of upper (resp.,
    lower) facets of $\sigma$ relative to \M.
  \end{itemize}
  We say that $\tau$ is {\em vertically free} in $K$ relative to \M if
  $\tau$ is either free from above or from below in $K$ relative to
  \M. See Figures~\ref{figure:collapses} and \ref{figure:sources-and-sinks}
for a depiction.
\end{definition}

\begin{remark}
  \label{remark:vertically-free-relative-to-hyperplanes}
  Definition \ref{definition:vertically-free-simplex} can be naturally extended to non-compact submanifolds \M. In particular, it holds for hyperplanes, a fact that we use in
  Algorithm~\ref{algo:practical}.
\end{remark}


\ignore{
  \bianca{Note that the definition can be naturally extended to non-compact surfaces.
  }
  \biancacmt{I don't think there is need to specifically talk abouit the hyperplanes once we said it holds for non-compact \M. But if you feel it would be more adequate, we could add something like:

  	In particular, it holds for hyperplanes, a fact that we use in Algorithm~\ref{algo:practical}.}
}

\begin{definition}[Vertical collapse]
A {\em vertical collapse} of $K$ 
relative to \M is the operation of removing the star of a simplex $\tau \in K$ that is vertically free
relative to \M.
\end{definition}

\begin{figure}[htb]
  \def\svgwidth{1.0\linewidth}
  \centering\input{Figures/collapses-modified.pdf_tex}
  \caption{ Schematic drawings of $K$ in blue (smooth filled
    areas). Top row: the edge $\tau$ is free but not vertically free
    relative to \M and collapsing $\tau$ does not preserve the
    vertical convexity of $K$. Bottom row: the vertex $\tau$ is free
    from above relative to \M, so that collapsing $\tau$ preserves the
    vertical convexity of $K$ (Lemma~\ref{lemma:invariant}). The
    $(d-1)$-simplices of $K$ that disappear with $\tau$ are precisely
    the upper facets of $\sigma$ (smooth edges, in green).  }
  \label{figure:collapses}
\end{figure}


A vertical collapse of $K$ can be seen as compressing the underlying
space of $K$ by shifting its upper or lower skin along directions
normal to $\M$; see Figure~\ref{figure:collapses}. Our
first algorithm, outlined in Algorithm~\ref{algo:generic}, simplifies
$K$ by iteratively applying vertical collapses relative to $\M$. It is
worth noting that the algorithm operates on any simplicial complex $K$
with $\US{K} \subseteq \Offset{\M}{\rtube}$ for $\rtube < \Reach{\M}$,
irrespective of whether $K$ is vertically convex relative to $\M$ or
not.

\begin{algorithm}
  \caption{\hypertarget{naivealgo}{$\NaiveVertSimp(K)$}}
  \begin{algorithmic}
    \WHILE{ there is a simplex $\tau$ vertically free in $K$ relative to \M }
    \STATE{ Collapse $\tau$ in $K$; }
    \ENDWHILE
  \end{algorithmic}
  \label{algo:generic}
\end{algorithm}

\subsection{Correctness}
\label{section:correctness}

We now establish conditions under which $\NaiveVertSimp(K)$ transforms $K$
into a triangulation of \M.  For that,
we introduce a binary relation over $d$-simplices:


\begin{definition}[Below relation $\below$]
  Let $\sigma_0, \sigma_1 \subseteq \Rspace^d$ be two $d$-simplices
  sharing a common facet $\nu = \sigma_0 \cap \sigma_1$
  and  let $\Conv{\sigma_0} \cup \Conv{\sigma_1} \subseteq
  \Offset \M \rtube$ for some $\rtube < \Reach{\M}$. We say that
  $\sigma_0$ is {\em below} $\sigma_1$ (or that $\sigma_1$ is {\em
    above} $\sigma_0$) relative to \M, denoted $\sigma_0 \below
  \sigma_1$, if $\nu$ is an upper facet of $\sigma_0$ and a lower
  facet of $\sigma_1$ relative to \M.
\end{definition}

Note that the relation $\below$ is not acyclic in general, see Figure~\ref{figure:cycle-2d}.

\begin{figure}[htb]
  \def\svgwidth{0.5\linewidth}
  \centering\input{Figures/socg-cyclic-complex-modified.pdf_tex}
  \caption{ Non-Delaunay triangles that form a cycle in the $\below$
    relation and their dual graph. \label{figure:cycle-2d} }
\end{figure}

\begin{theorem}[Correctness]
  \label{theorem:correctness-generic-simplification}
  Consider $K$ such that $\US{K} \subseteq \Offset \M \rtube$ for some
  $\rtube < \Reach{\M}$ and assume the following:
  \begin{description}
  \item[Injective projection:] $K$ has a non-vertical skeleton relative to \M.
  \item[Covering projection:] $\pi_\M(\US{K}) = \M$.
  \item[Vertical convexity:] $K$ is vertically convex relative to \M.
  \item[Acyclicity:] $\below$ is acyclic over $d$-simplices of $K$.
  \end{description}
  Then, $\NaiveVertSimp(K)$ transforms $K$ into a
  triangulation of $\M$.
\end{theorem}


The remaining of this section aims to prove
Theorem~\ref{theorem:correctness-generic-simplification} and we
consider $K$ such that $\US{K} \subseteq \Offset \M r$ for some $r < \Reach{\M}$.
Using the
relation $\below$, associate to $K$ its dual graph $G_\M(K)$ that has
one node for each $d$-simplex of $K$ and one arc for each pair of
$d$-simplices $\sigma_0, \sigma_1 \in K$ that share a common
facet $\sigma_0 \cap \sigma_1$. Direct an arc from $\sigma_0$
to $\sigma_1$ if $\sigma_0 \below \sigma_1$, and from $\sigma_1$ to
$\sigma_0$ otherwise. Since either $\sigma_0 \below \sigma_1$ or
$\sigma_1 \below \sigma_0$, this yields a well-defined orientation for
each arc in the dual graph. Figures~\ref{figure:cycle-2d} and
\ref{figure:sources-and-sinks} show examples.

\begin{figure}[htb]
  \def\svgwidth{.8\linewidth}
  \centering\input{Figures/socg-sources-and-sinks-modified.pdf_tex}
  \caption{A vertically convex simplicial complex $K$ relative to $\M$. All free simplices are highlighted by thickness. There are four simplices free from below (represented by three dotted edges and one triangular vertex, in pink) and four simplices free from above (represented by two dashed edges and two square vertices, in green). The dual graph (oriented edges, in blue) has four sources (vertices filled by dots, in pink) and four sinks (vertices with a smooth filling, in green), in
    	one-to-one correspondence with the free simplices from below and above.}
  \label{figure:sources-and-sinks}
\end{figure}


In a directed graph, a \emph{source} is a node with only outgoing
arcs, while a \emph{sink} is a node with only incoming arcs. The next
lemma states that a vertical collapse in $K$ corresponds to the
removal of either a sink or a source in $G_\M(K)$ and conversely. For that, given a
finite set of abstract simplices $\Sigma = \{\sigma_1, \sigma_2,
\ldots, \sigma_k\}$, let $\bigcap \Sigma = \bigcap_{i=1}^k \sigma_i$
denote the set of vertices that belong to all simplices in
$\Sigma$. If $\bigcap \Sigma \neq \emptyset$, it forms an abstract
simplex.


\begin{restatable}[Sinks and sources]{lemmma}{correspondFreeTerminalNode}
  \label{lemma:correspondance-free-terminal-node}
  Consider $K$ such that $\US{K} \subseteq \Offset \M
    \rtube$ for some $\rtube < \Reach{\M}$ and assume that $K$
    satisfies the injective projection, covering projection and
    vertical convexity assumptions of Theorem~\ref{theorem:correctness-generic-simplification}.
  Consider a $d$-simplex $\sigma \in K$ and let $\tau = \bigcap
    {\Above \sigma}$ and $\tau' = \bigcap {\Below \sigma}$. Then,
  \begin{itemize}
  \item $\tau$ is a free simplex of $K$ from above relative to \M
    $\iff$ $\sigma$ is a sink of $G_\M(K)$.
  \item $\tau'$ is a free simplex of $K$ from below relative to \M
    $\iff$ $\sigma$ is a source of $G_\M(K)$.
  \end{itemize}
\end{restatable}

\medskip

The next lemma provides an invariant for the while-loop of
Algorithm~\ref{algo:generic}.


\begin{restatable}[Loop invariant]{lemma}{AlgorithmInvariant}
  \label{lemma:invariant}
  Consider $K$ 
  such that $\US{K} \subseteq \Offset \M \rtube$ for some
  $\rtube < \Reach{\M}$. Let $\tau$ be a vertically free simplex in
  $K$ relative to \M. Let $K'$ be obtained from $K$ by collapsing
  $\tau$ in $K$. If $K$ satisfies the assumptions of
  Theorem~\ref{theorem:correctness-generic-simplification}, then so
  does $K'$.  
\end{restatable}


  \begin{lemma}[Upon termination]
    \label{lemma:termination}
    Consider $K$ such that $\US{K} \subseteq \Offset \M \rtube$ for
    some $\rtube < \Reach{\M}$ and assume that $K$ satisfies the
    injective projection and vertical convexity assumptions of
    Theorem~\ref{theorem:correctness-generic-simplification}.  If
    $G_\M(K) = \emptyset$, then
    $\LowerSkin{\US{K}}=\UpperSkin{\US{K}}$.
\end{lemma}


\begin{proof}
  We establish the contrapositive:
  \begin{equation*}
    \LowerSkin{\US{K}} \neq \UpperSkin{\US{K}} \quad \implies \quad G_\M(K) \neq \emptyset
  \end{equation*}
  Suppose that the two skins are distinct, in other words, that there
  exists $m \in \M$ such that $\low {\US{K}} m \neq \up {\US{K}}
  m$ and let us show that the segment $[\low {\US K} m,\up K m]$
  intersects the support of at least one $d$-simplex of $K$, implying
  $G_\M(K)\neq\emptyset$.  Suppose, for a contradiction, that $[\low
    {\US{K}} m,\up {\US K} m]$ only intersects the support of
  $i$-simplices of $K$ for $i<d$.  As $\low {\US K} m \neq \up {\US K}
  m$ and $K$ has a finite number of simplices, at least one of these
  $i$-simplices, say $\nu$, intersects $[\low {\US K} m,\up {\US K}
    m]$ in a non-zero length segment containing distinct points $x,y
  \in \Conv \nu \cap [\low {\US K} m,\up {\US K} m]$.  Hence, $x$ and
  $y$ share the same orthogonal projection $m$ onto \M, implying that
  $\nu$ is vertical relative to \M.  This contradicts the injective
  projection assumption on $K$ and therefore establishes the contrapositive.
\end{proof}


We now prove the correctness of $\NaiveVertSimp(K)$.

\begin{proof}[Proof of Theorem \ref{theorem:correctness-generic-simplification}.]
  The algorithm starts with $K$ that satisfies the theorem
  assumptions.  By Lemma~\ref{lemma:invariant}, after each iteration
  of the while-loop we obtain a new $K$ that continues to satisfy
  those assumptions.  Since each iteration involves a vertical
  collapse of $K$ relative to $\M$, the number of $d$-simplices of $K$
  is reduced. Thus, the algorithm must terminate. Upon termination,
  there are no vertically free simplices in $K$ relative to \M. By
  Lemma \ref{lemma:correspondance-free-terminal-node}, this implies
  that, when Algorithm~\ref{algo:generic} terminates, $G_\M(K)$ has no
  terminal node (neither a source nor a sink) and is therefore
  empty. By Lemma \ref{lemma:termination}, it follows that
    $\LowerSkin{\US{K}}=\UpperSkin{\US{K}}$.  By Lemma
  \ref{lemma:upper-equals-lower-consequence}, we have $K = \partial K$
  and Lemma~\ref{lemma:upper-and-lower-complex-equal-boundary} implies
  \[
  K = \partial K = \UpperC K = \LowerC K,
  \]
  with $K$ being a triangulation of \M.
\end{proof}


\subsection{Practical version}
\label{section:in-practice}

Algorithm~\ref{algo:generic} relies on knowledge of $\M$, which
renders it impractical for implementation since $\M$ is typically
unknown.  In this section, we introduce
Algorithm~\ref{algo:practical}, a feasible variant that is correct if
the $(d-1)$-simplices of $K$ form a sufficiently small angle with \M;
see Appendix \ref{appendix:angles} for a definition of the
angle between affine spaces. In this variant, we assign an affine
space $\HH_\tau$ to each $\tau \in K$: for a free simplex $\tau$ with
a $d$-dimensional coface $\sigma$, $\HH_\tau$ is defined as the
hyperplane spanned by any facet of $\sigma$. Otherwise, set $\HH_\tau
= \emptyset$. We also use the notion of vertically free simplices relative to
$\HH_\tau$, extending Definition~\ref{definition:vertically-free-simplex} as indicated in Remark~\ref{remark:vertically-free-relative-to-hyperplanes}.


\begin{algorithm}
  \caption{\hypertarget{practicalalgo}{$\PracticalVertSimp(K)$}}
  \begin{algorithmic}
    \WHILE{ there is a simplex $\tau$ vertically free in $K$ relative to $\HH_\tau$ }
    \STATE{ Collapse $\tau$ in $K$; }
    \ENDWHILE
  \end{algorithmic}
  \label{algo:practical}
\end{algorithm}

\begin{restatable}[Correctness]{theorem}{InPractice}
  \label{theorem:in-practice}
  Suppose that $K$ satisfies the assumptions of
  Theorem~\ref{theorem:correctness-generic-simplification} and, in addition, for all
  $(d-1)$-simplices $\nu$ of $K$
  \begin{equation}
    \label{eq:angle-in-practice}
    \max_{a \in \nu} \angle(\Aff \nu, \Tangent {\pi_\M(a)} \M) \, < \, \frac{\pi}{4}.    
  \end{equation}
  Then, $\PracticalVertSimp(K)$ transforms $K$ into a triangulation
  of $\M$.
\end{restatable}



\section{Correct reconstructions from \texorpdfstring{$\alpha$}{α}-complexes}
\label{section:alpha-complexes}

In this section, we assume that $\M$ is sampled by a finite point set $P$ and consider Algorithms~\ref{algo:naive-squash} and~\ref{algo:practical-squash}, which apply vertical collapses to $\Del{P,\alpha}$ either straightforwardly or practically. We introduce two parameters, $\varepsilon \geq 0$ and $\delta \geq 0$, to control the sample density and noise of $P$, respectively, and a scale parameter $\alpha \geq 0$. Section~\ref{section:stating-reconstruction-results} establishes conditions ensuring the correctness of Algorithms~\ref{algo:naive-squash} and~\ref{algo:practical-squash}, with the proof outlined in Section~\ref{section:proof-technique}. Section~\ref{section:surfaces-in-3D} shows how these conditions hold for a wide range of $\frac{\varepsilon}{\reach}$ and $\frac{\alpha}{\reach}$ when $\M$ is a surface in $\Rspace^3$ and $P$ is noiseless. This result is extended to the restricted Delaunay complex of $P$ in Section~\ref{section:restricted-Delaunay-complex}.

\begin{algorithm}
  \caption{\hypertarget{naivesquash}{$\NaiveSquash(P,\alpha)$}}
  \begin{algorithmic}
	\STATE{ $K \leftarrow \Del{P,\alpha}$;  $\NaiveVertSimp(K)$; {\bf return} $K$; }
  \end{algorithmic}
  \label{algo:naive-squash}
\end{algorithm}


\begin{algorithm}
  \caption{\hypertarget{practicalsquash}{$\PracticalSquash(P,\alpha)$}}
  \begin{algorithmic}
	\STATE{ $K \leftarrow \Del{P,\alpha}$;  $\PracticalVertSimp(K)$; {\bf return} $K$; }
  \end{algorithmic}
  \label{algo:practical-squash}
\end{algorithm}




\subsection{Sampling and angular conditions in $\Rspace^d$}
\label{section:stating-reconstruction-results}

	The next definition enables us to express our results in $\Rspace^d$ more concisely.


	\begin{definition}[Strict homotopy condition]
		We say that $\varepsilon, \delta \geq 0$ satisfy the {\em strict
			homotopy condition} if $(\reach-\delta)^2 - \varepsilon ^2 >
		(4\sqrt{2}-5)\reach^2$ for $\delta \leq \varepsilon$ and
		$\varepsilon + \sqrt{2}\delta < (\sqrt{2}-1)\reach$ for
		$\delta \geq \varepsilon$. 
	\end{definition}

	Let $I(\varepsilon,\delta)$ be an interval of $\alpha$ values so
    that $\Offset{P}{\alpha}$ is vertically convex with relation to
    $\M$. The exact definition can be found in
    Appendix~\ref{appendix:range-alpha}. The
    fact that this interval guarantees vertical convexity follows from
    the specialization of Propositions $5$ and $7$ in
    \cite{socg24-NSW} to the case where $\M$ has codimension-one:


\begin{theorem}[Specialization of \cite{socg24-NSW}]
	\label{theorem:NSW}
		Suppose that $\M \subseteq \Offset P \varepsilon$ and $P
        \subseteq \Offset \M \delta$ with $\varepsilon, \delta \geq 0$
        that satisfy the strict homotopy condition. Then, for all
        $\alpha \in I(\varepsilon,\delta)$, $\pi_\M(\Offset P \alpha)
        = \M$ and $\Offset P \alpha$ is vertically convex relative to
        $\M$. Thus, $\Offset P \alpha$ has associated upper and lower
        skins and deformation-retracts onto $\M$ along $\pi_\M$. In
        addition, the two skins partition $\partial \Offset
        P \alpha$.
\end{theorem}


	The above concepts can be put together to state our main theorem: 

    \ignore{
    \domi{I changed the range for $\alpha$ in the theorem so that the ratios are in $[-1,1]$.}
    \sidebianca{Doesn't it make the theorem look more complicated?}
    \domi{Unfortunately, necessary to be sure that \eqref{eq:angle-condition-for-vertical-convexity} and \eqref{eq:angle-condition-acyclicity} are well-defined (unless we are able to show that redundant with $\alpha \in I(\varepsilon,\delta)$). }
    }


\begin{restatable}{theorem}{TheoremAlphaComplex}
	\label{theorem:alpha-complex}
	Assume $\M \subseteq \Offset P \varepsilon$ and $P \subseteq \Offset \M \delta$ for $\varepsilon, \delta \geq 0$ that satisfy the strict homotopy condition. Let $\alpha \in
    \left[\delta, \frac{2(\reach - \delta)}{3}\right) \cap I(\varepsilon, \delta)$ and $\beta > 0$ such that $\Offset \M \beta \subseteq \Offset P \alpha$. Suppose that for all $i$-simplices $\tau \in \Del{P, \alpha}$, $0 < i < d$ and all $(d-1)$-simplices $\nu \in \Del{P, \alpha}$ it holds:


	\begin{align}
		\max_{x \in \Conv\tau} \angle(\Aff \tau, \Tangent {\pi_\M(x)} \M) \, &< \, \frac{\pi}{2},
		\label{eq:angle-condition-for-skeleton}
		\\
		\min_{a \in \tau} \angle(\Aff \tau, \Tangent {\pi_\M(a)} \M) \, &< \, \arcsin\left(\frac{(\reach+\beta)^2 - (\reach+\delta)^2 - \alpha^2}{2(\reach+\delta)\alpha}\right) %
		\,\text{and}
		\label{eq:angle-condition-for-vertical-convexity}
		\\
		\min_{x \in \Conv\nu} \angle(\Aff \nu, \Tangent {\pi_\M(x)} \M)
		\, &< \, \frac{\pi}{2} - 2 \arcsin\left( \frac{\alpha}{2(\reach - \delta - \alpha)} \right).
		\label{eq:angle-condition-acyclicity}
	\end{align}
	Then, $\Del{P,\alpha}$ satisfies the injective projection, covering
	projection, vertical convexity and acyclicity assumptions of
	Theorem~\ref{theorem:correctness-generic-simplification}.  Furthermore, both the upper and lower complexes of $\Del{P, \alpha}$ relative to $\M$ are triangulations of $\M$ and $\NaiveSquash(P, \alpha)$ returns a triangulation of $\M$.

\end{restatable}

One can check that Conditions~\eqref{eq:angle-condition-for-skeleton},
\eqref{eq:angle-condition-for-vertical-convexity} and
\eqref{eq:angle-condition-acyclicity}
are well-defined; see Remark~\ref{remark:conditions-well-defined}.




\begin{corollary}
	\label{theorem:correcness-squash-practical}
	Suppose the assumptions of Theorem \ref{theorem:alpha-complex} are
	satisfied and furthermore that for all $(d-1)$-simplices $\nu \in
	\Del{P,\alpha}$,
	\begin{align}
		\label{eq:angle-condition-practical}
		\max_{a \in \nu} \angle(\Aff \nu, \Tangent {\pi_\M(a)} \M) \, < \, \frac{\pi}{4}.
	\end{align}
	Then, $\PracticalSquash(P,\alpha)$ returns a triangulation of $\M$.
\end{corollary}

\subsection{Partial proof technique for Theorem \ref{theorem:alpha-complex}}
\label{section:proof-technique}
In this section, we establish the covering projection and vertical convexity of $\Del{P,\alpha}$, as guaranteed by Theorem~\ref{theorem:alpha-complex}. The complete proof of that theorem can be found in Appendix~\ref{appendix:alpha-complex-theorem}.

\begin{lemma}
\label{lemma:alpha-complex-vertical-convexity}
Assume $\M \subseteq \Offset P \varepsilon$ and $P \subseteq \Offset
\M \delta$ for $\varepsilon,\delta \geq 0$ that satisfy the strict homotopy
condition. Let $\alpha \in [\delta,\reach-\delta) \cap
  I{(\varepsilon,\delta)}$ and $\beta > 0$ be such that $\Offset \M
  \beta \subseteq \Offset P \alpha$. Suppose that for all
  $i$-simplices $\tau \in \Del{P,\alpha}$ with $0 < i < d$, Conditions
  \eqref{eq:angle-condition-for-skeleton} and
  \eqref{eq:angle-condition-for-vertical-convexity} hold.  Then,
  $\pi_\M(\US{\Del{P,\alpha}}) = \M$ and $\Del{P,\alpha}$ is
  vertically convex relative to \M.
\end{lemma}




