\subparagraph{Upper and lower joins.}
For proving this lemma, we introduce upper and lower joins.  Consider
$\M$, $P$, $\varepsilon$, $\delta$, $\alpha$ and $\beta$ that satisfy
the assumptions of Lemma~\ref{lemma:alpha-complex-vertical-convexity}
and notice that they also meet the conditions of
Theorem~\ref{theorem:NSW}.  Therefore, $\Offset P \alpha$ has
associated upper and lower skins and the two skins form a partition of
$\partial \Offset P \alpha$. Using that partition, we decompose the
set difference $\Offset P \alpha \setminus\US{\Del{P,\alpha}}^\circ$
into upper and lower joins, slightly adapting what is done
in~\cite{edelsbrunner2011alpha}; see Figures
\ref{figure:alpha-complex-simple} and
\ref{figure:upper-and-lower-joins}.  For that, notice that $\partial
\Offset P \alpha$ can be decomposed into faces, each face being the
restriction of $\partial \Offset P \alpha$ to a Voronoi cell of $P$.
There is a one-to-one correspondence between simplices of $\partial
\Del{P,\alpha}$ and faces of $\partial \Offset P \alpha$: the simplex
$\tau \in \partial \Del{P,\alpha}$ corresponds to the face $F_\tau =
V(\tau,P) \cap \partial \Offset P \alpha$ and conversely.  We can
further partition each face $F_\tau$ of $\partial \Offset P \alpha$
into a portion $F_\tau^+$ that lies on the upper skin of $\partial
\Offset P \alpha$ and a portion $F_\tau^-$ that lies on the lower skin
of $\partial \Offset P \alpha$. Note that $F_\tau^+$ or $F_\tau^-$ can
be empty. We refer to $F_\tau^+$ as an upper face and $F_\tau^-$ as a
lower face. The set of upper faces decompose the upper skin, while the
set of lower faces decompose the lower skin.  A \emph{join} $X * Y$ is
defined as the set of segments $[x,y]$ where $x \in X$ and $y \in
Y$~\cite{edelsbrunner2011alpha}. We call $F_\tau^+ * \Conv{\tau}$ an
\emph{upper join} and $F_\tau^- * \Conv{\tau}$ a \emph{lower
join}. The next lemma, proved in Appendix \ref{appendix:alpha-complex-vertical-convexity}, identifies
points in $\partial|\Del{P,\alpha}|$ that are connected to upper or
lower joins.


\begin{remark}
\label{remark:covering—joins}
The collection of upper and lower joins cover the set $\Offset P
\alpha \setminus \US{\Del{P,\alpha}}^\circ$.
\end{remark}

\begin{remark}
\label{remark:intersection-joins}
If an upper join and a lower join have a non-empty intersection, the
common intersection belongs to $\US{\Del{P,\alpha}}$.
\end{remark}

\begin{restatable}{lemma}{ConnectingBoundariesSimplified}
  \label{lemma:connecting-boundaries-simplified}
  Under the assumptions of Lemma
  \ref{lemma:alpha-complex-vertical-convexity}, let $\spx \in
  \Del{P,\alpha}$ and $x \in \Interior{\Conv{\gamma}}$. If for some
  $\lambda > 0$ ({\em resp.}  $\lambda<0$), the segment $(x,x+\lambda
  \normal {\pi_\M(x)}]$ lies outside $\US{\Del{P,\alpha}}$, then it
intersects an upper ({\em resp. lower} join).
\end{restatable}





\begin{proof}[Proof of Lemma \ref{lemma:alpha-complex-vertical-convexity}]
Consider $\M$, $P$, $\varepsilon$, $\delta$,
$\alpha$ and $\beta$ that satisfy the assumptions of
Lemma~\ref{lemma:alpha-complex-vertical-convexity}. As noted before, they also meet the
conditions of Theorem~\ref{theorem:NSW}. Therefore,
$\pi_\M(\Offset P\alpha) = \M$ and $\Offset P \alpha$ is
vertically convex relative to $\M$. Hence, there
exists $r< \Reach{\M}$ such that $\Offset P \alpha \subseteq \Offset
\M r$ and $\Offset P \alpha \cap \Normal m \M \cap B(m,\rtube)$ is a
line segment for any $m \in \M$. Fix $m \in \M$ arbitrarily. We show
that $\US{\Del{P,\alpha}} \cap \Normal m \M \cap B(m,\rtube)$ is also
a line segment.

First, we show  by contradiction that it is non-empty.
Let $u^+$ ({\em resp. $u^-$}) be the endpoint of the segment $\Offset P \alpha \cap \Normal m \M \cap B(m,\rtube)$ that lies on the upper (\emph{resp.} lower) skin of $\Offset P \alpha$ and hence is contained in an upper (\emph{resp.} lower) join.
By Remark~\ref{remark:covering—joins}, the entire segment $[u^+,u^-]$ is
covered by upper and lower joins.  Thus, at some point $c$ of $[u^+,u^-]$, an upper join and a lower join intersect. By Remark~\ref{remark:intersection-joins}, such an intersection places $c$ on $\US{\Del{P,\alpha}}$ as well.


\begin{figure}[htb]
	\centering\input{Figures/proof-alpha-complex-vertical-convexity.pdf_tex} 
	\caption{
		Reaching a contradiction in the proof of Lemma~\ref{lemma:alpha-complex-vertical-convexity}. We see the simplices of $\Del{P,\alpha}$ whose support intersects $\Normal m \M \cap B(m,r)$ (smooth filling, in pale blue) and one upper (hashed, in green) and one lower (dotted, in pink) joins that intersect $[a,b]$.
	\label{figure:proof-alpha-complex-vertical-convexity}
    }
\end{figure}


Second, we show by contradiction that $\US{\Del{P,\alpha}}\cap \Normal
m \M \cap B(m,r)$ is connected. Suppose that
$a,b\in\US{\Del{P,\alpha}}\cap\Normal m \M \cap B(m,r)$ are such that
$ [a,b] \cap \US{\Del{P,\alpha}} = \{a,b\}$ with $a$ being above
  $b$ along the direction of $\normal m$.  Since $a,b \in
\US{\Del{P,\alpha}} \subseteq \Offset P \alpha$ and $\Offset P \alpha$
is vertically convex, the segment $[a,b]$ is contained in $\Offset
P\alpha$. By Remark~\ref{remark:covering—joins}, the entire
  segment $[a,b]$ is covered by upper and lower joins. Let $\spx_a$
and $\spx_b$ be the simplices of $\Del{P,\alpha}$ that contain $a$ and
$b$, respectively, in their relative interior. Letting $\lambda =
  \frac{\|a-b\|}{2}$, then both segments $\left(a,a-\lambda \normal m\right]$ and
$\left(b,b+\lambda \normal m\right]$ lie outside $\US{\Del{P,\alpha}}$.
It follows, by Lemma~\ref{lemma:connecting-boundaries-simplified}, that
there are at least one lower and one upper joins among the joins that
cover $(a,b)$; see Figure
\ref{figure:proof-alpha-complex-vertical-convexity}. Hence, an upper
and a lower joins intersect at a point $c$ of the segment $(a,b)$. By
Remark~\ref{remark:intersection-joins}, $c$ lies in
$\US{\Del{P,\alpha}}$, a contradiction. Therefore, for all $m \in \M$,
$\US{\Del{P,\alpha}}\cap \Normal m \M \cap B(m,r)$ is non-empty and
  connected,
thus forming a line segment.
\end{proof}


\subsection{Sampling conditions for surfaces in $\Rspace^3$.}
\label{section:surfaces-in-3D}

Theorem~\ref{theorem:alpha-complex} requires that the $i$-simplices of $\Del{P,\alpha}$ form a small angle with the manifold \M, for $0 < i < d$. Ensuring this can be challenging in practice, especially for $i \geq 3$. 
However, in the specific case of noiseless edges ($i=1$) or triangles ($i=2$), it is possible to upper bound the angle these simplices form with \M.
For edges, it is known that:


\begin{lemma}[{\cite[Lemma 7.8]{boissonnat2018geometric}}]\label{lemma:angleBetweenEdgeAndTangentPlane}
	If $ab$ is a non-degenerate edge with $a,b \in \M$, then
	\[
	\sin \angle \Aff{ab}, \Tangent a \M \, \leq \,  \frac{\|b-a\|}{2\,\reach}.
	\]
\end{lemma}\label{lemma:edges_bound_r3}


For triangles, let $\rcirc{\tau}$
be the radius of the smallest $(d-1)$-sphere circumscribing
$\tau$. We establish a simple bound that is tighter than the previous one (see~\cite[Lemma 3.5]{Dey:2006:reconstruction_book}):


\begin{lemma}
	\label{lemma:angleBetweenTriangleAndTangentPlane}
 	If $abc$ is a non-degenerate triangle with
	longest edge $bc$, for $a,b,c \in \M$, then
	\begin{align*}
		\sin \angle \Aff{abc}, \Tangent a \M \, &\leq \, \frac{\rcirc{abc}}{\reach} && \text{if $abc$ is an obtuse triangle and} \\
		\sin \angle \Aff{abc}, \Tangent a \M \, &\leq \,  \frac{\sqrt{3}\, \rcirc{abc}}{\reach} && \text{if $abc$ is an acute triangle.}
	\end{align*}
	If $abc$ is obtuse, the bound is tight and
	happens when $\M$ is a
	sphere of radius $\reach$.
\end{lemma}

The proof is technical and is therefore provided in Appendix \ref{appendix:angles}. For the same reason, the proof of the following result, where we use the bounds for edges and triangles to establish sampling conditions for surfaces in $\Rspace^3$, is in Appendix \ref{appendix:alpha-complex-second-corrolary}.
Let us define
\begin{equation*}
  \label{eq:good-beta}
  \beta_{\varepsilon,\alpha} = -\frac{\varepsilon^2}{2\reach} + \sqrt{\alpha^2 + \frac{\varepsilon^4}{4\reach^2}-\varepsilon^2},
\end{equation*}
which is one particular value of $\beta$ that guarantees $\Offset \M \beta
\subseteq \Offset P \alpha$; see Appendix~\ref{appendix:size-r-beta}.

\begin{restatable}{theorem}{CorollaryThreeDimensionTheory}
  \label{corollary:3D-theory}
  Let $\M$ be a $C^2$ surface in $\Rspace^3$ whose reach is at
    least $\reach>0$. Let $P$ be a finite point set such that $P
    \subseteq \M \subseteq \Offset P \varepsilon$.
  \begin{enumerate}
  \item \label{item:naive-3D-sampling}
    For all $\varepsilon, \alpha \geq 0$ that satisfy
    $\frac{\sqrt{3} \, \alpha}{\reach} < \min \left\{
    \frac{(\reach+\beta_{\varepsilon,\alpha})^2 - \reach^2 - \alpha^2}{2\reach\alpha},\,
    \cos\left( 2 \arcsin\left( \frac{\alpha}{\reach} \right)\right)
    \right\}$,
	\begin{itemize}
	\item the upper and lower complexes of $\Del{P,\alpha}$ relative to \M are
	  triangulations of \M;
	\item $\NaiveSquash(P,\alpha)$ returns a triangulation of $\M$.
	\end{itemize}
  \item \label{item:practical-3D-sampling}
    For all  $\varepsilon, \alpha \geq 0$ that satisfy in addition
    $\frac{\sqrt{3} \, \alpha}{\reach} < \sin\left( \frac{\pi}{4} - 2 \arcsin \left( \frac{\alpha}{\reach} \right)\right)$,
	\begin{itemize}
	\item $\PracticalSquash(P,\alpha)$ returns a triangulation of $\M$.
	\end{itemize}
  \end{enumerate}
\end{restatable}


  \medskip \noindent
  The pairs of
  $(\frac{\varepsilon}{\reach},\frac{\alpha}{\reach})$ that satisfy
  \itemref{item:naive-3D-sampling} and
  \itemref{item:practical-3D-sampling} are depicted in Figures~\ref{fig:sampling-condition-3D-left} and \ref{fig:sampling-condition-3D-right}, respectively.

