\subsection{The restricted Delaunay complex}
\label{section:restricted-Delaunay-complex}

We recall from \cite{edelsbrunner1997triangulating} that the {\em restricted Delaunay complex} is
\[
\DelR{P} = \{ \sigma \subseteq P \mid  \sigma \neq \emptyset \text{ and }  V(\sigma,P) \cap \M \neq \emptyset \}.
\]

\begin{restatable}{theorem}{TheoremRestrictedDelaunayComplex}
  \label{theorem:3D-restricted-Delaunay-complex}
  Let $\M$ be a $C^2$ surface in $\Rspace^3$ whose reach is at least
  $\reach>0$. Let $P$ be a finite set such that $P \subseteq \M
  \subseteq \Offset P \varepsilon$ for $0 \leq
  \frac{\varepsilon}{\reach} \leq 0.225$.  Under the additional
    generic assumption that all Voronoi cells of $P$ intersect \M
    transversally, $\DelR{P}$ is a triangulation of \M.
\end{restatable}


