\section{Angle between flats}
\label{appendix:angles}

\subsection{Definitions and basic properties}

Consider two affine spaces $X,Y \subseteq \Rspace^d$. Let $U$ and $V$
be the vector spaces associated to $X$ and $Y$, respectively.  We
recall that the angle between two affine spaces $X$ and $Y$ is the
same as the angle between the two vector spaces $U$ and $V$ and is
defined as
\[
\angle(X,Y) = \angle(U,V) = \max_{\substack{u \in U \\ \|u\| = 1}}
\min_{\substack{v \in V \\ \|v\| = 1}} \angle (u,v).
\]
The definition is not symmetric in $X$ and $Y$, unless the two affine spaces $X$
and $Y$ (or equivalently, the two vector spaces $U$ and $V$) have same dimension. Given a vector space $V$, denote by
$V^\perp$ its orthogonal complement. The following properties will be
useful:

\begin{property}
  Let $U$ and $V$ be two vector spaces. Then,
  \[
  \angle(U,V) = \angle(V^\perp,U^\perp).
  \]
\end{property}

\begin{property}
  \label{property:complementary-angles}
  Let $U$ and $V$ be two vector spaces, with $\dim U = 1$. Then,
  \[
  \angle(U,V) + \angle(U,V^\perp) = \frac{\pi}{2}.
  \]
\end{property}

The angle between two vector spaces can also be written in terms of all hyperplanes that contain the second vector space:


\begin{lemma}\label{lemma:angleSpacesAsMaxOnHyperplane}
  Let $U$, $V$ be two vector spaces and $u\in U$. Then,
  \begin{align}\label{eq:angleSpacesAsMaxOnHyperplane_1}
	\min_{\substack{v \in V \\ \|v\| = 1}} \angle (u,v)
	= \max_{\substack {H \supseteq V  \\  \operatorname{codim}(H) = 1}} \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h)
  \end{align}
  and
  \begin{align}\label{eq:angleSpacesAsMaxOnHyperplane_2}
	\angle (U, V)  = \max_{\substack {H \supseteq V \\  \operatorname{codim}(H) = 1}} \angle (U,H),
  \end{align}
  where $H$ designates a vector space and $\operatorname{codim}(H) = \dim(H^\perp)$.
\end{lemma}
\begin{proof}
  For any codimension one vector space $H\supseteq V$, it holds that
  \[
  \min_{\substack{v \in V \\ \|v\| = 1}} \angle (u,v) \geq \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h).
  \]
  Thus, we have one direction of \eqref{eq:angleSpacesAsMaxOnHyperplane_1}:
	\[
	\min_{\substack{v \in V \\ \|v\| = 1}} \angle (u,v) 
	\geq \max_{ {H \supseteq V} \atop { \operatorname{codim}(H) = 1}} \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h).
	\]
	Note that if $u \in V$, \eqref{eq:angleSpacesAsMaxOnHyperplane_1}
    is trivially satisfied as both sides are $0$.  Hence, for the
    other direction of \eqref{eq:angleSpacesAsMaxOnHyperplane_1}, we consider $u \notin V$.
    Denote the vector in $V$ closest to $u$ by $\pi_{V} (u) = \arg
    \min_{v\in V} (v-u)^2$. From the definition of the angle, it
    holds that
	\[
    \min_{\substack{v \in V \\ \|v\| = 1}} \angle (u, v)
    =  \angle (u, \pi_{V} (u))
    = \arcsin \frac{\|\pi_{V} (u) - u\|}{\|u\|}.
    \]
	Next, define
	\[
	w = u - \pi_{V} (u) \in V^{\perp}
	\]
    and let $W$ be the vector space spanned by $w$. Since $\omega \in
    V^{\perp}$, one has $V \subseteq W^\perp$. Moreover, $\pi_{W^\perp}
    (u) = \pi_{V} (u)$ because $u - \pi_{V} (u) = \omega \in
    W$. Hence,
    \begin{align*}
	  \min_{\substack{v \in V \\ \|v\| = 1}} \angle (u,v) &=  \angle (u, \pi_{V} (u)) 
      =  \angle (u, \pi_{W^\perp} (u)) 
	  =  \min_{\substack{h \in W^\perp \\ \|h\|=1}} \angle (u,h) \\
	  &\leq \max_{ {H \supseteq V} \atop { \operatorname{codim}(H) = 1}} \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h). 
	\end{align*}
	Finally,~\eqref{eq:angleSpacesAsMaxOnHyperplane_2} holds because 
	\begin{align*}
		\angle (U, V)  &= \max_{\substack{u \in U \\ \|u\| = 1}} \min_{\substack{v \in V \\ \|v\| = 1}}  \angle (u,v) \\
		&=  \max_{\substack{u \in U \\ \|u\| = 1}} \max_{ {H \supseteq V} \atop { \operatorname{codim}(H) = 1}}   \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h) \\
		&= \max_{ {H \supseteq V} \atop { \operatorname{codim}(H) = 1}} \max_{\substack{u \in U \\ \|u\| = 1}}  \min_{\substack{h \in H \\ \|h\|=1}} \angle (u,h) \\
		&= \max_{ {H \supseteq V} \atop { \operatorname{codim}(H) = 1}} \angle (U,H). \qedhere
	\end{align*}
\end{proof}





\subsection{Angle between a triangle and a tangent space to the manifold}


Recall that Lemmas~\ref{lemma:angleBetweenEdgeAndTangentPlane}
and~\ref{lemma:angleBetweenTriangleAndTangentPlane} bound the angle
between the affine space spanned by a $1$- or $2$-simplex and a
tangent space to the manifold $\M$ in terms of the reach of $\M$. In this
section, we generalize these results by replacing the dependency on
the reach with a dependency on the local feature size. Additionally,
we relax the assumptions that $\M$ has codimension one and is
$C^2$. For that, assume $\M$ is a compact submanifold of $\Rspace^d$
with positive reach, from which it follows that $\M$ is
$C^{1,1}$~\cite[Proposition 1.4]{lytchak2005almost}.
Recall from~\cite{amenta1999surface} that the \emph{local feature size} at a
point $x$ on $\M$ is $\lfs{x} = d(x,\MA{\M})$ and that $\Reach{\M}
\leq \lfs{x}$ for all $x \in \M$.



\begin{lemma}
  \label{lemma:angleBetweenEdgeAndTangentPlane-lfs}
  Let \M be a compact submanifold of $\Rspace^d$ with positive reach.
	If $ab$ is a non-degenerate edge with $a,b \in \M$, then
	\[
	\sin \angle \Aff{ab}, \Tangent a \M \, \leq \,  \frac{\|b-a\|}{2\,\lfs{a}}.
	\]
\end{lemma}


\begin{proof}
  Point $b$ lies on or outside the set of spheres of radius $\lfs{a}$ that are tangent to $\M$ at $a$. In the worst case, where $b$ lies on one of these spheres, 
  $ab$ is a chord of that sphere.
\end{proof}

Let $\rcirc{\tau}$ designate the radius of the smallest $(d-1)$-sphere circumscribing a simplex $\tau$. 

\begin{lemma}
  \label{lemma:angleBetweenTriangleAndTangentPlane-lfs}
  Let \M be a compact submanifold of $\Rspace^d$ with positive reach.
 	If $abc$ is a non-degenerate triangle with
	longest edge $bc$, for $a,b,c \in \M$, then
	\begin{align*}
		\sin \angle \Aff{abc}, \Tangent a \M \, &\leq \, \frac{\rcirc{abc}}{\lfs{a}} && \text{if $abc$ is an obtuse triangle and} \\
		\sin \angle \Aff{abc}, \Tangent a \M \, &\leq \,  \frac{\sqrt{3}\, \rcirc{abc}}{\lfs{a}} && \text{if $abc$ is an acute triangle.}
	\end{align*}
	If $abc$ is obtuse, the bound is tight and happens when $\M$ is a
    $k$-sphere of radius $\reach$ with $2 \leq k \leq d-1$.
\end{lemma}


\begin{proof}
  Let $A = \angle cab$, $\vec{u} = \frac{b-a}{\|b-a\|}$, and $\vec{v}
  = \frac{c-a}{\|c-a\|}$. Let $H$ be any hyperplane that contains
  $\Tangent a \M$ and let $\vec{n}$ be an unit vector orthogonal to
  $H$. By construction, $\vec{n}$ is orthogonal to \M at
  $a$. Introduce the two angles
  \begin{align*}
    \theta_u &= \arccos(\vec{u} \cdot \vec{n}), \\
    \theta_v &= \arccos(\vec{v} \cdot \vec{n}).
  \end{align*}
  Thanks to Lemma \ref{lemma:angleBetweenEdgeAndTangentPlane-lfs}, we have that
    \begin{align}
      \left| \cos \theta_u \right| &= \left| \vec{u} \cdot \vec{n} \right| = \sin \angle \Aff{ab}, H \leq \frac{ \| b-a \| }{2 \, \lfs{a}}, \label{eq.UDotN}\\
    \left| \cos \theta_v \right| &= \left| \vec{v} \cdot \vec{n} \right| = \sin \angle \Aff{ac}, H\leq \frac{ \| c-a \| }{2 \, \lfs{a}}.\label{eq.VDotN}
  \end{align}
 Consider the vector
  \[
  \vec{w} = \frac{\vec{v} - (\vec{u} \cdot \vec{v})\, \vec{u}}{\left\| \vec{v} - (\vec{u} \cdot \vec{v})\, \vec{u} \right\| }
  = \frac{1}{\sin A} \left( \vec{v} - \cos A \, \vec{u} \right).
  \]
  By construction, $\vec{w}$ is a unit vector parallel to the affine
  plane spanned by triangle $abc$ and orthogonal to $\vec{v}$. It
  follows that $(\vec{u}, \vec{w} )$ is an orthonormal basis of the
  vector plane supporting the triangle $abc$ and we can write
  \begin{align*}
    \sin \angle \Aff{abc}, H  &= \max_{t\in [0,2\pi]}  (\cos t\, \vec{u} + \sin t\, \vec{w}) \cdot \vec{n}  \\
    &= \max_{t\in [0,2\pi]}   (\vec{u} \cdot \vec{n}) \cos t + (\vec{w} \cdot \vec{n} ) \sin t .
  \end{align*}
  The maximum over $[0,2\pi]$ of the map $t \mapsto x \cos t + y \sin t$ is $\sqrt{x^2+ y^2}$. Thus,
  \begin{align*}
        \left(\sin \angle \Aff{abc},H \right)^2 &=  (\vec{u} \cdot \vec{n})^2 +  (\vec{w} \cdot \vec{n})^2 \\
    &= \cos^2 \theta_u + \frac{1}{\sin^2 A} \left(\cos \theta_v - \cos A \cos  \theta_u  \right)^2 \\
    &= \frac{1}{\sin^2 A} \left(\cos^2 \theta_u +  \cos^2 \theta_v - 2 \cos A \cos  \theta_u  \cos \theta_v \right).
  \end{align*}
  For fixed $A$, the last expression is a homogeneous degree $2$
  polynomial in $\cos \theta_u$ and $\cos \theta_v$. Under the
  constraints \eqref{eq.UDotN} and \eqref{eq.VDotN}, its maximum is
  reached at one of the four corners of the constraint rectangle, i.e.
  when $\cos \theta_u = \pm \frac{ \| b-a \| }{2 \lfs{a}}$ and $ \cos
  \theta_v = \pm \frac{ \| c-a \| }{2 \lfs{a}}$. We distinguish two
  cases, depending on whether the triangle $abc$ is obtuse or acute.

  \medskip

  If $abc$ is acute, then $A \leq \frac{\pi}{2}$ and $\cos A \geq
  0$. It follows that the maximum of the polynomial is reached either when $\cos
  \theta_u = \frac{ \| b-a \| }{2 \lfs{a}}$ and $ \cos \theta_v =
  -\frac{ \| c-a \| }{2 \lfs{a}}$ or when $\cos \theta_u = -\frac{ \|
    b-a \| }{2 \lfs{a}}$ and $ \cos \theta_v = \frac{ \| c-a \| }{2
    \lfs{a}}$. Letting $b' = 2a - b$ be the symmetric point of $b$ with
  respect to $a$, we obtain
  \begin{align*}
      \left(\sin \angle \Aff{abc}, H \right)^2 
    &\leq  \frac{1}{4 \lfs{a}^2} \frac{1}{\sin^2 A} \left( \| b-a \|^2 +   \| c-a \|^2 + 2 \cos A  \| b-a \|   \| c-a \| \right) \\
    &=  \frac{1}{4 \lfs{a}^2} \frac{1}{\sin^2 A}  \| b'-c\|^2 \\
    &=  \frac{\rcirc{ab'c}^2}{\lfs{a}^2}.
  \end{align*}
  Since the last equation holds for any hyperplane $H$ that
  contains $\Tangent a \M$, it follows from
  \eqref{eq:angleSpacesAsMaxOnHyperplane_2} in Lemma
  \ref{lemma:angleSpacesAsMaxOnHyperplane} that
  \begin{align*}
    \left(\sin \angle \Aff{abc}, \Tangent a \M  \right)^2 \leq  
    \frac{\rcirc{ab'c}^2}{\lfs{a}^2}.
  \end{align*}
  Under the constraint that the longest edge in the triangle $abc$ is
  $bc$, the ratio $\frac{\rcirc{ab'c}}{\rcirc{abc}}$ is maximized when
  $abc$ is an equilateral triangle, in which case the ratio is equal
  to $\sqrt{3}$. The bound for acute triangles follows.

   \medskip


  If $abc$ is obtuse, then $A \geq \frac{\pi}{2}$ since $bc$ is the longest edge. Therefore, $\cos A \leq
  0$ and the maximum of the polynomial is reached either when $\cos
  \theta_u = \frac{ \| b-a \| }{2 \lfs{a}}$ and $\cos \theta_v = \frac{
  	\| c-a \| }{2 \lfs{a}}$ or when $\cos \theta_u = -\frac{ \| b-a \|
  }{2 \lfs{a}}$ and $\cos \theta_v = -\frac{ \| c-a \| }{2 \lfs{a}}$.
  We obtain that
  \begin{align*}
  	\left(\sin \angle \Aff{abc}, H \right)^2 
  	&\leq  \frac{1}{4 \lfs{a}^2} \frac{1}{\sin^2 A} \left( \| b-a \|^2 +   \| c-a \|^2 - 2 \cos A  \| b-a \|   \| c-a \| \right) \\
  	&=  \frac{1}{4 \lfs{a}^2} \frac{1}{\sin^2 A}  \| b-c \|^2 \\
  	&=  \frac{\rcirc{abc}^2}{\lfs{a}^2},
  \end{align*}
  where we used the formula $\rcirc{abc} = \frac{\| b-c \|}{2 \sin A}$
  to obtain the last equality. As for the acute case, we get that:
 \begin{align*}
  	\left(\sin \angle \Aff{abc}, \Tangent a \M \right)^2 
        \leq   \frac{\rcirc{abc}^2}{\lfs{a}^2},
  \end{align*}

 To see that the bound is tight in the obtuse case, consider a
 $k$-sphere of radius $\reach$ and center $o$ with $2 \leq k
 \leq d-1$ as $\M$. Let $o'$ be the center of the smallest
 $2$-sphere circumscribing $abc$. Then, the
 angle $\theta$ between the lines $oa$ (or $ob$ or $oc$) and $oo'$ is
 \[
 \theta
 = \angle \Aff{abc}, \Tangent a \M
 = \angle \Aff{abc}, \Tangent b \M
 = \angle \Aff{abc}, \Tangent c \M
 \]
  and $\sin \theta$  is precisely the bound $\frac{\rho(abc)}{\reach}=\frac{\rho(abc)}{\lfs{a}}$.
\end{proof}


\subsection{Difference between angular deviations at vertices}

Consider a simplex $\tau$ with vertices on $\M$. In this section, we
bound the variation of the angle $\angle(\Aff \tau, \Tangent{a} \M)$
as $a$ varies over the vertices of $\tau$.  Recall that $\rcirc{\tau}$
denotes the radius of the smallest $(d-1)$-sphere circumscribing the
simplex $\tau$.


\begin{lemma}
  \label{lemma:difference-max-min-angular-deviation-noiseless}
  Let $0 < i < d$. For any $i$-simplex $\tau$ whose vertices lie
  on $\M$ with $\rcirc{\tau} < \reach$,
  \begin{equation}
      \max_{a \in\tau} \angle(\Aff \tau, \Tangent {a} \M)
      -
      \min_{a \in\tau} \angle(\Aff \tau, \Tangent {a} \M)
      \leq 2 \arcsin{\left( \frac{\rcirc{\tau}}{\reach} \right)}.
  \end{equation}
\end{lemma}



\begin{proof}
  By \cite[Corollary 3]{boissonnat2019reach}, for all $m,m' \in \M$, we have $\angle (\Tangent m \M, \Tangent {m'} \M ) \leq 2 \arcsin \left( \frac{\|m'-m\|}{2\reach} \right)$.   Consider two vertices $a,b \in\tau$.
Since $\|a-b\| \leq 2\rcirc{\tau}$, it holds that
  \begin{equation*}
    \label{eq:angular-deviation-c-x}
    \angle (\Tangent {b} \M, \Tangent {a} \M )
    \leq 2 \arcsin\left( \frac{\rcirc{\tau}}{\reach} \right).
  \end{equation*}
  The result follows by combining the above inequality and the triangular inequality:
  \[
  \angle ( \Aff \tau, \Tangent {b} \M ) - \angle ( \Aff \tau, \Tangent {a} \M )
  \, \leq \,  \angle (\Tangent {b} \M, \Tangent {a} \M ) \,\leq\, 2 \arcsin\left( \frac{\rcirc{\tau}}{\reach} \right). \qedhere 
  \]
\end{proof}

