\subsection{Upper and lower skins}


\SkinsHomeomorphicToManifold*

\begin{proof}
  It suffices to show that $\UpperSkin {\US{K}}$ is a closed set and that the
  mapping $\pi_\M : \UpperSkin {\US{K}} \to \N$ is a homeomorphism. This
  result will automatically extend to $\LowerSkin {\US{K}}$ because the lower
  skin of $\US{K}$ becomes the upper skin of ${\US{K}}$ when the orientation of
  ${\US{K}}$ is reversed.

  We begin by proving that $\UpperSkin {\US{K}}$ is a closed set. To do this,
  we define a set $A$, which is closed by construction, and show that
  $A = \UpperSkin {\US{K}}$. Let the set of points lying above ${\US{K}}$ in the
  offset region $\Offset \M \rtube$ be
  \[
  \AboveSet {\US{K}} = \bigcup_{m\in \N} [\up {\US{K}} m, m + \rtube \normal{m}]
  \]
  and set
  \[
  A = \Closure{\AboveSet {\US{K}}} \cap |K|.
  \]
  $A$ is the intersection of two closed sets and hence it is closed. Recalling that
  \[
  \US{K}  = \bigcup_{m \in \N} [\low {\US{K}} m, \up {\US{K}} m],
  \]
  we observe that the sets $\AboveSet {\US{K}}$ and $\US{K}$ intersect at a
  single point, $\up {\US{K}} m$, along each normal segment $[m - \rtube
    \normal{m}, m + \rtube \normal{m}]$. Thus, by construction,
  $\UpperSkin {\US{K}} = \AboveSet {\US{K}} \cap \US{K}$ and hence $\UpperSkin {\US{K}}
  \subseteq A$.

  To prove the reverse inclusion, we first show that each normal
  segment $\Normal m \M \cap B(m, \rtube)$ intersects $A$ at exactly
  one point. We proceed in three stages.

  \begin{figure}[htb]
  	\centering\includegraphics{Figures/appBCase.pdf}
  	\caption{Schematics of the construction in Stage one.}
  	\label{fig:appBStage}
  \end{figure}


  \smallskip\noindent{\bf\underline{Stage one.}} We establish the following implication:
  \[
  x \in \Closure{\AboveSet {\US{K}}} \implies [x,m + \rtube \normal{m}] \subseteq \Closure{\AboveSet {\US{K}}}.
  \]
  Consider a point $x \in \Closure{\AboveSet {\US{K}}}$, implying the
  existence of a sequence of points $(x_i)_{i\in \Nintegers}$ in
  $\AboveSet {\US{K}}$ that converges to $x$ as $i \to +\infty$. Let $m =
  \pi_{\M}(x)$ and $m_i = \pi_{\M}(x_i)$, and consider the sequence of
  segments $([x_i, m_i+ \rtube \normal{m_i}])_{i \in \Nintegers}$ (see
  Figure~\ref{fig:appBStage} for a depiction). Each segment $[x_i,
    m_i+ \rtube \normal{m_i}]$ in the sequence belongs to $\AboveSet
  {\US{K}}$ since, given $x_i \in \AboveSet {\US{K}}$, it holds that  
  \[
    [x_i, m_i+ \rtube \normal{m_i} ] \subseteq [\up{K}{m_i} , m_i+ \rtube \normal{m_i} ] \subseteq \AboveSet {\US{K}}.
  \]
  Furthermore, we show that the sequence of segments $([x_i, m_i+
    \rtube \normal{m_i}])_{i\in \Nintegers}$ converges in Hausdorff
  distance to $[x, m+\rtube \normal{m}]$, completing the proof. It is
  enough to show the convergence of the endpoints of segments and
  since $\lim_{i \to +\infty} x_i = x$, we only need to show that
  $\lim_{i \to +\infty} (m_i + \rtube \normal{m_i}) = m + \rtube
  \normal{m}$. Let $f: \AboveSet {\US{K}} \to \AboveSet {\US{K}}$ be defined by $f(z) =
  \pi_\M(z) + \rtube \normal{\pi_\M(z)}$. Both $\pi_\M: \AboveSet{\US{K}}  \to \M$ and $\mathbf{n} : \M \to \normal m$ are continuous maps,
  hence $f$ is continuous and $\lim_{i \to +\infty} f(x_i) =
  f(x)$. Thus, $\lim_{i \to +\infty} (m_i + \rtube \normal{m_i}) = m +
  \rtube \normal{m}$.

  \smallskip\noindent{\bf\underline{Stage two.}} We show that for all
  $m \in \N$, the set $A \cap \Normal m \M \cap B(m,\rtube)$ is
  connected. Consider two points $x, y \in A \cap \Normal m \M \cap
  B(m,\rtube)$. Since $x, y \in \US{K} \cap \Normal m \M \cap
  B(m,\rtube)$, the vertical convexity assumption guarantees that $[x,y]
  \in \US{K} \cap \Normal m \M \cap B(m,\rtube)$. Since $x, y \in
  \Closure{\AboveSet {\US{K}}} \cap \Normal m \M \cap B(m,\rtube)$, the previous
  stage guarantees that $[x,y] \in \Closure{\AboveSet {\US{K}}} \cap \Normal m
  \M \cap B(m,\rtube)$. Therefore, $[x,y]$ belongs to $A \cap \Normal m
  \M \cap B(m,\rtube)$. 


  \smallskip\noindent{\bf\underline{Stage three.}}  We show that $A
  \cap \Normal m \M \cap B(m,\rtube)$ is reduced to a single point for
  all $m \in \N$. In the previous stage, we established that $A \cap
  \Normal m \M \cap B(m,\rtube)$ is connected, thus forming a
  segment. Assume, for a contradiction, that the endpoints $x$ and $y$
  of this segment are distinct. For each $z \in [x,y]$, let $\sigma_z$
  denote the unique simplex of ${\US{K}}$ containing $z$ in its relative
  interior. Since $A \subseteq \partial \US{K} = \US{\partial K}$,
  $\sigma_z$ belongs to the boundary complex $\partial {\US{K}}$ of ${\US{K}}$ and
  has $\dim \sigma_z < d$ for all $z \in [x, y]$. Given that $x \neq
  y$, there exists $z\in [x,y]$ with $\dim \sigma_z > 0$. Since
  $\sigma_z$ is a boundary simplex of ${\US{K}}$ containing $[x,y]$ locally
  around $z$, it must be vertical with $0 < \dim \sigma_z < d$,
  contradicting our assumption that ${\US{K}}$ contains no vertical
  $i$-simplices for $0 < i < d$.



  \smallskip


	From stage three, $A$ intersects $[m - \rtube\normal{m}, m
		+ \rtube \normal{m}]$ at a single point for all $m \in \N$.
		By construction, so does $\UpperSkin {\US{K}}$. Since $\UpperSkin {\US{K}}
		\subseteq A$, it follows that $\UpperSkin {\US{K}} = A $ along the
		normal segment $[m - \rtube \normal{m}, m + \rtube \normal{m}]$
		for all $m \in \N$. Hence, the upper skin of ${\US{K}}$ coincides with $A$ and is therefore closed.

  	We are now ready to conclude. The upper skin of ${\US{K}}$ is a closed
    set and, therefore, compact. The map $\pi_{\M}: \UpperSkin {\US{K}} \to
    \N$ is a continuous bijection from one compact set to another, and
    is thus a homeomorphism. Let us prove Equation \eqref{eq:boundary-equals-upper-and-lower}, that is,
    \[
    \partial \US{K} = \UpperSkin {\US{K}} \cup \LowerSkin {\US{K}}.
    \]
    By definition, the boundary of $\US{K}$ is the set $\partial \US{K} = \US{K}
    \cap \Closure{ \Rspace^d \setminus \US{K}}$. 


    Introducing the following sets (see Figure~\ref{fig:appB_schematics})
  \begin{align*}
    \BelowSet{{\US{K}}} &= \bigcup_{m \in \N} [m - \rtube \normal m, \low {\US{K}} m] \,\,\,\,\text{and}\\
    \Side{{\US{K}}} &= \big\{ x \in  \Offset \M \rtube \mid \pi_\M (x) \notin \N \big\},
  \end{align*}
  we can write
  \[
  \Rspace^d \setminus \US{K} = \AboveSet {\US{K}} \cup \BelowSet {\US{K}} \cup (\Rspace^d \setminus \Offset \M \rtube) \cup \Side{\US{K}} .
  \]

  \begin{figure}[htb]
  	\centering
  	\includegraphics{Figures/appBFigGeral.pdf}
  	\caption{The different regions in $\Offset \M \rtube$.}
 	\label{fig:appB_schematics}
  \end{figure}

  Taking the closure on both sides, it follows that
  \[\arraycolsep=1.4pt\def\arraystretch{2.2}
  \begin{array}{rcl}
  \Closure{\Rspace^d \setminus \US{K}} &= & \Closure{\AboveSet {\US{K}}} \cup \Closure{\BelowSet {\US{K}}} \cup \\[-3ex]
  & & \cup \Closure{\Rspace^d \setminus \Offset \M \rtube}
  \cup \Closure{\Side{\US{K}}}.
  \end{array}\]
  Intersecting both sides of the equality with $\US{K}$ and noting
  that the third term in the union has an empty
  intersection with $\US{K}$, we obtain that
  \begin{align*}
    \partial \US{K} &= \US{K} \cap \Closure{ \Rspace^d \setminus \US{K}}\\
    &= \US{K} \cap \left(  \Closure{\AboveSet {\US{K}}} \cup \Closure{\BelowSet {\US{K}}} \cup \Closure{\Side {\US{K}}} \right)\\
    &= \left( \US{K} \cap  \Closure{\AboveSet {\US{K}}} \right) \cup \left( \US{K} \cap \Closure{\BelowSet {\US{K}}} \right)\\
    &= \UpperSkin {\US{K}} \cup \LowerSkin {\US{K}},
  \end{align*}
  which concludes the proof.
\end{proof}


\UpperEqualsLowerConsequence*

\begin{proof}
  Since $\UpperSkin {\US{K}} = \LowerSkin {\US{K}}$, it follows that
  $\low {\US{K}} m = \up {\US{K}} m$ for all $m \in \pi_\M(\US{K})$
  and $\US{K} \subseteq \UpperSkin {\US{K}} = \LowerSkin {\US{K}}$. By
  Lemma~\ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold},
  \[
  \US{K} \subseteq \UpperSkin {\US{K}} \cup \LowerSkin {\US{K}} = \partial\US{K} = \US{\partial K}.
  \]
  Thus, $\US{K} \subseteq \US{\partial K}$ and therefore $K = \partial
  K$.
\end{proof}






By Lemma~\ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold}, we already know
that the union of the upper and lower skins is a simplicial
complex. However, since their intersection is non-empty, it is unclear
whether each one of them separately is a simplicial complex as well.
Lemma \ref{lemma:upper-and-lower-complex-equal-boundary}
establishes exactly that, replacing each set in
Equation~(\ref{eq:boundary-equals-upper-and-lower}) by a simplicial
counterpart. Its proof relies on the next lemma.



\begin{lemma}
  \label{lemma:exclusive-upper-and-lower}
  Suppose that $K$ has a non-vertical skeleton and is vertically convex relative to
  \M. Then, for all simplices $\nu \in {{K}}$, the following two implications hold:
  \begin{enumerate}
  \item $\Interior{\Conv\nu} \cap \UpperSkin {\US{K}} \neq \emptyset$ $\implies$ $\Conv\nu \subseteq \UpperSkin {\US{K}}$;
  \item $\Interior{\Conv\nu} \cap \LowerSkin {\US{K}} \neq \emptyset$ $\implies$ $\Conv\nu \subseteq \LowerSkin {\US{K}}$.
  \end{enumerate}
\end{lemma}

\begin{proof}
Let $\nu$ be a simplex of ${K}$ and $x \in
\Interior{\Conv\nu}$. Consider $t>0$ such that the only simplices of
${{K}}$ whose support intersects $B(x,t)$ are in the star of $\nu$.
Following ~\cite{federer1959curvature}, we define the \emph{tangent cone} of $x$ in ${\US{K}}$ as
\begin{equation}\label{eq:tangent_cone} \TanSpace(x,\US{K})=   \Big\{ \lambda u \mid x + u \in |K| \cap B(x, t) , \, \lambda \geq 0 \Big\}.
\end{equation}
Similarly, for any $\tau \in \Star{\nu}{{{K}}}$, we introduce the cone
\[
\TanSpace(x,\tau) =   \Big\{ \lambda u \mid x + u \in  \Interior{\Conv\tau} \cap B(x, t) , \, \lambda \geq 0 \Big\}. 
\]
Since $K$ is embedded, the family $\{\TanSpace(x,\tau) \mid \tau \in \Star{\nu}{{{K}}}\}$ is a partition of $\TanSpace(x,\US{K})$. Note that $x \mapsto \TanSpace(x,\US{K})$ remains constant on $\Interior{\Conv\nu}$ for each $\nu \in {{K}}$, thus depending only on the simplex of ${{K}}$ whose support contains $x$ in its relative interior. Additionally, we have:
\[
x \in \UpperSkin{{\US{K}}} \quad \iff \quad \normal{\pi_\M(x)} \notin \TanSpace(x,\US{K}).
\]
We next establish that:
\[
\Interior{\Conv\nu} \cap \UpperSkin {\US{K}}  \neq \emptyset \implies \Interior{\Conv\nu}
\subseteq \UpperSkin {\US{K}}.
\]
If $\dim \nu = 0$, the result is clear. For $\dim \nu > 0$, assume for contradiction that $x_0, x_1 \in \Interior{\Conv\nu}$ with $x_0 \in \UpperSkin{\US{K}}$ but $x_1 \notin \UpperSkin{\US{K}}$. The segment $[x_0, x_1]$ lies entirely within $\Interior{\Conv\nu}$. Since $K$ is vertically convex relative to $\M$, there exists $0 < r < \Reach{\M}$ such that $\US{K} \subseteq \Offset{\M}{r}$. Therefore, the projection map $\pi_\M$ is well-defined and continuous on $\US{K}$, as is the map $x \mapsto \normal{\pi_\M(x)}$. Consequently, at some point $x \in [x_0, x_1]$, we must have $\normal{\pi_\M(x)} \in \partial \TanSpace(x_0,\US{K})$, or equivalently:
\[
\normal{\pi_\M(x)} \in \partial \TanSpace(x,\US{K}).
\]
Observe that $\partial \TanSpace(x,\US{K})$ is contained in $\bigcup_{\tau} \TanSpace(x,\tau)$ such that $\tau \in \Star{\nu}{{{K}}}$ has dimension at most $d-1$. Hence, $\normal{\pi_\M(x)}$ belongs to $\TanSpace(x,\tau)$ for some $\tau \in \Star{\nu}{{K}}$ with $0 < \dim \tau < d$. This implies $\tau$ is vertical with $0 < \dim \tau < d$, contradicting the assumption that $K$ has a non-vertical skeleton. It follows that the relative interior of $\nu$ is contained in the upper skin. Moreover, the upper skin is closed, by Lemma~\ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold}. Hence,
\[
\Interior{\Conv\nu} \subseteq \UpperSkin{{\US{K}}} \implies \Conv{\nu} \subseteq \UpperSkin{{\US{K}}}.
\]
The first result, for the upper skin, follows. The proof for the lower skin is analogous. 
\end{proof}


\uppLowComplex*

\begin{proof}
  By construction, $\US{\UpperC K} \subseteq \UpperSkin{\US{K}}$. For
  the reverse inclusion, consider $x \in \UpperSkin{\US{K}}$ and let
  $\nu \in K$ be the simplex whose support contains $x$ in its
  relative interior. By Lemma \ref{lemma:exclusive-upper-and-lower},
  $\Conv \nu \subseteq \UpperSkin{\US{K}}$, showing that $\nu \in
  \UpperC K$ and $x \in \US{\UpperC K}$. We have just established the
  first equality. The second one is obtained similarly. For the third
  one, applying Lemma
  \ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold}, we obtain that
  \begin{align*}
    \US{\partial K}
    &= \UpperSkin{\US{K}} \cup \LowerSkin{\US{K}} \\
    &= \US{\UpperC K} \cup \US{\LowerC K} \\
    &= \US{\UpperC K \cup \LowerC K}.
  \end{align*}
  Since $\UpperC K \cup \LowerC K \subseteq \partial K$, the third
  equality follows. Finally, by Lemma
  \ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold}, when
  $\pi_\M(\US{K}) = \M$, both the upper complex and lower complex of
  $K$ are triangulations of \M.
\end{proof}


\subsection{Upper and lower facets of a $d$-simplex}



\facetsLem*

\begin{proof}
  Recall that the set of $i$-simplices of a simplicial complex $K$ is denoted $K^{[i]}$.
  By Lemma \ref{lemma:upper-and-lower-complex-equal-boundary} applied with $K = \Cl\sigma$,
  \[
  (\Cl\sigma)^{[d-1]} = \Above \sigma \cup \Below \sigma.
  \]
  We show that $\Above \sigma \cap \Below \sigma =
  \emptyset$. Suppose, for contradiction, that a facet $\nu$ of
  $\sigma$ satisfies $\Conv\nu \subseteq \UpperSkin{\US{K}}$ and
  $\Conv\nu \subseteq \LowerSkin{\US{K}}$. This would imply
  $\Conv\sigma \subseteq \Aff \nu$, making $\sigma$ degenerate, which
  is impossible.

  Next, we prove that $\Above \sigma \neq \emptyset$ by
  contradiction. If $\Above \sigma = \emptyset$, then $\Below \sigma$
  would contain all facets of $\sigma$, contradicting Lemma
  \ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold}, which
  states that the two skins of $\Cl \sigma$ (relative to $\M$) are
  homeomorphic. Similarly, $\Below \sigma \neq \emptyset$.
\end{proof}








