\subsection{Correctness}

\correspondFreeTerminalNode*



\begin{proof}
  Since the second item of the lemma can be obtained from the first
  one by reversing the orientation of \M, we only need to prove the first
  item. We start with the forward direction $\Longrightarrow$. Suppose
  that $\tau \in K$ is a free simplex of $K$ from above relative to
  \M. This implies that
  \[
  {\Star \tau K}^{[d-1]} = \Above \sigma,
  \]
  where $\Sigma^{[i]}$ stands for the set of $i$-simplices of
  $\Sigma$.  Observe that $\Star \tau K
  \setminus \{\sigma\} \subseteq \partial K$ and therefore $\Above
  \sigma \subseteq \partial K$. Hence, $\sigma$ has no
  $d$-simplex in $K$ above it. In other words, $\sigma$ is a sink
  of the dual graph $G_\M(K)$.


  Let us prove the backward direction $\Longleftarrow$. Suppose that
  $\sigma$ is a sink of $G_\M(K)$. Equivalently, $\sigma$ is a
  $d$-simplex of $K$ such that ${\Above \sigma} \subseteq \partial
  K$. By Lemma \ref{lemma:facets}, $\Above \sigma \neq \emptyset$ and it
  follows that $\tau \neq \emptyset$ and $\tau \in \partial K$.

  To establish the backward direction $\Longleftarrow$, it
    suffices to show that $\tau$ is a free simplex of $K$. Indeed, if
    we are able to show this, it follows immediately that $\tau$ is also free from
    above with respect to \M since its coface $\sigma$ has dimension
    $d$ and its $(d-1)$-cofaces are the upper facets of $\sigma$ by
    construction, {\em i.e.}
  \[
    {\Star \tau K}^{[d-1]} = \Above \sigma.
  \]
  The rest of the proof is devoted to showing that $\tau$ is a free
  simplex of $K$. By definition, this boils down to proving that
  $\Link \tau K$ is the closure of a simplex. We do this by showing
  that
  \begin{equation}\label{eq:LinksEqual}
    \Link \tau K = \Link \tau {\Cl \sigma}.      
  \end{equation}
  We first claim that the above equation is implied by the following one
  \begin{equation}\label{eq:BoundaryOfLinksEqual}
     \Link{\tau}{ \partial K } =  \Link{\tau}{ \partial \Cl{\sigma}}.
  \end{equation}
  Indeed, suppose that we have \eqref{eq:BoundaryOfLinksEqual}. Since $
  \Cl{\sigma}\subseteq K$, we get that $\Link{\tau}{ \Cl{\sigma}}
  \subseteq \Link{\tau}{ K }$ and we only need to establish the
  reverse inclusion to get \eqref{eq:LinksEqual}. For this, we use the fact that for any simplicial
  complex $X$ embedded in $\Rspace^d$ and any $\tau \in X$, we have
  that $\partial \Link \tau X = \Link \tau {\partial X}$. We thus deduce
  from \eqref{eq:BoundaryOfLinksEqual} that
  \[
  \partial \Link{\tau}{ K } =  \partial \Link{\tau}{ \Cl{\sigma}}.
  \]
   Because $\tau \in \partial K$, it follows that $\US{\Link{\tau}{ K }}$
   is topologically equivalent to a proper subset of the
   $(d-k-1)$-sphere, where $k = \dim \tau$. Because $\tau \in \partial
   \Cl \sigma$, we have similarly that $\US{\Link{\tau}{ \Cl \sigma }}$ is also
   topologically equivalent to a proper subset of the
   $(d-k-1)$-sphere.  Since the latter link is a subset of the former
   link and the two links share the same boundary complex, the only
   possibility is that they are equal and we get
   \eqref{eq:LinksEqual}. We have just established our claim that
   \eqref{eq:BoundaryOfLinksEqual} $\implies$
   \eqref{eq:LinksEqual}. Hence, to prove that $\tau$ is a free
   simplex of $K$, it suffices to establish
   \eqref{eq:BoundaryOfLinksEqual}. Let
   \begin{align*}
     \Bold A &= \Link \tau {\partial K} \\
     \Bold B &= \Link \tau {\UpperC K} \\
     \Bold C &= \Link \tau {\UpperC {\Cl \sigma}}\\
     \Bold D &= \Link \tau {\partial \Cl\sigma}.
   \end{align*}
   We prove \eqref{eq:BoundaryOfLinksEqual} by showing that $\Bold A =
   \Bold B = \Bold C = \Bold D$ in three steps. Before we start, we
   write two useful equalities due to the fact $\partial \Cl \sigma$ is a pure simplicial $(d-1)$-complex:
   \begin{align}
     \Cl{(\Above {\sigma})} &= \UpperC {\Cl \sigma}, \label{eq:from-upper-facets-to-complex}\\
     \Cl{(\Below {\sigma})} &= \LowerC {\Cl \sigma}. \label{eq:from-lower-facets-to-complex}
   \end{align}
   We refer the reader to Figure~\ref{figure:proof-free-terminal} for a pictorial representation of the objects in the proof. 

   \begin{figure}[htb]
     \def\svgwidth{0.7\linewidth}
     \centering\input{Figures/proof-free-terminal.pdf_tex}
     \caption{Notation for the proof of
       Lemma~\ref{lemma:correspondance-free-terminal-node}. The upper
       skin of $K$ is in green and its lower skin in pink. We have
       schematically represented $\sigma$ using curved edges. Its
       upper skin (in pale green) is a subset of the upper skin of
       $K$. The $k$-simplex $\tau$ is represented as a black dot. Its
       link in $\partial K$ is represented by the two white dots and
       is proved to triangulate the $(d-k-2)$-sphere.
       \label{figure:proof-free-terminal}}
   \end{figure}


   \smallskip{\bf Step 1:} $\Bold A = \Bold B$. By Lemma
   \ref{lemma:facets}, $\Above \sigma$ and $\Below \sigma$ partition
   the facets of $\sigma$.  Let us make a general observation. Suppose
   that $\Sigma$ and $\Sigma'$ partition the set of facets of
   $\sigma$. Let $\tau = \bigcap \Sigma$ and consider a point $x$ in
   the relative interior of $\Conv {\Sigma}$. Since $\Cl \sigma$ is
   embedded, $x$ does not lie on $\US{\Cl{(\Sigma')}}$. Applying this
   with $\Sigma = \Above \sigma$ and $\Sigma' = \Below \sigma$, we get
   that for any point $x$ in the relative interior of $\Conv\sigma$,
   we have that
   \[
   x \not \in \US{\Cl{(\Below {\sigma})}} = \US{\LowerC {\Cl \sigma}} = \LowerSkin {\Cl \sigma},
   \]
   where the first equality comes from \eqref{eq:from-lower-facets-to-complex} and the second
   equality comes from Lemma \ref{lemma:upper-and-lower-complex-equal-boundary}.  Let $m = \pi_\M(x)$. By
   construction, the normal segment $\Normal m \M \cap B(m,\rtube)$
   passes through $x$. It intersects $\LowerSkin {\Cl \sigma}$ in a
   point $y$ and $\LowerSkin {K}$ in a point $z$ in such a way that
   along direction $\normal m$, $x$ is strictly above $y$ and $z$
   cannot be above $y$.  This shows that $x \neq z$ and consequently
   $x \not\in \LowerSkin K$. Since $\LowerSkin{K}$ is a closed set by
   Lemma \ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold},
   $x$ is at distance greater than some $\epsilon > 0$ of
   $\LowerSkin{K}$.
      It follows
      that
   \begin{equation*}\label{eq:InBallAroundXSkinIsUpperSkin}
     B(x, \epsilon ) \cap  \US{ \partial K }   = B(x, \epsilon ) \cap  \US{ \UpperC {K} }.
   \end{equation*}
   Since $K$ is canonically embedded, the star (and therefore the link) 
   of $\tau$ in any subcomplex of $K$ depends only upon simplices whose support intersects some neighborhood of $x$. It follows that:
   \[
   \Link{\tau}{\partial K } =  \Link{\tau}{ \UpperC {K} }.
   \]


   \smallskip{\bf Step 2:} $\Bold C = \Bold D$. Consider again two sets $\Sigma$ and $\Sigma'$ that partition the set of facets of
   $\sigma$. Setting $\tau =
   \bigcap \Sigma$, one can observe that $\Link \tau {\Cl{(\Sigma)}} = \Link \tau {\partial
     \Cl \sigma}$. Applying this with $\Sigma = \Above \sigma$ and
   $\Sigma' = \Below \sigma$ and using \eqref{eq:from-upper-facets-to-complex}, we get that
   \[
   \Link \tau {\UpperC {\Cl \sigma}} = \Link \tau {\partial \Cl\sigma}.
   \]
   We see in particular that $\US{\Link \tau {\UpperC {\Cl \sigma}}}$ is a topological $(d-k-2)$-sphere.

   \smallskip{\bf Step 3:} $\Bold B = \Bold C$. Recall that
   ${\Above\sigma} \subseteq \partial K$. By Lemma
   \ref{lemma:upper-and-lower-complex-equal-boundary}, $\partial K$ is
   the union of the two subcomplexes $\UpperC K$ and $\LowerC K$ whose
   underlying spaces are the upper and lower skins of $K$ relative
   to \M, respectively. Each upper facet of $\sigma$ is contained in
   one of those two skins but not both. The only possibility is thus
   that $\Above {\sigma} \subseteq \UpperC {K}$ and therefore
   using~\eqref{eq:from-upper-facets-to-complex}
  \[
  \UpperC {\Cl{\sigma}} \subseteq  \UpperC {K}.
  \]
  Taking the  link of $\tau$ in each of those two subcomplexes
  of $K$, we get that
  \[
  \Link \tau {\UpperC {\Cl{\sigma}}} \subseteq \Link \tau {\UpperC {K}}.
  \]
  On the left side, we know from the previous step that the link is a
  triangulation of the $(d-k-2)$-sphere. We now study the link on the
  right side. By Lemma
  \ref{lemma:upper-and-lower-skins-homeomorphic-to-manifold},
  $\US{\UpperC {K}}$ is homeomorphic to \M. Since \M is a
  $(d-1)$-manifold without boundary, we deduce that so is $\US{\UpperC
    {K}}$. This implies that the link of any simplex in $\UpperC{K}$
  is a triangulation of the $(d-k-2)$-sphere. In summary, writing
  $X \approx Y$ if $X$ is homeomorphic to $Y$ and $\Sphere^i$ for the
  $i$-sphere, we obtain that
  \[
  \Sphere^{d-k-2} \, \approx \, \US{\Link{\tau}{\UpperC {\Cl{\sigma}} }} \, \subseteq \, \US{\Link{\tau}{ \UpperC {K} }} \, \approx \, \Sphere^{d-k-2}.
  \]
  The only subset of $\Sphere^{d-k-2}$ homeomorphic to
  $\Sphere^{d-k-2}$ being $\Sphere^{d-k-2}$ itself, we get that:
  \begin{equation*}\label{eq:LinkAreEqualsOnBoundary}
    \Link{\tau}{\UpperC {\Cl{\sigma}} }   = \Link{\tau}{ \UpperC {K} }
  \end{equation*}

  We have just proved that $\tau$ is a free simplex of $K$. This concludes the proof.
\end{proof}




\AlgorithmInvariant*

\begin{proof}
  Because $K' \subseteq K$, clearly $\US{K'} \subseteq \Offset \M
  \rtube$ and $K'$ has a non-vertical skeleton with respect to \M. Let us establish
  vertical convexity and covering projection for $K'$. Because $\tau$ is
  a vertically free simplex in $K$ relative to \M, the star
  $\Star \tau K$ has a unique inclusion-maximal simplex $\sigma$ whose
  dimension is $d$. Furthermore, one of the following two situations occurs:
  \[
    \text{(1) }  {\Star \tau K}^{[d-1]} = \Above \sigma \quad \text{or} \quad \text{(2) }  {\Star \tau K}^{[d-1]} = \Below \sigma,
  \]
  where $\Sigma^{[i]}$ stands for the set of $i$-simplices of
  $\Sigma$. Suppose that situation (1) occurs. In other words, $\tau$
  is a free simplex of $K$ from above relative to \M.
  This implies that the upper skin of $\US{\sigma}$
    is contained in the upper skin of $\US{K}$ and $\up {\Cl \sigma} m = \up K
    m$ for all $m \in \pi_\M(\Conv \sigma)$. We deduce that:
  \[
  \US{K'} \cap \Normal m \M \cap B(m,\rtube) =
  \begin{cases}
    [\low K m, \low {\Cl \sigma} m] & \text{if $m \in \pi_\M(\Conv \sigma)$},\\
    \US{K} \cap \Normal m \M \cap B(m,\rtube) & \text{otherwise}.
  \end{cases}
  \]
  We conclude that $K'$ is both vertically convex relative to \M and
  has a covering projection. Similarly, we obtain the same conclusion
  when situation (2) occurs. It remains to check that the acyclicity
  condition holds for $K'$ as well. Note that acyclicity of the
  relation $\below$ over $d$-simplices of $K$ is equivalent to
  acyclicity of the graph $G_\M(K)$.  By Lemma
  \ref{lemma:correspondance-free-terminal-node}, a vertical collapse
  in $K$ corresponds to the removal of a terminal node of
  $G_\M(K)$. We thus obtain acyclicity of the graph $G_\M(K')$ or,
  equivalently, acyclicity of the relation $\below$ over $d$-simplices
  of $K'$.
\end{proof}


\subsection{Practical version}

\InPractice*

\begin{proof}
  Let $\tau$ be a free simplex of $K$ whose inclusion-maximal coface
  $\sigma$ has dimension $d$. We prove the theorem by establishing the
  following equivalence: $\tau$ is vertically free in $K$ relative
  to \M if and only if $\tau$ is vertically free in $K$ relative to
  $\HH_\tau$.


  For any facet $\nu$ of $\sigma$, let $N_\nu$ denote the unit normal
  to $\Conv\nu$ pointing outwards $\Conv\sigma$, as illustrated in
  Figure~\ref{figure:outward-normals}.  We have assumed that for any
  facet $\nu$ of $\sigma$ and any vertex $a$ of $\nu$:
  \[
  \angle(\Aff \nu, \Tangent {\pi_\M(a)} \M) \, < \, \frac{\pi}{4}.
  \]
  It follows that for any facet $\nu$ of $\sigma$ and any vertex $a
  \in \nu$,
  \begin{align*}
    \angle(\normal {\pi_\M(a)}, N_\nu) &< \frac{\pi}{4}, && \text{if $\nu \in \Above \sigma$},\\
    \angle(\normal {\pi_\M(a)}, N_\nu) &> \frac{3\pi}{4}, && \text{if $\nu \in \Below \sigma$}.
  \end{align*}

  \begin{figure}[htb]
    \centering{\input{Figures/socg-simplex-outward-normals.pdf_tex}}
    \caption{Outward-pointing normal vectors to a triangle in
      $\Rspace^2$ can be partitioned in two groups, depending on the
      angle they make. One of the group consists of normal vectors to upper
      facets of $\sigma$, the other group consists of normal vectors to lower facets
      of $\sigma$.
      \label{figure:outward-normals} }
  \end{figure}


  Given any pair of facets $\nu_0, \nu_1$ of $\sigma$, we note that we
  can always find a common vertex $a \in \nu_0 \cap \nu_1$. It follows
  that $\angle(N_{\nu_0},N_{\nu_1}) < \frac{\pi}{2}$ if $\nu_0$ and
  $\nu_1$ are both upper facets of $\sigma$ relative to \M or both
  lower facets of $\sigma$ relative to \M and
  $\angle(N_{\nu_0},N_{\nu_1}) > \frac{\pi}{2}$ otherwise.  We can
  thus partition the facets of $\sigma$ in two groups, depicted in two
  different colors in Figure \ref{figure:outward-normals}. In each
  group, any two facets have their outward-pointing normal vectors
  that make an angle smaller than $\frac{\pi}{2}$. Two facets not in
  the same group have their outward-pointing normal vectors making an
  angle greater than $\frac{\pi}{2}$. Let $\nu$ be any facet of
  $\sigma$. Let $N$ be one of the two unit normal vectors to $\Aff\nu$
  and use it to orient $\Aff\nu$.  If $N = N_\nu$ ({\em resp.} $N = -
  N_\nu$), facets in the group of $\nu$ are precisely those that are
  upper ({\em resp.} lower) facets of $\sigma$ relative to
  $\Aff\nu$.  We thus deduce that either
  \[
  \begin{cases}
    \UpperFacets \sigma \M = \UpperFacets \sigma {\Aff \nu},\\
    \LowerFacets \sigma \M = \LowerFacets \sigma {\Aff \nu},
  \end{cases}
  \]
  or
  \[
  \begin{cases}
    \UpperFacets \sigma \M = \LowerFacets \sigma {\Aff \nu},\\
    \LowerFacets \sigma \M = \UpperFacets \sigma {\Aff \nu},
  \end{cases}
  \]
  depending upon the choice of $N$ to orient $\Aff\nu$.  The result
  follows immediately by noting that for $\X \in \{\M,\Aff\nu\}$,
  the simplex $\tau$ is vertically free in $K$ relative to \X if and
  only if
  \[
  {\Star \tau K}^{[d-1]} = \UpperFacets \sigma \X \quad \text{or} \quad {\Star \tau K}^{[d-1]} = \LowerFacets \sigma \X,
  \]
  where $\Sigma^{[i]}$ stands for the set of $i$-simplices of
  $\Sigma$.  Thus, $\tau$ is vertically free in $K$ relative to \M
  if and only if $\tau$ is vertically free in $K$ relative to
  $\Aff\nu$.  We get the desired equivalence.
\end{proof}


