\section{Proof of Theorem \ref{theorem:alpha-complex} in Section \ref{section:alpha-complexes}}
\label{appendix:alpha-complex-theorem}

The goal of this appendix is to establish Theorem
\ref{theorem:alpha-complex}:


\TheoremAlphaComplex*


\begin{remark}
  \label{remark:conditions-well-defined}
  It is easy to check that Conditions \eqref{eq:angle-condition-for-skeleton},
  \eqref{eq:angle-condition-for-vertical-convexity} and
  \eqref{eq:angle-condition-acyclicity} in Theorem
  \ref{theorem:alpha-complex} are well-defined. Because $P \subseteq
  \Offset \M \delta$, we obtain that $\US{\Del{P,\alpha}} \subseteq
  \Offset P \alpha \subseteq \Offset \M {(\delta+\alpha)}$. Since
  $\delta + \alpha < \reach \leq \Reach{\M}$,
    \[
    \US{\Del{P,\alpha}} \subseteq \Rspace^d \setminus \MA{\M}
    \]
    and the projection map $\pi_\M$ is thus well-defined on the
    support of any simplex in $\Del{P,\alpha}$. It follows that the
    left sides of Conditions \eqref{eq:angle-condition-for-skeleton},
    \eqref{eq:angle-condition-for-vertical-convexity} and
    \eqref{eq:angle-condition-acyclicity} are well-defined.
    We claim that 
    \[
    -1 \leq \frac{(\reach+\beta)^2 - (\reach+\delta)^2 - \alpha^2}{2(\reach+\delta)\alpha} \leq 1.
    \]
    The left inequality is equivalent to $\beta + \alpha \geq \delta$
    which holds since we have assumed that $\alpha \geq \delta$. The
    right inequality is equivalent to $\beta \leq \delta + \alpha$
    which holds because we have assumed that $P \subseteq \Offset
    \M \delta$ and $\Offset \M \beta \subseteq \Offset P \alpha$,
    implying that $\Offset \M \beta \subseteq \Offset \M {(\delta +
      \alpha)}$. Hence, the right side of Condition
    \eqref{eq:angle-condition-for-vertical-convexity} is
    well-defined. Similarly, using the assumption $\alpha \leq
    \frac{2}{3}(\reach - \delta)$, we easily get that
    \[
    0 \leq \frac{\alpha}{2(\reach - \delta - \alpha)} \leq 1,
    \]
    showing that the right side of Condition \eqref{eq:angle-condition-acyclicity} is also well-defined.
\end{remark}

\begin{proof}[Proof of Theorem \ref{theorem:alpha-complex}.]
  Injective projection for $\Del{P,\alpha}$ is shown in
  Section~\ref{appendix:alpha-complex-injective-projection} (Lemma~\ref{lemma:non-vertical}).
  Covering projection and vertical
  convexity for $\Del{P,\alpha}$ are established in
  Section~\ref{section:proof-technique}  (Lemma~\ref{lemma:alpha-complex-vertical-convexity}).
  Acyclicity is established in Section \ref{appendix:acyclicity}   (Lemma \ref{lemma:acyclicity}).
  Hence, all the assumptions of
  Lemma~\ref{lemma:upper-and-lower-complex-equal-boundary} and
  Theorem~\ref{theorem:correctness-generic-simplification} are
  satisfied. By
  Lemma~\ref{lemma:upper-and-lower-complex-equal-boundary}, the upper
  and lower complexes of $\Del{P,\alpha}$ relative to \M are each a
  triangulation of \M. By
  Theorem~\ref{theorem:correctness-generic-simplification},
  $\NaiveSquash(P,\alpha)$ returns a triangulation of \M.
\end{proof}



\subsection{Injective projection}
\label{appendix:alpha-complex-injective-projection}

In this section, we characterize non-verticality of an $i$-simplex $\tau
\in \Del{P,\alpha}$ relative to $\M$.


\begin{lemma}
  \label{lemma:non-vertical}
  Let $P$ be a finite point set in $\Rspace^d$ such that $P \subseteq
  \Offset \M \delta$ for some $\delta \geq 0$. Let $\alpha \in [0,
    \reach - \delta)$. Then, for all $i$-simplices $\tau \in
    \Del{P,\alpha}$ with $0 < i < d$,
  \[
  \eqref{eq:angle-condition-for-skeleton}
  \quad \iff \quad
  \text{$\tau$ is non-vertical relative to \M}
  \]
\end{lemma}


\begin{proof}
  It is easy to see that $\tau$ is
  non-vertical relative to $\M$ if and only if for all $x \in
  \Conv\tau$
  \begin{equation*}
    \angle( \Normal {\pi_\M(x)} \M, \Aff\tau) ) > 0.
  \end{equation*}
  Using Property \ref{property:complementary-angles}, 
  $\angle( \Normal {\pi_\M(x)} \M, \Aff\tau) ) = \frac{\pi}{2} -
  \angle( \Aff \tau, \Tangent {\pi_\M(x)} \M )$ and the above
  inequality is equivalent to
  $
  \angle( \Aff \tau, \Tangent {\pi_\M(x)} \M ) < \frac{\pi}{2}.
  $
  Hence, $\tau$ is non-vertical relative to \M if and only if
  \[
  \max_{x \in \Conv\tau} \angle(\Aff \tau, \Tangent {\pi_\M(x)} \M) \, < \, \frac{\pi}{2},
  \]
  which is equivalent to \eqref{eq:angle-condition-for-skeleton}.
\end{proof}


\subsection{Vertical convexity}
\label{appendix:alpha-complex-vertical-convexity}


Recall that vertical convexity for $\Del{P,\alpha}$ was proved in Section~\ref{section:proof-technique} (Lemma~\ref{lemma:alpha-complex-vertical-convexity}) and that the proof relies on Lemma~\ref{lemma:connecting-boundaries-simplified}. This section is dedicated to proving the latter lemma.


