Plugging the assumptions of Lemma
\ref{lemma:alpha-complex-vertical-convexity} inside Lemma
\ref{lemma:connecting-boundaries-simplified} and using Lemma
\ref{lemma:non-vertical} to replace
Condition~\eqref{eq:angle-condition-for-skeleton} with the assumption
that $\tau$ is non-vertical relative to \M, we can rewrite Lemma
\ref{lemma:connecting-boundaries-simplified} as follows:


\begin{lemma}
	\label{lemma:connecting-boundaries}
	Let $\M \subseteq \Offset P \varepsilon$ and $P \subseteq \Offset
    \M \delta$ for some $\varepsilon,\delta \geq 0$ that satisfy the
    strict homotopy condition.  Let $\alpha \in [\delta,\reach-\delta)
      \cap I{(\varepsilon,\delta)}$ and $\beta > 0$ be such that
      $\Offset \M \beta \subseteq \Offset P \alpha$. Suppose that for
      all $i$-simplices $\tau \in \Del{P,\alpha}$ with $0 < i < d$,
      $\tau$ is non-vertical relative to \M and
      Condition~\eqref{eq:angle-condition-for-vertical-convexity}
      hold.  Let $\spx \in \Del{P,\alpha}$ and $x \in
      \Interior{\Conv{\gamma}}$. If for some $\lambda > 0$ ({\em
        resp.}  $\lambda<0$), the segment $(x,x+\lambda \normal
               {\pi_\M(x)}]$ lies outside $\US{\Del{P,\alpha}}$, then
    it intersects an upper ({\em resp. lower} join).
\end{lemma}




