  \ref{figure:highest-point-on-dual-sphere}.  Let $\Bis{\spx}$ be the
  bisector of $\spx$.  By construction, $s_\spx(x) \in S(\spx,\alpha)
  \subseteq \Bis{\spx}$. Writing $x^* = \pi_\M(x)$ for short, we make
  the following remark:

  \begin{remark}
    \label{remark:cone-s-plus}
    For any simplex $\spx \subseteq \Rspace^d$ and $\alpha \geq 0$
    such that $\Conv{\spx} \subseteq \Rspace^d \setminus \MA{\M}$ and
    $S(\spx,\alpha) \neq \emptyset$ and for any $x \in \Conv{\spx}$,
    \begin{equation*}
      \angle(\normal{x^*} , s_\spx(x) - c_\spx) = \angle(\Normal {x^*} \M, \Bis \spx) = \angle(\Aff {\spx}, \Tangent {x^*} \M).
    \end{equation*}
  \end{remark}



  We start with a lemma.

  \begin{lemma}
    \label{lemma:highest-point-on-upper-skin}
    Assume that $\M \subseteq \Offset P \varepsilon$ and $P \subseteq
    \Offset \M \delta$ for some $\varepsilon,\delta \geq 0$, and let
    $\alpha \in [\delta,\reach-\delta)$. Let $\beta > 0$ be such that $\Offset
      \M \beta \subseteq \Offset P \alpha$. Consider a simplex $\tau$
      with $0 < \dim \tau < d$ satisfying~\eqref{eq:angle-condition-for-vertical-convexity}.
      Suppose $\tau$ is a boundary simplex of $\Del{P, \alpha}$. Then, $s_\tau(a)$ exists for all $a \in \tau$, and there exists $a \in \tau$ at which the following implication holds:
    \begin{equation}
      \label{eq:implication-upper-skin}
    s_\tau(a) \text{ lies on } \partial\Offset P \alpha \quad
    \implies \quad s_\tau(a) \text{ lies on the upper skin of } \Offset P \alpha.
    \end{equation}
  \end{lemma}


  \begin{figure}[htb]
    \centering\input{Figures/proof-connecting-boundaries.pdf_tex}
    \caption{We reach a contradiction in the proof of Lemma
      \ref{lemma:highest-point-on-upper-skin} by assuming that $s_\tau(a)$ lies on the lower skin of $\partial \Offset P \alpha$.
      \label{figure:connecting-boundaries}
    }
  \end{figure}


  \begin{proof}
    Because $\tau$ is a boundary simplex of $\Del{P,\alpha}$, we have
    that $S(\tau,\alpha) \neq \emptyset$ and for any $x \in
    \Conv{\tau}$, one can define $s_\tau(x)$ as the
    point of $S(\tau,\alpha)$ highest in direction $\normal {\pi_\M(x)}$.
    Thus, $s_\tau(x)$ exists for all $x \in \Conv{\tau}$.
    Consider $a \in \tau$
    and write $a^* = \pi_\M(a)$ for short.  Suppose that $a \in \tau$
    is such that
    \begin{align}
      \label{eq:claim-skin}
      s_\tau(a) \text{ lies on } \partial\Offset P \alpha
      \quad \text{ and } \quad  s_\tau(a) \text{ does not lie on the upper skin of } \Offset P \alpha.
    \end{align}
    The only possibility is thus that $s_\tau(a)$ lies on the lower
    skin of $P$, as illustrated in Figure
    \ref{figure:connecting-boundaries}.  Let $z = {a^*} + \reach
    \normal {a^*}$ and note that the ball $B(z,\reach)$ is tangent to
    \M at $a^*$ and does not contain any point of \M in its
    interior. Since $\Offset \M \beta \subseteq \Offset P \alpha$, we
    deduce that the lower skins of both $\Offset \M \beta$ and
    $\Offset P \alpha$ do not intersect the interior of $B(z,\beta +
    \reach)$. Hence, $\|z-{s_\tau(a)}\| \geq \reach + \beta$. By
    construction, $\|a-s_\tau(a)\| = \alpha$ and $\|a - z\| \leq
    \|a-{a^*}\| + \|{a^*}-z\| = \delta + \reach$. Consider the
    triangle with vertices $a$, ${s_\tau(a)}$ and $z$. Using the
    formula that gives the angle at vertex $a$ in triangle
    $az{s_\tau(a)}$ with respect to the length of the sides of the
    triangle, we obtain
  \begin{align}
    \notag
    \cos\left( \angle(\normal {a^*} , s_\tau(a) - a) \right)
    \, &= \, \frac{\|a-z\|^2 + \|a-{s_\tau(a)}\|^2 - \|z-{s_\tau(a)}\|^2}{2 \|a-z\| \|a-{s_\tau(a)}\|}\\
    \notag
    \, &\leq \, \frac{\|a-z\|^2 + \alpha^2 - (\reach+\beta)^2 }{2 \|a-z\| \alpha}\\
    \label{eq:angle-towards-lower-skin}
    \, &\leq \, \frac{(\delta+\reach)^2 + \alpha^2 - (\reach+\beta)^2 }{2 (\delta+\reach) \alpha},
  \end{align}
  where the first inequality comes from the fact that
  $\|a-s_\tau(a)\|=\alpha$ and $\|z-{s_\tau(a)}\| \geq \reach + \beta$
  and the second inequality comes from the fact that $\lambda \mapsto
  \frac{\lambda^2 - A}{\lambda}$ is increasing for $A >0$ and
  $\lambda>0$, applied with $\lambda = \|a-z\|$ and $A = - \alpha^2 +
  (\reach+\beta)^2$. We are going to exhibit a point $a \in \tau$ for
  which \eqref{eq:angle-towards-lower-skin} does not hold, showing
  that for that $a$, statement \eqref{eq:claim-skin} is false and its
  negation, statement \eqref{eq:implication-upper-skin}, is true. By
  Remark \ref{remark:conditions-well-defined}
  \[
    -1 \, \leq \, \frac{(\reach+\beta)^2 - (\reach+\delta)^2 -
      \alpha^2}{2(\reach+\delta)\alpha} \, \leq  \, 1.
    \]
    and it makes sense to introduce the angle
  \[
    \theta = \arcsin \left(\frac{(\reach+\beta)^2 - (\reach+\delta)^2
      - \alpha^2}{2(\reach+\delta)\alpha} \right) \in
    \left[-\frac{\pi}{2},\frac{\pi}{2}\right].
    \]
  Assumption \eqref{eq:angle-condition-for-vertical-convexity}
  can then be rewritten as $\min_{a \in \tau} \angle(\Aff \tau,
  \Tangent {\pi_\M(a)} \M) < \theta$ and we let $a \in \tau$ be any vertex
  such that
  \begin{equation}
  \label{eq:angle-condition-for-vertical-convexity-obtuse-in-proof}
  \angle(\Aff\tau,\Tangent {a^*} \M) < \theta.
  \end{equation}
  Let us show that:
  \begin{equation}
    \label{eq:inside-cone-obtuse}
    \angle (\normal {a^*} , s_\tau(a) - a) < \frac{\pi}{2} + \theta.
  \end{equation}

  \begin{figure}[htb]
    \centering\input{Figures/proof-angle-normal-direction-highest-point.pdf_tex}
    \caption{Notation for the proof of Lemma
      \ref{lemma:highest-point-on-upper-skin}.
      \label{figure:angle-normal-direction-highest-point}
    }
  \end{figure}

  \noindent If $\angle (\normal {a^*} , s_\tau(a) - a) < \frac{\pi}{2}$,
  clearly \eqref{eq:inside-cone-obtuse} holds. If $\angle (\normal {a^*} ,
  s_\tau(a) - a) \geq \frac{\pi}{2}$ (see Figure
  \ref{figure:angle-normal-direction-highest-point}), then using
  \eqref{eq:angle-condition-for-vertical-convexity-obtuse-in-proof} and Remark
  \ref{remark:cone-s-plus}, we get that
  \begin{align*}
    \theta \, &> \, \angle(\Aff {\tau}, \Tangent {a^*} \M) = \angle (\normal {a^*}, s_\tau(a) - c_\tau) 
    = \angle (\normal {a^*}, c_\tau - a) - \frac{\pi}{2} \\
    \, &\geq \, \angle (\normal {a^*}, s_\tau(a) - a) - \frac{\pi}{2}.
  \end{align*}
  Hence, we obtain \eqref{eq:inside-cone-obtuse} as desired. Taking
  the cosine on both sides of \eqref{eq:inside-cone-obtuse}, we obtain that
  \begin{align*}    
    \cos\left( \angle(\normal {a^*} , s_\tau(a) - a) \right)
    > - \sin\theta = \frac{(\reach+\delta)^2 + \alpha^2 - (\reach+\beta)^2 }{2 (\reach+\delta)\alpha}.
  \end{align*}
  But, this contradicts \eqref{eq:angle-towards-lower-skin} which was
  a consequence of \eqref{eq:claim-skin}. Hence, for that particular
  $a$, \eqref{eq:claim-skin} is false. We thus deduce that there
  exists $a \in \tau$ such that if $s_\tau(a)$ lies on
  $\partial \Offset P \alpha$, then $s_\tau(a)$ lies on the upper skin
  of $\Offset P \alpha$. This concludes the proof.
  \end{proof}

  Before proving Lemma \ref{lemma:connecting-boundaries}, we make a useful remark:

\begin{remark}
  \label{remark:sign-dot-product-invariant}
  Consider a $(d-1)$-simplex $\nu \subseteq \Rspace^d$ that is non-vertical relative to \M
  and whose support is contained in $\Rspace^d \setminus \MA{\M}$ and let
  $N$ be a unit vector orthogonal to $\Aff{\nu}$. If $N \cdot \normal
  {\pi_\M(x)} > 0$ for some $x \in \Conv\nu$, then $N \cdot \normal
  {\pi_\M(x)} > 0$ for all $x \in \Conv\nu$.
\end{remark}



\begin{proof}[Proof of Lemma \ref{lemma:connecting-boundaries}.]
  The proof is by descending induction over the dimension of $\spx$.

  \smallskip \noindent \underline{Induction basis:} Suppose that
  $\spx$ has dimension $d-1$. Then, $\Aff\spx$ is an hyperplane and
  $S(\spx,\alpha)$ is a $0$-sphere that consists of two points
  (possibly equal).  Consider $x \in \Interior{\Conv{\spx}}$ and
  $\lambda > 0$ such that the segment $(x,x+\lambda
  \normal{\pi_\M(x)}]$ lies outside $\US{\Del{P,\alpha}}$.  Let $N$ be
  the unit vector orthogonal to $\Aff \spx$ that satisfies
  \[
  \normal{\pi_\M(x)} \cdot N > 0
  \]
  and observe that, for $\mu>0$ small enough, the segment
  $(x,x+\mu N]$ lies outside $\US{\Del{P,\alpha}}$. Let $s$ be
the highest point of $S(\spx,\alpha)$ along direction $N$. By duality
between the boundary simplices of $\Del{P,\alpha}$ and the faces of
$\partial \Offset P \alpha$, we deduce that $s$ lies on
$\partial\Offset P \alpha$.  Let $a \in \gamma$. Since $\gamma$ is non-vertical, Remark
\ref{remark:sign-dot-product-invariant} tells us that
    \[
    \normal{\pi_\M(a)} \cdot N > 0.
    \]
    Note that $s$ is also the point of $S(\spx,\alpha)$ highest along
    direction $\normal{\pi_\M(a)}$, namely $s = s_\spx(a)$. Thus,
    $s_\spx(a)$ lies on  $\partial\Offset P \alpha$. Applying
    Lemma \ref{lemma:highest-point-on-upper-skin} with $\tau=\spx$, we
    get that $s_\spx(a)$ lies on the upper skin of $\Offset P
    \alpha$. Hence, the set $\{s_\spx(a)\} * \Conv\spx$ is contained
    in the upper join of $\spx$ and the segment $(x,x+\lambda \normal
    {\pi_\M(x)}]$ has a non-empty intersection with the upper join of
      $\spx$. This concludes the induction basis.

    \smallskip \noindent \underline{Induction step:} Let $k \in
    \{0,\ldots,d-1\}$ and assume that the lemma holds for all $\spx$
    with dimension $i \geq k+1$. Let us prove that the lemma also
    holds when $\spx$ has dimension $k$.  We distinguish two cases:

    \smallskip\styleitem{(a)} $\spx$ has no proper coface in
    $\Del{P,\alpha}$. In that case, the whole sphere $S(\spx,\alpha)$
    lies on $\partial \Offset P \alpha$ and so does $s_\spx(a)$ for
    any $a \in \gamma$. Pick $a \in \gamma$. By Lemma
    \ref{lemma:highest-point-on-upper-skin} applied with $\tau =
    \spx$, $s_\spx(a)$ lies on the upper skin of $\Offset P
    \alpha$. Since for $0 \leq k < d-1$, the $(d-k-1)$-sphere
    $S(\spx,\alpha)$ is connected, the whole sphere $S(\spx,\alpha)$
    has to lie on the upper skin. Hence, $S(\spx,\alpha) * \Conv \spx$
    is the upper join of $\spx$. It follows that for any point $x \in
    \Interior{\Conv \spx}$ and any $\lambda >0$, the upper join $S(\spx,\alpha) *
    \Conv\spx$ has a non-empty intersection with the segment
    $(x,x+\lambda \normal {\pi_\M(x)}]$. This concludes
      case~\styleitem{(a)}.


  \begin{figure}[htb]
    \centering\input{Figures/path-face-coface.pdf_tex}
    \caption{
      Construction of a path $\Gamma$ connecting $z \in
      \Interior{\Conv\spx}$ to $z'\in\Interior{\Conv\sigma}$ when
      $d=2$ and $\spx$ is a vertex. As we move any point $x \in [z,z']$ in direction
      $\normal{x^*}$, $x$ enters the gray cone formed of all points $p$
      such that $\angle(\normal{z^*},p-x) < \varphi$ and therefore goes outside $\US{\Del{P,\alpha}}$.
      \label{figure:path-face-to-coface}}
  \end{figure}


  \smallskip\styleitem{(b)} $\spx$ has at least one proper coface in
  $\Del{P,\alpha}$; see Figure \ref{figure:path-face-to-coface}.
  Consider $z \in \Interior{\Conv \spx}$ and $\lambda > 0$ such that the
  segment $(z,z+\lambda \normal{\pi_\M(z)}]$ lies outside
  $\US{\Del{P,\alpha}}$ and let us prove that the segment intersects an upper
  join. Write $z^* = \pi_\M(z)$ for short. Let $\Sigma =
  \Star{\spx}{\Del{P,\alpha}}$ denote the set of cofaces of $\spx$ in
  $\Del{P,\alpha}$. Recall that the tangent cone to $\US{\Sigma}$
  at $z$ (see Equation~\eqref{eq:tangent_cone}) is denoted $\TanSpace(z,\US{\Sigma})$. Let
  \[
  \varphi = \min_{0 \neq v \in \TanSpace(z,\US{\Sigma})}
  \angle(\normal{z^*},v).
  \]
  Because of our assumption that $(z,z+\lambda \normal{\pi_\M(z)}]$ lies
    outside $\US{\Del{P,\alpha}}$, we have that $\varphi > 0$.
    Consider a ball $B$ centered at $z$ whose radius is small enough
    so that $B \subseteq \Offset P \alpha$ and $B$ does not intersect
    the support of any simplex in $\Del{P,\alpha} \setminus
    \Sigma$. Note that $\US{\Sigma} \cap B$ is star-shaped at $z$,
    that is,
  \[
  x \in \US{\Sigma} \cap B \quad \implies \quad [x,z] \subseteq \US{\Sigma} \cap B.
  \]
  By considering $B$ small enough, we may assume furthermore that for
  all $x \in \US{\Sigma} \cap B$ with $x \neq z$, the half-line with
  origin at $z$ and passing through $x$ intersects $\US{\Sigma} \cap
  B$ in a radius of $B$, that is, a segment connecting the center of
  $B$ to its bounding sphere $\partial B$. We also assume that $B$ is
  small enough so that for all $x \in B$
  \begin{equation*}
    \label{eq:cone-outside-around-north-pole}
    \angle (\normal{z^*},\normal{x^*}) < \varphi,
  \end{equation*}
  where, as usual, we write $x^* = \pi_\M(x)$. Consider the $(d-k)$-dimensional
  affine space $H$ passing through $z$ and orthogonal to $\Aff\spx$.
  Associate to each proper coface $\sigma \in \Sigma \setminus
  \{\spx\}$ the angle:
  \[
  \psi_\sigma = \min_{s \in \Conv{\sigma} \cap \partial B \cap H} \angle (\normal{z^*}, s-z).
  \]
  Note that  $\psi_\sigma \geq \varphi$ because $\varphi$ can be expressed as
  \[
  \varphi = \min_{s \in \US{\Sigma} \cap \partial B} \angle (\normal{z^*}, s-z).
  \]
  Let $\sigma \in \Sigma \setminus \{\spx\}$ that achieves the
  smallest $\psi_\sigma$. One can always find $z' \in
  \Interior{\Conv{\sigma}} \cap B$ and $\mu>0$ such that the
  $\mu$-offset of the segment $[z,z']$ is contained in $B$; see
  Figure \ref{figure:path-face-to-coface}.  Let
  \[
  f(x) = x + \mu \normal{x^*}.
  \]
  By construction, for all $x \in [z,z']$, we have $(x,f(x)] \subseteq
    B \subseteq \Offset P \alpha$. Moreover,
  \[
  (x,f(x)] \subseteq \Offset P \alpha \setminus \US{\Del{P,\alpha}}.
    \]
    Indeed,  $\sigma$ has been chosen so that any
    point $x \in \Conv\sigma \cap B$ is the highest point of
    $\US{\Sigma} \cap B$ along direction $\normal{z^*}$ and therefore
    \[
    (x,x+\mu \normal{z^*}] \subseteq \Offset P \alpha \setminus
      \US{\Del{P,\alpha}}
      \]
      Because $\angle (\normal{z^*},\normal{x^*}) < \varphi \leq
      \psi_\sigma$, the same remains true when replacing
      $\normal{z^*}$ with $\normal{x^*}$ in the above
      inclusion; see Figure \ref{figure:path-face-to-coface}. Consider now the path
  \[
  \Gamma = (z,f(z)] \cup f([z,z']) \cup [f(z'),z').
  \]
  By construction,
  \[
  \Gamma \subseteq  \Offset P \alpha \setminus \US{\Del{P,\alpha}}
  \]
  and, by Remark \ref{remark:intersection-joins}, $\Gamma$ is covered
  either by upper joins or by lower joins but cannot be covered by
  both. Applying the induction hypothesis to $\sigma$, we obtain that
  sufficiently close to $z' \in \Conv\sigma$, the path $\Gamma$ is
  covered by an upper join. Hence, the entire path $\Gamma$ is covered
  by upper joins and the segment $(z,z+\lambda \normal{z^*}]$ intersects
    an upper join. This concludes case~\styleitem{(b)} and the proof
    of the lemma.
\end{proof}





\subsection{Acyclicity}
\label{appendix:acyclicity}

The relation $\below$ over the $d$-simplices of a simplicial complex
$K$ is not acyclic in general; see Figure~\ref{figure:cycle-2d}.
However, when $K$ is the $\alpha$-complex of a finite point set $P$
within distance $\delta$ of $\M$, we state conditions under which
$\below$ becomes acyclic. The result is akin to an acyclicity result
on Delaunay complexes in \cite{edelsbrunner2001geometry}.




\begin{lemma}[Acyclicity]
  \label{lemma:acyclicity}
  Let $P$ be a finite point set in $\Rspace^d$ such that $P \subseteq
  \Offset \M \delta$ for some $\delta \geq 0$. Let $\alpha \in
   \left[0,\frac{2(\reach - \delta)}{3}\right)$.  Assume that all $(d-1)$-simplices $\nu \in
    \Del{P,\alpha}$ are non-vertical relative to \M and satisfy
    \[
      \min_{x \in \Conv\nu} \angle(\Aff \nu, \Tangent {\pi_\M(x)} \M) \, < \,  
      \frac{\pi}{2} - 2 \arcsin\left( \frac{\alpha}{2(\reach - \delta - \alpha)} \right).
    \]
    Then, the relation $\below$ defined over the Delaunay $d$-simplices is acyclic.
\end{lemma}


Any $(d-1)$-simplex $\nu$ that satisfies the conditions of the above
lemma is non-vertical relative to \M and has a support contained in $\Rspace^d
\setminus \MA{\M}$. 

\begin{definition}
  \label{definition:consistently-oriented}
  Consider a $(d-1)$-simplex $\nu$ that is non-vertical relative to
  \M and whose support is contained in $\Rspace^d \setminus
  \MA{\M}$. We say that the unit vector $N$ normal to $\Aff\nu$ is
     {\em consistently oriented} with \M if there exists $x \in
     \Conv\nu$ such that $N \cdot \normal {\pi_\M(x)} > 0$.
\end{definition}

By Remark \ref{remark:sign-dot-product-invariant}, $\nu$ has exactly
one of its two unit normal vectors that is consistently oriented with
\M and for that unit vector $N$, we have that $N \cdot \normal
   {\pi_\M(x)} > 0$ for all $x \in \Conv\nu$.  Let $Z(\sigma)$
   designates the center of the $(d-1)$-sphere that circumscribes a
   $d$-simplex $\sigma$ and associate to each point $z \in \Rspace^d
   \setminus \MA{\M}$ the real number:
\[
\alt{z} = (z - \pi_\M(z)) \cdot \normal{ \pi_\M(z) }.
\]

The proof of Lemma \ref{lemma:acyclicity} relies on the following
lemma:

\begin{lemma}
  \label{lemma:height-is-increasing}
  Let $P$ be a finite point set in $\Rspace^d$ such that $P \subseteq
   \Offset \M \delta$ for some $\delta \geq 0$. Let $\alpha \in
           \left[0,\frac{2(\reach - \delta)}{3}\right)$ and consider a $(d-1)$-simplex $\nu \in
             \Del{P,\alpha}$ that is non-vertical relative to
             \M. Assume that
     \[
     \min_{x \in \Conv\nu} \angle(\Aff \nu, \Tangent {\pi_\M(x)} \M) \, < \,  
     \frac{\pi}{2} - 2 \arcsin\left( \frac{\alpha}{2(\reach - \delta - \alpha)} \right).
     \]
   \begin{enumerate}
   \item Let $N$ be the unit normal vector to $\Aff\nu$ that is
     consistently oriented with \M. As we move a point $z$ on the
     segment $V(\nu,P) \cap \Offset P \alpha$ along direction $N$,
     $\alt{z}$ is increasing.
   \item Suppose that $\nu$ is the common facet of two
     $d$-simplices $\sigma_0, \sigma_1 \in \Del{P,\alpha}$ such that
     $\sigma_0 \below \sigma_1$.  As we move a point $z$ on the
     Voronoi edge dual to $\nu$ in direction $Z(\sigma_1) -
     Z(\sigma_0)$, $\alt{z}$ is increasing and therefore:
     \[
     \sigma_0 \below \sigma_1 \quad \implies \quad \alt{Z(\sigma_0)} < \alt{Z(\sigma_1)}.
     \]
   \end{enumerate} 
\end{lemma}



\begin{proof}
  We first note that $V(\nu,P) \cap \Offset P \alpha$ is indeed a segment because
  \[
  V(\nu,P) \cap \Offset P \alpha = V(\nu, P) \cap \bigcap_{p \in
    \nu} B(p,\alpha)
  \]
  and this segment is parallel to $N$.
  Let $z_0$ and $z_1$ be the two endpoints of that segment and name
  them so that $(z_1-z_0)\cdot N \geq 0$.  For all $t \in [0,1]$, let
  $z(t) = (1-t) z_0 + t z_1$ and $\varphi(t) = \alt{z(t)}$. We show
  the first item of the lemma by establishing that $\varphi'(t) > 0$
  for all $t \in (0,1)$. Since $\nabla \alt{z} = \normal {\pi_\M(z)}$
  and $z'(t) = z_1 - z_0$, we obtain that
  \begin{align*}
    \varphi'(t) &= \nabla \alt{z(t)} \cdot z'(t)\\
    &= \normal {\pi_\M(z(t))} \cdot (z_1 - z_0).
  \end{align*}
  To show that $\varphi'(t) > 0$, it suffices to show that
  $\angle(\normal {z(t)} , z_1 - z_0) < \frac{\pi}{2}$ for all $t \in
  (0,1)$; see Figure~\ref{figure:proof-increasing-height}, left. Consider
  $t \in (0,1)$ and $x \in \Conv\nu$. Write $z = z(t)$, $z^* =
  \pi_\M(z(t))$, and $x^* = \pi_\M(x)$ for short. We have
  \begin{equation*}
    \angle(\normal {z^*} , z_1 - z_0) \leq \angle(\normal {z^*}, \normal {x^*}) + \angle( \normal {x^*}, z_1-z_0 ).
  \end{equation*}

  \begin{figure}[htb]
    \begin{center}
      \def\svgwidth{.49\linewidth}
      \raisebox{1.5cm}{\input{Figures/proof-increasing-height-1.pdf_tex}}
      \def\svgwidth{.49\linewidth}
      \input{Figures/proof-increasing-height-0.pdf_tex}
    \end{center}
    \caption{Notation for the proof of Lemma
      \ref{lemma:height-is-increasing}. The angle $\angle(\normal {x^*}, z_1 - z_0)$ is
       in purple. \label{figure:proof-increasing-height}}
  \end{figure}

  Let us first upper bound $\angle(\normal {z^*}, \normal {x^*})$. Set $r = \delta
  + \alpha < \Reach{\M}$. Since $P \subseteq \Offset \M \delta$, we get that $x,z
  \in \Offset P \alpha \subseteq \Offset \M {(\delta+\alpha)} =
  \Offset \M r$. We know from \cite[page 435]{federer1959curvature}
  that for $r < \Reach{\M}$, the projection map $\pi_\M$ onto
  $\M$ is $\left( \frac{\reach}{\reach - r} \right)$-Lipschitz for
  points in $\Offset \M r$.  Hence,
  $ \|z^* - x^*\| \leq \frac{\reach}{\reach-\alpha-\delta} \, \|z-x\|$.
  Then, using a result in \cite{boissonnat2018geometric} which says that for all 
   $m,m' \in \M$, we have 
  $\angle (\normal m, \normal {m'}) \leq 2 \arcsin \left( \frac{\|m'-m\|}{2\reach} \right)$, 
  we obtain that
 \begin{equation*}
  \angle(\normal {z^*}, \normal {x^*}) \leq 2 \arcsin\left( \frac{\|z^* -
    x^*\|}{2\reach} \right) \leq 2 \arcsin \left( \frac{\|z-x\|}{2(\reach-\alpha-\delta)} \right).
 \end{equation*}
 Because $z \in V(\nu,P) \cap \bigcap_{p
   \in \nu} B(p,\alpha)$ and $x \in \Conv{\nu}$, we deduce that
  $\|z-x\| \leq \alpha$ and 
 \begin{equation}
   \label{eq:bound-angle-between-normals}
  \angle(\normal {z^*}, \normal {x^*}) \leq 2 \arcsin \left(
  \frac{\alpha}{2(\reach-\alpha-\delta)} \right).
 \end{equation}
 Because $N$ is consistently oriented with \M, we have that $N \cdot
 \normal{x^*} > 0$ and
 \begin{equation}
   \label{eq:relation-normals-tangents}
    \angle( \normal {x^*}, z_1-z_0 ) = \angle( \normal {x^*}, N ) =  \angle (\Tangent {x^*} \M, \Aff {\nu})
 \end{equation}
 Using \eqref{eq:bound-angle-between-normals} and \eqref{eq:relation-normals-tangents}, we obtain that
 \begin{align*}
   \angle(\normal {z^*} , z_1 - z_0) &\leq \angle(\normal {z^*}, \normal {x^*}) + \angle( \normal {x^*}, z_1-z_0 )\\   &\leq  2 \arcsin \left(
  \frac{\alpha}{2(\reach-\alpha-\delta)} \right) + \angle (\Tangent {x^*} \M, \Aff {\nu}).
 \end{align*}
 Since the above inequality is true for all $x$, we get that
 \begin{equation*}
   \angle(\normal {z^*} , z_1 - z_0) \leq
   2 \arcsin \left(\frac{\alpha}{2(\reach-\alpha-\delta)} \right) + \min_{x \in \Conv\nu} \angle (\Tangent {x^*} \M, \Aff {\nu})
 \end{equation*}
 and using our angular hypothesis, we deduce that $ \angle(\normal
 {z^*} , z_1 - z_0) < \frac{\pi}{2}$ and $\varphi'(t) > 0$ for all $t \in (0,1)$ as desired.

 \medskip

 For the proof of the second item of the lemma, define $z_0$ and $z_1$
 as in the proof of the first item and note that the hypothesis
 $\sigma_0 \below \sigma_1$ implies $z_1 = Z(\sigma_1)$, $z_0 =
 Z(\sigma_0)$, and $N = \frac{z_1-z_0}{\|z_1-z_0\|}$; see
 Figure~\ref{figure:proof-increasing-height}, right.  The first item
 then implies that
 \[
 \alt{Z(\sigma_0)} < \alt{Z(\sigma_1)},
 \]
 which yields the second item.
\end{proof}


\begin{proof}[Proof of Lemma \ref{lemma:acyclicity}.]
   Let $\sigma_0, \sigma_1 \in \Del{P,\alpha}$ be two $d$-simplices
   with a common $(d-1)$-face. If $\sigma_0 \below \sigma_1$, then
   Lemma~\ref{lemma:height-is-increasing} implies that
   $\alt{Z(\sigma_0)} < \alt{Z(\sigma_1)}$. The acyclicity of the
   relation $\below$ follows, because no function can increase along a
   cycle.
\end{proof}


