\section{Sampling conditions for surfaces in $\Rspace^3$}
\label{appendix:alpha-complex-second-corrolary}

\ignore{
\biancacmt{It would make it easier to know what we are referring to if the section title would be more explicit, like "Proof of the sampling conditions on a surface" or "When is the sample a triangulation of M".} \Domi{What about the following section title?}
}

This appendix contains the proof of
Theorem~\ref{corollary:3D-theory} in
Section~\ref{section:alpha-complexes}. Recall that
\[
  \beta_{\varepsilon,\alpha} = -\frac{\varepsilon^2}{2\reach} + \sqrt{\alpha^2 + \frac{\varepsilon^4}{4\reach^2}-\varepsilon^2}.
\]


\CorollaryThreeDimensionTheory*

\bigskip

As an intermediate step, we establish Lemma \ref{lemma:3D-conditions}.

\begin{lemma}
  \label{lemma:3D-conditions}
  Let \M be a surface in $\Rspace^3$ and $P \subseteq \M$ a finite
  point set such that $\M \subseteq \Offset P \varepsilon$. Let $\delta = 0$ and $\beta =
  \beta_{\varepsilon,\alpha}$. Consider $\varepsilon \geq 0$ and $\alpha \geq 0$ that satisfy 
  the following condition:
  \begin{equation}
    \label{eq:3D-domain}
    \frac{\sqrt{3} \, \alpha}{\reach} < \min \left\{
    \frac{(\reach+\beta_{\varepsilon,\alpha})^2 - \reach^2 - \alpha^2}{2\reach\alpha},\,
    \cos\left( 2 \arcsin\left( \frac{\alpha}{\reach} \right)\right)
    \right\}.
  \end{equation}
  Then, the assumptions of Theorem
  \ref{theorem:alpha-complex} are satisfied. If furthermore
  \begin{equation}
    \label{eq:3D-practical}
    \frac{\sqrt{3} \, \alpha}{\reach} < \sin\left( \frac{\pi}{4} - 2 \arcsin \left( \frac{\alpha}{\reach} \right)\right),
  \end{equation}
   then the assumptions of Corollary
   \ref{theorem:correcness-squash-practical} are also satisfied.
\end{lemma}

\begin{figure}
	\centering
    \def\svgwidth{.5\textwidth}
    \input{Figures/corollary-3D-homotopy.pdf_tex}
	\caption{Pairs of $(\frac{\varepsilon}{\reach},\frac{\alpha}{\reach})$ for which Condition \eqref{eq:3D-feasible-range} is satisfied (in orange) and for which both Conditions \eqref{eq:3D-domain} and \eqref{eq:3D-feasible-range} are satisfied (in blue), for $P \subseteq \M \subseteq \Offset P \varepsilon$ and $d=3$.}
	\label{fig:sampling-condition-3D-homotopy}
\end{figure}




\begin{proof}
  For short, set $I(\varepsilon) = I(\varepsilon,0)$.  We are going to
  establish the lemma, adding to Condition \eqref{eq:3D-domain} the
  following one:
  \begin{equation}
    \label{eq:3D-feasible-range}
    \varepsilon \leq \sqrt{6 - 4 \sqrt{2}}\, \reach \quad \text{and}
    \quad \alpha \in I(\varepsilon) \cap \left[0,\frac{\reach}{\sqrt{3}}\right].
  \end{equation}
  Indeed, one can check numerically that the domain of $\varepsilon
  \geq 0$ and $\alpha \geq 0$ defined by \eqref{eq:3D-domain}
  and \eqref{eq:3D-feasible-range} is exactly the same as the one defined by
  \eqref{eq:3D-domain} alone; see Figure \ref{fig:sampling-condition-3D-homotopy}. Hence, adding
  \eqref{eq:3D-feasible-range} to \eqref{eq:3D-domain}
  does not change the statement of the lemma, except that under that
  form, the lemma becomes easier to establish.

  Let us first check that the assumptions of Theorem
  \ref{theorem:alpha-complex} are satisfied. In Theorem
  \ref{theorem:alpha-complex}, we require that $\varepsilon, \delta
  \geq 0$ satisfy the strict homotopy condition. Since $\delta = 0$,
  this condition can be rewritten as $\reach^2-\varepsilon^2 \geq
  (4\sqrt{2}-5)\reach^2$ or equivalently
\[
\varepsilon \leq \sqrt{6 - 4 \sqrt{2}}\, \reach.
\]
We also require that $\alpha \in I(\varepsilon,\delta) \cap \left[\delta,\frac{2(\reach-\delta)}{3}\right)$ which can be rewritten as $\alpha \in I(\varepsilon) \cap \left[0,\frac{\reach}{\sqrt{3}}\right]$ since $\delta=0$.  Lemma~\ref{lemma:tubular-neighborhood-in-alpha-offset} ensures that
  for $\beta = \beta_{\varepsilon,\alpha}$, we have $\Offset \M \beta
  \subseteq \Offset P \alpha$, as required in Theorem
  \ref{theorem:alpha-complex}. Suppose that $\tau$ is either an edge
  or a triangle of $\Del{P,\alpha}$. Then, $\rcirc{\tau} \leq \alpha$
  and applying Lemmas~\ref{lemma:angleBetweenEdgeAndTangentPlane} and
  \ref{lemma:angleBetweenTriangleAndTangentPlane}, we obtain that for
  $\alpha \leq \frac{\reach}{\sqrt{3}}$
  \begin{equation}
    \label{eq:min-angle-bound}
\min_{x \in \Conv\tau} \angle(\Aff \tau, \Tangent {\pi_\M(x)} \M) \leq \min_{a \in \tau} \angle(\Aff \tau, \Tangent {\pi_\M(a)} \M) \leq
\arcsin\left( \frac{\sqrt{3} \, \alpha}{\reach}\right).    
  \end{equation}
Applying Lemma
\ref{lemma:difference-max-min-angular-deviation-noiseless}, we deduce that for any edge and triangle $\tau
\in \Del{P,\alpha}$
  \begin{equation}
    \label{eq:max-angle-bound}
\max_{a \in \tau} \angle(\Aff \tau, \Tangent {\pi_\M(a)} \M) \leq \arcsin\left(\frac{\sqrt{3} \, \alpha}{\reach}\right) + 2 \arcsin \left( \frac{\alpha}{\reach} \right).
  \end{equation}
Replacing the left side of Condition~\eqref{eq:angle-condition-for-skeleton} with the right side of the above inequality, we obtain the stronger condition:
\begin{equation}
  \label{eq:3D-domain-C1}
\arcsin\left(\frac{\sqrt{3} \, \alpha}{\reach}\right) < 
    \frac{\pi}{2} - 2 \arcsin\left( \frac{\alpha}{\reach} \right).
\end{equation}
Similarly, when replacing the left side of
Conditions~\eqref{eq:angle-condition-for-vertical-convexity} and
\eqref{eq:angle-condition-acyclicity} with
the right side of \eqref{eq:min-angle-bound} and after
plugging $\beta = \beta_{\varepsilon,\alpha}$ and $\delta = 0$ on the
right side, we get the respectively stronger conditions:
\begin{align}
  \label{eq:3D-domain-C2}
  \arcsin\left(\frac{\sqrt{3} \, \alpha}{\reach}\right) &< 
  \arcsin\left(\frac{(\reach+\beta_{\varepsilon,\alpha})^2 - \reach^2 - \alpha^2}{2\reach\alpha}\right),\\
  \label{eq:3D-domain-C3}
  \arcsin\left(\frac{\sqrt{3} \, \alpha}{\reach}\right) &< 
  \frac{\pi}{2} - 2 \arcsin\left( \frac{\alpha}{2(\reach - \alpha)} \right).
\end{align}
Hence, for $\beta=\beta_{\varepsilon,\alpha}$ and $\delta = 0$, Conditions \eqref{eq:angle-condition-for-skeleton},
\eqref{eq:angle-condition-for-vertical-convexity}, and
\eqref{eq:angle-condition-acyclicity} are implied by
\eqref{eq:3D-domain-C1}, \eqref{eq:3D-domain-C2}, and
\eqref{eq:3D-domain-C3} which can be rewritten as \eqref{eq:3D-domain}
since \eqref{eq:3D-domain-C3} is redundant with \eqref{eq:3D-domain-C1}.

Second, let us check that if furthermore Condition
\eqref{eq:3D-practical} is satisfied, the assumptions of Corollary
\ref{theorem:correcness-squash-practical} are also satisfied.
When
replacing the left side of Condition
\eqref{eq:angle-condition-practical} with the right side of 
\eqref{eq:max-angle-bound}, we get a stronger condition, namely
\eqref{eq:3D-practical}.
\end{proof}

Thanks to the above lemma, the proof of
Theorem~\ref{corollary:3D-theory} is now straightforward.

\begin{proof}[Proof of Theorem~\ref{corollary:3D-theory}.]
  Let $\delta = 0$ and $\beta = \beta_{\varepsilon,\alpha}$.  By Lemma
  \ref{lemma:3D-conditions}, if \itemref{item:naive-3D-sampling}
  holds, then the assumptions of Theorem \ref{theorem:alpha-complex}
  are met. It can thus be applied to obtain the first part of the
  theorem. In addition, if \itemref{item:practical-3D-sampling}
  holds, the assumptions of Corollary
  \ref{theorem:correcness-squash-practical} are met. It can thus be
  applied to obtain the second part of the theorem.
\end{proof}



