\section{The restricted Delaunay complex}
\label{appendix:restricted-Delaunay-complex}

Given $\M \subseteq \Rspace^d$ and a finite $P
\subseteq \Rspace^d$, we recall that the {\em restricted Delaunay
  complex} is
\[
\DelR{P} = \{ \sigma \subseteq P \mid \sigma \neq \emptyset \text{ and
} V(\sigma,P) \cap \M \neq \emptyset \}.
\]
The goal of this section is to establish the following theorem.

\TheoremRestrictedDelaunayComplex*


Instrumental to the proof, we introduce the core Delaunay
complex. Given $\M \subseteq \Rspace^d$ and a finite point set $P
\subseteq \Rspace^d$, the {\em core Delaunay complex} is the
collection of $d-1$ simplices in the restricted Delaunay complex
together with all their faces:
\[
\DelC{P} = \Cl{\left(\DelR{P}^{[d-1]}\right)}.
\]

\begin{proof}[Proof of Theorem \ref{theorem:3D-restricted-Delaunay-complex}]
  By Lemma \ref{lemma:3D-crossing-Delaunay}, $\DelC{P}$ triangulates
  \M. By Lemma \ref{lemma:WhenRestrictedDelaunayIsPure2D}, the
  restricted Delaunay complex is a pure 2-dimensional simplicial
  complex. In other words,
  \[
  \DelR{P} = \DelC{P},
  \]
  yielding the result.
\end{proof}

In the rest of the section, we establish the two lemmas needed for the
proof of Theorem~\ref{theorem:3D-restricted-Delaunay-complex}.


\subsection{The core Delaunay complex}
\label{appendix:core-Delaunay-complex}

In this section, we provide conditions under which the core Delaunay
complex triangulates \M. The first lemma is true for all dimensions $d$
and the second one is true for $d=3$ and is the one used in the proof
of Theorem \ref{theorem:3D-restricted-Delaunay-complex}.


\begin{lemma}
	\label{lemma:crossing-Delaunay}
	Under the assumptions of Theorem~\ref{theorem:alpha-complex} and
    the additional generic assumption that none of the Voronoi
    vertices of $P$ lie on \M, there exists an execution of
    $\NaiveSquash(P,\alpha)$ that outputs $\DelC{P}$. Consequently,
    $\DelC{P}$ is a triangulation of \M.
\end{lemma}


\begin{algorithm}
  \caption{$\NonCrossingVertSimp(K)$
  }
  \begin{algorithmic}
    \WHILE{ $G_\M(K) \neq \emptyset$ }
    \IF{ $G_\M(K)$ has a sink $\sigma$ whose circumcenter lies above \M }
    \STATE { Collapse  $\bigcap \Above \sigma$ in $K$;}
    \ELSIF { $G_\M(K)$ has a source $\sigma$ whose circumcenter lies below \M }
    \STATE { Collapse  $\bigcap \Below \sigma$ in $K$;}
    \ENDIF
    \ENDWHILE
  \end{algorithmic}
  \label{algo:non-crossing-simplification}
\end{algorithm}

\begin{algorithm}
  \caption{$\NonCrossingSquash(P,\alpha)$}
  \begin{algorithmic}
	\STATE{ $K \leftarrow \Del{P,\alpha}$;  $\NonCrossingVertSimp(K)$; {\bf return} $K$; }
  \end{algorithmic}
  \label{algo:non-crossing-squash}
\end{algorithm}


\begin{proof}
  Before we start, recall that given a point $x \in \Rspace^d \setminus
  \MA{\M}$,
  \[
  \alt{x} = (x - \pi_\M(x)) \cdot \normal{ \pi_\M(x) }
  \]
  is the signed distance of $x$ from \M. We shall say that a point $x
  \in \Rspace^d \setminus \MA{X}$ lies above \M iff $\alt{x} \geq 0$,
  $x$ lies below \M iff $\alt{x} \leq 0$, and $x$ lies on \M iff
  $\alt{x} = 0$. We also note that the core Delaunay complex can 
  equivalently be defined as
  \[
  \DelC{P} = \Cl{\left( \{ \nu \in \Del{P}^{[d-1]} \mid V(\nu,P) \cap \M
    \neq \emptyset\} \right)}.
  \]
  The proof is done in four steps:


  \Step{1} We show that $\NonCrossingSquash(P,\alpha)$ corresponds to
  one particular execution of $\NaiveSquash(P,\alpha)$.  For this, we
  show that when running $\NonCrossingVertSimp(K)$
  on $K =
  \Del{P,\alpha}$, each execution of the while-loop results in one
  vertical collapse relative to \M. This boils down to proving that at
  least one of the two conditional expressions in $\NonCrossingVertSimp(K)$
  evaluates to true
  whenever $G_\M(K) \neq \emptyset$. Suppose that $G_\M(K) \neq
  \emptyset$ and contains a node $\sigma_0$, which, by definition, is
  a $d$-simplex of $K$. Let $Z(\sigma_0)$ denote the circumcenter of
  $\sigma_0$. We consider two cases:

  \smallskip \styleitem{(a)} Suppose that $Z(\sigma_0)$ lies above
  \M. Because $G_\M(K)$ is a directed acyclic graph, we can find a
  directed path that connects $\sigma_0$ to a sink $\sigma$.  By Lemma
  \ref{lemma:height-is-increasing}, the map that associates to each
  node $v$ the quantity $\alt{Z(v)}$ is increasing along the directed
  path. Since $Z(\sigma_0)$ lies above \M, so does $Z(\sigma)$. Thus,
  we find a sink whose circumcenter lies above \M.


  \smallskip \styleitem{(b)} Suppose that $Z(\sigma_0)$ lies below
  \M. Similarly, we find a source $\sigma$ whose circumcenter lies
  below \M.

  \smallskip

  This shows that at least one of the two conditional expressions in
  $\NonCrossingVertSimp(K)$
  evaluates to true whenever
  $G_\M(K) \neq \emptyset$. 

  \Step{2} We show that
  $
  \DelC P \subseteq \Del{P,\alpha}.
  $
  Indeed, consider a $(d-1)$-simplex $\gamma \in \DelC P$. By
  definition, there exists a sphere that circumscribes $\gamma$ and
  whose center lies on \M. Because $\M \subseteq \Offset P
  \varepsilon$, we deduce that the radius of that sphere is
  $\varepsilon$ at most and $\gamma \in \Del{P,\varepsilon}$.  Because
  $\alpha \in I(\varepsilon,\delta) = [\alpha_{\min},\alpha_{\max}]$,
  one can easily check from the definition of $\alpha_{\min}$ in
  Appendix~\ref{appendix:range-alpha} that $\varepsilon \leq \alpha$
  and therefore $\gamma \in \Del{P,\alpha} = K$.

  \Step{3} We show that when running
  $\NonCrossingVertSimp(K)$
  on $K = \Del{P,\alpha}$, we have the loop invariant:
  \begin{equation*}
    \label{eq:loop-invariant}
    \DelC P \subseteq K \subseteq \Del{P,\alpha}.
  \end{equation*}
  This is true before beginning the while-loop thanks to the previous
  step. We only need to prove that during an execution of the
  while-loop, one cannot remove $(d-1)$-simplices of $\DelC P$. We
  examine in turn each of the two possibilities that may occur:

  \smallskip \styleitem{(a)} $G_\M(K)$ has a sink $\sigma$ whose
  circumcenter $Z(\sigma)$ lies above \M and
  $
  \bigcap \Above \sigma
  $
  is collapsed in $K$. In that case, the set of $(d-1)$-simplices of
  $K$ that disappear are exactly the upper facets of $\sigma$. Each
  upper facet $\gamma$ of $\sigma$ is dual to some Voronoi edge
  $V(\gamma,P)$. Let
  \begin{equation}
    \label{eq:restricted-Voronoi-edge}
      \gamma^* = V(\gamma,P) \cap \Offset P \alpha = V(\gamma, P) \cap
  \bigcap_{p \in \gamma} B(p,\alpha).
  \end{equation}
  $\gamma^*$ is a segment with one endpoint at $Z(\sigma)$. By
  Lemma~\ref{lemma:height-is-increasing}, the map $x \mapsto \alt{x}$
  is increasing along the segment $\gamma^*$ as we move $x$ on
  $\gamma^*$ from $Z(\sigma)$ to the other endpoint. Since $\alt{x}>0$
  for all $x \in \gamma^*$, we deduce that $\gamma^*$ does not
  intersect \M. Since $V(\gamma,P) \setminus \gamma^*$ lies outside
  $\Offset P \alpha$ and $\M \subseteq \Offset P \alpha$, we deduce
  that $V(\gamma,P) \cap \M = \emptyset$ and $\gamma \not \in \DelC
  P$.

  \smallskip \styleitem{(b)}  $G_\M(K)$ has a source $\sigma$ whose
  circumcenter $Z(\sigma)$ lies below \M and
  $
  \bigcap \Below \sigma
  $
  is collapsed in $K$. Similarly, we can show that none of the
  $(d-1)$-simplices that disappear from $K$ during the collapse of
  $\tau$ in $K$ belong to $\DelC P$.

  \Step{4} We show that as we run
   $\NonCrossingVertSimp(K)$
  on $K = \Del{P,\alpha}$, when
  the algorithm terminates, then $K = \DelC P$. For this, we are going
  to prove that during the course of the algorithm, all
  $(d-1)$-simplices $\gamma \in \Del{P,\alpha} \setminus \DelC P$
  disappear at some point.  Consider a $(d-1)$-simplex $\gamma \in
  \Del{P,\alpha} \setminus \DelC P$ and define again $\gamma^*$ as in
  \eqref{eq:restricted-Voronoi-edge}:
  \begin{equation*}
    \label{eq:restricted-Voronoi-edge}
      \gamma^* = V(\gamma,P) \cap \Offset P \alpha = V(\gamma, P) \cap
  \bigcap_{p \in \gamma} B(p,\alpha).
  \end{equation*}
  Note that $\gamma^*$ is connected. Since $\gamma^*$ does not
  intersect \M and is connected, either $\gamma^*$ lies above \M or
  $\gamma^*$ lies below \M. We are going to charge any $(d-1)$-simplex
  $\gamma \in \Del{P,\alpha} \setminus \DelC P$ to a $d$-simplex
  $\sigma \in \Del{P,\alpha}$, considering  two cases:

  \smallskip \styleitem{(a)} Suppose that $\gamma^*$ lies above \M. We
  claim that, in that case, there is a $d$-simplex $\sigma \in
  \Del{P,\alpha}$ such that $\sigma \below \gamma$ with $Z(\sigma)$
  above \M.  Suppose for a contradiction that this is not true and
  $\gamma$ has no $d$-simplex of $\Del{P,\alpha}$ below it
  relative to \M. Then, Lemma~\ref{lemma:connecting-boundaries}
  implies that $\gamma$ belongs to a lower join of the form $c * \Conv
  \gamma$ with $c \in \gamma^*$ lying on the lower skin of $\Offset P
  \alpha$. Since the lower skin of $\Offset P \alpha$ lies below \M,
  we thus get that $c \in \gamma^*$ lies below \M, yielding a
  contradiction. In that case, we charge $\gamma$ to $\sigma$.

  \smallskip \styleitem{(b)} Suppose that $\gamma^*$ lies below
  \M. Similarly, one can show that there is a $d$-simplex $\sigma \in
  \Del{P,\alpha}$ such that $\gamma \above \sigma$ with
  $Z(\sigma)$ lying below \M. In that case, we charge $\gamma$ to
  $\sigma$.

  \smallskip
  At the end of Algorithm~\ref{algo:non-crossing-simplification}, every
  $d$-simplex $\sigma$ of $\Del{P,\alpha}$ has been removed at some
  point. The charging is done in such a way that, when the $d$-simplex
  $\sigma$ is removed from $K$, so are all $(d-1)$-simplices charged
  to it.  Hence, when Algorithm~\ref{algo:non-crossing-simplification}
  terminates, $K$ does not contain any $(d-1)$-simplices of
  $\Del{P,\alpha} \setminus \DelC P$ and therefore $K = \DelC P$.

  \medskip

  To summarize, Step~1 guarantees that $\NonCrossingSquash(P,\alpha)$
  corresponds to one particular execution of
  $\NaiveSquash(P,\alpha)$. Applying
  Theorem~\ref{theorem:alpha-complex}, we obtain that it returns a
  triangulation of \M, which, by Step~4, is $\DelC P$.
\end{proof}


\begin{lemma}
  \label{lemma:3D-crossing-Delaunay}
  Let $\M$ be a $C^2$ surface in $\Rspace^3$ whose reach is at least
  $\reach>0$. Let $P$ be a finite point set such that $P \subseteq \M
  \subseteq \Offset P \varepsilon$ for $\frac{\varepsilon}{\reach}
  \leq 0.225$.  Assuming no Voronoi vertices of $P$ lie on \M,
  $\DelC{P}$ is a triangulation of \M.
\end{lemma}


\begin{proof}
  Let $\varepsilon \in [0, 0.225\reach]$ and note that it is always
  possible to choose $\alpha \geq 0$ such that the pair
  $(\frac{\varepsilon}{\reach},\frac{\alpha}{\reach})$ belongs to the
  region depicted in Figure~\ref{fig:sampling-condition-3D-left} or
  equivalently such that $\varepsilon,\alpha \geq 0$ satisfy
  \itemref{item:naive-3D-sampling} in Lemma \ref{corollary:3D-theory}.
  Let $\delta=0$ and $\beta = \beta_{\varepsilon,\alpha}$. By Lemma
  \ref{lemma:3D-conditions}, the assumptions of Theorem
  \ref{theorem:alpha-complex} are satisfied.  It is thus possible to
  apply Lemma \ref{lemma:crossing-Delaunay} and deduce that $\DelC{P}$
  is a triangulation of \M.
\end{proof}


\subsection{A pure 2-dimensional simplicial complex when $d=3$}
\label{appendix:pure-simplicial-complex}

In this section, we establish conditions under which the restricted
Delaunay complex is a pure 2-dimensional complex, when $\M$ is a
smooth surface in $\Rspace^3$.

\begin{lemma}
  \label{lemma:WhenRestrictedDelaunayIsPure2D}
  Let $\M$ be a $C^2$ surface in $\Rspace^3$ whose reach is at least
  $\reach>0$. Let $P$ be a finite point set such that $P \subseteq \M
  \subseteq \Offset P \varepsilon$ for $\varepsilon \geq 0$. Let us make
  the generic assumption that all Voronoi cells of $P$ intersect \M
  transversally\footnote{We recall that two smooth submanifolds of
  $\Rspace^d$ intersect transversally if at every intersection point,
  the tangent spaces of the two submanifolds span $\Rspace^d$.}. For
  all $\varepsilon < \reach$ that satisfy
  \[
  2  \arcsin \frac{\varepsilon}{2\reach} +   \arcsin \frac{\varepsilon}{\reach} < \frac{\pi}{2}
  \]
  or, equivalently, for all $\frac{\varepsilon}{\reach} \leq 0.732\ldots$,
  $\DelR{P}$ is a pure 2-dimensional simplicial complex.
\end{lemma}

Before giving the proof, we start with some remarks.  Define the
restricted Voronoi region of $q \in P$ as the intersection of the
Voronoi region of $q$ with \M:
\[
V_\M(q,P) = V(q,P) \cap \M = \{ x \in \M \mid \|x-q\| \leq \|x-p\|,
\text{ for all $p \in P$} \}.
\]

\begin{remark}
  $\DelR{P}$ is the nerve of the collection of restricted Voronoi
  regions,
  \[
  \DelR{P} = \Nerve{\{ V_\M(q,P) \}_{q \in P}}.
  \]
\end{remark}

\begin{remark}
  \label{remark:restricted-region-small}
  If $\M \subseteq \Offset P \varepsilon$, then $V_\M(p,P) \subseteq B(p,\varepsilon)$ for all $p \in P$.
\end{remark}

\begin{proof}[Proof of Lemma \ref{lemma:WhenRestrictedDelaunayIsPure2D}]
Our generic assumption implies that no Voronoi vertices of $P$ lie on
\M and therefore $\DelR{P}$ has dimension 2 or less.

\begin{figure}[htb]
  \centering
  \def\svgwidth{.49\textwidth}
  \input{Figures/proof-pure-vertices-left.pdf_tex} \hfill
    \def\svgwidth{.49\textwidth}
  \input{Figures/proof-pure-vertices-right.pdf_tex}
    \caption{ If the restricted Delaunay complex $\DelR{P}$ has one
      vertex $p$ with no coface (left), then the connected component $\M_p$ of $\M$ passing through $p$ is contained in
      the (yellow) Voronoi region $V(p,P)$ (right).
      \label{figure:proof-pure-vertices}
    }
\end{figure}

Let us show that any vertex in $\DelR{P}$ has at least one edge as a
coface. Suppose for a contradiction that $\DelR{P}$ contains a vertex
$p \in P$ with no proper coface. Consider the connected component of
\M that passes through $p$ and denote it as $\M_p$. Because $\M_p$
passes through $p \in V(p,P)$ and does not intersect the boundary
of $V(p,P)$, we obtain that $\M_p \subseteq V(p,P)$; see Figure \ref{figure:proof-pure-vertices}. By
Remark~\ref{remark:restricted-region-small}, $V_\M(p,P) \subseteq
B(p,\varepsilon)$ and therefore
\[
\M_p \subseteq \M \cap B(p,\varepsilon).
\]
$\M_p$ being a surface without boundary, it cannot be contractible and
neither can be $\M \cap B(p,\varepsilon)$ which is a surface (possibly
with boundary) that contains $\M_p$. But, this contradicts Lemma~6 in
\cite{Dominique_Andre:2015:collapse_cech_into_triangulation} which
states that $\M \cap B(p,\varepsilon)$ is contractible, being the
non-empty intersection of a set $\M$ with a ball whose radius
$\varepsilon$ is smaller than the reach of \M.

We now focus on the non-trivial part of the proof, showing that any
edge in $\DelR{P}$ has at least one triangle as a coface. Suppose for a
contradiction that $\DelR{P}$ contains an edge $pq$ with no proper
coface. Consider the restricted Voronoi cell of $pq$:
\[
V_\M(pq,P) = V_\M(p,P) \cap V_\M(q,P) = V(pq,P) \cap \M.
\]
Recall that the Voronoi cell $V(pq,P)$ is contained in the bisector
$\Pi_{pq}$ of $p$ and $q$ and that its relative boundary is defined as
its boundary within the hyperplane $\Pi_{pq}$. We note that $pq$ is an
edge of $\DelR{P}$ with no proper coface if and only if $\M$
intersects $V(pq,P)$ and does not intersect the relative boundary of
$V(pq,P)$.

Our generic assumption implies that $\M$ intersects $V(pq,P)$ in a
smooth curve (precisely, a $1$-dimensional $C^1$ submanifold).
Thanks to Remark \ref{remark:restricted-region-small}, the curve is
contained in $B(p,\varepsilon) \cap B(q,\varepsilon)$ and therefore is
bounded.  On the other hand, the curve does not intersect the relative
boundary of $V(pq,P)$. Thus, the curve consists of one or several
loops, {\em i.e. topological circles}.  Let us choose one of these
loops which, by Jordan Theorem, is the boundary of some closed
topological disk $D$ within $\Pi_{pq}$; see Figure
\ref{figure:proof-pure-edges-3D}.  Note that
\begin{equation}
  \label{eq:D-bounded}
    D \subseteq B(p, \varepsilon) \cap B(q,\varepsilon) \cap \Pi_{pq}.  
\end{equation}



\begin{figure}[htb]
  \centering
  \input{Figures/proof-pure-edges-3D.pdf_tex}
    \caption{ If $pq$ is an edge of $\DelR{P}$ with no proper coface,
      then $\M$ intersects the (yellow) Voronoi cell $V(pq,\M)$ in one
      or several loops (in bold). A key step in the proof of Lemma
      \ref{lemma:WhenRestrictedDelaunayIsPure2D} consists in showing
      that $y$ belongs to the dome (in dashed green) of
      $B(p,\varepsilon)$ above $\Pi_{pq}$.
      \label{figure:proof-pure-edges-3D}
    }
\end{figure}


By compactness, there exist a point $x \in D$ that maximizes $d(x,\M)$
and a point $y \in \M$ such that $\|x - y\| = d(x,\M)$. Furthermore,
we have
\begin{equation}\label{eq:TgtParallelToPIpq}
\angle(\Tangent y \M, \Pi_{pq}) = 0,
\end{equation}
as illustrated in Figure~\ref{figure:proof-pure-edges-3D}. Without loss of generality, we may rename
$p$ and $q$ so that $p$ and $y$ both lie on the same side of $\Pi_{pq}$;
see Figure~\ref{figure:proof-pure-edges-3D}.

We claim that $y\in B(p, \varepsilon)$.  If $y=x$, the claim is
trivial since $x \in D \subseteq B(p, \varepsilon) \cap \Pi_{pq}$. If
$y \neq x$, consider the half-line with origin at $y$ and passing
through $x$. Let $z$ be the point on this half-line whose distance to
$y$ is $\reach$; see Figure \ref{fig:EdgePQContradicts}.
By construction, the sphere centered at $z$ with radius $\reach$ is
tangent to \M at $y$. Since the reach of $\M$ is at least $\reach$,
the open ball $B^\circ(z,\reach)$ does not intersect $\M$. In
particular, it does not intersect the relative boundary of $D$ which,
by construction, is contained in \M. Hence, on one hand, $x$ belongs
to both the open disk $B^\circ(z,\reach) \cap \Pi_{pq}$ and the
topological disk $D$. On the other hand, the open disk
$B^\circ(z,\reach) \cap \Pi_{pq}$ does not meet the relative boundary
of $D$. The only possibility is that $B^\circ(z,\reach) \cap \Pi_{pq}
\subseteq D$. Combining this inclusion with the inclusion in
\eqref{eq:D-bounded}, we get that
\[
 B^\circ(z,\reach) \cap \Pi_{pq} \subseteq B(p, \varepsilon) \cap \Pi_{pq}.
\]
Denote by $\Pi_{pq}^+$ the half-space whose boundary is $\Pi_{pq}$ and
which contains $p$ (and therefore $y$). Next, we show that the above
inclusion still holds when replacing $\Pi_{pq}$ with $\Pi_{pq}^+$. In
the context of the proof of the claim, for any ball $B$ (either closed
or open), let us call the restriction of $B$ to $\Pi_{pq}^+$ the {\em
  dome} of $B$ above $\Pi_{pq}$. Because $\| x-y\| = d(x,\M) \leq \|
x-p\| \leq \varepsilon < \reach$, the dome of $B^\circ(z,\reach)$
above $\Pi_{pq}$ is less than half the ball
$B^\circ(z,\reach)$. Because $\varepsilon < \reach$, the dome of $B(p,
\varepsilon)$ above $\Pi_{pq}$ must contain the dome of
$B^\circ(z,\reach)$ above $\Pi_{pq}$:
\[
 B^\circ(z,\reach) \cap \Pi_{pq}^+ \subseteq B(p, \varepsilon) \cap \Pi_{pq}^+.
\]
Since $y$ lies on the boundary of the dome on the left side, it also
belongs to the dome on the right side.  This establishes our claim
that $y \in B(p,\varepsilon)$.



\begin{figure}[htb]
  \centering
  \scalebox{0.85}{\input{Figures/proof-pure-edges-contradiction.pdf_tex}}
  \caption{Notation for the proof of the claim in Lemma
    \ref{lemma:WhenRestrictedDelaunayIsPure2D}.  Note that, although
    the proof assumes $\varepsilon < \reach$, the ball
    $B(p,\varepsilon)$ is depicted as significantly larger than
    $B(z,\reach)$, which might be misleading.
	This is because the assumptions made within the proof are designed to lead to a contradiction, making the situation impossible to depict while satisfying all of those assumptions.
}
  \label{fig:EdgePQContradicts}
\end{figure}



We are now ready to reach a
contradiction.  By \cite[Corollary 3]{boissonnat2019reach}:
 \begin{equation}\label{eq:AngleTgtpy}
\angle (\Tangent y \M, \Tangent p \M) \leq 2  \arcsin \frac{\varepsilon}{2\reach}.
\end{equation}
Since $x\in B(p, \varepsilon) \cap B(q, \varepsilon) \neq \emptyset$,
we get that $||p-q|| \leq 2 \varepsilon$ and by Lemma
\ref{lemma:angleBetweenEdgeAndTangentPlane},
\begin{equation}\label{eq:AngleTgtpq}
\angle (q-p , \, \Tangent p \M) \leq \arcsin
\frac{\varepsilon}{\reach}.
\end{equation}
Since $q-p$ is orthogonal to $\Pi_{pq}$, we get that
\eqref{eq:TgtParallelToPIpq} is equivalent to $\angle (q-p, \,
\Tangent y \M) = \frac{\pi}{2}$.  This with \eqref{eq:AngleTgtpy} and
\eqref{eq:AngleTgtpq} gives:
\begin{equation*}
2  \arcsin \frac{\varepsilon}{2\reach} +   \arcsin \frac{\varepsilon}{\reach} \geq \frac{\pi}{2}.
\end{equation*}
But, this contradicts our assumption that
\[
2  \arcsin \frac{\varepsilon}{2R} +   \arcsin \frac{\varepsilon}{R} < \frac{\pi}{2}.
\]  
Hence, the assumed situation cannot occur. In other words, if an edge
belongs to $\DelR{P}$, it must have at least one triangle as a
coface.
\end{proof}

