\begin{definition}[Two-layer hierarchical game $\mathcal{G}^H$ integrated with $\mathcal{G}^{Up}_{t}$ and $\mathcal{G}^{Low}_t$]
	Formally, $\mathcal{G}^H$ can be defined as
	\begin{equation}
		\begin{aligned}
			 \mathcal G^{H} = \big \langle G^H, \{\mathcal{G}^{Up}_{t}, \Pi^{Up}_t\}_{\forall t}, \{\mathcal{G}^{Low}_t, \Pi^{Low}_{t}\}_{\forall t}, \mathcal{U}_{CS},\mathcal{U}_{\mathcal{B}} \big \rangle, \label{GHdef1}
		\end{aligned}
	\end{equation}
	where $G^H = CS \cup \mathcal{B}$ represents the set of participants in $\mathcal{G}^H$, i.e., the cloud $CS$ and all ESs $\mathcal{B}$;
	$\mathcal{G}^{Up}_{t}$ stands for the upper-layer subgame in each time frame $t$, with $\Pi^{Up}_t$ being the corresponding strategy, and $\mathcal{G}^{Low}_t$ is the lower-layer subgame in each time frame $t$, with $\Pi^{Low}_{t}$ being the corresponding strategy; $\mathcal{U}_{CS}=\{U_{CS}(t)\}_{\forall t}$ and $\mathcal{U}_{\mathcal{B}}=\{U_{b}(t)\}_{\forall b,t}$ include the utilities of the cloud and ESs in all time frames, respectively.
\end{definition}

%x_{c,b}(t)取决于什么，因此存在什么关系
\begin{definition}[Upper-layer subgame: two-sided matching game $\mathcal{G}^{Up}_{t}$] For solving $[\mathcal{P}_2]$ in each time frame $t$, the decision on partial-DT assignments $x_{c,b}(t), \forall c \in \mathcal{C}, \forall b \in \mathcal{B}$, can actually be viewed as a bidirectional matching between partial-DTs in $\mathcal{C}$ and ESs in $\mathcal{B}$, such that each partial-DT has different preferences for being created on different ESs and vice versa \cite{GS0}. Hence, $\mathcal{G}^{Up}_{t}$ can be defined as
\begin{equation}
	\begin{aligned}
		\hspace{-1.5mm} \mathcal{G}^{U\hspace{-0.2mm}p}_{t} \hspace{-0.5mm} = \hspace{-0.5mm} \big \langle \hspace{-0.5mm} G^{U\hspace{-0.2mm}p}\hspace{-0.5mm}, \Pi^{U\hspace{-0.2mm}p}_t\hspace{-0.5mm}=\hspace{-0.5mm}\{\varPhi_t(i)\}_{\forall i\in G^{U\hspace{-0.2mm}p}}, \textbf{p}, U_{CS}(t),\{U_{b}(t)\}_{\forall b}\big \rangle,\label{GMdef}
	\end{aligned}
\end{equation}
where $G^{U\hspace{-0.2mm}p} = \mathcal{C} \cup \mathcal{B}$ denotes all partial-DTs and ESs involved in $\mathcal{G}^{U\hspace{-0.2mm}p}_{t}$; $\textbf{p}=\{\textbf{p}_c(t)=\{\{p^{c,b}\}_{\forall b}\},\textbf{p}_b(t)=\{p^{b,c}\}_{\forall b}\}_{\forall c,b}$ are the sets of all partial-DTs' and ESs' preference lists in time frame $t$, respectively, with $p^{c,b}, p^{b,c}\in [0,1]$ being the ranking value; $\varPhi_t(i), \forall i\in G^{U\hspace{-0.2mm}p}$ is the bidirectional matching between $\mathcal{C}$ and $\mathcal{B}$ in each time frame $t$, i.e.,
\begin{equation}
	\begin{aligned}
		\varPhi_t(c) = &~ b \Leftrightarrow \varPhi_t(b) = c, \text{if and only if } x_{c,b}(t) = 1, \\
		&\forall c \in \mathcal{C}, \forall b \in \mathcal{B}.
	\end{aligned}
\end{equation}
\end{definition}



%y_{b,n}(t)取决于什么，存在什么关系
\begin{definition}[Lower-layer subgame: overlapping coalition formation game $\mathcal{G}^{Low}_t$] For solving $[\mathcal{P}_3]$ in each time frame $t$, the decisions on ES-sensor associations $y_{b,n}(t)$ and resource allocations $z_{b,n,w}(t), T_b(t)$ can actually be viewed as an overlapping coalition formation among sensors and ESs. Specifically, all sensors are grouped into multiple overlapping coalitions, each of which associated with one ES, and each ES determines $z_{b,n,w}(t), T_b(t)$ based on the state of all coalitions. Sensors may strategically adjust their coalitions based on $z_{b,n,w}(t), T_b(t)$, and this process is conducted in an iterative manner till the convergence.
%	In $\mathcal G^{Low}_{t}$, the strategy of sensor association $y_{b,n}(t)$ can be viewed as an overlapping coalition formation among all sensors, under the resource allocation $z_{b,n,w}(t), T_b(t)$ of all ESs.
%	The sensor association $y_{b,n}(t)$ inherently divides all sensors into multiple overlapping groups for each ES, which not only vary with time, but are also interdependent since extra cost (i.e., $C^{Conf}$ in $\mathcal{U}_{Sys}$) will occur when these groups change. 
%	Therefore, $y_{b,n}(t)$ can be viewed as a nature overlapping coalition formation process from the perspective of all sensors, where each group of sensors associated with the same ES refers to one overlapping coalition \cite{OCFG0, OCFG1}.
Hence, we define $\mathcal{G}^{Low}_t$ as
\begin{equation}
	\begin{aligned}
		\mathcal G^{Low}_{t}=&\big \langle G^{Low},\Delta, \Pi^{Low}_{t}  = \big\{\mathcal{CP}(t), \{\pi^R_b(t)\}_{\forall b}\big\},\\
		& \{U_{b}^{t}(Co_b)\}_{\forall b}, \{U_{n}(t)\}_{\forall n} \big \rangle,\label{GOdef}
	\end{aligned}
\end{equation}
where $G^{Low} = \mathcal{N} \cup \mathcal{B}$ denotes all sensors and ESs involved in $\mathcal{G}^{Low}_t$; $\Delta$ stands for the set of possible overlapping coalitions;  $\mathcal{CP}(t)=\{Co_b(t)\}_{\forall b \in \mathcal{B}}$ represents the coalition partition in time frame $t$, with $Co_b(t) = \{n \big| y_{b,n}(t)=1, \forall n \in \mathcal{N} \}$ being the coalition for ES $b \in \mathcal{B}$; $\pi^R_b(t) = \{z_{b,n,w}(t),T_b(t)\}_{\forall n,w}$ is the resource allocation strategy of ES $b\in\mathcal{B}$ in time frame $t$; 
$U_{b}^{t}(Co_b) = U_b(t), \text{if } Co_b = Co_b(t)$, shows the utility of ES $b\in\mathcal{B}$ in time frame $t$ given that its associated sensor coalition is $Co_b$, $U_{n}(t)=\sum\nolimits_{b \in \mathcal{B}}y_{b,n}(t)U^{Co_b}_{n}(t)$ can be seen as the coalitional utility of sensor $n\in \mathcal{N}$ in time frame $t$, with $U^{Co_b}_{n}(t)$ being the contribution of sensor $n$ to coalition $Co_b(t)$, calculated as the difference between the utility of ES $b$ with and without sensor $n$ in its associated coalition $Co_b$, i.e.,
\begin{align}
	\hspace{-0.8mm}&U^{Co_b}_{n}(t) = U^t_b(Co_b) - U^t_b(Co_b/n)  \notag\\
	\hspace{-0.8mm}&=x_{c,b}(t)\xi I_c(t) 
	\big [\varGamma \big (\hspace{-0.5mm}\sum\nolimits_{i=1}^t \hspace{-0.8mm}d_c(i) \hspace{-0.5mm} \big )\hspace{-0.5mm} \big (\hspace{-0.5mm} 1 \hspace{-0.5mm}-\hspace{-0.5mm} 2^{\left( T_b(t)(L\delta-2)\delta \gamma \right)/2} \big )  \notag\\
	\hspace{-0.8mm}&~~~~\hspace{-0.5mm}-\hspace{-0.5mm}\varGamma \big (\hspace{-0.5mm}\sum\nolimits_{i=1}^t d_c(i) \hspace{-0.5mm}-\hspace{-0.5mm} d_{n,c}(t) \hspace{-0.5mm}\big )\hspace{-0.5mm} \big (\hspace{-0.5mm} 1 \hspace{-0.5mm}-\hspace{-0.5mm} 2^{\frac{\hspace{-0.1mm}T_b\hspace{-0.1mm}(t)\hspace{-0.1mm}T^*_{b\hspace{-0.1mm}/\hspace{-0.1mm}n}\hspace{-0.1mm}(t)(\hspace{-0.1mm}L\delta \hspace{-0.1mm}-\hspace{-0.1mm}2)\delta \gamma}{2T^*_{b}(t)} }\hspace{-0.5mm} \big ) \big ]  \notag\\
	\hspace{-0.8mm}&~~~~\hspace{-0.5mm}-\hspace{-0.5mm}\kappa \big[\rho_b(F_b)^2\Upsilon_b \big (T_b(t)-{T_b(t)T^*_{b/n}(t)}/{T^*_{b}(t)} \big )  \notag\\
	\hspace{-1.0mm}&~~~~+ P_n x_{c,b}(t) d_{n,c}(t) \big / {R^T_{n,b}(t)}\big] \hspace{-0.5mm}-\hspace{-0.5mm} {C^{Conf}\mathcal{F}_b(t)}/{|\mathcal{B}|}. \label{UCobnt}
\end{align}
\end{definition}

