\begin{definition}[Equilibrium of the upper-layer subgame $\mathcal{G}^{Up}_{t}$]\label{Stable_Matching}
	Given the equilibrium $\Pi^{Low*}_{t}$ of lower-layer subgame $\mathcal{G}^{Low}_{t}$, in $\mathcal{G}^{Up}_t$, the equilibrium $\Pi^{Up*}_t$ is defined as a stable matching $\{\varPhi^{*}_t(i)\}_{\forall i\in G^{U\hspace{-0.2mm}p}}$, which satisfies the condition that no blocking pair $(c, b)$ exists for any partial-DT $c \in \mathcal{C}$ and ES $b \in \mathcal{B}$. Particularly, a pair $(c, b)$ is blocking if both conditions $p^{c,b} > p^{c,\varPhi_t(c)}$ and $p^{b,c} > p^{b,\varPhi_t(b)}$ hold simultaneously, where $\varPhi_t(c)$ and $\varPhi_t(b)$ represent the current matched partners of $c$ and $b$ in time frame $t$, respectively. \end{definition}

\begin{definition}[Equilibrium of the lower-layer subgame $\mathcal G^{Low}_{t}$] \label{SOCP}
	In $\mathcal G^{Low}_{t}$, the equilibrium $\Pi^{Low*}_{t}$ is defined as the best response $\big (\mathcal{CP}^*(t), \{\pi^{R*}_b\}_{\forall b}\big )$, satisfying
	\begin{equation}
		\begin{aligned}
			&U_{b}(t)|\mathcal{CP}^*(t), \{\pi^{R*}_b(t)\}_{\forall b} \geq   \\
			&U_{b}(t)|\mathcal{CP}(t), \{\pi^{R*}_b(t)\}_{\forall b}, \text{ and}\\
			&U_{b}(t)|\{\pi^{R*}_b(t)\}_{\forall b}, \mathcal{CP}^*(t) \geq   \\
			&U_{b}(t)|\pi^{R}_b(t),\{\pi^{R*}_{b'}(t)\}_{\forall b' \neq b}, \mathcal{CP}^*(t), ~\forall b \in \mathcal{B}, \label{GLowE}
		\end{aligned}
	\end{equation}
	where $\mathcal{CP}^*(t)=\{Co^*_b(t)\}_{\forall b \in \mathcal{B}}$ represents the stable overlapping coalition partition of all sensors in time frame $t$. Here, we say the overlapping coalition partition $\mathcal{CP}^*(t)$ is stable if and only if the total utility of all ESs cannot be improved by unilaterally altering the coalition of any sensor even in an overlapped manner.
\end{definition}


