\begin{definition}[Overlapping coalition switch rules]
	Let $Co_a, Co_b \in \Delta$ respectively denote sensor coalitions associated to any two ESs $a, b\in \mathcal{B}$ and $a\neq b$ in $\mathcal{G}^{Low}_t$, a sensor $n \in Co_a$ while $n \notin Co_b$ can be determined to change its coalition in an overlapped manner by i) transferring from $Co_a$ to $Co_b$, denoted as $\mathcal{T}_n(Co_a, Co_b)$, ii) joining $Co_b$ as an overlap, denoted as $\mathcal{J}_n(Co_b)$, and iii) unilaterally quitting $Co_a$, denoted as $\mathcal{Q}_n(Co_a)$, of which their respective conditions are as follows:

	\textbf{\textit{1) Transferring rule:}}
	$\mathcal{T}_n(Co_a, Co_b)$ is performed only when i) the remaining subcarriers of ES $b$ is sufficient, i.e., (\ref{PCB8}) holds, making it feasible; ii) the utility of $n$ can be increased, i.e., $U^{Co_b \cup n}_{n}(t) \geq \max\{0, U^{Co_a}_{n}(t) \}$; iii) the utility of all sensors except $n$ in $Co_b$ cannot be decreased, i.e., $U^{Co_b \cup n}_{\bar{n}}(t) \geq U^{Co_b}_{\bar{n}}(t), \forall \bar{n} \in Co_b$; and iv) the utility of all sensors in other coalitions that $n$ joins as an overlap cannot be decreased, i.e.,
	\begin{equation}
		\begin{aligned}
			&U^{Co_e}_{\bar{n}}(t) ~\Big |~ \mathcal{CP}(t)=\{Co_a/i, Co_b\cup n, Co_{-a,b}\} \geq  \\ 
			&U^{Co_e}_{\bar{n}}(t) ~\Big |~ \mathcal{CP}(t)=\{Co_a, Co_b, Co_{-a,b}\}, \\
			&\forall \bar{n} \in Co_e, \forall Co_e \in Co_{-a,b}, x_{e,n}=1, \label{TO4}
		\end{aligned}
	\end{equation}
	where $Co_{-a,b}$ stands for all coalitions in $\mathcal{CP}(t)$ other than $Co_a$ and $Co_b$.

	\textbf{\textit{2) Joining rule:}}
	$\mathcal{J}_n(Co_b)$ is performed only when i) resource constraints (\ref{sensorassociation}) and (\ref{PCB8}) are satisfied, making it feasible; ii) the utility of $n$ can be increased, i.e., $U^{Co_b \cup n}_{n}(t) \geq 0$; iii) the utility of all sensors except $n$ in $Co_b$ cannot be decreased, i.e., $U^{Co_b \cup n}_{\bar{n}}(t) \geq U^{Co_b}_{\bar{n}}(t), \forall \bar{n} \in Co_b$; and iv) the utility of all sensors in other coalitions that $n$ joins as an overlap cannot be decreased, i.e.,
	\begin{equation}
		\begin{aligned}
			&U^{Co_e}_{\bar{n}}(t) \Big | \mathcal{CP}(t)=\{Co_b\cup n, Co_{-b}\} \geq \\ 
			&U^{Co_e}_{\bar{n}}(t) \Big | \mathcal{CP}(t)=\{Co_b, Co_{-b}\}, \\
			&\forall \bar{n} \in Co_e, \forall Co_e \in Co_{-b}, x_{e,n}=1. \label{JO5}
		\end{aligned}
	\end{equation}

	\textbf{\textit{3) Quitting rule:}}
	$\mathcal{Q}_n(Co_a)$ is performed only when i) the utility of $n$ can be increased, i.e., $U^{Co_a}_{n}(t) \leq 0$; ii) the utility of all sensors except $n$ in $Co_a$ cannot be decreased, i.e., $U^{Co_a / n}_{\bar{n}}(t) \geq U^{Co_a}_{\bar{n}}(t), \forall \bar{n} \in Co_a$.
\end{definition}

