\begin{algorithm}[t!]
	\footnotesize
	\caption{SOCF Algorithm for $\mathcal{CP}^*(t)$} %Switch Operations-Based Overlapping Coalition Formation (SOCF) Algorithm for $\mathcal{G}^{Low}_t$
	\KwIn{Partial-DT assignment $x_{c,b}(t)$, initial decisions on $z_{b,n,w}(t)$ and $T_b(t)$, previous decision on $y_{b,n}(t-1)$;}
	\KwOut{Stable coalition partition $\mathcal{CP}^*(t)$, or equivalently the optimal ES-sensor associations $y^*_{b,n}(t)$;}
	\For{ES $b \in \mathcal{B}$}{
		ES $b$ calculates $\mathbb{N}_b(t)$ according to constraint (\ref{ESaccess})\;
		ES $b$ selects all sensors in $Co_b(t-1)$ and randomly selects at most $\max\{|\mathcal{W}|- |Co_b(t-1)|\}$ sensors in $\mathbb{N}_b(t)$. 
	}
	All ESs generate the initial overlapping coalition partition $\mathcal{CP}(t)$\;
	\While{$\mathcal{CP}(t)$ is different from it in the previous loop}{
		\For{$n \in \mathcal{N}$}{
			\For{$Co_a \in \{Co_x \big | n \in Co_x \}$}{
				\For{$Co_b \notin \{Co_x \big | n \in Co_x \}$}{
					\If{\textit{Transferring rule} is satisfied}{
						$\mathcal{T}_n(Co_a, Co_b)$ is performed\;
					}
					\ElseIf{\textit{Joining rule} is satisfied}{
						$\mathcal{J}_n(Co_a, Co_b)$ is performed\;
					}
					\ElseIf{\textit{Quitting rule} is satisfied}{
						$\mathcal{Q}_n(Co_a)$ is performed\;
					}
				}
			}
			Update $\mathcal{CP}(t)$, all ESs synchronize such information\;
		}
	}
	According to final $\mathcal{CP}(t)$, all ESs update $y_{b,n}(t)$.
\end{algorithm}
