% Defining $\alpha := 1+\gamma^2.n^2L^2-2\gamma\lambda, \beta := P^2\eta^2, \tilde{\alpha} := 1+\eta^2.m^2\tilde{L}^2-2\eta\tilde{\lambda}, \tilde{\beta} := \tilde{P}^2\gamma^2$, and minimizing the RHSs of \Cref{eq:g^2,eq:gt^2} w.r.t.\ $\rho_1$ and $\rho_2$ respectively, we get
% \begin{equation}
%     \label{eq:tighter-bound}
%     \begin{split}
%         \|g(w^{t+1},s^{t+1},\mu^{t+1})\|_2^2 &\leqslant \left(\sqrt{\alpha}\|g(w^t,s^t,\mu^t)\|_2 + \sqrt{\beta}\|\tilde{g}(w^t,s^t)\|_2 \right)^2 \\
%         \|\tilde{g}(w^{t+1},s^{t+1})\|_2^2 &\leqslant \left(\sqrt{\tilde{\alpha}}\|\tilde{g}(w^t,s^t)\|_2 + \sqrt{\tilde{\beta}}\|g(w^t,s^t,\mu^t)\|_2\right)^2
%     \end{split}
% \end{equation}
% which implies
\begin{equation}
    \label{eq:tighter-bound-norm}
    \begin{split}
        \|g(w^{t+1},s^{t+1},\mu^{t+1})\|_2 &\leqslant \sqrt{\alpha}\|g(w^t,s^t,\mu^t)\|_2 + \sqrt{\beta}\|\tilde{g}(w^t,s^t)\|_2 \\
        \|\tilde{g}(w^{t+1},s^{t+1})\|_2 &\leqslant \sqrt{\tilde{\alpha}}\|\tilde{g}(w^t,s^t)\|_2 + \sqrt{\tilde{\beta}}\|g(w^t,s^t,\mu^t)\|_2
    \end{split}
\end{equation}
Adding the inequalities of \Cref{eq:tighter-bound-norm}
\begin{equation}
    \label{eq:contraction}
    \begin{split}
        \lefteqn{\|g(w^{t+1},s^{t+1},\mu^{t+1})\|_2+ \|\tilde{g}(w^{t+1},s^{t+1})\|_2 }\\
        & \leqslant \max\{\sqrt{\alpha} + \sqrt{\tilde{\beta}}, \sqrt{\tilde{\alpha}} + \sqrt{\beta}\}\left(\|g(w^t,s^t,\mu^t)\|_2 + \|\tilde{g}(w^t,s^t)\|_2 \right)
    \end{split}
\end{equation}
To ensure that the above inequality is a contraction, we need to ensure $\sqrt{\alpha} + \sqrt{\tilde{\beta}}, \sqrt{\tilde{\alpha}} + \sqrt{\beta} \in (0,1)$. These imply (i) $0 < \alpha < 1, 0 < \tilde{\alpha} < 1$, (ii) $\sqrt{\tilde{\beta}} < 1, \sqrt{\beta} < 1$, and (iii) $\sqrt{\alpha} + \sqrt{\tilde{\beta}} < 1, \sqrt{\tilde{\alpha}} + \sqrt{\beta} < 1$. 
We can solve for $\gamma$ and $\eta$ from these inequalities and obtain the sufficient conditions when $\lambda>\tilde{P}$ and $\tilde{\lambda}>P$:
\begin{align*}
            \gamma &< \frac{1}{\tilde{P}}, \gamma <\frac{2\lambda}{n^2 L^2}, \text{ and } \gamma < \frac{\lambda - \tilde{P}}{n^2 L^2 - \tilde{P}^2},\\
            \eta &< \frac{1}{P}, \eta < \frac{2\tilde{\lambda}}{m^2 \tilde{L}^2}, \text{ and } \eta < \frac{\tilde{\lambda} - P}{m^2 \tilde{L}^2 - P^2}.
        \end{align*}
Notice that from conditions~\ref{cond:concavity} and \ref{cond:bound-deriv} of \Cref{assump:conv-NE}, we have that $\lambda< L$ and $\tilde{\lambda}<\tilde{L}$. Thus $n^2 L^2-\tilde{P}^2>0$ and $m^2\tilde{L}^2-P^2>0$.
For the $\gamma,\eta$ chosen as above, we find $W_1 = \sqrt{\alpha} + \sqrt{\tilde{\beta}} < 1$ and $W_2 = \sqrt{\tilde{\alpha}} + \sqrt{\beta} < 1$, and hence $W=\max\{W_1,W_2\} < 1$. Therefore,
\begin{align*}
    &\|g(w^{t+1},s^{t+1},\mu^{t+1})\|_2+ \|\tilde{g}(w^{t+1},s^{t+1})\|_2\\
    &\leqslant W\left(\|{g}(w^{t},s^{t},\mu^t)\|_2+\|\tilde{g}(w^{t},s^{t})\|_2\right).
\end{align*}
Recursively iterating over this inequality, we get
\begin{equation*}
    \begin{aligned}
        &\|g(w^{T},s^{T},\mu^T)\|_2+ \|\tilde{g}(w^{T},s^{T})\|_2 \\
        &\leqslant W^T\left(\|{g}(w^{0},s^{0},\mu^0)\|_2+\|\tilde{g}(w^{0},s^{0})\|_2\right).
    \end{aligned}
\end{equation*}
Defining $E=\|g(w^0,s^0,\mu^0)\|_2+\|\tilde{g}(w^0,s^0)\|_2$ and $$T_0(w^0,s^0) = \nicefrac{\left(\ln{\ddfrac{E}{\epsilon}}\right)}{\left(\ln{\ddfrac{1}{W}}\right)},$$
we get that for all $T \geqslant T_0(w^0,s^0)$,
\begin{align*}
    &\|g(w^{T},s^{T},\mu^T)\|_2+ \|\tilde{g}(w^{T},s^{T})\|_2 < \epsilon \\
    \implies & \|g(w^{T},s^{T},\mu^T)\|_2<\epsilon, \text{ and }
    \|\tilde{g}(w^{T},s^{T})\|_2< \epsilon.
\end{align*}
This completes the proof.

