\subsection{Algorithm for \strategic{}}
\label{sec:strategic}
In the \strategic{} algorithm, the agents choose to contribute their data strategically as in \mech{}, and stick to this contribution in the entire training phase of \FedAvg{}.
\strategic{} is formally given by \Cref{algo:fedavgstrategic}.

\begin{algorithm}[t]

\DontPrintSemicolon
\LinesNumbered
\SetStartEndCondition{ }{}{}
% \SetKwFor{For}{for}{:}{}
\caption{\strategic\label{algo:fedavgstrategic}}


\KwIn{Step size $\gamma, \eta$, initialization $w^0$, $s_i^0$ for $i \in N$, number of iterations $T$}
\KwOut{$w^T$}
\textbf{Center} broadcasts $w^0, s^0$, set $t=0$\tcc*[r]{Begin phase 1}
 \While{$\exists i \in N \text{ such that } [g(w^0,s^t,\mu^t)]_i>0$ }{
    \textbf{Center} broadcasts $s^t$\;
    \For{\textbf{agent} $i \in N$ in parallel}{
        Perform local training step and compute $[g(w^0,s^t,\mu^t)]_i$\;
        $s_i^{t+1} = s_i^t + \gamma [g(w^0,s^t,\mu^t)]_i$\;
        Send $s_i^{t+1}$ to the center\;
    }
    $t = t+1$\tcc*[r]{End phase 1}}
% }\;
$s^*=s^t$\;
\For(\tcc*[r]{Begin phase 2}){$t=0$ \textbf{to} $T$}
{
    \textbf{Center} broadcasts $w^t$\;
    \For{\textbf{agent} $i \in N$ in parallel}{
        Compute local gradient: $d_i^{t+1} = \nabla_w \:a_i(w^{t},s_i^{*},s_{-i}^{*})$\;
        Send $d_i^{t+1}$ to the center\;
    }
    \textbf{Center} updates: $w^{t+1} = w^t + \frac{\eta}{n} \sum_{i \in N} d_i^{t+1} = w^t + \eta \tilde{g}(w^t, s^{*})$
}
\Return $w^T$\tcc*[r]{End phase 2}
% \textbf{End phase 2}\;

\end{algorithm}
