@\label{slice:mutex}@@\gplus@ @\textcolor{darkgreen}{ chLock   sync.Mutex}@
}

func (fmr * fmrImpl) Update(...) {
  ...
@\gplus@ @\textcolor{darkgreen}{ fmr.chLock.Lock()}@
  newChan := make(chan struct{})
@\label{slice:append}@  fmr.ch = append(fmr.ch, newChan)
@\gplus@ @\textcolor{darkgreen}{ fmr.chLock.Unlock()}@
  ... // Rest of the code
}
func (fmr * fmrImpl) setSync(idx int32) {
  go func() {
    ...
    select {
      ...
@\rminus@     @\label{slice:read1}\textcolor{red}{case <-fmr.ch[idx]:}@
@\gplus@     @\textcolor{darkgreen}{ case <-func\(\) chan struct\{\} \{}@
@\gplus@        @\textcolor{darkgreen}{ fmr.chLock.Lock()}@
@\gplus@        @\textcolor{darkgreen}{ defer fmr.chLock.Unlock()}@
@\gplus@        @\label{slice:read2}\textcolor{darkgreen}{ return fmr.ch[idx]}@
@\gplus@     @\textcolor{darkgreen}{ \}():}@
      return
    }
  }()
}
