\paragraph{Preliminaries.}% \label{prelim}
For an open set $O \subset \mathbb{R}^2$,  we denote the Sobolev space $W^{m,2}(O)$ by $H^m(O)$  and equip it with the norm $\norm{w}_{H^m(O)}= (\underset{{|i| \le m}}{\sum} \norm{D^iw}_{L^2(O)}^2)^{1/2}$ and semi-norm $| w |^2_{H^m(O)}=(\underset{{|i| = m}}{\sum}\|D^iw \|_{L^2(O)}^2)^{1/2}$. For simplicity, we denote $L^2$ inner product by $(\bullet, \bullet)$ and norm by $\| \bullet \|$. Throughout this paper, $\mathcal{T}$ denotes a shape-regular triangulation of $\Omega$, $H^m({\cal T})$ denotes the Hilbert space $\underset {{K \in {\cal T}}}{\prod}H^m (K)$, and $P_r({\cal T})$, the space of globally $L^2$ functions which are polynomials of degree at most $r$ in each $K$. The notation $\nabla$ (resp. $\nabla^2$)  denotes the   gradient (resp. Hessian). The piecewise energy norm is denoted by $\trinl \bullet \trinr_{\text{pw}}:=|\bullet|_{H^{2}({\cal T})}$ and $D^2_\text{pw}$ (resp. $\Delta_{\rm pw}$) stands for the piecewise Hessian (Laplacian).

Let $X$ be a normed space with norm $\|\bullet\|_X$ and $g:(0,T) \rightarrow X$ be a measurable function. Then for $1 \le p \le \infty$, we recall that  
%\begin{align*}
%\norm{g}^p_{L^p(0,T;X)}=
\[\displaystyle \norm{g}_{L^p(0,T;X)}=\norm{g}^p_{L^p(X)}:=\int_0^T \norm{g(t)}_X^p \dt, \ 1\le p< \infty \quad \text{ and }\quad 
 % \norm{g}_{L^\infty(0,T;X)}=    
\ \norm{g}_{L^\infty(0,T;X)}:=\underset{0 \le t \le T}{\text{ess sup}} \norm{g(t)}_X.\]
%\end{align*}
Let  $L^p(0,T;X):=\left\{g:(0,T) \rightarrow X: \norm{g}_{L^p(X)}<\infty\right\}$. The space {$W^{1,p}(0,T;X)$  consists of all functions  $u \in L^p(0,T;X)$  such that  $u_t$  exists in the weak sense and belongs to  $L^p(0,T;X).$} For all non-negative integers $k$,   $C^k([0,T];X)$ denotes all $C^k$ functions $s :[0,T] \rightarrow X$ with $\norm {s}_{C^k([0,T];X)}=\underset{0 \le i \le k}{\sum} \underset{0 \le t\le T}{\max} {\norm{\frac{\partial^i s}{\partial t^i}}} < \infty$. 

For  real numbers $a > 0$, $b > 0$, and $\epsilon > 0$, we will make repeated use of the {Young's}  inequality $ab \leq \frac{\epsilon}{2}a^2 + \frac{1}{2\epsilon}b^2$. Finally, as usual, the notation $a \lesssim b$ represents $a \le Cb$, where the generic constant $C$ is independent of both mesh-size and time discretization parameter.

\begin{lemma}[Gronwall's Lemma \cite{MR1638130}]\label{P1 gronwall}
Let $g$, $h$, and $r$ be non-negative integrable functions on $[0,T]$ and let $g$ satisfy 
 $\displaystyle g(t) \le h(t)+ \int_0^t r(s) g(s) \ds$  for all $t \in (0,T)$. Then 
\begin{equation*}
  g(t) \le h(t)+ \int_0^t h(s)r(s) e^{\int_s ^{t}{r(\tau )\;\text{d}\tau }}\ds  \quad \text{for all $t \in (0,T)$}.
   \end{equation*}
 \end{lemma}

\section{Well-posedness and regularity results}\label{sec:eq}
In this section, we establish the well-posedness of the problem through the finite Galerkin approach, which follows these steps: (i) construct a sequence of approximate solutions to the continuous problem, (ii) derive a priori bounds on these approximations based on the initial data, (iii) use a compactness argument to show the existence of a limit for a subsequence in the weak topology, and (iv) prove that this limit is the weak solution. After this, we also prove the additional regularity of continuous solution given the extra regularity conditions on given data, which is required in  later sections for  error analysis. 
