+(a_2+|\gamma|\gamma_0)\norm{p^m_t(0)}^2
+\norm{f_{t}}^2_{L^2(0,T;L^2(\Omega))}+\norm{\phi_{t}}^2_{L^2(0,T;L^2(\Omega))}+\norm{g_{t}}^2_{L^2(0,T;L^2(\Omega))}. \label{uttm}
