\begin{align*}
    ( u^{m}_t,u_{tt}^{m},\theta_t^{m},p_t^{m})  &\xrightarrow{\text{weak*}}(u_t,u_{tt},\theta_t,p_t) \quad  \text{in}\ L^\infty\big(0,T;H_0^2(\Omega) 
