\subsection{Additional regularity}\label{sec:reg}
%We now present regularity result needed in the forthcoming analysis. 
The next theorem establishes a priori bounds of the solution and its higher-order time derivatives, provided that the initial and source data are sufficiently smooth. While the specific approach followed here is relatively standard (see, e.g.,  \cite{Rivera} and the references therein), its adaptation to the present model is novel. A summary of the regularity results is displayed in Table~\ref{table:summary}. 




\noindent
\textbf{Regularity estimate.} It is well known  \cite{AGMON,Rannachar} that if $\Phi^* \in H^{-r}(\Omega
)$ (resp. $F^* \in H^{-s}(\Omega
)$) are such that $-\Delta \chi   =\Phi^*$ (resp.   $\Delta^2 w  =F^*$) then 
\begin{align}
 \norm{\chi}_{H^{2-r}(\Omega)} \le C_{\text{reg}}(r) \norm{\Phi^*}_{H^{-r}(\Omega)}\; (\text{ resp.} \norm{w}_{H^{4-s}(\Omega)} \le C_{\text{reg}}(s) \norm{F^*}_{H^{-s}(\Omega)}),\label{ellip-reg}
\end{align}
for all $1-\sigma^1_{\text{reg}} \le r \le 1$ (resp. $2-\sigma^2_{\text{reg}} \le s \le 2$),  where $\sigma_{\text{reg}}^1>0$ (resp. $\sigma_{\text{reg}}^2>0$), is the elliptic  regularity index of the Laplace  (resp. biharmonic) operator, and the constants $C_{\text{reg}}(r)$  (resp. $C_{\text{reg}}(s)$) depend only on $\Omega$ and $s$ (resp. $r$). Lowest-order \ac{fe} schemes typically  achieve at most linear convergence in energy norm, so it is reasonable to assume throughout the paper that $\sigma= \text{min}\{1,\sigma_{\text{reg}}^1,\sigma_{\text{reg}}^2\}$, whence $0 < \sigma \le 1$. Note that if $\Omega$ is a convex polygon, then $\sigma =1$, whereas for non-convex polygons we have $1/2< \sigma < 1$. The elliptic regularity index 
$\sigma$ plays an important role in determining the rate of convergence presented in Section~\ref{sec:fully}. 
 We are now in a position to state the regularity of the weak solution. From the estimates  \eqref{reg-utt}, we can write (also using \eqref{model22}-\eqref{p2;model33}):
\begin{align*}
    % u_{tt}-a_0 \Delta u_{tt}+d_0\Delta^2 u+\beta \Delta p+\alpha \Delta \theta&=f \qquad \qquad  \text{ in }\Omega \times [0,T],\label{p2;model11}\\
   -c_1 \Delta \theta &=\phi - a_1\theta_t+\gamma p_t-b_1\theta+\alpha \Delta u_t:=\Phi^* \in L^2(\Omega),\; \qquad\quad\text{ for all } 0\le t \le T ,\nonumber\\
   -\kappa \Delta p&=g  -a_2 p_t+\gamma \theta_t +\beta \Delta  u_t:=G^* \in L^2(\Omega),\qquad\;\;\quad\qquad\;\text{ for all } 0\le t \le T,\nonumber\\
   d_0\Delta^2 u&= f- u_{tt}+a_0 \Delta u_{tt} -\frac{\alpha}{c_1}\Phi^*-\frac{\beta}{\kappa}G^*:=F^* \in H^{-1}(\Omega),\quad \text{ for all } 0\le t \le T ,
\end{align*}
where in the last equation we have used the fact that $\norm{\nabla u_{tt}} $ is bounded (cf. \eqref{reg-utt}), and hence $a_0 \Delta u_{tt} \in H^{-1}(\Omega)$, whence $F^* \in H^{-1}(\Omega).$ Then we utilize \eqref{ellip-reg} to see that, for all $1/2< \sigma \le 1$, there holds 
\begin{equation}
    u \in L^\infty(0,T;H^{2+\sigma}(\Omega)) \text{ and } \theta , p  \in L^\infty(0,T;H^{1+\sigma}(\Omega)). \label{ell-reg-sol}
\end{equation}
The next theorem guarantees higher regularity of weak solution (needed for the error estimates in   Section~\ref{p2;fully-error-sec}). The proof is based on the arguments used in   \cite[Prop. 2.5.2]{Lasiecka}, and details are postponed to Appendix~\ref{appendix}. 

\begin{thm}[Regularity]\label{thm;regularity}
\begin{itemize}
    \item[(a)]
 Let $f,\phi , g \in H^2(0,T;L^2(\Omega))$
, $u^0,u^{*0}\in H^3(\Omega) \cap H^2_0(\Omega),  \theta^{0}\in H^2(\Omega) \cap H^1_0(\Omega), \text{ and }p^{0}\in H^2(\Omega) \cap H^1_0(\Omega).$
Assume that the compatibility conditions 
\begin{subequations}\label{compat1}
\begin{align}
 & u_{tt}(0)-a_0 \Delta u_{tt}(0)=f(0)-d_0\Delta^2 u^0-\alpha\Delta \theta^0-\beta \Delta p^0,\\
    &  a_1 \theta_{t}(0)  -\gamma p_{t}(0)=\phi(0)-b_1 \theta^0 +c_1 \Delta \theta^0 +\alpha \Delta u^{*0},  \\
   &    a_2  p_{t}(0)-\gamma \theta_{t}(0)=g(0) +\kappa \Delta p^0+\beta \Delta  u^{*0},
\end{align} 
    \end{subequations}
\noindent hold and  $(u_{tt}(0), \theta_t(0) , p_t(0) )$ 
 belongs to $
   (H^2(\Omega) \cap H^1_0(\Omega))^3.$
Then,  
%the solution to \eqref{eq:coupled} satisfies  
\begin{align}
 &\underset{t\in [0,T]}{\rm {ess \;sup}}\big(\norm{u_{t}}^2_{H^{2+\sigma}(\Omega)}+\norm{\theta_{t}}^2_{H^{1+\sigma}(\Omega)}+\norm{p_{t}}^2_{H^{1+\sigma}(\Omega)}+E(u_{tt},\theta_{tt},p_{tt};t)\big)
\text{ is bounded.} \label{reg-uttt}
\end{align}
\item[(b)] Let $f,\phi , g \in  H^3(0,T;L^2(\Omega)$, $u^0,u^{*0}, u_{tt}(0) \in H^3(\Omega) \cap H^2_0(\Omega),  \theta^{0},\theta_t{(0)},p^{0},p_t(0)\in H^2(\Omega) \cap H^1_0(\Omega).$ 
Assume that  the compatibility conditions 
\begin{subequations}\label{compat2}
\begin{align}
 & u_{ttt}(0)-a_0 \Delta u_{ttt}(0)=f_t(0)-d_0\Delta^2 u_t(0)-\alpha\Delta \theta_t(0)-\beta \Delta p_t(0),\\
  &    a_1 \theta_{tt}(0)  -\gamma p_{tt}(0)=\phi_{t}(0)-b_1 \theta_t(0) +c_1 \Delta \theta_t(0) +\alpha \Delta u_{tt}(0),  \\
     & a_2  p_{tt}(0)-\gamma \theta_{tt}(0)=g_t(0) +\kappa \Delta p_t(0)+\beta \Delta  u_{tt}(0).
\end{align}
\end{subequations}
hold and $(u_{ttt}(0), \theta_{tt}(0) , p_{tt}(0) )$ belongs to $
   (H^2(\Omega) \cap H^1_0(\Omega))^3$ . Then, 
   %the solution to \eqref{eq:coupled} satisfies 
\[ \underset{t\in [0,T]}{\rm{ess \; sup}}\big(\norm{u_{tt}}^2_{H^{2+\sigma}(\Omega)}+\norm{\theta_{tt}}^2_{H^{1+\sigma}(\Omega)}+\norm{p_{tt}}^2_{H^{1+\sigma}(\Omega)}+E(u_{ttt},\theta_{ttt},p_{ttt};t)\big)  \text{ is bounded.}
  % \label{reg-utttt}
\]%end{align}
\end{itemize}
\end{thm}

