Let $K \in \mathcal{T}$ be any triangle in the shape-regular triangulation $\mathcal{T}$ of $\bar{\Omega}$. We denote its diameter by $h_K$, its area by $|K|$, and use $\bn_K$ to refer to the outward unit normal vector on $\partial K$. Define $h := \max_{K \in \mathcal{T}} h_K$. The sets of interior and boundary vertices of $\mathcal{T}$ are denoted by $\mathcal{V}(\Omega)$ and $\mathcal{V}(\partial \Omega)$, respectively, with the combined set represented as $\mathcal{V} = \mathcal{V}(\Omega) \cup \mathcal{V}(\partial \Omega)$. Similarly, we use $\mathcal{E}(\Omega)$ and $\mathcal{E}(\partial \Omega)$ for the sets of interior and boundary edges, and write $\mathcal{E} = \mathcal{E}(\Omega) \cup \mathcal{E}(\partial \Omega)$. For any edge $e \in \mathcal{E}$, the corresponding edge patch $\omega(e)$ is defined as $\text{int}(K_+ \cup K_-)$ if $e = \partial K_+ \cap \partial K_- \in \mathcal{E}(\Omega)$, and $\text{int}(K)$ when $e \in \mathcal{E}(\partial \Omega)$. Consider two neighbouring triangles, $K_+$ and $K_-$, with the unit normal vector along $e$ satisfying $\bn_{K_+}|_{e} = \bn|_{e} = -\bn_{K_-}|{_e}$, directed outward from $K_+$ towards $K_-$. The jump of a function $\varphi$, written as $ \big[\!\!\big[\varphi\big]\!\!\big]$, is defined by $  \varphi |_{K_{+}}-  \varphi |_{K_{-}}\text{ if } e=\partial K_+ \cap \partial K_-  \in {\cal E}(\Omega)$ and $\varphi|_e  \text{ if } e \in {\cal E}(\partial \Omega)$.The average $\big\{\!\!\!\big\{\varphi\big\}\!\!\!\big\}$ is defined by $\frac{1}{2} (\varphi |_{K_{+}}+  \varphi|_{K_{-}} )\text{ if } e=\partial K_+ \cap \partial K_-  \in {\cal E}(\Omega)$ and  $\varphi|_e  \text{ if } e \in {\cal E}(\partial \Omega)$.

Let $V_h:=P_2({\cal T}) \cap H^1_0(\Omega) \subset {\mathcal H}^2({\cal T})$ and $W_h:=P_1({\cal T}) \cap H^1_0(\Omega) \subset  H^1_0(\Omega) $ be  finite-dimensional subspaces and define the bilinear form $a_h(\cdot, \cdot):V_h \times V_h \rightarrow \mathbb{R}$ by
\begin{align*}
     a_h(w_h,v_h) &:=\int_\Omega D^2_{{\rm pw}}w_h:D^2_{\rm{pw}}v_h \dx-\sum_{e \in {\cal E}} \int_e \big[\!\!\big[\nabla w_h\big]\!\!\big] \cdot \big\{\!\!\!\big\{D^2_{\rm{pw}}v_h\big\}\!\!\!\big\}{\bn }\ds\\
   &\quad
   -\sum_{e \in {\cal E}} \int_e \big[\!\!\big[\nabla v_h\big]\!\!\big] \cdot \big\{\!\!\!\big\{D^2_{\text{\rm pw}}w_h\big\}\!\!\!\big\}\bn \ds+\sum_{e \in {\cal E}} \frac{\sigma_{\rm{IP}}}{h_e} \int_e  \Big[\!\!\Big[\frac{\partial w_h}{{\partial {\bn}}} \Big]\!\!\Big] \Big[\!\!\Big[\frac{\partial v_h}{{\partial {\bn}}} \Big]\!\!\Big]\ds,
\end{align*}
with respect to a mesh-dependent (broken) norm on $V_h$ defined by 
%t. On a finite-dimensional space $V_h\subset H^2(\mathcal{T})$, we also define
\begin{equation*}
\norm{v_h}_{h}^2:= \norm{D^2_{{\rm pw}}v_h}^2+\sum_{e \in {\cal E}} \frac{\sigma_{\rm{IP}}}{h_e} \int_e  \Big[\!\!\Big[\frac{\partial v_h}{{\partial {\bn}}} \Big]\!\!\Big]^2 \ds, %\label{P1 mesh_norm}
\end{equation*}
where, $D^2_{\rm{pw}}$ is the piecewise Hessian and  the penalty parameter $\sigma_{\rm{IP}}>0$ is chosen sufficiently large \cite{Brener-sung}. 

It is well-known that  $a_h(\bullet ,\bullet)$ is  symmetric, continuous, and elliptic, i.e., there exist $ C_{\rm{Coer}}, C_{\rm{Cont}}>0$ such that for all $w_h, v_h \in V_h$ (see, for e.g.,  \cite{MR3371900})
\begin{equation}
    a_h(w_h,v_h)=a_h(v_h,w_h), \quad C_{\rm{Coer}} \|w_h\|_h^2 \le a_h(w_h,w_h), \quad a_h(w_h,v_h) \le C_{\rm{Cont}} \|w_h\|_h\|v_h\|_h.\label{P1 a_h_properties}
\end{equation}  
