\begin{lemma}[Companion operator and properties \cite{carsput2020,CC}]\label{bhcompanion_lem} 
Let ${\rm HCT}(\mathcal{T})$  denote the Hsieh--Clough--Tocher  element.
 %\cite[Chapter 6]{MR1930132}. 
There exists a linear mapping $J: {\rm M}(\mathcal{T})\to ({\rm HCT}(\mathcal{T})+P_8(\mathcal{T})) \cap H^2_0(\Omega)$ such that any $w_{\rm M}\in {\rm M}(\mathcal{T})$ satisfies
\begin{align*}
%\begin{aligned}
&\text{(i) } Jw_{\rm M}(z)=w_{\rm M}(z) \quad \text{ for } z\in\mathcal{V}, \nonumber \\ 
&\text{(ii) } \nabla ({J}w_{\rm M})(z)=
|\mathcal{T}(z)|^{-1}\sum_{K\in\mathcal{T}(z)}(\nabla w_{\rm M}|_K)(z)
\quad \text{ for }z\in\mathcal{V}(\Omega),  \nonumber\\
&\text{(iii) } \fint_e \frac{\partial J w_{\rm M}}{{\partial {\bn}}} \ds=\fint_e \frac{ \partial w_{\rm M}}{{\partial {\bn}}} \ds \text{ for any } e\in\mathcal{E},\nonumber\\ 
&\text{(iv) }  \trinl w_{\rm M}- J w_{\rm M} \trinr_{\rm pw} \lesssim  \min_{v\in  H^2_0(\Omega)}  \trinl w_{\rm M}- v \trinr_{\rm pw}, \nonumber \\
&\text{(v) } \|{v_h -Qv_h}\|_{H^s({\cal T})} \le C_1 h^{2-s}\min_{v\in  H^2_0(\Omega)}\norm{v- v_h}_h\quad \text{ for }v_h \in V_h,\ C_1>0, \text{ and }0 \le s \le 2. %\label{P1 norm_Q}
\end{align*} 
Here  $Q =JI_{\rm M}$ is a smoother operator defined from $ V_h $ to $ H^2_0(\Omega)$.
