\subsection{Fully discrete scheme}\label{sec:fully}
This subsection discusses a fully discrete scheme for   \eqref{weak form}. To the best of our knowledge, this is the first fully discrete scheme for a hyperbolic-parabolic coupled problem with explicit initial error estimates. In contrast with  \cite{Madureira_num}, where the initial error is assumed to be bounded with the required convergence and the formulation begins from the second time   step, our approach starts from the initial step and provides a general framework for defining the fully discrete formulation for any coupled hyperbolic-parabolic system. 
%We begin this section by defining some notation and presenting the fully discrete formulation.


For a positive integer $N$, consider the partition $ 0=t_0 < t_1<t_2< \cdots<t_N=T$ of the interval $[0,T]$
 with $t_n=n\Delta t$, and $\Delta t=T/N$ being the time step.
For any function $\upsilon(\bx,t)$, the following notations are adopted:  
%\begin{subequations}
\begin{align*}
& \upsilon^n  := \upsilon(\bx,t_n)= \upsilon(t_n), \quad \upsilon^{n+1/2}:= \frac{1}{2}\left(\upsilon^{n+1}+\upsilon^n \right),
\quad \upsilon^{n,1/4} :=\frac{1}{4} \left(\upsilon^{n+1}+2\upsilon^n+  \upsilon^{n-1}\right)= {\frac{1}{2} \left(v^{n+1/2} +v^{n-1/2} \right)},\\
& \bar{\partial}_t \upsilon^{n+1/2} :=\frac{\upsilon^{n+1}-\upsilon^{n}}{\Delta t} ,\quad 
{\bar{\partial}}^2_t \upsilon^n := \frac{\upsilon^{n+1}-2\upsilon^n+\upsilon^{n-1}}{(\Delta t)^2} ,\quad 
\delta_t \upsilon^n := \frac{\upsilon^{n+1}-\upsilon^{n-1}}{2\Delta t}. %\label{P1 phi_c}
\end{align*}
 Let $(U^n,\Theta^n,P^n)=(U(t_n),\Theta(t_n),P(t_n))$ denote the approximation of the continuous solution $(u,\theta,p)$ at time $t_n$.  Considering the following approximation of the initial solution 
\begin{equation}
    (U^0,\Theta^0,P^0)=({\mathcal{R}_h}u^0,\Pi_h \theta^0,\Pi_h p^0) ,\label{U0,THETA0,P0}
    \end{equation}
    we compute $(U^1,\Theta^1,P^1) \in V_h \times W_h \times W_h$ by solving the following elliptic system for all $(v_h,\psi_h, q_h) \in V_h \times W_h \times W_h$ 
    \begin{subequations}\label{3.10}
\begin{align}
    &2(\Delta t)^{-1}\big[(\bar{\partial}_tU^{1/2}-u^{*0},v_h)+a_0(\nabla \bar{\partial}_tU^{1/2}-\nabla u^{*0},\nabla v_h)\big]\nonumber\\
 &\qquad\qquad\qquad\qquad\qquad\;+d_0 a_h(U^{1/2}, v_h)  -  \alpha( \nabla \Theta^{1/2}, \nabla v_h)-\beta( \nabla P^{1/2}, \nabla v_h) 
   =( f^{1/2},v_h)
     ,\label{int_u0}\\
   & a_1(\bar{\partial}_t{\Theta}^{1/2}, \psi_h)-\gamma \bar{\partial}_t{P^{1/2}}, \psi_h)
+b_1(\Theta^{1/2},\psi_h)
   +c_1(\nabla\Theta^{1/2},\nabla\psi_h) +\alpha(\nabla \bar{\partial}_tU^{1/2},\nabla\psi_h)  =(\phi^{1/2},\psi_h)  ,\label{int_theta0} \\
    &a_2 (\bar{\partial}_tP^{1/2},q_h)-\gamma (\bar{\partial}_t{\Theta}^{1/2},q_h)+\kappa (\nabla P^{1/2},\nabla q_h)+\beta (\nabla \bar{\partial}_tU^{1/2},\nabla q_h)=(g^{1/2},q_h) .\label{int_p0}
    \end{align}\end{subequations}
    The solution is calculated at $t_1$ using \eqref{int_u0}-\eqref{int_p0} in order to align the two numerical schemes, since the Newmark scheme \eqref{un} requires solutions at $t_0$ and $t_1$ to compute the solution at $t_2$, while the Crank--Nicolson scheme begins its computation from $t_1$.
    %Thus, to ensure compatibility between these approaches for the hyperbolic-parabolic coupled system, it is necessary to introduce approximations like \eqref{int_u0}-\eqref{int_p0}. 
    The idea of the discrete equation \eqref{int_u0} is based on  the discretisation of  biharmonic wave  \cite{nry_preprint} for coupled system, and \eqref{int_theta0}-\eqref{int_p0} are based on the Crank--Nicolson method to determine the solution at $t_1$. The construction of \eqref{3.10} guarantees quadratic convergence in time, implying that also the fully discrete scheme is quadratically convergent. % and this ensures that we obtain quadratic convergence in time for the fully discrete scheme.
 %   ; this objective is achievable only if Equation \eqref{3.10} itself exhibits quadratic convergence.}

\noindent For $n=1,2, \cdots,N-1$, the fully discrete scheme consists in finding $(U^{n+1},\Theta^{n+1},P^{n+1}) \in V_h \times W_h \times W_h$ such that for all $(v_h,\psi_h, q_h) \in V_h \times W_h \times W_h$
\begin{subequations}
   \label{fully-discret-scheme}
    \begin{align}
   (\bar{\partial}_t^2U^{n},v_h)+a_0 (\nabla \bar{\partial}_t^2U^{n},\nabla v_h)+d_0 a_h(U^{n,1/4}, v_h)
    -  \alpha (\nabla \Theta^{n,1/4},\nabla v_h) -\beta ( \nabla P^{n,1/4}, \nabla v_h) 
    &=( f^{n,1/4},v_h), \label{un}\\
    a_1(\bar{\partial}_t{\Theta}^{n+1/2}, \psi_h)-\gamma (\bar{\partial}_t{P^{n+1/2}}, \psi_h)+b_1(\Theta^{n+1/2},\psi_h)+c_1 (\nabla \Theta^{n+1/2},\nabla \psi_h)&\nonumber\\
    +\alpha (\nabla \bar{\partial}_t U^{n+1/2},\nabla \psi_h) &=(\phi^{n+1/2},\psi_h), \label{thetan} \\
    a_2 (\bar{\partial}_tP^{n+1/2},q_h)
   -\gamma (\bar{\partial}_t{\Theta}^{n+1/2},q_h)
 +\kappa (\nabla P^{n+1/2},\nabla q_h)+\beta (\nabla\bar{\partial}_t U^{n+1/2},\nabla q_h)&=(g^{n+1/2},q_h).\label{pn}
    \end{align}\end{subequations}
 This section and the rest of the paper uses the discrete Gronwall Lemma {that is} stated below.
