\subsection{Stability}\label{p2;stability_sec}
Here we demonstrate the stability of  the fully discrete scheme \cblue{in \eqref{fully-discret-scheme}} and establish a uniform bound of the solution \( (U^{m+1},\Theta^{m+1},P^{m+1}) \) at \( t_{m+1} \) for \( 1 \le m \le N-1 \) in terms of the solution at \( t_0 \), \( t_1 \), and the load/source functions. % \\ 
 For any $\chi_h^n, Q_h^n \in W_h  ; n\in\{1,2,\cdots,m\}$ with $1 \le m \le N-1$, define
\begin{equation}
   \norm{(\chi_h^{m},Q_h^{m})}^2_{H}:= \Delta t \sum_{n=1}^m\Big[ {b_1}\norm{\chi_h^{n+1/2}}^2
   +c_1 \norm{\nabla\chi_h^{n+1/2}}^2 +{\kappa}\norm{\nabla Q_h^{n+1/2}}^2\Big].\label{t-norm}
\end{equation}
 Also, we define
\begin{align*}
    ((U^0,U^1,f))&:=6\norm{\bar{\partial}_t U^{1/2}}^2+4a_0\norm{\nabla \bar{\partial}_t U^{1/2}}^2+4d_0C_{\rm{Cont}}\norm{U^{1/2}}_h^2+4T^2\norm{f}_{L^\infty(0,T;L^2(\Omega))}^2,\\
    ((\Theta^0,\Theta^1,\phi))&:= 
  {\frac{1}{2}(3a_1+|\gamma|/\gamma_0)}\norm{\Theta^1}^2 +{c_1}\Delta t\norm{\nabla \Theta^{1/2}}^2+\frac{T^2}{a_1-|\gamma|/\gamma_0}\norm{\phi}^2_{L^\infty(0,T;L^2(\Omega))},\\
  ((P^0,P^1,g))&:=\frac{1}{2}{(3a_2+|\gamma|\gamma_0)}\norm{P^1}^2+{\kappa}\Delta t\norm{\nabla P^{1/2}}^2
+ \frac{T^2}{a_2-|\gamma|\gamma_0}\norm{g}^2_{L^\infty(0,T;L^2(\Omega))}.
\end{align*}
In relation with  \eqref{energy}, we define the discrete energy of  \eqref{eq:coupled} at time $t_n$, for 
$m=1,\cdots,N$,  as 
\begin{align*}
E_h(U^{m+1},\Theta^{m+1},P^{m+1})&:= \norm{\bar{\partial}_t U^{m+1/2}}^2+a_0\norm{\nabla \bar{\partial}_t U^{m+1/2}}^2+d_0 C_{\rm{Coer}}\norm{U^{m+1/2}}^2_h
   \\
  &  \qquad+({a_1-|\gamma|/\gamma_0}) \norm{\Theta^{m+1}}^2+{(a_2-|\gamma|\gamma_0)}\norm{P^{m+1}}^2+ \norm{(\Theta^{m},P^{m})}^2_{H}.
\end{align*}
Then, as in Theorem~\ref{weak-sol-thm}, the next theorem leads to the well-posedness  of \eqref{fully-discret-scheme}.
%\footnote{Discrete energy, connect stability, initial bounds, final bounds to discrete energy.;Done}
    \begin{thm}[Stability]\label{p2;stability-thm}
    %\footnote{Assumptions?- THESE ARE NOT MATCHING WITH THOSE GIVEN IN REGULARITY SECTION - THEOREM 2.1}
 Let $f, \phi,g \in L^\infty(0,T;L^2(\Omega))$,  $u^0 \in H^2_0(\Omega) ,u^{*0} \in H^1_0(\Omega)$,  and both $\theta^0,p^0 \in H^1_0(\Omega) $. Then, the scheme \eqref{fully-discret-scheme} is unconditionally stable. Moreover, for $1 \le m \le N-1$, the following bound holds:
\begin{align*}
 E_h(U^{m+1},\Theta^{m+1},P^{m+1}) \lesssim ((U^0,U^1,f))+((\Theta^0,\Theta^1,\phi))+((P^0,P^1,g)).
\end{align*}
The constant absorbed in "$\lesssim$'' above depends on $T$ and on the model coefficients $a_0,c_1, \alpha,\beta, \kappa$.
\end{thm}
\begin{proof}[\textbf{Proof}]
