First we choose $v_h=\delta_t U^n$ in \eqref{un}, $\psi_h=\Theta^{n+1/2}$ in \eqref{thetan}, and $q_h=P^{n+1/2}$ in \eqref{pn}. Then, multiply \eqref{un} by $4\Delta t$ and both \eqref{thetan} and \eqref{pn} by 
$\Delta t$ to obtain
\begin{align*}
   4 \Delta t\big[(\bar{\partial}_t^2U^{n},\delta_t U^n)+a_0 (\nabla \bar{\partial}_t^2U^{n},\nabla \delta_t U^n)+d_0 a_h(U^{n,1/4}, \delta_t U^n)
   -(\alpha  \nabla \Theta^{n,1/4}+\beta \nabla P^{n,1/4}, \nabla \delta_t U^n) \big]&=4 \Delta t ( f^{n,1/4},\delta_t U^n), \\
    \Delta t \big[(a_1\bar{\partial}_t{\Theta}^{n+1/2} -\gamma \bar{\partial}_t{P^{n+1/2}}, {\Theta}^{n+1/2})+b_1(\Theta^{n+1/2},{\Theta}^{n+1/2})
    +(c_1 \nabla \Theta^{n+1/2} +\alpha \bar{\partial}_tU^{n+1/2},\nabla  \Theta^{n+1/2})\big]&=\Delta t(\phi^{n+1/2},{\Theta}^{n+1/2}), \\
    \Delta t \big[a_2 (\bar{\partial}_tP^{n+1/2},P^{n+1/2})-\gamma (\bar{\partial}_t{\Theta}^{n+1/2},P^{n+1/2})& \\
   +\kappa (\nabla P^{n+1/2},\nabla P^{n+1/2})+\beta (\nabla \bar{\partial}_tU^{n+1/2},\nabla P^{n+1/2})\big]&=\Delta t(g^{n+1/2},P^{n+1/2}) .
