\section{Error Analysis}\label{p2;fully-error-sec}
This section establishes the error estimates for the fully discrete scheme presented in the previous section. In Subsection~\ref{subsec-initial}, we prove the error estimates at the initial time steps $t_0$ and $t_1$ for the scheme \eqref{U0,THETA0,P0}-\eqref{3.10}. The subsequent subsection provides error estimates for the scheme \eqref{fully-discret-scheme} in different norms. 
Let us consider the following  decomposition of errors at time $t_n$, for $n=1,\ldots, N$ 
\begin{subequations}\label{spilit}
\begin{align} 
    &
    u(t_n)-U^n=\big(u(t_n)-\mathcal{R}_h u(t_n)\big)+\big(\mathcal{R}_hu(t_n)-U^n \big):=\rho^n+\zeta^n,\label{p2;splitting1}\\
    &
    \theta(t_n)-\Theta^n=\big(\theta(t_n)-\Pi_h\theta(t_n)\big)+\big(\Pi_h\theta(t_n)-\Theta^n\big):=\eta^n+\Psi^n,\label{p2;splitting2}\\
    &
     p(t_n)-P^n=\big(p(t_n)-\Pi_hp(t_n)\big)+\big(\Pi_hp(t_n)-P^n\big):=\varrho^n+\xi^n,\label{p2;splitting3}
\end{align}
\end{subequations}
where $\mathcal{R}_h$ and $\Pi_h$ are the projections defined in \eqref{P1 ritz_projection} and \eqref{p2;ritzprojection2}, respectively.
