\begin{lemma}[Initial error bounds]\label{initial-error-lemm}
 Under the regularity assumptions on given data as stated in Theorems~\ref{existence;thm}-\ref{thm;regularity}, the following estimates are satisfied:
\begin{align*}
&\norm{\bar{\partial}_t\zeta^{1/2}}^2+  a_0\norm{\nabla \bar{\partial}_t\zeta^{1/2}}^2+d_0C_{\rm{Coer}}\norm{\zeta^{1/2}}_h^2+(a_1-|\gamma|/\gamma_0)\norm{\Psi^{1/2}}^2+(a_2-|\gamma|\gamma_0)\norm{\xi^{1/2}}^2\\
       &
      \quad
      +\Delta t \big[b_1\norm{\Psi^{1/2}}^2+ c_1 \norm{\nabla \Psi^{1/2}}^2
       + \kappa \norm{\nabla \xi^{1/2}}^2\big]
        \lesssim h^{4\sigma} +L_{(u,\theta,p,t_1)} h^{4\sigma}+ M_{(u,\theta,p,t_1)} (\Delta t)^4,
\end{align*}
where the absorbed constant in "$\lesssim$" depends on $C_F$, $C_{\rm{Coer}}$, $C_{\rm{Cont}}$, $C_1$,$C_2$, $C_3$,  $T$, and the model coefficients.
\end{lemma}
