\noindent{\bf Main result}

\smallskip\noindent Before proceeding to establish the error estimates at $t=t_2,t_3, \cdots, t_N$, we first  note that the following quantities are bounded, thanks to Table~\ref{table:summary}
\begin{subequations}  \label{lm}
  \begin{align} L_{(u,\theta,p,T)}&:=\norm{u}^2_{L^\infty(0,T;H^{2+\sigma}(\Omega))}+\norm{u_t}^2_{L^\infty(0,T;H^{2+\sigma}(\Omega))}+\norm{u_{tt}}^2_{L^2(0,T;H^{2+\sigma}(\Omega))}+\norm{\theta}^2_{L^\infty(0,T;H^{1+\sigma}(\Omega))}\nonumber\\
    &\qquad\qquad\qquad\qquad
    + \norm{\theta_t}^2_{L^\infty(0,T;H^{1+\sigma}(\Omega))}+\norm{p}^2_{L^\infty(0,T;H^{1+\sigma}(\Omega))}+ \norm{p_t}^2_{L^\infty(0,T;H^{1+\sigma}(\Omega))},\\   
M_{(u,\theta,p,T)}&:=\norm{u_{ttt}}^2_{L^2(0,T;H^1(\Omega))}+\norm{u_{tttt}}^2_{L^2(0,T;H^1(\Omega))}+\norm{\theta_{ttt}}^2_{L^2(0,T;L^2(\Omega))}+\norm{p_{ttt}}^2_{L^2(0,T;L^2(\Omega))}.\label{last}
    \end{align}
    \end{subequations}

\begin{thm}[Error estimates] \label{error-estimates thm}
Under the regularity assumptions on given data as stated in Theorem \ref{thm;regularity},  for $1 \le m \le N-1$, the following estimates are satisfied:
   \begin{align*}
   &\norm{\bar{\partial}_t (u^{m+1/2}-U^{m+1/2})}^2+a_0\norm{\nabla \bar{\partial}_t (u^{m+1/2}-U^{m+1/2})}^2+{(a_1-|\gamma|/\gamma_0)} \norm{\theta^{m+1}-\Theta^{m+1}}^2\nonumber\\ 
    & 
    +{(a_2-|\gamma|\gamma_0)}\norm{p^{m+1}-P^{m+1}}^2+{d_0}h^{2\sigma}\norm{u^{m+1/2}-U^{m+1/2}}^2_h+h^{2\sigma}\norm{(\theta^{m}-\Theta^{m},p^{m}-P^{m})}^2_{H}  \\
    &\qquad\qquad\qquad\qquad\qquad\lesssim h^{4\sigma}+\big[L_{(u,\theta,p,t_1)}+L_{(u,\theta,p,T)}\big]h^{4\sigma} +M_{(u,\theta,p,T)}(\Delta t)^4\nonumber,
  % &
 %  $\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
%  \lesssim  \textcolor{cyan}%{\big[C_F+C_F'\big]h^4+\big[L_{(u,\theta,p,T)}\big]h^{4\sigma}+\big[M_{(u,\theta,p,T)}\big](\Delta t)^4},\nonumber
   \end{align*}
   where the absorbed constant in "$\lesssim$" depends on $C_{\rm{Coer}}$, $C_{\rm{Cont}}$, $C_1$,$C_2$, $C_3$,  $T$, and the model coefficients.
\end{thm}
