\subsection{Example 2: Convergence against smooth solutions}\label{subsec-num-smooth}
The theoretical results of  Section~\ref{sec:fully} are validated in this section by choosing a smooth manufactured  solution of \eqref{p2;model11}-\eqref{p2;model11}.  We consider the spatial domain $\Omega=(0,1)^2$ and time interval $[0,1]$. All model parameters are set to 1, except for $a_1 =35, a_2=40$, and $\gamma=1$ (and $\gamma=-1$) which are selected so that the condition \eqref{gamma_0} is satisfied and the result are robust with respect to $\gamma$. The   transverse load $f$, heat source $\phi$, and a total amount of mass source $g$ and the initial data $u^0$, $u^{*0}, \theta^0$ and $p^0$ are  chosen such that the exact solution of \eqref{eq:coupled} is given by
\begin{gather*}
    u(\bx,t)=\exp(5t)(x(x-1)y(y-1))^2, \\
\theta(\bx,t)=\exp(-t)\sin(\pi x)\sin(\pi y),\quad p(\bx,t)=\cos(t)\sin(\pi x)\sin(\pi y),\end{gather*}
and hence our theoretical regularity results with $\sigma=1$ (as well as the clamped boundary conditions) are satisfied. 

We construct a sequence of successively refined uniform triangular meshes $\mathcal{T}^i$ of $\Omega$ of size $h_i$ and split the time domain using the refined time step $\Delta t ={2}^{-3/2}h_i$. For each mesh refinement, we calculate errors 
%the errors between the exact and approximate solutions 
%in norm defined in 
as 
\begin{subequations}\label{num-norms}
\begin{align}
    &\norm{e_u}^{\ell^\infty}:=\underset{0 \le n \le N}{\max}{\norm{u^{n}-U^{n}}},\\
   &\norm{{\nabla}e_u}^{{\ell}^\infty}:=\underset{0 \le n \le N}{\max}{\norm{\nabla(u^{n}-U^{n})}},\qquad \norm{\hat{e}_u}^{\ell^\infty}_h:=\underset{0 \le n \le N-1}{\max}{\norm{u^{n+1/2}-U^{n+1/2}}}_h,\label{norm1}\\
    &\norm{e_{\theta}}^{\ell^\infty}:=\underset{0 \le n \le N}{\max}{\norm{\theta^{n}-\Theta^{n}}},\qquad \norm{{\nabla}\hat{e}_{\theta}}^{\ell^2}:=\big(\Delta t\sum_{n=0}^{N-1}{\norm{\nabla(\theta^{n+1/2}-\Theta^{n+1/2})}}^2\big)^{1/2},
   \\
&\norm{e_{p}}^{\ell^\infty}:=\underset{0 \le n \le N}{\max}{\norm{p^{n}-P^{n}}},\qquad 
\norm{{\nabla}\hat{e}_{p}}^{\ell^2}:=\big(\Delta t\sum_{n=0}^{N-1}{\norm{\nabla(p^{n+1/2}-P^{n+1/2})}}^2\big)^{1/2}.\label{norm3}
\end{align}\end{subequations}
The experimental rates of convergence in space are computed as $\texttt{Rate} =$\, $\log(e_{i+1}/{e}_{i})[\log(h_{i+1}/{h}_i)]^{-1}$, where $e_{i}$ denotes a norm of the error on the mesh $\mathcal{T}^i$.  Then by Theorem~\ref{error-estimates thm} and Corollary~\ref{corr}, the expected convergence rates are of order  $\mathcal{O}(h^\sigma)$ for $\norm{\hat{e}_u}^{\ell^\infty}_h,\norm{{\nabla}\hat{e}_{\theta}}^{\ell^2}, \norm{{\nabla}\hat{e}_{p}}^{\ell^2}$  and $\mathcal{O}(h^{2\sigma})$  for $\norm{e_u}^{\ell^\infty},\norm{{\nabla}e_u}^{\ell^\infty},\norm{{e}_{\theta}}^{\ell^\infty},\norm{{e}_{p}}^{\ell^\infty}$  norms defined in \eqref{num-norms}. Table~\ref{Table-smooth} shows the error history and convergence results for $u$, $\theta$ and $p$ and the numerical solution at final time given in Figure~\ref{fig:TEDsmoothsol} for $\gamma=-1$. In all cases, the  numerical results are consistent with the expected theoretical results.


