\section{Appendix}\label{appendix}
\begin{proof}[\textbf{Proof of Theorem~\ref{existence;thm}}]
{The proof of existence is presented in Steps 1-4 and that of uniqueness using energy arguments in Step~5.} 

\medskip
\noindent \textit{{Step 1} (Construction of a sequence of approximate solutions).}
{It is well known that} there exists an orthogonal basis $\{w^1,w^2, \cdots \}$ (resp. $\{y^1,y^2, \cdots \}$) of $H_0^2(\Omega)$ (resp.  $H_0^1(\Omega)$)  and {this also forms an orthonormal basis of $L^2(\Omega)$ \cite{MR1115235,MR990018}}. For a fixed integer $m$, we proceed to write 
\begin{equation}
 u^m(t):=\sum_{k=1}^{m}{\rm d}_m^k(t)w^k,\; \theta^m(t):=\sum_{k=1}^{m}\eta_m^k(t)y^k \text{ and } p^m(t):=\sum_{k=1}^{m}{\rm l}_m^k(t)y^k, \label{rep}
 \end{equation}
 where the coefficients ${\rm d}_m^k(t)$, $\eta_m^k(t)$ and ${\rm l}_m^k(t)$ are selected such that
\begin{subequations}\label{weak-mo}
\begin{align}
    &{\rm d}_m^k(0)=(u^0,w^k), \qquad {{\rm d}_m^k}'(0)+a_0\norm{\nabla w^k}^2 {{\rm d}_m^k}'(0)=(u^{*0},w^k)+a_0(\nabla u^{*0},\nabla w^k), \label{d0}\\
    &\eta_m^k(0)=(\theta^0,y^k), \qquad {\rm l}_m^{k}(0)=(p^0,y^k)  \label{l0}
\end{align} 
\end{subequations}
and
%and {for all $0 < t \le T$ and $k=1,2 \cdots ,m$},
 % to satisfy 
\begin{subequations}
\label{weak-m}
\begin{align}
 (u^m_{tt},w^k)+a_0 (\nabla u^m_{tt},\nabla w^k)+d_0(\nabla ^2 u^m, \nabla^2 w^k) -\alpha (\nabla \theta^m, \nabla w^k)-\beta (\nabla p^m, \nabla w^k)&=(f,w^k), \label{um} \\
     a_1(\theta^m_{t}, y^k)-\gamma (p^m_{t}, y^k)+b_1(\theta^m,y^k) +c_1 (\nabla \theta^m,\nabla y^k) +\alpha (\nabla u^m_{t}, \nabla y^k)&=(\phi,y^k),  \label{thetam} \\
    a_2 (p^m_{t},y^k)-\gamma (\theta^m_{t},y^k)+\kappa (\nabla p^m,\nabla y^k)+\beta (\nabla u^m_{t},\nabla y^k)&=(g,y^k),\label{pm}
     \end{align} 
     \end{subequations} 
     hold {for all $0 < t \le T$ and $k=1,2 \cdots ,m$}.
(Since \eqref{weak-m} forms a linear ODE system with initial conditions \eqref{weak-mo}, standard ODE theory \cite{evans}, guarantees the existence of unique $C^2$ (resp. $C^1 $) functions 
  $({\rm d}_m^1(t),  {\rm d}_m^2(t), \cdots, {\rm d}_m^m(t))$ (resp. $(\eta_m^1(t), \eta_m^2(t), \cdots, \eta_m^m(t))$ and $({\rm l}_m^1(t),{\rm l}_m^2(t), \cdots, {\rm l}_m^m(t))$), that satisfy \eqref{weak-mo}-\eqref{weak-m} for $0\le t \le T. $)

\medskip
\noindent
\textit{ Step 2 (Derivation of a
priori bounds for approximate solutions)}. 
{We aim to take the limit 
$m \rightarrow \infty $ and hence shall} derive estimates that are uniform with respect to $m$.  
Multiply the equations \eqref{um}, \eqref{thetam}, and \eqref{pm} by ${{\rm d}_m^k}'(t),\eta_m^k(t)$, and ${\rm l}_m^k(t)$, respectively {and sum} up the result    for $k=1,2,\ldots, m.$ {Then definitions in \eqref{rep} lead to}
\begin{align*}
    \frac{1}{2}&\frac{d}{dt}\big(\norm{u^m_t}^2+a_0\norm{\nabla u_{t}^m}^2+d_0 \norm{\nabla^2 u^m}^2+a_1\norm{\theta^m}^2+a_2\norm{p^m}^2\big)\\
    &+b_1\norm{\theta^m}^2+c_1\norm{\nabla \theta^m}^2+\kappa\norm{\nabla p^m}^2-\gamma \frac{d}{dt}(\theta ^m,p^m)=(f,u^m_t)+(\phi, \theta^m)+(g,p^m).
\end{align*}
{An integration from $0$ to $t$ and} simple manipulations show
\begin{align}
&   \frac{1}{2}\big(\norm{u^m_t}^2+a_0\norm{\nabla u_{t}^m}^2+d_0 \norm{\nabla^2 u^m}^2+a_1\norm{\theta^m}^2+a_2\norm{p^m}^2\big) +\int_0^t \big( b_1\norm{ \theta^m}^2+c_1\norm{\nabla \theta^m}^2+\kappa\norm{\nabla p^m}^2 \big) \ds \nonumber \\
   &
   \quad =\frac{1}{2}\big(\norm{u^m_t(0)}^2+a_0\norm{\nabla u_{t}^m(0)}^2+d_0 \norm{\nabla^2 u^m(0)}^2+a_1\norm{\theta^m(0)}^2+a_2\norm{p^m(0)}^2\big)\nonumber\\
   &\qquad
   +\gamma (\theta ^m,p^m) -\gamma (\theta^m(0)  ,p^m(0)) + \int_0^t \big((f,u^m_t)+(\phi, \theta^m)+(g,p^m)\big)\ds.\label{int}
\end{align}
An application of Cauchy--Schwarz and Young's inequalities to the {last three terms in \eqref{int} yields}
\begin{align}
    \gamma (\theta ^m,p^m) &-\gamma (\theta^m(0)  ,p^m(0)) 
   + \int_0^t \big((f,u^m_t)+(\phi, \theta^m)+(g,p^m)\big)\ds \nonumber\\
   &\qquad 
   \le \frac{|\gamma|}{2\gamma_0}\big(\norm{\theta^m}^2+\norm{\theta^m(0)}^2\big)+\frac{|\gamma|\gamma_0}{2}\big(\norm{p^m}^2 +\norm{p^m(0)}^2\big)\nonumber\\
   & \quad\qquad 
   + \frac{1}{2} \int_0^t \big(\norm{f}^2+\norm{\phi}^2+\norm{g}^2+\norm{u^m_t}^2+\norm{\theta^m}^2+\norm{p^m}^2 \big)\ds,\label{gamma}
\end{align}
where $\gamma_0$ is defined in \eqref{gamma_0}.
%
Next, substitute \eqref{gamma} in \eqref{int}, to obtain
\begin{align}
   &\norm{u^m_t}^2+a_0\norm{\nabla u_{t}^m}^2+d_0 \norm{\nabla^2 u^m}^2+(a_1-|\gamma|/\gamma_0)\norm{\theta^m}^2+(a_2-|\gamma|\gamma_0)\norm{p^m}^2\nonumber \\
   &\quad \qquad 
   +2\int_0^t \big( b_1\norm{ \theta^m}^2+c_1\norm{\nabla \theta^m}^2+\kappa\norm{\nabla p^m}^2 \big) \ds \nonumber \\
   & 
   \le\norm{u^m_t(0)}^2+a_0\norm{\nabla u_{t}^m(0)}^2+d_0 \norm{\nabla^2 u^m(0)}^2+(a_1+|\gamma|/\gamma_0)\norm{\theta^m(0)}^2+(a_2+|\gamma|\gamma_0)\norm{p^m(0)}^2\nonumber\\
   &\quad \qquad 
+\norm{f}_{L^2(0,T;L^2(\Omega))}^2+\norm{\phi}^2_{L^2(0,T;L^2(\Omega))}+\norm{g}^2_{L^2(0,T;L^2(\Omega))}+ \int_0^t \big(\norm{u^m_t}^2+\norm{\theta^m}^2+\norm{p^m}^2 \big)\ds.\label{int1}
\end{align}

We next utilize \eqref{d0}-\eqref{l0} to show
\begin{align}
&\norm{u^m_t(0)}^2+a_0\norm{\nabla u_{t}^m(0)}^2+d_0 \norm{\nabla^2 u^m(0)}^2+(a_1+|\gamma|/\gamma_0)\norm{\theta^m(0)}^2+(a_2+|\gamma|\gamma_0)\norm{p^m(0)}^2\nonumber\\
&\qquad\;\;\;\;
\lesssim 
\norm{u^{*0}}^2+a_0\norm{u^{*0}}^2_{H^1(\Omega)}+d_0\norm{u^0}^2_{H^2(\Omega)}+(a_1+|\gamma|/\gamma_0)\norm{\theta^0}^2+(a_2+|\gamma|\gamma_0)\norm{p^0}^2.\label{intt2}
\end{align}
A combination of \eqref{int1}-\eqref{intt2} and an  application of Lemma~\ref{P1 gronwall} lead to the bound
\begin{align} \label{eq:aprioribounds}
&2E(u^m, \theta^m, p^m; t)=\norm{u^m_t}^2+a_0\norm{\nabla u_{t}^m}^2+d_0 \norm{\nabla^2 u^m}^2+(a_1-|\gamma|/\gamma_0)\norm{\theta^m}^2+(a_2-|\gamma|\gamma_0)\norm{p^m}^2\nonumber \\
   &\quad \qquad 
   +2\int_0^t \big( b_1\norm{ \theta^m}^2+c_1\norm{\nabla \theta^m}^2+\kappa\norm{\nabla p^m}^2 \big) \ds \nonumber \\
   &\qquad \lesssim 
\norm{u^{*0}}^2+a_0\norm{u^{*0}}^2_{H^1(\Omega)}+d_0\norm{u^0}^2_{H^2(\Omega)}+(a_1+|\gamma|/\gamma_0)\norm{\theta^0}^2+(a_2+|\gamma|\gamma_0)\norm{p^0}^2\nonumber\\
&\qquad\qquad\qquad+\norm{f}_{L^2(0,T;L^2(\Omega))}^2+\norm{\phi}^2_{L^2(0,T;L^2(\Omega))}+\norm{g}^2_{L^2(0,T;L^2(\Omega))}.
\end{align}

Now, fix any $v \in H^2_0(\Omega)$ and $\psi,q \in H^1_0(\Omega)$ with $ \norm{v}_{H^2_0(\Omega)} \le 1,\; \norm{\psi}_{H^1_0(\Omega)} \le 1,$ and $ \norm{q}_{H^1_0(\Omega)} \le 1$. Write $v=v_1+v_2,$ $\psi=\psi_1+\psi_2$ and $q=q_1+q_2$,  where $v_1 \in$ span $\{w^k\}_{k=1}^m$, and both   $\psi_1,q_1 \in$ span $\{y^k\}_{k=1}^m$ with $(v_2, w^k)=(\nabla v_2, \nabla w^k)=(\psi_2,y^k)=(q_2,y^k)=0$ $(k =1,2,\cdots,m).$ Note $\norm{v_1}_{H^2_0(\Omega)} \le 1,\; \norm{\psi_1}_{H^1_0(\Omega)}\le 1$, and $\norm{q_1}_{H^1_0(\Omega)}\le 1.$ Then \eqref{rep} and \eqref{um} imply that 
\begin{align}
    \langle u^m_{tt}, v \rangle+a_0\langle \nabla u^m_{tt},\nabla v\rangle&=(u^m_{tt}, v)+a_0(\nabla u^m_{tt},\nabla v)=(u^m_{tt}, v_1)+a_0(\nabla u^m_{tt},\nabla v_1)\nonumber\\
    &=(f,v_1)-d_0(\nabla^2 u^m, \nabla^2 v_1)+\alpha (\nabla \theta^m, \nabla v_1)+\beta (\nabla p^m, \nabla v_1).\label{duality}
\end{align}
This and a Cauchy--Schwarz inequality reveals
\begin{align*}
\norm{u_{tt}^m}_{H^{-1}(\Omega)}&\lesssim| \langle u^m_{tt}, v\rangle+ 
 \langle \nabla u^m_{tt},\nabla v\rangle| \lesssim  | \langle u^m_{tt}, v\rangle+ 
 a_0\langle \nabla u^m_{tt},\nabla v\rangle| \lesssim \norm{f}+d_0\norm{\nabla^2 u^m}+\alpha \norm{\nabla \theta^m}+ \beta \norm{\nabla p^m}.
\end{align*}
An integration from $0$ to $T$ and the bounds from \eqref{eq:aprioribounds} allow us to assert that 
\begin{align}
\int_0^T\norm{u_{tt}^m}_{H^{-1}(\Omega)} \: \dt &\lesssim \norm{u^{*0}}^2+a_0\norm{u^{*0}}^2_{H^1(\Omega)}+d_0\norm{u^0}^2_{H^2(\Omega)}+(a_1+|\gamma|/\gamma_0)\norm{\theta^0}^2+(a_2+|\gamma|\gamma_0)\norm{p^0}^2\nonumber\\
& \; +\norm{f}_{L^2(0,T;L^2(\Omega))}^2+\norm{\phi}^2_{L^2(0,T;L^2(\Omega))}+\norm{g}^2_{L^2(0,T;L^2(\Omega))}.\label{uttm-h-2}
\end{align}
On the other hand, the combination of \eqref{rep} and \eqref{thetam}–\eqref{pm} with similar arguments as in  \eqref{duality}, yields 
\begin{align*}
    &a_1 \langle \theta^m_{t}, \psi\rangle-\gamma \langle p^m_{t}, \psi \rangle=a_1 ( \theta^m_{t}, \psi_1)-\gamma ( p^m_{t}, \psi_1 )=(\phi,\psi_1)-b_1(\theta^m,\psi_1) -c_1 (\nabla \theta^m,\nabla \psi_1 ) -\alpha (\nabla u^m_{t}, \nabla y^k),   \\
   & a_2 \langle p^m_{t},q \rangle -\gamma \langle \theta^m_t,q\rangle =a_2 (p^m_{t},q_1 ) -\gamma ( \theta^m_t,q_1)=(g,q_1)-\kappa (\nabla p^m,\nabla q_1)-\beta (\nabla u^m_{t},\nabla q_1).
\end{align*}
Applying Cauchy--Schwarz inequality again (shifting the second terms from left to right-hand side in both inequalities and using $|\gamma \langle p^m_{t}, \psi \rangle| \le |\gamma| \norm{p^m_t}_{H^{-1}(\Omega)}$ and $|\gamma \langle \theta^m_t,q\rangle| \le |\gamma| \norm{\theta^m_t}_{H^{-1}(\Omega)} $, we readily get 
\begin{align*}
a_1\norm{\theta^m_t}_{H^{-1}(\Omega)}&\le  |\gamma| \norm{p^m_t}_{H^{-1}(\Omega)}+C \Big( \norm{\phi}+b_1\norm{\theta^m}+c_1\norm{\nabla\theta^m} +\alpha \norm{\nabla u^m_t}\Big),\\
a_2\norm{p^m_t}_{H^{-1}(\Omega)} &\le  |\gamma| \norm{\theta^m_t}_{H^{-1}(\Omega)}+C \Big( \norm{g}+\kappa\norm{\nabla p^m} +\beta \norm{\nabla u^m_t}\Big).
\end{align*}
Next, we multiply the first equation above by ${\gamma_0}^{{1}/{2}}$, the second by ${\gamma_0}^{-{1}/{2}}$, and add the two inequalities. Again, applying integration from $0$ to $T$ and the bounds from \eqref{eq:aprioribounds},  lead to
\begin{align}
&  {\gamma_0}^{{1}/{2}}(a_1-|\gamma|/\gamma_0)\int_0^T\norm{\theta^m_t}_{H^{-1}(\Omega)} \: \dt +\gamma_0^{-{1}/{2}}(a_2-|\gamma|\gamma_0)\int_0^T\norm{p^m_t}_{H^{-1}(\Omega)  } \dt \nonumber\\
&\; \lesssim  \norm{u^{*0}}^2+a_0\norm{u^{*0}}^2_{H^1(\Omega)}+d_0\norm{u^0}^2_{H^2(\Omega)}+(a_1+|\gamma|/\gamma_0)\norm{\theta^0}^2+(a_2+|\gamma|\gamma_0)\norm{p^0}^2\nonumber\\
&\qquad\qquad\qquad\qquad+\norm{f}_{L^2(0,T;L^2(\Omega))}^2+\norm{\phi}^2_{L^2(0,T;L^2(\Omega))}+\norm{g}^2_{L^2(0,T;L^2(\Omega))}.\label{t-p-h-1}
\end{align}

\medskip
\noindent
\textit{{Step 3} (Existence of a limit for a subsequences).}
The estimates in \eqref{eq:aprioribounds} indicate that $ \{u^{m}\}_{m=1}^\infty $ and $ \{u_t^{m}\}_{m=1}^\infty $ are bounded in the spaces $ L^\infty(0,T;H^2_0(\Omega)) $ and $ L^\infty([0,T]
;H^1_0(\Omega)) $, respectively, and both $ \{\theta^{m}\}_{m=1}^\infty $ and $ \{p^{m}\}_{m=1}^\infty $ are bounded in $ L^\infty(0,T;L^2(\Omega)) $ as well as in $ L^2(0,T;H^1_0(\Omega)) $. Moreover, the estimates in \eqref{uttm-h-2} and \eqref{t-p-h-1} reveal that  $ \{u_{tt}^{m}\}_{m=1}^\infty $, $ \{\theta_t^{m}\}_{m=1}^\infty $ and $ \{p_t^{m}\}_{m=1}^\infty $ are bounded in  $ L^2(0,T;H^{-1}(\Omega)) $.  Consequently, there exist subsequences $ \{u^{m}\}_{m=1}^\infty $, $ \{\theta^{m}\}_{m=1}^\infty $, and $ \{p^{m}\}_{m=1}^\infty $ (where re-labelling is used), and some $ u \in L^\infty(0,T;H^2_0(\Omega)) $ with $ u_t \in L^\infty(0,T;H^1_0(\Omega)) $, and $u_{tt} \in L^2(0,T;H^{-1}(\Omega)) $, $ \theta, p \in L^\infty(0,T;L^2(\Omega)) \cap L^2(0,T;H^1_0(\Omega)) $, and $ \theta_t, p_t \in L^2(0,T;H^{-1}(\Omega))$ such that
%Consequently, there exist subsequences $ \{u^{m_r}\}_{r=1}^\infty $, $ \{\theta^{m_r}\}_{r=1}^\infty $, and $ \{p^{m_r}\}_{r=1}^\infty $ and some $u\in L^\infty([0,T];H^2_0(\Omega))$ with $u_t \in L^\infty([0,T];H^1_0(\Omega)) $  and $(\theta,p) \in (L^\infty([0,T];L^2(\Omega)))^2 \cap (L^2(0,T;;H^1_0(\Omega)))^2  $ such that 
\begin{subequations}\label{m-inf}
\begin{align}
    ( u^{m},u_t^{m},\theta^{m},p^{m})  &\xrightarrow{\text{weak*}}(u,u_t,\,\theta,p) \quad  \text{in}\ L^\infty\big(0,T;H_0^2(\Omega) 
 \times H^1_0(\Omega) \times (L^2(\Omega) )^2\big), \label{c1}\\
   (\theta^{m}, p^{m})  &\xrightarrow{\text{weak}} (\theta,p) \quad \qquad \; \;\;  \text{in} \ L^2 \big(0,T; (H_0^1(\Omega))^2\big),\label{c2}\\
{(u_{tt}^{m},\theta^m_t ,p^{m}_t) }&\xrightarrow{\text{weak}} (u_{tt},\theta_t,p_t)  \quad \;\; \;  \text{in} {\ L^2 \big(0,T; (H^{-1}(\Omega))^3\big)}.
\end{align}\end{subequations}
\textit{{Step 4} (Limit is a weak solution).} Now we show that $(u,\theta,p)$ satisfies \eqref{u}-\eqref{p}.
%the weak convergence for $u^m_{tt}$, $\theta^m_t$ and $p^m_t$.
For this, we introduce 
$\widehat{\rm d}_{j_0}^k(t)\in C^2[0,T]$, $\widehat{\eta}_{j_{0}}^k(t)$ and $\widehat{\rm l}_{j_{0}}^k(t) \in C^1[0,T]$  such that $\widehat{\rm d}_{j_{0}}^k(T)=\widehat{\rm d}_{j_{0}t}^k(T)=\widehat{\eta}_{j_{0}}^k(T)=\widehat{\rm l}_{j_{0}}^k(T)=0$,  and  define 
\begin{equation}
