Let us take $v \in H^{2}_0(\Omega)$, $\psi \in H^1_0(\Omega)$, and $q \in H^1_0(\Omega)$ and further denote 
    \[\tilde{v}^t(s,\bx)= \rho_\varepsilon(t-s)v(\bx),\; \tilde{\psi}^t(s,\bx)=\rho_\varepsilon(t-s) \psi(\bx), \; \tilde{q}^t(s,\bx)=\rho_\varepsilon(t-s) q(\bx) {\text{ for } t \in [0,T].}\]
    Clearly, $\tilde{v}^t \in C^\infty([0,T];H^2_0(\Omega)), \, \tilde{\psi}^t\in C^\infty([0,T];H^1_0(\Omega)), \, \tilde{q}^t\in C^\infty([0,T];H^1_0(\Omega))$ for   $0\le t \le T.$ Substituting  $\tilde{v}^t,\;\tilde{\psi}^t$,\ and $ \tilde{\psi}^t$ in \eqref{u}-\eqref{p}, and noting that $\rho_\varepsilon(t)=(d/dt)\rho_\varepsilon(t)=0$ for $0 \le t \le T$, yields  
    \begin{subequations}
    \begin{align}
        (u_{\varepsilon tt}(t,\cdot), v)+a_0(\nabla u_{\varepsilon tt}(t,\cdot), \nabla v)+d_0 (\nabla^2 u_{\varepsilon }(t,\cdot), \nabla^2 v)-\alpha (\nabla \theta_\varepsilon(t,\cdot), \nabla v)-\beta (\nabla p_\varepsilon(t,\cdot), \nabla v)=0,\label{uep}\\
        a_1(\theta_{\varepsilon t }(t,\cdot),\psi)-\gamma(p_{\varepsilon t}(t,\cdot),\psi)+b_1(\theta_{\varepsilon}(t,\cdot),\psi)+c_1(\nabla \theta_\varepsilon(t,\cdot),\nabla \psi)+\alpha (\nabla u_{\varepsilon t}(t,\cdot),\nabla\psi)=0,\label{thetaep}\\
        a_2(p_{\varepsilon t }(t,\cdot),q)-\gamma(\theta_{\varepsilon t}(t,\cdot),q)+\kappa(\nabla p_\varepsilon(t,\cdot),\nabla q)+\beta (\nabla u_{\varepsilon t}(t,\cdot),\nabla q)=0, \label{pep}
        \end{align}\end{subequations}
        for any $ 0 \le t \le T$, $v \in H^2_0(\Omega)$, $\psi \in H^1_0(\Omega)$, and $q \in H^1_0(\Omega)$, where 
