We now give a proof of Theorem~\ref{thm:trunc_sol},
which bounds the error in the potential $u_{\epsilon}$ obtained by solving for
densities $(\sigma_{\epsilon}, \tau_{\epsilon})$ on any truncated
curve $\tGamma_{\epsilon}$. Since we now include the contribution
of the free-space kernel, we again assume that $0<\beta.$
\begin{proof}[Proof of Theorem~\ref{thm:trunc_sol}]
   Recall that $0<\beta$ and $\tGamma^c_{\epsilon}=\{y_2\in\tGamma:\:
   e^{-\beta|\Im y_2|}<\epsilon\}.$ Let~$[\sigma_\epsilon,\tau_\epsilon]$ solve \eqref{eqn5.60.11} and~$[\sigma,\tau]$ solve the equation
        \begin{equation}
        \lp\cI+\cK_{\tGamma}\rp\begin{bmatrix}
            \sigma\\ \tau
        \end{bmatrix}=\begin{bmatrix}
            f_D \\ f_N
        \end{bmatrix}
    \end{equation}
    on all of~$\Gamma_C$. By Theorem~\ref{thm:trunc_IE} and Lemma~\ref{lem:solve_compact}, we have that
    \begin{equation}
        \|\sigma-\sigma_\epsilon\|_{\alpha,\beta} +\|\tau-\tau_\epsilon\|_{\alpha + \frac 12 , \beta} < C\epsilon\left(  \|f_D\|_{\alpha,\beta} + \|f_N\|_{\alpha+\frac 12,\beta}\right).
    \end{equation}
    We then write
    \begin{equation}
        \cS^{l}_{\tGamma_{\epsilon}}[\tau_\epsilon] -\cS^{l}_{\tGamma}[\tau]= \cS^{l}_{\tGamma}[\tau_{\epsilon}-\tau] + \lp\cS^{l}_{\tGamma_{\epsilon}}-\cS^{l}_{\tGamma}\rp[\tau_{\epsilon}].
    \end{equation}


    Using Lemma~\ref{lemma:w_decay} and~\eqref{eq:Hank_asymp} we can prove that
    \begin{equation}\label{eqn5.51.110}
    \begin{aligned}
        \left|\lp\cS^{l}_{\tGamma_{\epsilon}}-\cS^{l}_{\tGamma}\rp[\tau_{\epsilon}](\bx )\right|&\leq C\epsilon \|\tau_\epsilon\|_{\alpha+\frac 12,\beta} \\
        &\leq C'\epsilon \left(  \|f_D\|_{\alpha,\beta} + \|f_N\|_{\alpha+\frac 12,\beta}\right)\,,
        \end{aligned}
    \end{equation}
    with a similar proof to Lemma~\ref{lem:trunc_op}. Using the same
    steps as the proof of Lemma~\ref{lem:op_bd} and
    Theorem~\ref{thm:trunc_IE}, we can show that
    \begin{equation}
    \begin{aligned}
        |\cS^{l}_{\tGamma}[\tau_{\epsilon}-\tau] (\bx)|&\leq C \|\tau_{\epsilon}-\tau\|_{\alpha+\frac 12,\beta} \\
        &\leq C'\epsilon \left(  \|f_D\|_{\alpha,\beta} + \|f_N\|_{\alpha+\frac 12,\beta}\right)\,.
        \end{aligned}
    \end{equation}
    A similar proof shows that
    \begin{equation}
        |\cD^{l}_{\tGamma_{\epsilon}}[\sigma_\epsilon](\bx) -\cD^{l}_{\tGamma}[\sigma](\bx)|< C'\epsilon \left(  \|f_D\|_{\alpha,\beta} + \|f_N\|_{\alpha+\frac 12,\beta}\right)\,.
    \end{equation}
    Summing these two bounds and applying Theorem~\ref{thm:IE_outgoing} gives that
    \begin{equation}
    \begin{aligned}
        \left|\cS^{l}_{\tGamma_{\epsilon}}[\tau_\epsilon]-\cD^{l}_{\tGamma_{\epsilon}}[\sigma_\epsilon](\bx) -u^l(\bx)\right| &=  \left|\cS^{l}_{\tGamma_{\epsilon}}[\tau_\epsilon]-\cD^{l}_{\tGamma_{\epsilon}}[\sigma_\epsilon](\bx) -\cS^{l}_{\tGamma}[\tau]+\cD^{l}_{\tGamma}[\sigma](\bx)\right|\\
        &<2C\epsilon \left(  \|f_D\|_{\alpha,\beta} + \|f_N\|_{\alpha+\frac 12,\beta}\right).
        \end{aligned}
    \end{equation}
    Repeating the same argument for~$u^r$ gives the desired result.
\end{proof}
