\section{Properties of the partial Fourier transforms of $w^{l,r}$}
\label{app:a}
Recall that the kernels $w^{l,r}$ are functions of $x_{1} - y_{1}$ and thus their analytical properties can be understood by
studying their partial Fourier transform $\tilde{w}^{l,r}$, given by
\begin{equation}
w^{l,r}(\bx; \by) = \int_{\gamma} e^{i \xi (x_{1} - y_{1})} \tilde{w}^{l,r}(\xi; x_{2}, y_{2}) d\xi\,, 
\end{equation} 
for an appropriately chosen contour $\gamma$. In this section, we establish
several key analytical properties of the functions $\tilde{w}^{l,r}$. For
notational convenience, we drop the superscripts $l,r$. In particular, let $q$
be a piecewise continuous function with compact support in $[-d,d]$, let $G =
G_{0} + w$ denote the outgoing Green's function of $\Delta+k^2(1+q(x_2)),$ where
$G_{0}$ is, as before, the free-space Green's function for wave number $k^2.$
Finally let $\tilde{w}$ denote the partial Fourier transform of $w$ in the $x_1$-direction.

We denote the four open quadrants of the complex plane by $Q_1,\, Q_2,\, Q_3,\, Q_4,$ i.e., $Q_1=\{z:\: \Re z>0,\Im z>0\}$ and $Q_j=e^{\frac{i(j-1)\pi}{2}}Q_1,$ for $j=2,3,4.$ For $\theta <\pi/2,$ let $S_{\theta}$ denote the union of the sectors in $\oQ_{2} \cup \oQ_{4}$ given by
\begin{equation}
    S_{\theta} = \left\{\xi: \, \frac{\pi}{2} \leq \arg{\xi} \leq \frac{\pi}{2}+\theta \right\} \cup \left\{\xi: \, -\frac{\pi}{2}\leq \arg{\xi} \leq \theta - \frac{\pi}{2}\right\}. 
\end{equation}
The analysis of $\tilde{w}$ requires integrals involving the function $\astar(\xi):=-\sqrt{\xi^2-k^2}$ for $\xi \in \mathbb{C},$ which has branch points at $\xi = \pm k.$ The following definition fixes our choice of branch cuts.
\begin{definition}
    Let~$\sqrt{\cdot}$ be chosen to have the branch cut along the
    negative real axis, such that~$\Re \sqrt{z}\geq 0$.

    We define the functions $\astar$ by
    \begin{equation}    
        \astar(\xi) = -\sqrt{i(\xi-k)}\sqrt{-i(\xi+k)}\label{eq:w_c_formula},
    \end{equation}
    which has a branch cut pointing vertically into the lower half plane at $-k$ and a branch cut pointing vertically
    into the upper half plane at $k$.  Along the real axis where $|\xi|<k,$ $\astar(\xi)=i\sqrt{k^2-\xi^2},$ and where $|\xi|>k,$ $\astar(\xi)=-\sqrt{\xi^2-k^2}.$ $\astar(\xi)$ maps $\oQ_{2}\cup\oQ_{4}$ into $\oQ_{2}$ and in $S_{\theta}$ is equal to $i \sqrt{k^2 - \xi^2}$.
\end{definition}

Returning to $\tilde{w},$ we begin by observing that for fixed $y_{2}$ and $\xi$, $\tilde{w}$ is the unique outgoing solution to the ordinary differential equation (ODE)
\begin{equation}
L_{\xi}[\tilde{w}] := (\partial^{2}_{x_{2}} - \xi^2 + k^2 (1+q)) \tilde{w} = -\frac{1}{2\astar(\xi)} k^2 q(x_{2}) e^{\astar(\xi)|x_{2} - y_{2}|};
\end{equation}
the outgoing  condition implies that $\tilde{w}'(x_2) = {\rm sign}(x_2)
\alpha_k(\xi) \tilde{w}(x_2)$ for all $|x_2| >d.$ To analyze the behavior of
solutions to this ODE, we begin by constructing the outgoing resolvent of
$L_{\xi},$ denoted by $g(\xi; x_{2}, z_{2}),$ and defined so that the solution
of $L_{\xi}[v] = f$ is given by
\begin{equation}
\label{eq:out_res}
v(x_{2}) = \int_{-\infty}^{\infty} g(\xi; x_{2}, z_{2}) f(z_{2}) dz_{2} \, ,
\end{equation}
provided $f$ decays sufficiently rapidly at $\infty$. 
For $x_{2} > d$, $L_{\xi}$ reduces to $(\partial^{2}_{x_{2}} - \xi^2 + k^2)$ and its two linearly independent solutions are given by $e^{\pm \astar(\xi) x_{2}}$.  
Following the analysis in~\cite[Appendix A]{epstein2023solvinga}, the outgoing resolvent can be expressed explicitly as
\begin{equation}
g(\xi; x_{2}, z_{2}) := \frac{1}{W(\xi)} \left[ \tilde{u}_{+}(\xi; x_{2}) \tilde{u}_{-}(\xi; z_{2}) \chi_{z_{2} {\le} x_{2}} + \tilde{u}_{-}(\xi; x_{2}) \tilde{u}_{+}(\xi; z_{2}) \chi_{z_{2} > x_{2}}  \right] \,,
\end{equation}
where $\tilde{u}_{\pm}$ are particular solutions of $L_{\xi}$ satisfying
    \begin{align}\label{eq:basic}
    \begin{split}
        L_\xi \tilde{u}_\pm (\xi;x_2)= 0, \qquad &x_2 \in \mathbb{R}\\
        \tilde{u}_\pm (\xi;x_2) = e^{\pm\astar (\xi) x_2}, \qquad &\pm x_2 > d\,,
    \end{split}
    \end{align}
$W_{\xi}$ is their Wronskian given by
    \begin{align*}
        W(\xi) := \tilde{u}_- (\xi;x_2) \partial_{x_2} \tilde{u}_+ (\xi;x_2) - \tilde{u}_+ (\xi;x_2) \partial_{x_2} \tilde{u}_- (\xi; x_2) \,,
    \end{align*}
 and $\chi_{S}$  is the indicator function of the set $S$.

In the following lemma, we show that the functions $\tilde{u}_{\pm}$ are uniquely defined, and describe their region of analyticity.

 \begin{lemma}\label{lemma:basic}
    For every $\xi \in \mathbb{C}$, $\tilde{u}_{\pm}$ satisfying equation~\eqref{eq:basic} are uniquely defined. 
    Moreover, when viewed as a function of $\zeta = \astar(\xi)$, the functions $\tilde{u}_{\pm}$, and $\partial_{x_{2}} \tilde{u}_{\pm}$ are entire in $\zeta$.
\end{lemma}
\begin{proof}
The proof is standard, see \cite{deift1979inverse} for example. We sketch the
proof for $\tilde{u}_-.$ Let
$$v (\xi; x_2) := (e^{\astar(\xi)x_2}\tilde{u}_- (\xi;
x_2), \partial_{x_2} e^{\astar(\xi)x_2} \tilde{u}_- (\xi; x_2))^T$$
and
$$
B(\zeta; x_2) := \begin{pmatrix} 0 & 1\\ -k^2 q(x_2) & 2 \zeta
    \end{pmatrix} \, .$$ 
 Then \eqref{eq:basic} is equivalent to
    $$\partial_{x_2} v (\xi; x_2) =
    B(\astar(\xi); x_2) v (\xi; x_2), \quad v (\xi; -d) = \left(1, 0\right),$$
    which in integral form is given by
    \begin{align}\label{eq:vA}
    v(\xi; x_2) = v(\xi; -d) + \int_{-d}^{x_2} B(\astar (\xi); z) v(\xi; z) {\rm d} z.
    \end{align}
    As in\cite{deift1979inverse}, we iterate the above Volterra integral equation, and use the initial data, to obtain
    \begin{align}\label{eqn:neum}
        %v(\xi; x_2) = (v(\xi; -d)) + \sum_{j=0}^\infty \fA_{\astar (\xi)}^{(j)}[v (\xi; \cdot)] (x_2),
        v(\xi; x_2) = (1,0)^T + \sum_{j=1}^\infty \fB_{\astar (\xi)}^{(j)}[(1,0)^T] (x_2),
    \end{align}
    with 
    \begin{align}
       \fB_{\astar (\xi)}^{(j)} [w] (x_2):= \int_{-d}^{x_2}\int_{-d}^{z_1}\cdots \int_{-d}^{z_{j-1}} B(\astar (\xi); z_1) \cdots B(\astar (\xi); z_j) w(z_j)\,\dd z_j \cdots \dd z_1.
    \end{align}
    Noting that $\|B(\zeta,z)\| \le \sqrt{4|\zeta|^2+k^2 \|q\|_\infty + 1}$ we find that 
    $$|\fB_{\astar (\xi)}^{(j)} [w] (x_2)| \le \frac{[(x_2+d)\,\sqrt{4|\zeta|^2+k^2 \|q\|_\infty + 1}]^j}{j!}\|w\|_\infty,$$
    where the bound holds for both components. It is then straightforward to show that the sum in (\ref{eqn:neum}) converges uniformly for $\zeta$ bounded with
    $$|v(\xi;x_2)| \le \exp((x_2+d)\,\sqrt{4|\zeta|^2+k^2 \|q\|_\infty + 1}).$$
    More refined bounds can be found for the region with $x_2 >d$ by restarting the Volterra integral equation at $x_2=d.$ For $\Re \zeta \le 0, \zeta \neq 0,$ at the expense of a multiplicative constant independent of $\zeta$ and $x_2,$ we can replace $x_2$ in the above estimate by $\min (x_2,d).$ Since each term in (\ref{eqn:neum}) is clearly analytic in $\zeta,$ and the convergence of the sum is uniform on compact sets, the analyticity of $v(\xi;x_2)$ follows immediately.

    Finally, we observe that $\tilde{u}_+ (\xi; x_2) = \tilde{u}_-^\sharp (\xi; -x_2)$, where $\tilde{u}_-^\sharp$ is the solution $\tilde{u}_-$ of \eqref{eq:basic} with $q(x_2)$ replaced by $q(-x_2)$. Thus we have established the analyticity of $\tilde{u}_\pm$ and $\partial_{x_2} \tilde{u}_\pm$, and the proof is complete.
\end{proof}

Since the outgoing resolvent $g$ has $W(\xi)$ in its denominator, the zeros of the Wronskian correspond to poles of $g$. In the following lemma, we show that the Wronskian has finitely many zeros on the real axis, and provide a uniform lower bound on $W$ outside of a ball in $\oQ_{2} \cup \oQ_{4}$. We denote this region by $\xiset :=\{\oQ_2 \cup \oQ_4 : |\xi| \ge \ximin\}$,  assuming that $q$ is not identically zero, we set $\ximin := k \sqrt{1+\|q\|_\infty}$.
\begin{lemma}
\label{lemma:w-est}
The Wronskian $W(\xi)$ has a finite number of zeros $\{\pm \xi_j\}$, all of which are real and have absolute value in the interval $[k, \ximin)$. %$[k, k \sqrt{1+\|q\|_\infty})$. %greater than $k$. 
%Finally, for any $\ximin > k \sqrt{1+\|q\|_\infty}$,
Moreover, there exists a constant $c>0$ such that $|W(\xi)| \ge c|\xi|$ uniformly in $\xi \in \xiset$. %$\xi \in \{\oQ_2 \cup \oQ_4 : |\xi| \ge \ximin\}$.
%$\xi \in \{\oQ_2 \cup \oQ_4 : |\xi| \ge k \sqrt{1+\|q\|_\infty}\}$.
\end{lemma}
The proof of this result is classical; we include it only for completeness. In particular, the bound \eqref{eq:bd_phi} follows immediately from \cite[Lemma 1 (i)]{deift1979inverse}.
\begin{proof}
The self-adjointness of the operator $\partial^2_{x_2} +k^2 (1 + q(x_2))$ implies that all the zeros of $W$ must lie on the real or imaginary axes.
    However, the imaginary axis and real interval $(-k, k)$ cannot contain zeros of $W$, as these zeros would correspond to nontrivial outgoing solutions $u$ to $L_\xi u = 0$ (see, e.g. \cite[Proposition 1.4]{tang2007potential}).
    For $\xi\in \mathbb{R}$ satisfying $|\xi| > k$, $W(\xi) = 0$ if and only if $\tilde{u}_+ (\xi;\; \cdot)$ is an eigenfunction of $\partial^2_{x_2} + k^2 q (x_2)$ with eigenvalue $\xi^2 - k^2$.
    Since $q$ is compactly supported and piecewise continuous, %it is well known (see, e.g. \cite[Corollary 9.43]{Teschl}) that 
    the operator $\partial^2_{x_2} + k^2 q(x_2)$ has a finite number of positive eigenvalues, all of which are less than $k^2 \|q\|_\infty$. Indeed, by the Courant-Fischer min-max principle \cite{RS4}, each positive eigenvalue of $\partial^2_{x_2} + k^2 q(x_2)$ is bounded above by a distinct positive eigenvalue of $\partial^2_{x_2} + k^2 \|q\|_\infty \chi_{x_2 \in \supp q}$ (see also \cite[Corollary 9.43]{Teschl}). Thus we have shown that $W$ has a finite number of zeros, all of which lie in $(-\ximin, -k] \cup [k, \ximin) \subset \mathbb{R}$. %$(-k \sqrt{1+\|q\|_\infty}, -k] \cup [k, k \sqrt{1+\|q\|_\infty}) \subset \mathbb{R}$. %as desired.

    It remains to verify the growth condition for $W$. 
    Observe that for any $z<-d,$ $\tilde{u}_-(\xi;x_2)$ satisfies the integral equation 
    $$\tilde{u}_-(\xi;x_2) = e^{-\astar(\xi) x_2} - \int_{z}^{x_2} \frac{1}{\astar(\xi)}\sinh(\astar(\xi)(x_2-s))k^2q(s)\tilde{u}_-(\xi;s)\,{\rm d}s,$$
    where ${\chi}_{s>0} \sinh(\astar(\xi) s)/\astar(\xi)$ is the causal Green's function. In particular, setting $$\phi_-(\xi;x_2) := e^{\astar(\xi)x_2}\tilde{u}_-(\xi,x_2),$$ it follows straightforwardly that
    \begin{align}\label{eq:straightforward}
    \phi_-(\xi;x_2) = 1 - \int_{-\infty}^{x_2}\frac{e^{2\astar(\xi)(x_2-s)}-1}{2\astar(\xi)}k^2q(s)\phi_-(\xi;s)\,{\rm d}s =: 1 + \causal [\phi_- (\xi; \;\cdot)] (x_2).
    \end{align}
    Since $\Re \astar (\xi) \le 0$ for all $\xi \in \oQ_2 \cup \oQ_4$ and $\supp (q) \subseteq [-d,d]$,
    we have
    $$|\causal [\phi_- (\xi; \;\cdot)] (x_2)| \le \frac{C}{|\astar (\xi)|} \|\phi (\xi; \; \cdot) \|_{L^\infty[-d,d]}, \qquad \xi \in \oQ_2 \cup \oQ_4, \quad x_2 \in \mathbb{R}.$$
    Hence for all $\xi \in \oQ_2 \cup \oQ_4$ sufficiently large, $I-\causal$ is boundedly invertible on $L^\infty (\mathbb{R})$ with $\| (I - \causal)^{-1} - I \| \le C/|\xi|$. It then follows from \eqref{eq:straightforward} that
    \begin{align}\label{eq:bd_phi}
        \left|\phi_- (\xi; x_2) - 1\right| \le \frac{C}{|\xi|}, \qquad \xi \in \xiset, \quad x_2 \in \mathbb{R}.
    \end{align}
    %for any $\ximin > k$. 
    %where $\ximin := k \sqrt{1+\|q\|_\infty}$.
    Now, when $x_2 > d$,
    \begin{align}\label{eq:tildeu_minus}
        \tilde{u}_- (\xi;x_2) = a(\xi) e^{x_2 \astar (\xi)} + b(\xi) e^{-x_2 \astar (\xi)},
    \end{align}
    and thus
    \begin{align}\label{eq:W}
        W (\xi) = b(\xi) \astar (\xi), \qquad b(\xi) = \phi_- (\xi; x_2) - a(\xi) e^{2 x_2 \astar (\xi)}.
    \end{align}
    By \eqref{eq:bd_phi},
    \begin{align}\label{eq:b_bd}
        |b(\xi) - 1| \le \inf_{x_2 \in \mathbb{R}} \left( |\phi_- (\xi; x_2) - 1| + \left| a(\xi) e^{2 x_2 \astar (\xi)}\right|\right) \le \frac{C}{|\xi|} + |a(\xi)|\inf_{x_2 \in \mathbb{R}}\left|e^{2 x_2 \astar (\xi)}\right| = \frac{C}{|\xi|}
    \end{align}
    uniformly in $\xi \in \xiset \cap \{\Re \xi \ne 0\}$.
    Indeed, for any $\xi \in \xiset$ with $\Re\xi \ne 0$, we have %$\astar (\xi) \in \oQ_2$ and $\astar (\xi) \ne 0$, 
    $\Re \astar (\xi) < 0$, meaning that the last infimum in the above equation vanishes. %Finally, we use that
    Recalling Lemma \ref{lemma:basic} and the expression for $W$ in \eqref{eq:W}, we see that $b(\xi) = W(\xi)/\astar (\xi)$ is an analytic function of $\xi$ in the strip $\{|\Re \xi| < k/2\}$, hence the bound \eqref{eq:b_bd} extends to all $\xi \in \xiset$.
    Since $W$ does not vanish in $\xiset$, we have thus established the existence of a constant $c>0$ such that $|W (\xi)| \ge c |\xi|$ for all $\xi \in \xiset$.
\end{proof}

The following corollary is a straightforward consequence of Lemmas~\ref{lemma:basic} and~\ref{lemma:w-est}.
\begin{corollary}
The outgoing resolvent $g$ when viewed as a function $\zeta = \astar(\xi)$ is analytic in $\zeta$ with the exception of $\zeta_j = \astar(\xi_{j})$.
\end{corollary}

In the following lemma, we turn our attention to properties of solutions to $L_{\xi} v = f$. In the remainder of the section, let %$\xiset :=\{\oQ_2 \cup \oQ_4 : |\xi| > \ximin\}$, and 
$\rho_{a,b}$, for $a<b$, denote the following piecewise linear function 
\begin{align}\label{eq:ls_def}
    \ls_{a,b}(y) := \begin{cases}
        0, & y < a\\
        y-a, & a \le y \le b\\
        b-a, & y > b
    \end{cases} \, .
\end{align}
\begin{lemma}\label{lemma:decay}
    Let $m \ge 0$ and suppose $f: \mathbb{C} \times \mathbb{R}^2 \to \mathbb{C}$ satisfies
    \begin{align}\label{eq:decay_g}
        |f(\xi; x_2, y_2)|\le \begin{cases}
            C x_2^m e^{\Re \astar (\xi) (x_2 - d + |y_2-d|)}, & x_2 > d\\
            C e^{\Re \astar (\xi) |x_2 - y_2|}, & -d \le x_2 \le d\\
            C|x_2|^m e^{\Re \astar (\xi) (|x_2 + d| + |y_2+d|)}, & x_2 < -d
        \end{cases}
    \end{align}
    uniformly in $(\xi; x_2, y_2) \in \xiset \times \mathbb{R}^2$. Then the solution $v$ to
    $
        L_\xi v (\xi;x_2,y_2) = f(\xi; x_2,y_2)
    $
    satisfies
    \begin{align}\label{eq:decay_v}
        |v(\xi; x_2, y_2)| \le
        \begin{cases}
            Cx_2^m e^{\Re \astar (\xi) (x_2 - d + |y_2-d|)} \left(\frac{1}{|\xi|^2}+\frac{\ls_{-d,d}(-y_2)+x_2-d}{|\xi|}\right), & x_2 > d\\
            Ce^{\Re \astar (\xi) |x_2-y_2|} \left(\frac{1}{|\xi|^2}+\frac{\ls_{x_2,d}(y_2)+\ls_{-x_2,d}(-y_2)}{|\xi|}\right), & -d \le x_2 \le d\\
            C|x_2^m| e^{\Re \astar (\xi) (|x_2 + d| + |y_2+d|)} \left(\frac{1}{|\xi|^2}+\frac{\ls_{-d,d}(y_2)+|x_2+d|}{|\xi|}\right), & x_2 < -d
        \end{cases}
    \end{align}
    uniformly in $(\xi; x_2, y_2) \in \xiset \times \mathbb{R}^2$. Moreover, 
    if $f(\xi; x_2, y_2) = \mathfrak{f} (\astar (\xi); x_2, y_2)$ for some function $\mathfrak{f} (\zeta; x_2, y_2)$ which is analytic in $\zeta \in \mathbb{C} \setminus \{\astar (\xi_j)\}$, then $v(\xi; x_2, y_2) = \mathfrak{v} (\astar (\xi); x_2, y_2)$ with $\mathfrak{v} (\zeta; x_2, y_2)$ analytic in $\zeta \in \mathbb{C}\setminus \{\astar (\xi_j)\}$.
\end{lemma}

\begin{proof}
The analyticity of $v$ in $\zeta$ follows from~\eqref{eq:out_res}, and the analyticity of $f$ and the outgoing resolvent $g$. 

It remains to verify the decay estimates \eqref{eq:decay_v}.
Observe that \eqref{eq:out_res} implies
    \begin{align*}
        |v (\xi; x_2, y_2)| &\le C\frac{e^{\Re \astar (\xi) x_2}}{|W (\xi)|} \Big(
        \int_{-\infty}^{-d} |z_2|^me^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (|z_2 + d| + |y_2+d|)} {\rm d} z_2\\
        &\qquad + \int_{-d}^d |\tilde{u}_- (\xi; z_2)|e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 + \int_d^{x_2} z_2^m|\tilde{u}_- (\xi; z_2)|e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)}{\rm d} z_2
        \Big)\\
        &+ C\frac{|\tilde{u}_- (\xi; x_2)|}{|W(\xi)|} \int_{x_2}^\infty z_2^m e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)} {\rm d} z_2
    \end{align*}
    uniformly in $(\xi;x_2, y_2) \in \xiset \times (d,\infty)\times\mathbb{R}$. 
    By %\eqref{eq:DT}, 
    \eqref{eq:bd_phi}, the above factors of $\tilde{u}_- (\xi; z_2)$ are well approximated by $e^{-z_2 \astar (\xi)}$, up to terms that decay faster in $|\xi|$. Therefore,
    \begin{align*}
        |v (\xi; x_2, y_2)| &\le C\frac{e^{\Re \astar (\xi) x_2}}{|W (\xi)|} \Big(
        \int_{-\infty}^{-d}|z_2|^m e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (|z_2 + d| + |y_2+d|)} {\rm d} z_2\\
        &\qquad + \int_{-d}^d e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 + \int_d^{x_2}z_2^m e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)}{\rm d} z_2
        \Big)\\
        &+ C\frac{e^{-\Re \astar (\xi) x_2}}{|W(\xi)|} \int_{x_2}^\infty z_2^m e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)} {\rm d} z_2
    \end{align*}
    uniformly in $(\xi;x_2, y_2) \in \xiset \times (d,\infty)\times\mathbb{R}$.
    These integrals are estimated by
    \begin{align}\label{eq:integral_bounds}
        \begin{split}
        &\int_{-\infty}^{-d} |z_2|^m e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (|z_2 + d| + |y_2+d|)} {\rm d} z_2 \le 
            \frac{C}{|\xi|} e^{\Re \astar (\xi) d} e^{\Re \astar (\xi) |y_2+d|},\\
            &\int_{-d}^d e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 \\
            &\qquad =
        -\frac{1}{2\Re \astar (\xi)} (e^{-\Re \astar (\xi)d} e^{\Re \astar (\xi)|y_2-d|} - e^{\Re \astar (\xi)d}e^{\Re \astar (\xi)|y_2+d|})
        +
        \ls_{-d,d} (-y_2) e^{-y_2 \Re \astar (\xi)},\\
        &\int_d^{x_2}z_2^m e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)}{\rm d} z_2 \le x_2^m (x_2 - d)e^{-\Re\astar (\xi) d}e^{\Re\astar (\xi)|y_2-d|},\\
        &\int_{x_2}^\infty z_2^m e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)} {\rm d} z_2 \le \frac{C}{|\xi|} x_2^m e^{-\Re \astar (\xi) d} e^{2 \Re \astar (\xi) x_2} e^{\Re\astar (\xi)|y_2-d|},
        \end{split}
    \end{align}
    which implies that
    \begin{align*}
        |v (\xi; x_2, y_2)| \le \frac{C}{|W(\xi)|} e^{\Re \astar (\xi)(x_2 - d + |y_2 - d|)} \left( \frac{x_2^m}{|\xi|} + \ls_{-d,d} (-y_2) + x_2^m (x_2 - d) \right)
    \end{align*}
    uniformly in $(\xi;x_2, y_2) \in \xiset \times (d,\infty)\times\mathbb{R}$. The bound in \eqref{eq:decay_v} for $x_2 > d$ then follows from the growth condition $|W(\xi)| \ge c |\xi|$ established in Lemma \ref{lemma:w-est}.

    Applying this result to the function $v(\xi; -x_2, -y_2)$, we obtain the desired bound for $x_2 < -d$.
    It remains to establish \eqref{eq:decay_v} when $-d \le x_2 \le d$. To this end, we again use \eqref{eq:out_res} to write
    \begin{align*}
        |v (\xi; x_2, y_2)| &\le C\frac{|\tilde{u}_+ (\xi; x_2)|}{|W (\xi)|} \Big(
        \int_{-\infty}^{-d} |z_2|^me^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (|z_2 + d| + |y_2+d|)} {\rm d} z_2\\
        &\hspace{5cm}+ \int_{-d}^{x_2} |\tilde{u}_- (\xi; z_2)|e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 \Big)\\
        &+ C\frac{|\tilde{u}_- (\xi; x_2)|}{|W (\xi)|}\Big( \int_{x_2}^{d} |\tilde{u}_+ (\xi; z_2)|e^{\Re \astar (\xi) |z_2-y_2|}{\rm d} z_2
        \\
        &\hspace{5cm} + \int_{d}^\infty z_2^m e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)} {\rm d} z_2\Big),
    \end{align*}
    and apply %\eqref{eq:DT} 
    \eqref{eq:bd_phi} and the analogous bound for $\tilde{u}_+$ to obtain
    \begin{align}\label{eq:v_bd_mid}
        \begin{split}
        |v (\xi; x_2, y_2)| &\le C\frac{e^{\Re \astar (\xi) x_2}}{|W (\xi)|} \Big(
        \int_{-\infty}^{-d} |z_2|^me^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (|z_2 + d| + |y_2+d|)} {\rm d} z_2\\
        &\hspace{5cm}+ \int_{-d}^{x_2} e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 \Big)\\
        &+ C\frac{e^{-\Re \astar (\xi) x_2}}{|W (\xi)|}\Big( \int_{x_2}^{d} e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|}{\rm d} z_2
        \\
        &\hspace{5cm} + \int_{d}^\infty z_2^m e^{\Re \astar (\xi) z_2}e^{\Re \astar (\xi) (z_2 - d + |y_2-d|)} {\rm d} z_2\Big)
        \end{split}
    \end{align}
    uniformly in $(\xi;x_2, y_2) \in \xiset \times [-d,d]\times\mathbb{R}$. A direct calculation reveals that
    \begin{align*}
        &\int_{-d}^{x_2} e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2\\
        &\hspace{0.5cm} = -\frac{1}{2 \Re \astar(\xi)} e^{\Re \astar (\xi) y_2} \left( e^{-2 \Re \astar (\xi) \min \{x_2, y_2\}} - e^{2\Re \astar (\xi) d}\right)\chi_{(-d,\infty)} (y_2)+ e^{-\Re \astar (\xi) y_2} \ls_{-x_2,d}(-y_2),
    \end{align*}
    where %$y_2 \mapsto \frac{x_2+d}{2d}\ls \left( \frac{2d}{x_2+d} \left(\frac{x_2 - d}{2} - y_2 \right)\right)$ is the continuous function that linearly interpolates the points $(-d, x_2+d)$ and $(x_2, 0)$, and is constant in the intervals $y_2 \le -d$ and $y_2 \ge x_2$.
    $\chi_I$ is the indicator function of the set $I$.
    Since $\ls_{-x_2,d} (-y_2)$ vanishes for all $y_2 > x_2$, it follows that
    \begin{align*}
        &e^{\Re \astar (\xi) x_2}\int_{-d}^{x_2} e^{-\Re \astar (\xi) z_2}e^{\Re \astar (\xi) |z_2-y_2|} {\rm d} z_2 \\
        &\hspace{0.5cm} = -\frac{1}{2 \Re \astar(\xi)} \left( e^{\Re \astar (\xi) |x_2-y_2|} - e^{\Re \astar (\xi) (x_2+y_2+2d)}\right)\chi_{(-d,\infty)} (y_2)+ e^{\Re \astar (\xi) |x_2-y_2|} \ls_{-x_2,d} (-y_2).
    \end{align*}
    The first integral in \eqref{eq:v_bd_mid} was already controlled in \eqref{eq:integral_bounds}, while the third and fourth integrals in \eqref{eq:v_bd_mid} evaluated at $(x_2, y_2)$ are the same as the first and second evaluated at $(-x_2, -y_2)$. %follow immediately from bounds on the first and second by symmetry.
    Combining these bounds and again using that $W(\xi) \ge c |\xi|$, %and using that
    % \begin{align*}
    %     \frac{x_2+d}{2d}\ls \left( \frac{2d}{x_2+d} \left(\frac{x_2 - d}{2} - y_2 \right)\right) \le \ls (-y_2 + x_2 - d)
    % \end{align*}
    we obtain
    \begin{align*}
        |v (\xi; x_2, y_2)| &\le \frac{C}{|\xi|^2} \left(e^{\Re \astar (\xi) |x_2 -y_2|} + e^{\Re \astar (\xi) (x_2+d+|y_2+d|)}+ e^{\Re \astar (\xi) (-x_2+d+|y_2-d|)}\right)\\
        &\hspace{5cm} + \frac{C}{|\xi|}e^{\Re \astar (\xi) |x_2 -y_2|} (\ls_{x_2,d}(y_2) + \ls_{-x_2,d}(-y_2))
    \end{align*}
    uniformly in $(\xi;x_2, y_2) \in \xiset \times [-d,d]\times\mathbb{R}$.
    Since $\pm x_2 + d + |y_2 \pm d| \ge |x_2 - y_2|$ for all $-d \le x_2 \le d$, we have established the remaining bound in \eqref{eq:decay_v} and the result is complete.
\end{proof}

We now turn our attention to the main result of this appendix which summarizes estimates on the partial Fourier transform of the resolvent kernel.

\begin{theorem}\label{prop:suitable}
Suppose $q: \mathbb{R} \to [0,\infty)$ is piecewise continuous with $\supp (q)
  \subset [-d,d]$.  For fixed $(x_{2}, y_{2}) \in \bbR^2$, the partial Fourier transform $\tilde{w}(\xi; x_{2}, y_{2})$ of the resolvent kernel has a finite set of real
  poles denoted by $\{\pm\xi_{j}:\:j=1,2,\ldots n_{p}\},$ all of which have
  modulus greater than $k.$ Furthermore, it takes the form
\begin{equation}
      \tilde{w}(\xi;x_2,y_2) =
            e^{\astar(\xi)(|x_2\mp d|+|y_2 \mp d|)} A_{\pm} (\xi, y_2), \qquad A_{\pm} (\xi,y_2) = \begin{cases}
                A_{\pm,+}(\xi), & y_2 > d\\
                A_{\pm,0}(\xi, y_2), & |y_2| \le d\\
                A_{\pm,-}(\xi), & y_2 < -d
            \end{cases}       \label{eq:waveguide_def}
\end{equation}
for all $\pm x_2 > d$, where the $A_{\pm}$ are of the form
\begin{align}\label{eq:B_pm}
    A_\pm (\xi, y_2) = \frac{1}{\astar (\xi)}B_{\pm} (\astar (\xi), y_2), \qquad \xi \in \mathbb{C}, \quad y_2 \in \mathbb{R},
\end{align}
with the functions $B_\pm (\zeta, y_2)$ analytic in $\zeta \in \mathbb{C} \setminus \{ \astar (\xi_j) \}$. 
For any $j \ge 0$, the functions $\partial^{j}_\zeta B_\pm (\zeta, y_2)$ are uniformly bounded over compact subsets of $(\mathbb{C} \setminus \{\astar ( \xi_j)\})\times \mathbb{R}$.
Moreover, there exists a constant $\ximin > 0$ such that,
\begin{align}\label{eq:decay_A}
    |\partial_{\xi}^jA_{\pm}(\xi,y_2)| \leq \frac{C_j}{|\xi|^3} \left( 1 + |\xi| \ls_{-d,d} (\mp y_2) \right), \qquad \xi \in \xiset, \quad y_2 \in \mathbb{R}.
\end{align}
Finally, when $-d \le x_2 \le d$ and $-d \le y_2 \le d$,
\begin{align*}
    \tilde{w}(\xi;x_2,y_2) =
            e^{\astar(\xi)|x_2 - y_2|} A_{0,0} (\xi, x_2,y_2),
\end{align*}
where $A_{0,0} (\xi, x_2, y_2) = B_{0,0} (\astar (\xi), x_2, y_2)/\astar (\xi)$ with $B_{0,0} (\zeta, x_2, y_2)$ analytic in $\zeta \in \mathbb{C} \setminus \{\astar (\xi_j)\}$ and $\partial^j_\zeta B_{0,0} (\zeta, x_2, y_2)$ uniformly bounded over compact subsets of $(\mathbb{C} \setminus \{\astar ( \xi_j)\})\times \mathbb{R}$. For any $j \in \mathbb{N}_0$,
\begin{align}\label{eq:decay_A_00}
    |\partial_{\xi}^jA_{0,0}(\xi,x_2,y_2)| \leq \frac{C_j}{|\xi|^3} \left( 1 + |\xi| (\ls_{x_2,d} (y_2) + \ls_{-x_2, d}(-y_2))\right)
\end{align}
uniformly in $\xi \in \xiset$ and $(x_2, y_2) \in [-d,d]^2$.
\end{theorem}

\begin{proof}
    Recall that the function $\tilde{w} (\xi; x_2, y_2)$ satisfies $L_\xi \tilde{w}(\xi;x_2,y_2) = f(\xi; x_2, y_2)/\astar (\xi)$, where
    \begin{align*}
        f(\xi; x_2, y_2) := -\frac{1}{2} k^2 q(x_2) e^{\astar (\xi) |x_2-y_2|}
    \end{align*}
    satisfies the assumptions of Lemma \ref{lemma:decay} with $m=0$. It follows that $\astar (\xi) \tilde{w} (\xi; x_2, y_2)$  
    is analytic in $\astar (\xi) \in \mathbb{C} \setminus \{\astar (\xi_j)\}$.

    Since $q$ is compactly supported in $[-d,d]$, it follows from \eqref{eq:out_res} and the definition of $f$ that $\tilde{w} (\xi;x_2,y_2) e^{-(|x_2 \mp d| + |y_2 \mp d|)\astar (\xi)}$ is independent of $\pm x_2 > d$, and constant in $y_2$ over the intervals $y_2 > d$ and $y_2 < -d$. We conclude that 
    \begin{align}\label{eq:w_A}
        \tilde{w}(\xi;x_2,y_2) =
            e^{\astar(\xi)(|x_2\mp d|+|y_2 \mp d|)}A_{\pm}(\xi, y_2), \qquad \pm x_2 > d, \quad y_2 \in \mathbb{R},
    \end{align}
    where the $A_{\pm} (\xi, y_2)$ are constant in $y_2$ over the intervals $y_2 > d$ and $y_2 < -d$, and are 
    of the form \eqref{eq:B_pm} with the $\partial^{j}_\zeta B_\pm (\zeta, y_2)$ locally bounded by continuity. Lemma \ref{lemma:decay} then implies that
    \begin{align*}
        |A_{\pm}(\xi,y_2)| \leq \frac{C}{|\xi|^3} \left( 1 + |\xi| \ls_{-d,d} (\mp y_2) \right), \qquad    \xi \in \xiset , \quad y_2 \in \mathbb{R}.
    \end{align*}
    The analogous properties of $A_{0,0}$ follow from parallel arguments, thus we have verified
    that $\astar (\xi) \tilde{w} (\xi; x_2, y_2)$ satisfies the bound in \eqref{eq:decay_v}.

    It remains to verify that derivatives of $A_\pm$ and $A_{0,0}$ satisfy the same decay estimate. 
    With $$\tilde{w}^{(j)}(\xi;x_2,y_2) := \partial^j_\xi \tilde{w}(\xi;x_2,y_2),$$ we have that $L_\xi \tilde{w}^{(j)}(\xi;x_2,y_2) = f_j (\xi;x_2, y_2)/\astar (\xi)$, where
    \begin{align*}
        \frac{f_j (\xi;x_2, y_2)}{\astar (\xi)} := 
        \partial^j_\xi \frac{f(\xi; x_2, y_2)}{\astar (\xi)} + 2j\xi \tilde{w}^{(j-1)} (\xi;x_2, y_2) + 2 \binom{j}{2}\tilde{w}^{(j-2)} (\xi;x_2, y_2).
    \end{align*}
    Since $\partial^j_\xi (f(\xi; \; \cdot, y_2)/\astar (\xi))$ vanishes outside $[-d,d]$ and satisfies     
    \begin{align*}
        |\partial^j_\xi (f (\xi; x_2, y_2)/\astar (\xi))| \le C (1+|y_2|)^j\frac{1}{|\xi|}e^{-\Re \astar (\xi) |x_2 - y_2|}, \qquad (\xi; x_2, y_2) \in \xiset \times [-d,d]\times \mathbb{R},
    \end{align*}
    the function $(1+|y_2|)^{-j}|\xi|\partial^j_\xi (f (\xi; x_2, y_2)/\astar (\xi))$ is bounded by the right-hand side of \eqref{eq:decay_g} with $m=0$. 
  An inductive argument shows that $f_{j}/\astar(\xi)$ satisfies \eqref{eq:decay_g} with $m=j-1$, and thus $\tilde{w}^{(j)}$ satisfies \eqref{eq:decay_v} with $m = j -1$. 
    %    Since we showed that $\xi \astar (\xi) \tilde{w} (\xi; x_2, y_2)$ also satisfies \eqref{eq:decay_g} with $m=0$, it follows from Lemma~\ref{lemma:decay} that $(1+|y_2|)^{-1}\astar (\xi) \tilde{w}^{(1)} (\xi; x_2, y_2)$ satisfies \eqref{eq:decay_v} with $m=0$. We then conclude by induction that for all $j \ge 1$, the function $(1+|y_2|)^{-j}\astar (\xi) \tilde{w}^{(j)} (\xi; x_2, y_2)$ satisfies \eqref{eq:decay_v} with $m=j-1$. Indeed,
 %   if $(1+|y_2|)^{-\ell}\astar (\xi)\tilde{w}^{(\ell)} (\xi; x_2, y_2)$ satisfies \eqref{eq:decay_v} with $m=\ell-1$ for every $\ell < j$, then the functions $(1+|y_2|)^{-j}\xi \astar (\xi)\tilde{w}^{(j-1)} (\xi; x_2, y_2)$ and $(1+|y_2|)^{-j}\astar (\xi)\tilde{w}^{(j-2)} (\xi; x_2, y_2)$ satisfy \eqref{eq:decay_g} with $m=j-1$, which in turn implies that $(1+|y_2|)^{-j}\astar (\xi)\tilde{w}^{(j)} (\xi; x_2, y_2)$ satisfies \eqref{eq:decay_v} with $m=j-1$. 
        It then follows from \eqref{eq:w_A} that
    \begin{align*}
        |\partial_{\xi}^jA_{\pm}(\xi,y_2)| \leq \frac{C_j}{|\xi|^3} \left( 1 + |\xi| \ls_{-d,d} (\mp y_2) \right)(1+|y_2|)^j, \qquad \xi \in \xiset, \quad y_2 \in \mathbb{R}.
    \end{align*}
    Since $A_\pm (\xi, \cdot)$ is constant in the intervals $(-\infty,-d)$ and $(d,\infty)$, the factor $(1+|y_2|)^j$ can be absorbed into $C_j$. Similarly, the definition of $A_{0,0}$ implies \eqref{eq:decay_A_00}
    and the proof is complete.
\end{proof}

\begin{corollary}
\label{cor:tw-analyticity}
For all $\xi \neq \astar(\xi_{j})$, the function $\tilde{w}(\xi; x_{2}, y_{2})$ admits an analytic extension to $x_{2}, y_{2} \in \GammaC \times \GammaC$.
\end{corollary}
\begin{proof}
The result is an immediate consequence of equation~\eqref{eq:waveguide_def}.
\end{proof}

\section{Kernel estimates}\label{sec:kern_est}
Having established properties of the partial Fourier transforms
$\tilde{w}^{l,r}$, we now turn our attention to the analytical properties of
$w^{l,r}$. The purpose of the section is twofold: a) to establish that the
kernels $k_{C}$, and $k_{D}$ defined in terms of $w^{l,r}$ lie in the required
$\cA_{\alpha}$ spaces, and b) obtain bounds for the kernels
$w^{l,r}(x_{1},x_{2}; 0, y_{2})$ that are uniform in $x_{1} \in \mathbb{R}$,
$|x_{2}|\leq \lt$, and $y_{2} \in \GammaC$.  These estimates are essential for
the proofs of Theorems~\ref{thm:trunc_sol} and~\ref{thm:kern_decay}.

Recall that
\begin{equation}
\label{eq:IFT-appb}
w^{l,r}(\bx; \by) = \int_{\gamma_{F}} e^{i \xi (x_{1} - y_{1})} \tilde{w}^{l,r}(\xi; x_{2}, y_{2}) d\xi\,, 
\end{equation}
and that
\begin{equation}\label{eqnB.2.31}
\begin{aligned}
k_{D}(x_{2},y_{2}) &= w^{r}(0,x_2;0,y_2)-w^{l}(0,x_2;0,y_2) = \int_{\gamma_{F}} (\tilde{w}^{r}(\xi; x_{2},y_{2}) - \tilde{w}^{l}(\xi; x_{2}, y_{2})) d\xi \,, \\
k_{C}(x_{2},y_{2}) &= \frac{\partial^2}{\partial x_1\partial y_1} \left(w^{r}(0,x_2;0,y_2)-w^{l}(0,x_2;0,y_2) \right) =  \int_{\gamma_{F}} \xi^2(\tilde{w}^{r}(\xi; x_{2},y_{2}) - \tilde{w}^{l}(\xi; x_{2}, y_{2})) d\xi \,.
\end{aligned}
\end{equation}

In the following lemma, we establish the analyticity of $w^{l,r}$.
\begin{lemma}\label{lem:kern_analytic}
    The formula~\eqref{eq:IFT-appb} defines $w^{l,r}(x_1,x_2;y_1,y_2)$ for any~$x_2,y_2\in \GammaC$ and~$x_1,y_1\in \bbR$. Further, $w^{l,r}(x_1,x_2;y_1,y_2)$ and their~$x_1$ and~$y_1$ derivatives are  analytic functions of~$x_2$ and~$y_2$ in the interiors of~$\GammaC$.
%
%    Moreover, there are locally bounded smooth functions~$C$ and~$C'$ of $(x_1,y_1)\in\bbR^2$ such that for~$x_2,y_2\in\GammaC$ we have 
%\begin{equation}
%    |w^{l,r}(x_1,x_2;y_1,y_2)| \leq \frac{C(x_1,y_1)e^{-k(|\Im x_2|+|\Im y_2|)}}{(|x_2|+|y_2|)^{\frac 12}}
%\end{equation}
%and
%\begin{equation}
%    |\partial_{x_1}w^{l,r}(x_1,x_2;y_1,y_2)| \leq \frac{C(x_1,y_1)e^{-k(|\Im x_2|+|\Im y_2|)}}{(|x_2|+|y_2|)^{\frac 32}}.
%\end{equation}
\end{lemma}
\begin{proof}
    From Corollary~\ref{cor:tw-analyticity}, it is known that~$\tilde w^{l,r}(\xi;x_2,y_2)$ can be analytically extended as a function of $x_2$ and $y_2$  from the real line to~$\GammaC$.  The result then follows from a combination of dominated convergence theorem, Morera's theorem and the estimates in Theorem~\ref{prop:suitable}. 
%Using dominated convergence theorem, and the estimates in~\ref{} it then follows that $w^{l,r}$ It is clear that~$w^{l,r}$ is continuous by the dominated convergence theorem. We may therefore use Morera's thoerem to prove that~$w^{l,r}(x_1,x_2;y_1,y_2)$ are separately analytic for~$x_2, y_2\in \GammaL\cup\Gamma_R$ with~$x_1,y_1$  fixed. The smoothness as a function of $(x_1,y_1)$ follows as we can freely differentiate this integral representation so long as at least one of $x_2$ or $y_2$ belongs to $\GammaL\cup\GammaR.$
%    
%    From  Proposition~\ref{prop:suitable}, and stationary phase, it follows that the functions~$w^{l,r}(x_1,x_2;y_1,y_2)$ satisfy the exponential decay estimates as $|\Im x_2|+|\Im y_2|\to\infty$ in $\GammaC\times\GammaC,$ so long as $(x_1,y_1)$ remains in a bounded set.
\end{proof}

This lemma and~\eqref{eqnB.2.31} lead easily to the following corollary.
\begin{corollary}
\label{cor:analytic-kcd}
The kernels $k_{C}(x_2,y_2)$ and $k_{D}(x_2,y_2)$ extend analytically to $x_{2},
y_{2}$ in the interior of $\GammaC.$
\end{corollary}


Next we turn our attention to the analysis of the asymptotics of $k_{C}$, and
$k_{D}$. The absence of the $e^{i \xi (x_{1} - y_{1})}$ term in their
definitions simplifies this analysis in comparison to the analysis
of $w^{l,r}$.  In order to establish that $k_{D} \in \cA_{\frac{3}{2}}$, and
$k_{C} \in \cA_{\frac{1}{2}}$, all that remains to be shown are the asymptotic
estimates~\ref{eq:cc-est} and~\ref{eq:cm-est}. Both of these follow from a
steepest descent argument, which we formulate as follows.

\begin{lemma}[Steepest descent]\label{lem:steep_de}
    Let~$ A(\xi)$ have the following properties:
    \begin{enumerate}[label=\roman*)]
    \item $A$ is an even function of $\xi.$
        \item The function~$ A(\xi)$ is analytic on~$\bbC$, apart from the branch cuts of~$\astar$ and finitely many                             poles on the real axis, and~$\xi=0,\pm k$ are not poles.
        \item There exists $p \in \mathbb{N}$ and $c>0$ such that for each
          $\delta >0$ there is a constant $C_\delta$ such that $|{A}(\xi)| \le
          C_\delta \lp(1+|\xi|)^{(p+1)}+e^{c|\Im\xi|}\rp$ for all $\xi \in
          \mathbb{C} \setminus T_\delta$ where $T_\delta$ is the union of
          $\delta$-balls around each of the poles and branch points.
    \end{enumerate}
    We denote by~$\gamma_F$ the contour defined by~$\Im \xi = -\tanh \Re\xi$, see Figure~\ref{fig_contours}.
    For~$z$ in the first quadrant  let $I(z)$ be the function defined by the  contour integral
    \begin{equation}
        I(z) = \int_{\gamma_F} e^{\astar(\xi) z}A(\xi) d\xi.\label{eq:steep_des}
    \end{equation}
    Then, there exist constants~$\{C_j:\: j=0,1,\dots\}$  depending on~$A$  such that, for any~$n\in\bbN$,  there is a constant $K_{n}$ so that
    \begin{equation}
        \left|I(z) - \frac{e^{ik z}}{\sqrt{z}}\sum_{j=0}^n\frac{C_j }{z^{j}}  \right|\leq e^{-k \Im z}\frac{K_{n}}{|z|^{n+\frac 32}}.\label{eq:de_asym}
    \end{equation}
  as $z$ tends to infinity in the first quadrant with~$|z|>4c.$
\end{lemma}
\begin{figure}[h]
    \centering
    \includegraphics[width = 0.6\textwidth]{contours.pdf}
    \caption{Plot in the $\xi$-plane showing $\gamma_F$ in blue and
      $w(t)$ in green. The cuts used in the definition of
      $\astar(\xi)$ are shown in red, for $k=5.$}\label{fig_contours}
\end{figure}
\begin{proof}
    To prove this expansion for $z$ in the first quadrant, recall that $\astar(\xi)$ maps $\oQ_{2} \cup \oQ_{4}$ into $\oQ_{2}$,  and therefore
    $\Re(\astar(\xi) z)\le 0$ for $\xi\in \oQ_2\cup \oQ_4$ and $z\in \oQ_1.$ 
    Suppose that $w$ is the contour given by
    \begin{equation}
    w(t) := kt \sqrt{2} e^{-3i\pi/8} \sqrt{1+\frac{t^2}{2} e^{i\pi/4} }  \,,
    \end{equation}
    for $t\in \bbR$. This contour is contained in the sector $\overline{S}_{\pi/4}$, is an odd function on the real axis, is such that both $w(t)$ and $A(w(t))$ are analytic functions of $t$ in a strip containing the real axis, and there exists a $\delta>0$ such that $w(t)$ and $A(w(t))$ have convergent Taylor expansions centered at $t=0$ in $|t|<\delta$.
    The purpose of this contour is three fold: to avoid the singularities of the integrand in $I(z)$, to ensure that the curve asymptotes at $\infty$ at an angle between $(\pi/2, \pi)$, and most importantly, so that the exponent $\astar(w(t))$ simplifies to
    \begin{equation}
    \begin{aligned}
    \astar(w(t)) &= i \sqrt{k^2 - w(t)^2} \,, \\
    &= ik - kt^2e^{-i\pi/4} \, .
    \end{aligned}
    \end{equation}
    It is not difficult to show, using the estimates above and Cauchy's theorem, that
    \begin{equation}
    \begin{aligned}
          I(z) &= \int_{w} e^{\astar z}A(\xi) d\xi\,\\
          &= e^{ikz}\int_{-\infty}^{\infty}
 e^{-kt^2 ze^{-i\pi/4} }  A(w(t)) w'(t) \, dt    \,.    
 \end{aligned}
    \end{equation}

    Letting $b(t) = A(w(t))w'(t)$ and using the properties of $A$, and $w$, we note that $b$ is an analytic
    function in a strip around the real axis, is an even function of $t$ and 
    there exist a constant $C_{0}$ such that
    \begin{equation}
      \begin{aligned}
       |w(t)| &\leq k(1+t^2)\,,\\
       |b(t)| &= |A(w(t)) w'(t)| \leq C_{\delta} \left( (1+|w|)^{(p+1)} + e^{c|\Im(w)|} \right) |w'(t)| \leq C_{0} e^{2ck(1+t^2)} \, ,
       \end{aligned}
    \end{equation}
    for $t \in \bbR$. Moreover, $b$ has a Taylor expansion centered at $t=0$
    valid in $|t_{0}|<\delta$, i.e. there exist coefficients $b_{j}$, $j=1,2,\ldots \infty$, and constants $R_{j}$ such that
    \begin{equation}
      \left| b(t) - \sum_{j=0}^{N} b_{j} t^{2j} \right| \leq R_{N} |t|^{2N+2} \, ,
    \end{equation} 
    for all $|t| < \delta$. To establish the asymptotic expansions
    in~\eqref{eq:de_asym}, we split the integral into two parts $|t|<\delta$ and
    the remainder.  For the infinite piece, we have
    \begin{equation}
    \begin{aligned}
   \left| \int_{\bbR \setminus [-\delta, \delta]} e^{-kt^2 ze^{-i\pi/4}} b(t) dt \right| &\leq \int_{\bbR \setminus [-\delta, \delta]} e^{-kt^2 |z|/2} |b(t)| dt \,, \\
   &\leq C_{0} e^{2ck} \int_{\bbR \setminus [-\delta, \delta]} e^{-kt^2 |z|/2 + 2ck t^2} dt \,,\\
   & \leq C_{0} e^{2ck} \frac{e^{-k\left(\frac{|z|}{2} - 2c \right)\delta^2}}{\left(\frac{|z|}{2} - 2c \right)\delta} \,, 
   \end{aligned}
   \label{eq:inf-steepest-est}
    \end{equation}
 where the last inequality follows from the fact that $|z|> 4c$
 and~\cite[\href{https://dlmf.nist.gov/7.8.E3}{(7.8.3)}]{NIST:DLMF}.

 For the integral on $[-\delta, \delta]$, we have
 \begin{equation}	
\int_{-\delta}^{\delta} e^{-kt^2 ze^{-i\pi/4}} b(t) dt = \int_{-\delta}^{\delta} e^{-kt^2 ze^{-i\pi/4}} \sum_{j=0}^{N} b_{j} t^{2j}  dt  + \int_{-\delta}^{\delta}  e^{-kt^2 ze^{-i\pi/4}} r_{N}(t) dt \, ,
 \end{equation}
 where $|r_{N}(t)| \leq R_{N} |t|^{2N+2}$. Using the identity
 \begin{equation}
 \int_{-\infty}^{\infty} e^{-kt^2 ze^{-i\pi/4}} t^{2j} dt = \frac{\Gamma(j+1/2)}{(kze^{-i\pi/4})^{j+1/2}} \, ,
 \end{equation}
 and an estimate similar to equation~\eqref{eq:inf-steepest-est}, we get
 \begin{equation}
 \int_{-\delta}^{\delta} e^{-kt^2 ze^{-i\pi/4}} \sum_{j=0}^{N} b_{j} t^{2j}  dt = \sum_{j=0}^{N} b_{j} \frac{\Gamma(j+1/2))}{(kze^{-i\pi/4})^{j+1/2}} + O\left( e^{-\frac{|z|}{2} k \delta^2}\right) \,.
 \label{eq:bounded-steepest-est}
 \end{equation}
The remainder term $r_{n}(t)$ can be bounded in a similar manner so that
\begin{equation}
\label{eq:bounded-steepest-est-rem}
\left| \int_{-\delta}^{\delta} e^{-kt^2 ze^{-i\pi/4}} r_N(t) dt \right| \leq \frac{C_{N}}{|z|^{N+3/2}} \,, 
\end{equation}
for some $C_{N}>0$. The proof then follows by combining
equations~\eqref{eq:inf-steepest-est},~\eqref{eq:bounded-steepest-est},
and~\eqref{eq:bounded-steepest-est-rem}.
\end{proof}
In the following lemma, we prove asymptotic estimates for the kernels $k_{C}$, and $k_{D}$.

\begin{lemma}
\label{lem:asymp-est-kcd}
Suppose $q^{l,r}$ satisfy the hypothesis in Theorem~\ref{prop:suitable}. Then the corresponding kernels $k_{C}$ and $k_{D}$ satisfy the estimates~\eqref{eq:cc-est} and~\eqref{eq:cm-est} with $\alpha = 3/2$ and $1/2$ respectively.
\end{lemma}

\begin{proof}
As an example, we  prove the estimate for~$k_D$ when~$x_2,y_2\in \Gamma_R$. The other cases  follow by  nearly identical proofs.
From Theorem~\ref{prop:suitable}, it follows that there exists functions $A_{++,r}(\xi)$ and $A_{++,l}(\xi)$ such that
$\tilde{w}^{l,r}(\xi; x_{2}, y_{2}) = A_{++,l,r}(\xi) e^{\astar(\xi)(x_{2} + y_{2} - 2d)}$. This implies that
\begin{equation}
k_{D}(x_{2}, y_{2}) = \int_{\gamma_{F}} (A_{++,r}(\xi) - A_{++,l}(\xi)) e^{\astar(\xi)(x_{2} + y_{2} - 2d)} d\xi \, .
\end{equation}
Furthermore, Theorem~\ref{prop:suitable} also implies that $A_{++,r}(\xi) - A_{++,l}(\xi)$ satisfy the conditions in
Lemma~\ref{lem:steep_de}. The result then follows from Lemma~\ref{lem:steep_de} since $x_{2} + y_{2} - 2d \in \overline{Q}_{1}$.

Similarly, the kernel~$k_C$ has the form 
        \begin{equation}
        k_C(x_2,y_2)=e^{ik (x_2+y_2-2d)}\int_{\gamma_{F}} \xi^2 \lp A_{++,r}(\xi)-A_{++,l}(\xi)\rp e^{-(\astar+ik)(x_2+y_2-2d)}d\xi,
    \end{equation}
    which is of the form required by Lemma~\ref{lem:steep_de} with
    \begin{equation}
        A(\xi)=\xi^2 \lp A_{++,r}(\xi)-A_{++,l}(\xi)\rp.
    \end{equation}
    Since this has a second order zero at~$\xi=0$, the~$j=0$ term in~\eqref{eq:de_asym} vanishes. Repeating this argument for the other regions gives the desired result.
\end{proof}

Next we turn our attention to the asymptotic behavior of $w^{l,r}$. In the
remainder, for notational convenience, we will assume that $y_{1} = 0$, since
the kernels are only a function of $x_{1} - y_{1}$. Referring to
equation~\eqref{eq:IFT-appb}, we note that for any finite $x_{1}, y_{1}$, the
functions $w^{l,r}$ agree with the construction
in~\cite{epstein2023solvinga}. However, the contour $\gamma_{F}$ is not suitable
for analyzing the asymptotics as $|x_1|\to\infty$ as it involves values of $\xi$
with $\Im \xi$ of both signs.  For these calculations one needs to deform to the
contours $\Gamma^{\pm}_{\nu}$ for $\pm x_{1}>0$, introduced
in~\cite{epstein2023solvinga}, see Figure~\ref{fig:contour-gamma-nu}. These
deformations require crossing poles of $w^{l,r}(\xi;x_2,y_2),$ which leads to a
residue contribution composed of waveguide modes: for $\pm x_1>0$ we have with
$l\leftrightarrow -,\, r\leftrightarrow +,$
\begin{equation}\label{eqn5.21.103}
     w^{l,r}(x_1,x_2;0,y_2) =\int_{\Gamma^{\pm}_{\nu}} e^{i\xi x_1}\tilde w^{l,r}(\xi;x_2,y_2)d\xi+\sum_{j=1}^{N_{l,r}}v^{\pm}_j(x_2)v^{\pm}_j(y_2)e^{\pm i\xi^{\pm}_jx_1}.
\end{equation}
In this representation the contributions to the integral from non-real $\xi$
decay exponentially as $\pm x_1\to\infty.$ Where $\pm x_2\gg d$ the functions
$v^{\pm}_j(x_2)=c_{j,\pm}^{\pm}e^{\mp x_2\sqrt{(\xi^{\pm}_{j})^2-k^2}},$ and so
obviously have analytic continuations to $\GammaC,$ which decay exponentially as
$|\Re x_2|\to\infty,$ but do not decay as $|\Im x_2|\to \infty.$ This leads to
the restriction that the data belongs to a space
$\cC^{\alpha,\beta}\oplus\cC^{\alpha+\frac 12,\beta},$ with
{$\beta\ge 0$}, and the restriction that $y_{2}$ lie on a contour,
$\tGamma,$ that satisfies the slope condition in~\eqref{eq:slop-cond}.  In the
following lemma, we establish the asymptotic properties of $w^{l,r}$.

\begin{figure}[h]
    \centering
    \includegraphics[width = 0.6\textwidth]{gamma_p.pdf}
    \caption{Plot in the $\xi$-plane showing $\Gamma_\nu^+$ in blue. The zeros of the Wronskian are marked by red stars, and the branch points are marked by diamonds. }\label{fig:contour-gamma-nu}
\end{figure}


\begin{lemma}\label{lemma:w_decay}
Suppose that $y_{2} \in \tGamma \subset \cG$ where $\tGamma$ satisfies the slope condition in~\eqref{eq:slop-cond}.
Then for any $n \in \mathbb{N}_{0}$,
    \begin{align}\label{eq:w_bd}
        |w^{l,r}(x_1,x_2;0,y_2)| + |\partial_{x_1}w^{l,r}(x_1,x_2;0,y_2)| \leq C_n\frac{1+|x_1|^n + |y_2|^n}{1+|y_2|^{2n+1}} 
    \end{align}
    uniformly in $\bx \in \mathbb{R}^2 \cap\{|x_2| \le \lt\}$ and $y_2 \in \tilde{\Gamma}$.
\end{lemma}
\begin{proof}
Note that various decay estimates for $w^{l,r} (x_1, x_2;0, y_2)$ with $x_1, x_2$ and $y_2$ real were already established in  \cite{epstein2023solvingb}. All that remains to be shown is that the estimates continue to hold when $y_{2} \in \tGamma$.
    Assume $x_1 > 0$ for concreteness. We recall \eqref{eqn5.21.103}, which states that
    \begin{align*}
        w(x_1,x_2;0,y_2) =
        w_0 (x_1, x_2; y_2) + w_{{\rm wg}} (x_1, x_2; y_2)
    \end{align*}
    where
    \begin{align}\label{eq:w2}
        w_0 (x_1, x_2; y_2) = \int_{\Gamma^{+}_{\nu}} e^{i\xi x_1}\tilde w(\xi;x_2,y_2){\rm d}\xi, \qquad w_{{\rm wg}} (x_1, x_2; y_2) = \sum_{j=1}^{N_{{\rm wg}}}v_j(x_2)v_j(y_2)e^{ i\xi_jx_1}
    \end{align}
    and we have dropped the superscripts $l,r$ for convenience. The waveguide contribution $w_{{\rm wg}}$ decays exponentially in $|\Re y_2|$ and thus clearly satisfies \eqref{eq:w_bd}.

    We next consider $w_0$.
    By the decay of $\tilde{w} (\cdot \; ; x_2, y_2)$ established in Theorem~\ref{prop:suitable}, $$\int_{\Gamma^{+}_{\nu}} |\tilde w(\xi;x_2,y_2)|{\rm d}\xi + \int_{\Gamma^{+}_{\nu}} |\xi \tilde w(\xi;x_2,y_2)|{\rm d}\xi$$ is a continuous function of $(x_2, y_2)$. Since $\Im \xi \ge 0$ for all $\xi \in \Gamma_\nu^+$, this means that $w_0 (x_1, x_2; y_2)$ and $\partial_{x_1} w_0 (x_1, x_2; y_2)$ are bounded uniformly in $x_1 \in \mathbb{R}$ over $(x_2, y_2)$ in compact sets. It remains to bound $w_0 (x_1, x_2; y_2)$ and $\partial_{x_1} w_0 (x_1, x_2; y_2)$ for $y_2 \in \tGamma \cap \{ |\Re y_2| > d\} \cap \{c|\Re y_2| \le |\Im y_2| \le C |\Re y_2|\}$.

    Using the shorthand $z := |x_2 - d| + \sqrt{(y_2 - d)^2}$, we invoke Theorem~\ref{prop:suitable} to write
    \begin{align*}
        \tilde{w} (\xi; x_2, y_2) = e^{-\astar (\xi) z} A(\xi, x_2), \qquad \xi \in \Gamma_\nu^+, \quad x_2 \in \mathbb{R}, \quad y_2 \in \tGamma \cap \{\Re y_2 > d\},
    \end{align*}
    where $A(\xi, x_2) = B(\astar (\xi), x_2)/\astar (\xi)$ with $B (\zeta, x_2)$ analytic in $\zeta \in \mathbb{C} \setminus \{\astar (\xi_j)\}$.
    We estimate the integral in \eqref{eq:w2} by separately handling the region where $\astar (\xi)$ is small. To this end, fix $0 < \delta < \min \{k, \xi_1 - \nu - k\}$ and let $\psi \in \mathcal{C}^\infty_c ((-k-\delta, -k+\delta) \cup (k-\delta, k+\delta))$ such that $\psi \equiv 1$ in $(-k-\delta/2, -k+\delta/2) \cup (k-\delta/2, k+\delta/2)$. This definition ensures that $\Gamma_\nu^+$ is real on the support of $\psi$, and we extend $\psi$ to be $0$ on the parts of $\Gamma_\nu^+$ that are not real. We write $w_0 = w_{0,0} + w_{0,1}$, where
    \begin{align*}
        w_{0,1} (x_1, x_2; y_2) := \int_{\Gamma^{+}_{\nu}} e^{i\xi x_1}\tilde w(\xi;x_2,y_2) \psi(\xi){\rm d}\xi.
    \end{align*}
    Looking first at $w_{0,0},$ since $\Re \astar (\xi) \ge \sqrt{\delta k - \delta^2/4} =: \eta$ and $0 \le \Im \astar (\xi) \le 2 \nu (\xi_p + \nu)$ for all $\xi \in \Gamma_\nu^+ \cap \supp (1 - \psi)$,
    \begin{align}\label{eq:w_02}
        |w_{0,0} (x_1, x_2; y_2)| \le \int_{\Gamma^{+}_{\nu}} e^{-\Re \astar (\xi) \Re y_2 + \Im \astar (\xi) \Im y_2} |A (\xi, x_2) (1-\psi(\xi))| {\rm d} \xi
        \le C e^{2\nu (\xi_p + \nu) \Im y_2-\eta\Re y_2}
    \end{align}
    uniformly in $\bx \in \mathbb{R}^2\cap \{x_1 > 0\} \cap\{|x_2| \le N\}$ and $y_2 \in \tGamma \cap \{\Re y_2 > d\}$.

    The remaining contribution is given by
    \begin{align*}
        w_{0,1} (x_1, x_2; y_2) = \int_{\Gamma_\nu^+}e^{i \xi x_1 - \astar (\xi) y_2}\frac{B(\astar (\xi), x_2)}{\astar (\xi)} \psi (\xi) {\rm d}\xi.
    \end{align*}
    After a change of variables in the integral, this becomes
    \begin{align*}
        w_{0,1} (x_1, x_2; y_2) &= 2\int_{0}^{\eta_+} \cos (\sqrt{\zeta^2 + k^2}x_1)e^{- \zeta y_2}\frac{B(\zeta, x_2)}{\sqrt{\zeta^2 + k^2}} \psi (\sqrt{\zeta^2 + k^2}) {\rm d}\zeta\\
        &\qquad +2i\int_{0}^{\eta_-} \cos (\sqrt{k^2 - \zeta^2}x_1)e^{i \zeta y_2}\frac{B(-i\zeta, x_2)}{\sqrt{k^2 - \zeta^2}} \psi (\sqrt{k^2 - \zeta^2}) {\rm d}\zeta,
    \end{align*}
    where we have assumed without loss of generality that $\psi$ is even, and have defined $\eta_+ := \sqrt{(k+\delta)^2- k^2}$ and $\eta_- := \sqrt{k^2 - (k-\delta)^2}$. It is clear that the first term on the right-hand side is bounded by $C/\Re y_2$, with the second bounded by $C/\Im y_2$.   
We note that almost identical arguments apply to the case for which $y_2 \in \tGamma \cap \{ \Re y_2 < -d\}$ and $x_1 < 0.$ Enforcing the comparability constraint $c |\Re y_2| \le |\Im y_2| \le C |\Re y_2|$, and choosing $\nu > 0$ sufficiently small, \eqref{eq:w_02} together with the above bounds imply that
    \begin{align*}
        |w_0 (x_1, x_2; y_2)| \le \frac{C}{1 + |y_2|}, \qquad \bx \in \mathbb{R}^2 \cap \{|x_2| \le \lt\}, \quad y_2 \in \tGamma.
    \end{align*}
    It is clear that the above arguments extend to $\partial_{x_1} w_0$, thus we have verified \eqref{eq:w_bd} when $n=0$.

    To extend this result to arbitrary $n$, we define $\varphi (\xi, \zeta, x_1, y_2) := i \xi x_1 - \zeta y_2$ and use that
    $$\partial_\xi \varphi (\xi, \astar (\xi), x_1, y_2) = ix_1 - \astar' (\xi) y_2 = \varphi (\astar (\xi), \xi, x_1, y_2)/\astar (\xi)$$
    to write
    \begin{align*}
        w_{0,1} (x_1, x_2; y_2) =
        \int_{\Gamma_\nu^+} \frac{B(\astar (\xi), x_2)\psi (\xi)}{\astar (\xi)}\left(\frac{\astar (\xi)}{\varphi (\astar (\xi), \xi, x_1, y_2)}\partial_\xi \right)^n e^{\varphi (\xi, \astar (\xi), x_1, y_2)}{\rm d}\xi.
    \end{align*}
    Now, observe that since $\astar (\mathbb{R}) \subset \mathbb{R} \cup i \mathbb{R}$, the function $\varphi (\astar (\xi), \xi, x_1, y_2)$ is nonzero for all $(\xi, x_1, y_2) \in \supp (\psi) \times \mathbb{R} \times Q_1$, and $\partial_\xi \varphi (\astar (\xi), \xi, x_1, y_2) = \varphi (\xi, \astar (\xi),x_1, y_2)/\astar (\xi)$ is locally integrable. We stress here that the comparability constraint implies that $\arg y_2$ is bounded away from zero in the above integral. Therefore, we can integrate by parts to obtain
    \begin{align*}
        w_{0,1} (x_1&, x_2; y_2) = (-1)^n \int_{\Gamma_\nu^+} e^{\varphi (\xi,\astar (\xi), x_1, y_2)}\left(\partial_\xi \frac{\astar (\xi)}{\varphi (\astar (\xi), \xi, x_1, y_2)}\right)^n \frac{B(\astar (\xi), x_2)\psi (\xi)}{\astar (\xi)} {\rm d} \xi,
    \end{align*}
    which by the local boundedness of the $\partial^n_\zeta B(\zeta, x_2)$ can be written as
    \begin{align*}
        w_{0,1} (x_1&, x_2; y_2) = \int_{\Gamma_\nu^+}e^{\varphi (\xi,\astar (\xi), x_1, y_2)}\frac{1}{\astar (\xi)} \sum_{j=0}^n \frac{\phi_j (\xi, x_1, y_2)}{\varphi^{n+j}(\astar (\xi), \xi, x_1, y_2)} {\rm d} \xi,
    \end{align*}
    where the $\phi_j$ are compactly supported in $\xi$ and satisfy $|\phi_j (\xi, x_1, y_2)| \le C (1 + |x_1|^j + |y_2|^j)$ uniformly in all variables. As above, we change variables in the integral to obtain
    \begin{align*}
        w_{0,1} (x_1, x_2; y_2) &= \sum_{\eps \in \{-1, 1\}} \Bigg\{ \int_0^{\eta_+}e^{\eps i\sqrt{\zeta^2 + k^2}x_1}e^{- \zeta y_2}\frac{1}{\sqrt{\zeta^2 + k^2}}\sum_{j=0}^n \frac{\phi_j (\eps\sqrt{\zeta^2 + k^2}, x_1, y_2)}{\varphi^{n+j} (\zeta, \eps \sqrt{\zeta^2 + k^2}, x_1, y_2)} {\rm d}\zeta\\
        &\qquad +i\int_{0}^{\eta_-} e^{\eps i\sqrt{k^2 - \zeta^2}x_1}e^{i \zeta y_2}\frac{1}{\sqrt{k^2 - \zeta^2}} \sum_{j=0}^n \frac{\phi_j (\eps \sqrt{k^2 - \zeta^2}, x_1, y_2)}{\varphi^{n+j} (-i \zeta, \eps\sqrt{k^2 - \zeta^2}, x_1, y_2)}{\rm d}\zeta \Bigg\}.
    \end{align*}
    Since $|1/\varphi (\zeta, \eps \sqrt{\zeta^2 + k^2}, x_1, y_2)| + |1/\varphi (-i\zeta, \eps \sqrt{k^2 - \zeta^2}, x_1, y_2)| \le C/|y_2|$ uniformly in $0 < \zeta < \eta_+$,
    \begin{align*}
        |w_{0,1} (x_1, x_2; y_2)| \le C \sum_{j=0}^n \frac{1+|x_1|^j+|y_2|^j}{|y_2|^{n+j}} \left( \int_0^{\eta_+} e^{-\zeta \Re y_2} {\rm d} \zeta +\int_0^{\eta_-} e^{-\zeta \Im y_2} {\rm d} \zeta \right) \le C\frac{1+|x_1|^n+|y_2|^n}{|y_2|^{2n+1}},
    \end{align*}
    where the last inequality follows from the comparability assumption $c |\Re y_2| \le |\Im y_2| \le C |\Re y_2|$.
    Given the exponential decay of $w_{0,0}$ in \eqref{eq:w_02} with $\nu > 0$ sufficiently small, we have now established that
    \begin{align*}
        |w_{0} (x_1, x_2; y_2)|\le C_n\frac{1+|x_1|^n+|y_2|^n}{1 + |y_2|^{2n+1}}, \qquad \bx \in \mathbb{R}^2 \cap \{|x_2| \le \lt\}, \quad y_2 \in \tGamma.
    \end{align*}
    It is again clear that the same estimates apply to $\partial_{x_1} w_0$, and the proof is complete.
\end{proof}

