\appendix

\section{Quasi-interpolation on curved meshes}

\label{appendix:section:quasi-interpolation}

\subsection{Setting}

In this appendix, we consider a domain $\Omega \subset \mathbb R^d$, with $d=2$ or $3$.
We denote by $L$ the diameter of $\Omega$. $\GD \subset \partial \Omega$ is a relatively
open subset of the boundary that is assumed to have a (possible empty) Lipschitz boundary
$\partial \GD$.

\subsubsection{Reference simplicies}

In this section we fix a (closed) reference $d$ simplex $\widehat{K}$. We also fix a
reference $d-1$ simplex $\widehat{F}_{d-1} \subset \mathbb R^{d-1}$. For simplicity, we assume that
$|\widehat{K}| \leq 1$, which is the case for the standard choice of the convex hull
formed from the canonical basis vectors of $\mathbb R^d$. We denote by $\widehat{\mathcal{F}}$
the set of faces of $\widehat{K}$. For each face $\widehat{F} \in \widehat{\mathcal{F}}$,
there exists a finite number of bijective affine mappings $A: \widehat{F} \to \widehat{F}_{d-1}$.
A specific affine mapping is selected by specifying on which vertex of $\widehat{F}_{d-1}$
is mapped each vertex of $\widehat{F}$.

\subsubsection{Curved meshes}

\begin{definition}[Curved matching mesh]
\label{definition_curved_mesh}
A curved matching mesh $\mathcal{T}_h$ of $\Omega$ is a finite collection of elements
$K$ with associated mappings $\mathcal{F}_K: \widehat{K} \to K$ having the following properties.
We first ask that the elements are non-degenerate, meaning that for each
$K \in \mathcal{T}_h$ the mapping $\mathcal{F}_K: \widehat{K} \to K$ is bilipschitz.
We further demand that $\mathcal{T}_h$ is non-overlapping, i.e., that for any two distinct
elements $K_\pm \in \mathcal{T}_h$, the intersection $K_- \cap K_+$ is either empty, a single
point, or an $\ell$-manifold with boundary for some $\ell \in \{1,\dots,d-1\}$.
We also require that the mappings are compatible, meaning that if $F := K_- \cap K_+$
is a $d-1$ manifold for some $K_\pm \in \mathcal{T}_h$ then
$\widehat{F}_\pm := \mathcal{F}_{K_\pm}^{-1}(F) \in \widehat{\mathcal{F}}$
and there exist bijective affine mappings $A_\pm: \widehat{F}_{d-1} \to \widehat{F}_\pm$
such that
\begin{equation}
\label{eq_compatible_mappings}
\mathcal{F}_{K_-} \circ A_- = \mathcal{F}_{K_+} \circ A_+
\end{equation}
as maps from $\widehat{F}_{d-1}$ to $F$. Finally, we demand that the mesh covers the domain, i.e.,
\begin{equation*}
\overline{\Omega} = \bigcup \mathcal{T}_h,
\end{equation*}
and that the mesh is compatibly with the boundary condition, meaning that every boundary face
either entirely belongs to $\overline{\GD}$ or $\partial \Omega \setminus \GD$.
\end{definition}

In what follows we consider such a curved matching mesh $\mathcal{T}_h$ of $\Omega$.
Notice that Definition~\ref{definition_curved_mesh} implies that the elements
$K \in \mathcal{T}_h$ are closed sets. It is also clear that if the maps $\mathcal{F}_K$
are affine, then our definition is the standard definition of a matching mesh
(see e.g.~\cite[Definition 6.1.1]{ern_guermond_2021a}).

The notion of ``patch'' will be important in what follows. For $K \in \mathcal{T}_h$,
we finally employ the notation
\begin{equation*}
\mathcal{T}_h^K := \left \{
K' \in \mathcal{T}_h \; | \; K' \cap K \neq \emptyset
\right \}
\end{equation*}
for the patch of elements around $K$.

We now introduce a few metrics that measure the fineness and regularity of the mesh.
Classically, the fineness of the mesh is quantified with the elements diameters
\begin{equation*}
%% TODO: we may need to modify this
h_K := \max_{\bx,\by \in K} |\bx-\by| \qquad \forall K \in \mathcal{T}_h,
\end{equation*}
and $h := \max_{K \in \mathcal{T}_h} h_K$ is known as the mesh size.
The ``shape regularity'' of each element $K \in \mathcal{T}_h$, is
measured by the quantity
\begin{equation*}
M_K := \max(h_K \|(J\mathcal{F}_K)^{-1}\|_{L^\infty(\widehat{K})},h_K^{-1} \|J\mathcal{F}_K\|_{L^\infty(\widehat{K})}),
\end{equation*}
where $J\mathcal{F}_K$ denotes the Jacobian of $\mathcal{F}_K$ and where, for each $\widehat{\bx} \in \widehat{K}$, the matrix norm
associated with the Euclidean metric is considered. For $\mathcal{T} \subset \mathcal{T}_h$,
we also use the notation $M_{\mathcal{T}} := \max_{K \in \mathcal{T}} M_K$. These
metrics are the natural extensions of the ones used for straight elements.
The fact that $M_{\mathcal{T}_h}$ is well-defined and finite is a consequence of
Definition~\ref{definition_curved_mesh}.
%
We will sometimes need more regularity on the element mappings.
We will say that the element $K \in \mathcal{T}_h$ is $r$-regular
if $\mathcal{F}_K \in C^r(\widehat{K},K)$. In this case, we will
write
\begin{equation}
\label{eq_dJFK}
M_K(r)
:=
\max_{|\alpha| \leq r}
\left (\frac{h_K}{L}\right )^{|\alpha|}
\frac{\|\partial^\alpha \mathcal{F}_K\|_{L^\infty(\widehat{K})}}{L}.
\end{equation}
The mesh $\mathcal{T}_h$ is $r$-regular if all its elements are, and we then write
$M_{\mathcal{T}}(r) := \max_{K \in \mathcal{T}} M_K(r)$ for all $\mathcal{T} \subset \mathcal{T}_h$.

For later reference, we note that for all $K \in \mathcal{T}_h$,
there exists a constant $\mu_K \geq 1$ solely depending on $M_K$
such that
\begin{equation}
\label{eq_muK}
\mu_K^{-1} h_K^d \leq |(\det J\mathcal{F}_K)(\widehat{\bx})| \leq \mu_K h_K^d
\qquad
\forall \widehat{\bx} \in \widehat{K}.
\end{equation}

\subsubsection{Finite element space}

In the remainder, we fix $p \geq 1$,  and consider a finite element space
\begin{equation*}
V_h := \left \{
v_h \in H^1_{\GD}(\Omega) \; | \;
v_h|_K \circ \mathcal{F}_K \in \mathcal{P}_p(\widehat{K})
\right \}
\end{equation*}
where $\mathcal{P}_p(\widehat{K})$ is the space of (complex-valued) polynomials
of degree at most $p$ defined on the reference simplex $\widehat{K}$. The
notation
\begin{equation*}
\mathcal{P}(K) := \left \{
v \in H^1(K) \; | \; v \circ \mathcal{F}_K \in \mathcal{P}_p(\widehat{K}),
\right \}
\end{equation*}
will sometimes be useful. We also denote by
\begin{equation*}
V_h^\flat
:=
\left \{
v_h \in L^2(\Omega) \; | \; v_h|_K \in \mathcal{P}(K) \; \forall K \in \mathcal{T}_h
\right \}.
\end{equation*}
the ``broken'' counterpart of $V_h$.

\subsubsection{Sobolev spaces}

For a submesh $\mathcal{T} \subset \mathcal{T}_h$ covering a domain $D$,
if $s \geq 1$ and $1 \leq q \leq +\infty$, we introduce the broken Sobolev space
\begin{equation*}
W^{s,q}(\mathcal{T})
:=
\left \{
v \in L^q(D) \; | \; v|_K \in W^{s,q}(K) \; \forall K \in \mathcal{T}
\right \}
\end{equation*}
equipped with the semi-norm
\begin{equation*}
|v|_{W^{s,q}(\mathcal{T})}
:=
\left (
\sum_{K \in \mathcal{T}} \sum_{|\alpha| \leq s} \|\partial^\alpha v\|_{L^q(K)}^q
\right )^{1/q}
\end{equation*}
and the norm
\begin{equation*}
\|v\|_{W^{s,q}(\mathcal{T})}
=
\sum_{t=0}^s L^t |v|_{W^{t,q}(\mathcal{T})}.
\end{equation*}

As usual, we employ the notation $H^1(\mathcal{T}) = W^{1,2}(\mathcal{T})$,
for the Hilbert space and for the subscript in the associated norm and semi-norm.

\subsection{Main result}

\begin{theorem}[Quasi-interpolation]
\label{theorem_quasi_interpolant}
If $\mathcal{T}_h$ is a curved matching mesh of $\Omega$, then there exists a projection
$I_h: H^1_{\GD}(\Omega) \to V_h$ with the following properties.
If $v \in H^1_{\GD}(\Omega) \cap W^{s+1,q}(\mathcal{T}_h)$ for some
$2 \leq q \leq +\infty$ and $0 \leq s \leq p$ and if $\mathcal{T}_h$
is $s+1$ regular, then for each $K \in \mathcal{T}_h$, we have
\begin{equation}
\label{eq_error_estimate}
h_K^{-1} \|v-I_h(v)\|_{L^r(K)}+|v-I_h(v)|_{W^{1,r}(K)}
\lesssim
h_K^{d/r-d/q}
\left (\frac{h_K}{L}\right )^s
\sum_{t=0}^s L^t|v|_{W^{t+1,q}(\mathcal{T}_h^K)}.
\end{equation}
for all $1 \leq r \leq q$, with a hidden constant
depending on $p$, $r$, $q$, $M_{\mathcal{T}_h^K}$
and $M_{\mathcal{T}_h^K}(s+1)$.  It follows in particular that
\begin{equation}
\label{eq_error_estimate_global}
h^{-1}\|v-I_h(v)\|_{L^r(\Omega)} + |v-I_h(v)|_{W^{1,r}(\Omega)}
\lesssim
h^{d/r-d/q} h^s \|v\|_{W^{s+1,q}(\mathcal{T}_h)}
\end{equation}
with a hidden constant depending on $p$, $r$, $q$,
$M_{\mathcal{T}_h}$ and $M_{\mathcal{T}_h}(s+1)$.
\end{theorem}

For easy reference, we highlight the following direct consequence
of Theorem~\ref{theorem_quasi_interpolant}. The proof simply follows
by selecting $r=q=2$ and $s=0$, and applying a triangular inequality.

\begin{corollary}[Stability in energy norm]
Let $v \in H^1_{\GD}(\Omega)$. For all $K \in \mathcal{T}_h$ we have
\begin{equation*}
|I_h(v)|_{H^1(K)}
\lesssim
|v|_{H^1(\mathcal{T}_h^K)},
\end{equation*}
In particular,
\begin{equation*}
|I_h(v)|_{H^1(\Omega)}
\lesssim
|v|_{H^1(\Omega)}.
\end{equation*}
Here, $I_h$ is the projection from Theorem~\ref{theorem_quasi_interpolant}
and the hidden constants only depend on $M_{\mathcal{T}_h}$.
\end{corollary}

\subsection{Consequences of mesh regularity}

Here, we show that the number of elements in a patch is bounded
by a constant that only depends on $M_{\mathcal{T}_h}$, and
that they all have similar diameters. These results are standard
for straight elements and are extended here to curved ones.

\begin{lemma}[Element patches]
\label{lemma_patch}
There exists a constant $N_{\mathcal{T}_h}$ only depending on $M_{\mathcal{T}_h}$
such that the cardinality of $\mathcal{T}_h^K$ is less than
$N_{\mathcal{T}_h}$ for all $K \in \mathcal{T}_h$. In addition, we have
\begin{equation}
\label{eq_comparable_diameters}
h_{K'} \simeq h_K
\end{equation}
with hidden constants only depending on $M_{\mathcal{T}_h}$.
\end{lemma}

\begin{proof}
Consider an element $K \in \mathcal{T}_h$ and one of its vertices
$\ba$ (i.e. the image of a vertex of $\widehat{K}$ through $\mathcal{F}_K$).
We can then consider, for each $K' \in \mathcal{T}_h$ with $\ba \in K'$ the affine map
\begin{equation*}
F_{K'}: \widehat{K} \ni \widehat{\bx} \to \ba+(J\mathcal{F}_{K'})(\ba) \,\widehat{\bx} \in K_\dagger',
\end{equation*}
where $K_\dagger'$ is a straight tetrahedron with shape-regularity measure only depends
on $M_{K'}$.  We now observe that because the mappings are matching, the collection of all
straight elements $K_\dagger'$ obtained from $K' \in \mathcal{T}_h$ with $\ba \in K'$ is a
standard shape-regular vertex patch of straight elements, with shape-regularity measure only
controlled by $M_{\mathcal{T}_h}$. For a straight vertex patch,
it is a standard result that the number of elements is bounded by a constant that
only depends on the shape-regularity measure, which shows that the number of elements
$K$ sharing $\ba$ is bounded. Since $K$ has only $d+1$ vertices and all $K' \in \mathcal{T}_h^K$,
must have at least one of those vertices, this concludes the existence of the constant
$N_{\mathcal{T}_h}$ controlling the cardinality of $\mathcal{T}_h^K$.

To prove~\eqref{eq_comparable_diameters}, we first consider two elements
$K_\pm \in \mathcal{T}_h$ sharing a face $F$. We let
$\widehat{F}_\pm := \mathcal{F}_{K_\pm}^{-1}(F)$, and denote by
$A_\pm: \widehat{F}_{d-1} \to \widehat{F}_\pm$ the affine maps from~\eqref{eq_compatible_mappings}.
%
We now pick two distinct points $\widehat{\bx}_{d-1},\widehat{\by}_{d-1} \in \widehat{F}_{d-1}$.
We let $\widehat{\bx}_\pm := A_\pm(\widehat{\bx}_{d-1})$
and    $\widehat{\by}_\pm := A_\pm(\widehat{\by}_{d-1})$.
Since the $A_\pm$ is a bijective affine mapping, we have
\begin{equation*}
|\widehat{\bx}_\pm-\widehat{\by}_\pm| \simeq |\widehat{\bx}-\widehat{\by}|.
\end{equation*}
We then let $\bx := \mathcal{F}_{K_\pm}(\widehat{\bx}_\pm)$
and         $\by := \mathcal{F}_{K_\pm}(\widehat{\by}_\pm)$,
where the definition is not ambiguous due to~\eqref{eq_compatible_mappings}.
We can then write on the one hand that
\begin{equation*}
|\bx-\by|
=
|\mathcal{F}_{K_+}(\widehat{\bx}_+)-\mathcal{F}_+(\widehat{\by}_+)|
\lesssim
h_{K_+}|\widehat{\bx}_+-\widehat{\by}_+|
\lesssim
h_{K_+}|\widehat{\bx}_{d-1}-\widehat{\by}_{d-1}|,
\end{equation*}
where the hidden constant only depends on $M_{K_+}$ and on the other hand that
\begin{equation*}
|\widehat{\bx}_{d-1}-\widehat{\by}_{d-1}|
\lesssim
|\widehat{\bx}_--\widehat{\by}_-|
=
|\mathcal{F}_{K_-}^{-1}(\bx)-\mathcal{F}_{K_-}^{-1}(\by)|
\lesssim
h_{K_-}^{-1}|\bx-\by|,
\end{equation*}
with a hidden constant solely depending on $M_{K_-}$. This is eventually leads to
$h_{K_-} \lesssim h_{K_+}$, and we can conclude that
\begin{equation}
\label{tmp_comparable_diameters}
h_{K_-} \simeq h_{K_+}
\end{equation}
by flipping the roles of $K_-$ and $K_+$, where the hidden constant
depends only on $M_{\mathcal{T}_h}$.

Now, if $K \in \mathcal{T}_h$ and $K' \in \mathcal{T}_h^K$, then
we can join $K$ to $K'$ by a chain $K = K_1,\dots,K_n = K'$ of
$n \leq N_{\mathcal{T}_h}$ elements connected through a face.
And we obtain~\eqref{eq_comparable_diameters} by applying~\eqref{tmp_comparable_diameters} $n$.
This is indeed concludes the proof since the constants in~\eqref{tmp_comparable_diameters}
are then exponentiated at most to power $N_{\mathcal{T}_h}$.
\end{proof}

\subsection{Change of variables properties}

As per usual, our error estimates will rely on scaling arguments,
which ultimately hinge on changes of variables. Such reasoning is
completely standard for straight elements, and is extended to curved
elements with an effort of using minimal assumptions.

\begin{lemma}[Change of variable for Lebesgue spaces]
Let $K \in \mathcal{T}_h$. We have
\begin{equation}
\label{eq_change_of_variable}
\mu_K^{-1/r} h_K^{d/r} \|v \circ \mathcal{F}_K\|_{L^r(\widehat{K})}
\leq
\|v\|_{L^r(K)}
\leq
\mu_K^{1/r}h_K^{d/r} \|v \circ \mathcal{F}_K\|_{L^r(\widehat{K})}
\end{equation}
for all $1 \leq r \leq +\infty$ and all $v \in L^r(K)$.
\end{lemma}

\begin{proof}
The statement is obvious for $r = +\infty$. If $1 \leq r < +\infty$,
we introduce the short-hand notation
$\widehat{v} := v \circ \mathcal{F}_K \in L^q(\widehat{K})$.
We have
\begin{equation*}
\|v\|_{L^r(K)}^r
=
\int_K |v(\bx)|^r d\bx
=
\int_{\widehat K} |\widehat{v}(\widehat{\bx})|^r
|\det J\mathcal{F}_K(\widehat{\bx})| d\widehat{\bx}
\leq
\mu_K h_K^d \|\widehat{v}\|_{L^r(\widehat{K})}^r
\end{equation*}
which is the upper bound in~\eqref{eq_change_of_variable}.
The lower bound is obtained similarly, after observing that~\eqref{eq_muK}
implies that
\begin{equation*}
|\det(J\mathcal{F}_K^{-1})(\bx)| \leq \mu_K h_K^{-d}
\end{equation*}
for all $\bx \in K$.
\end{proof}

\begin{lemma}[Change of variables for Sobolev spaces]
Let $K \in \mathcal{T}_h$ and $v \in W^{1,q}(K)$. Then, we have
\begin{equation}
\label{eq_W1q_K_hK}
h_K |v|_{W^{1,q}(K)}
\leq
M_K \mu_K^{1/q} h_K^{d/q} |v \circ \mathcal{F}_K|_{W^{1,q}(\widehat{K})}.
\end{equation}
In addition, if~\eqref{eq_dJFK} holds true with $r = s$ %% TODO: double check
and $v \in W^{s,q}(K)$ for some $s \geq 1$, then
\begin{equation}
\label{eq_Wsq_hK_K}
h_K^{d/q} |v \circ \mathcal{F}_K|_{W^{s,q}(\widehat{K})}
\lesssim
\left (\frac{h_K}{L} \right )^s
\sum_{t=1}^s
L^t|v|_{W^{t,q}(K)}
\end{equation}
where the hidden constant depends on $M_K$, $M_K(s)$, $s$ and $q$.
\end{lemma}

\begin{proof}
Let us first establish~\eqref{eq_W1q_K_hK}. For that, we let
$g := \nabla v \in L^q(K)$, $\widehat{v} := v \circ \mathcal{F}_K \in W^{1,q}(\widehat{K})$
and $\widehat{g} := \nabla \widehat{v} \in L^q(\widehat{K})$, so that
$\|g\|_{L^q(K)} = |v|_{W^{1,q}(K)}$ and
$\|\widehat{g}\|_{L^q(\widehat{K})} = |\widehat{v}|_{W^{1,q}(\widehat{K})}$.
Due to the chain rule, we have
\begin{equation*}
\widehat{g} = (J\mathcal{F}_K)^T \cdot (g \circ \mathcal{F}_K)
\end{equation*}
and it follows that
\begin{equation*}
\|g \circ \mathcal{F}_K\|_{L^q(\widehat{K})}
=
\|J\mathcal{F}_K^{-T} \cdot \widehat{g}\|_{L^q(\widehat{K})}
\leq
M_K h_K^{-1} \|\widehat{g}\|_{L^q(\widehat{K})}.
\end{equation*}
We then conclude the proof with the estimate
\begin{equation*}
\|g\|_{L^q(K)} \leq \mu_K^{1/q} h_K^{d/q}\|g \circ \mathcal{F}_K\|_{L^q(\widehat{K})}
\end{equation*}
which we obtain by applying~\eqref{eq_change_of_variable} component wise.

The estimate in~\eqref{eq_Wsq_hK_K} is established with similar arguments,
though more technical. For shortness, we do not repeat those here, and
follow the proof of~\cite[Lemma B.3]{chaumontfrelet_galkowski_spence_2024a}
where the estimate
\begin{equation*}
|\partial^\alpha(v \circ \mathcal{F}_K)|
\lesssim
\sum_{\substack{\beta \leq \alpha \\ |\beta| \geq 1}}
L^{|\beta|} \left (\frac{h}{L}\right )^{|\alpha|}
|(\partial^{\beta} v) \circ \mathcal{F}_K|
\end{equation*}
is established a.e. in $\widehat{K}$ for all multi-indices
$\alpha$ with $|\alpha| = s$ with hidden constant depending on
$\alpha$ and $M_K(s)$. It also follows from the triangular inequality that
\begin{equation*}
\|\partial^\alpha(v \circ \mathcal{F}_K)\|_{L^q(\widehat{K})}
\lesssim
\sum_{\substack{\beta \leq \alpha \\ |\beta| \geq 1}}
L^{|\beta|} \left (\frac{h}{L}\right )^{|\alpha|}
\|(\partial^{\beta} v) \circ \mathcal{F}_K\|_{L^q(\widehat{K)}}
\end{equation*}
and~\eqref{eq_Wsq_hK_K} follows from~\eqref{eq_change_of_variable}.
\end{proof}

\begin{lemma}[Change of exponent]
Assume that $1 \leq r \leq q \leq +\infty$. Then, for all $v \in L^q(K)$, we have
\begin{equation}
\label{eq_Lr_Lq}
\|v\|_{L^r(K)} \leq \mu_K^{1/r+1/q} h_K^{d/r-d/q} \|v\|_{L^q(K)}.
\end{equation}
\end{lemma}

\begin{proof}
Here too, we introduce the short-hand notation
$\widehat{v} := v \circ \mathcal{F}_K \in L^q(\widehat{K})$.
We are first going to show that
\begin{equation}
\label{tmp_Lr_Lq_hK}
\|\widehat{v}\|_{L^r(\widehat{K})} \leq \|\widehat{v}\|_{L^q(\widehat{K})}
\end{equation}
on the reference element. Let us first observe that~\eqref{tmp_Lr_Lq_hK}
clearly holds true if $r=q$. We may therefore assume that $1 \leq r < q$. Then,
since $q/r > 1$, H\"older
inequality gives that
\begin{equation*}
\|\widehat{v}\|_{L^r(\widehat{K})}^r
=
\||\widehat{v}|^r\|_{L^1(\widehat{K)}}
\leq
\|1\|_{L^{q/(q-r)}\widehat{K}}\||\widehat{v}|^r\|_{L^{q/r}(\widehat{K})}
=
|\widehat{K}|^{(q-r)/q}\|\widehat{v}\|_{L^q(\widehat{K})}^r,
\end{equation*}
which we indeed gives~\eqref{tmp_Lr_Lq_hK} since $|\widehat{K}| \leq 1$ by assumption and
$(q-r)/(qr) \geq 0$. Now,~\eqref{eq_Lr_Lq} simply follows by applying the upper bound
in~\eqref{eq_change_of_variable},~\eqref{tmp_Lr_Lq_hK} and the lower bound in~\eqref{eq_change_of_variable}.
\end{proof}

\subsection{Properties of the element-wise projection}

Our quasi-interpolation operator hinges on an element-wise
$H^1$ orthogonal projection operator. Specifically, for $K \in \mathcal{T}_h$
and $v \in H^1(K)$ we define the elementwise projection $\Pi_Kv \in \mathcal{P}(K)$
by requiring that
\begin{equation*}
(v-\Pi_Kv,1)_K = 0,
\qquad
(\nabla(v-\Pi_Kv)),\nabla w_K) = 0 \quad \forall w_K \in \mathcal{P}(K).
\end{equation*}
In this section, we established some key properties of this elementwise projection.
These results are elementary for straight elements $K$ with affine mappings
$\mathcal{F}_K$. The extension to curved elements under suitable regularity
assumptions for the mapping is straightforward, but we include it here for completeness.

\begin{lemma}[Poincar\'e inequality]
For all $K \in \mathcal{T}_h$ and $w \in H^1(K)$ with $(w,1)_K = 0$, we have
\begin{equation}
\label{eq_poincare_mean}
\|w\|_{L^2(K)} \lesssim h_K|w|_{H^1(K)}
\end{equation}
where the hidden constant only depends on $M_K$. It follows in particular that
\begin{equation}
\label{eq_poincare}
\|v-\Pi_K v\|_{L^2(K)} \lesssim h_K|v-\Pi_K v|_{H^1(K)}
\end{equation}
for all $v \in H^1(K)$.
\end{lemma}

\begin{proof}
We first observe that since $(w,1)_K = 0$, we have
\begin{equation*}
\|w\|_{L^2(K)} \leq \|w-k\|_{L^2(K)}
\end{equation*}
for any choice of constant $k \in \mathbb C$. We now apply~\eqref{eq_change_of_variable},
which gives
\begin{equation*}
\|w-k\|_{L^2(K)}
\lesssim
h_K^{d/2} \|w \circ \mathcal{F}_K-k\|_{L^2(\widehat{K})}.
\end{equation*}
We can now choose $k := (w\circ\mathcal{F}_K,1)_{\widehat{K}}$ so that
\begin{equation*}
\|w \circ \mathcal{F}_K-k\|_{L^2(\widehat{K})}
\lesssim
|w \circ \mathcal{F}_K|_{H^1(\widehat{K})},
\end{equation*}
where the hidden constant only depends on the choice of the reference
element $\widehat{K}$. Then,~\eqref{eq_poincare_mean} follows from~\eqref{eq_Wsq_hK_K}.
\end{proof}

\begin{lemma}[Stability]
Let $K \in \mathcal{T}_h$. For all $q \geq 2$, we have
\begin{equation}
\label{eq_stability_Lq}
\|\Pi_K v\|_{L^q(K)} \lesssim \|v\|_{L^q(K)} + h_K|v|_{W^{1,q}(K)}
\end{equation}
and
\begin{equation}
\label{eq_stability_W1q}
|\Pi_K v|_{W^{1,q}(K)} \lesssim |v|_{W^{1,q}(K)}
\end{equation}
for all $v \in W^{1,q}(K)$, where the hidden constants depend on $p$, $q$ and $M_K$.
\end{lemma}

\begin{proof}
We start with~\eqref{eq_stability_Lq}. 
By the change of exponent
formula in~\eqref{eq_change_of_variable}, we first observe that
\begin{equation*}
\|\Pi_K v\|_{L^q(K)}
\lesssim
h_K^{d/q} \|(\Pi_K v) \circ \mathcal{F}_K\|_{L^q(\widehat{K})}.
\end{equation*}
Since $(\Pi_K v) \circ \mathcal{F}_K \in \mathcal{P}_p(\widehat{K})$
by assumption, we have
\begin{equation*}
\|(\Pi_K v) \circ \mathcal{F}_K \|_{L^q(\widehat{K})}
\lesssim
\|(\Pi_K v) \circ \mathcal{F}_K \|_{L^2(\widehat{K})}
\end{equation*}
since $\mathcal{P}_p(\widehat{K})$ is a finite dimensional space.
We apply again the change of variable formula from~\eqref{eq_change_of_variable},
leading to
\begin{equation*}
\|(\Pi_K v) \circ \mathcal{F}_K \|_{L^2(\widehat{K})}
\lesssim
h_K^{-d/2} \|\Pi_K v\|_{L^2(K)},
\end{equation*}
and all in all
\begin{equation}
\label{tmp_Lq_L2}
\|\Pi_K v\|_{L^q(K)} \lesssim h^{d/q-d/2} \|\Pi_K v \|_{L^2(K)}.
\end{equation}
We continue with the Poincar\'e inequality in~\eqref{eq_poincare}, giving us that
\begin{equation*}
\|\Pi_K v\|_{L^2(K)}
\leq
\|v\|_{L^2(K)}+\|v-\Pi_K v\|_{L^2(K)}
\lesssim
\|v\|_{L^2(K)} + h_K|v|_{H^1(K)}.
\end{equation*}
We now apply~\eqref{eq_Lr_Lq} to $v$ and each $\partial^\alpha v$ with $|\alpha| = 1$, yielding
\begin{equation}
\label{tmp_L2_W1q}
\|\Pi_K v\|_{L^2(K)}
\leq
C_q h_K^{d/2-d/q}\left (
\|v\|_{L^q(K)}+h_K|v|_{W^{1,q}(K)}
\right ),
\end{equation}
which is possible since $q \geq 2$. Combining~\eqref{tmp_Lq_L2} and~\eqref{tmp_L2_W1q}
proves~\eqref{eq_stability_Lq}.

We now turn to~\eqref{eq_stability_W1q}. For simplicity, we introduce the notation
$\widehat{g} := \nabla( \Pi_K v\circ\mathcal{F}_K) \in L^q(\widehat{K})$.
Due to~\eqref{eq_W1q_K_hK}, we have
\begin{equation*}
|\Pi_K v|_{W^{1,q}(K)}
\lesssim
h_K^{-1} h_K^{d/q} |\Pi_K v \circ \mathcal{F}_K|_{W^{1,q}(\widehat{K})}
=
h_K^{-1}h_K^{d/q}\|\widehat{g}\|_{L^q(\widehat{K})}.
\end{equation*}
Since each component $\widehat{g}$ is a polynomial of degree $p-1$, we
can again apply a finite-dimensional argument to show that
\begin{equation*}
|\Pi_K v|_{W^{1,q}(K)}
\lesssim
h_K^{-1} h_K^{d/q}\|\widehat{g}\|_{L^2(\widehat{K})}
=
h_K^{-1} h_K^{d/q}|\Pi_K v \circ \mathcal{F}_K|_{H^1(\widehat{K})}
\lesssim
h_K^{d/q-d/2} |\Pi_K v|_{H^1(K)}
\end{equation*}
where we emloyed~\eqref{eq_Wsq_hK_K} in the last estimate.
Since $\Pi_K$ is the $H^1(K)$ orthogonal projection onto $\mathcal{P}(K)$,
we now have
\begin{equation*}
|\Pi_K v|_{H^1(K)} \leq |v|_{H^1(K)},
\end{equation*}
and we conclude by applying~\eqref{eq_Lr_Lq} to each $\partial^\alpha v$, with $|\alpha| = 1$.
\end{proof}

\begin{theorem}[Error estimate]
\label{lemma_bramble_hilbert}
Let $1 \leq r \leq +\infty$, $\max(2,r) \leq q \leq +\infty$ and $0 \leq s \leq p$.
Assume that $K \in \mathcal{T}_h$ is $(s+1)$-regular, then
\begin{equation}
\label{eq_bramble_hilbert}
h_K^{-1} \|v-\Pi_K v\|_{L^r(K)} +|v-\Pi_K v|_{W^{1,r}(K)}
\lesssim
h_K^{d/r-d/q} \left (\frac{h_K}{L}\right )^s
\sum_{t=0}^{s} L^{t} |v|_{W^{t+1,q}(K)}
\end{equation}
for all $v \in W^{s+1,q}(K)$, where the hidden constants depend on $p$, $r$, $q$, $s$,
$M_K$ and $M_K(s+1)$.
\end{theorem}

\begin{proof}
Since $\Pi_K$ is a projection onto
$\mathcal{P}(K)$, we have
\begin{equation*}
\|v-\Pi_K v\|_{L^r(K)}
=
\|v-v_h-\Pi_K(v-v_h)\|_{L^r(K)}
\leq
\|v-v_h\|_{L^r(K)}+\|\Pi_K(v-v_h)\|_{L^r(K)},
\end{equation*}
and similarly
\begin{equation*}
|v-\Pi_K v|_{W^{1,r}(K)}
\leq
|v-v_h|_{W^{1,r}(K)}+|\Pi_K(v-v_h)|_{W^{1,r}(K)},
\end{equation*}
for all $v_h \in \mathcal{P}(K)$. It then follows from~\eqref{eq_stability_Lq}
and~\eqref{eq_stability_W1q} that
\begin{equation*}
h_K^{-1} \|v-\Pi_K v\|_{L^r(K)} + |v-\Pi_K v|_{W^{1,r}(K)}
\lesssim
h_K^{-1} \|v-v_h\|_{L^r(K)}+|v-v_h|_{W^{1,r}(K)}.
\end{equation*}
We next apply~\eqref{eq_change_of_variable} and~\eqref{eq_W1q_K_hK} which give
\begin{equation*}
\|v-\Pi_K v\|_{L^r(K)}
\lesssim h^{d/r} h_K^{-1}
\left (\|\widehat{v}-v_h \circ \mathcal{F}_K\|_{L^r(\widehat{K})}
+
|\widehat{v}-v_h \circ \mathcal{F}_K|_{W^{1,r}(\widehat{K})}
\right )
\end{equation*}
where $\widehat{v} := v \circ \mathcal{F}_K$. Since $v_h \in \mathcal{P}_K$
was arbitrary, it follows that
\begin{equation*}
\|v-\Pi_K v\|_{L^r(K)}
\lesssim
h^{d/r} h_K^{-1}
\min_{\widehat{v}_h \in \mathcal P_p(\widehat{K})}
\left (\|\widehat{v}-\widehat{v}_h\|_{L^r(\widehat{K})}
+
|\widehat{v}-\widehat{v}_h|_{W^{1,r}(\widehat{K})}
\right )
\end{equation*}
and it follows from~\cite[Theorem 3.1.1]{Cia02} that
\begin{equation*}
\|v-\Pi_K v\|_{L^r(K)}
\lesssim
h^{d/r} h_K^{-1}
|\widehat{v}|_{W^{s+1,q}(\widehat{K})}.
\end{equation*}
At that point,~\eqref{eq_bramble_hilbert} follows from~\eqref{eq_Wsq_hK_K}.
\end{proof}

\subsection{Construction of the quasi-interpolation operator}

We are almost ready to introduce a quasi-interpolation operator satisfying
Theorem~\ref{theorem_quasi_interpolant}. Before that, we need to recall some
standard facts about the nodal basis of $V_h$.

There exists a finite set of nodes $\mathcal{D}_h \subset \overline{\Omega} \setminus \GD$
and an associated basis $\{\phi_{\ba}\}_{\ba \in \mathcal{D}_h}$ of $V_h$ such that
\begin{equation*}
\phi_{\ba}(\bb) = \delta_{\ba,\bb}
\end{equation*}
for all $\ba,\bb \in \mathcal{D}_h$.
These basis functions are obtained in each physical element from reference basis functions,
meaning that there exists a finite set $\widehat{\Phi} \subset \mathcal{P}_p(\widehat{K})$
such that for each $\ba \in \mathcal{D}_h$ and $K \in \mathcal{T}_h$, we have
\begin{equation}
\label{eq_phia_mapping}
\phi_{\ba}|_K = \widehat{\phi} \circ \mathcal{F}_K
\end{equation}
for some $\widehat{\phi} \in \widehat{\Phi}$. The nodes in $\mathcal{D}_h$ are associated
with vertices, edges or interiors of cells of the mesh $\mathcal{T}_h$, and the basis functions
have local support.

We denote by $\mathcal{D}_h(K) := \mathcal{D}_h \cap K$ the set of nodes $\ba \in \mathcal{D}_h$
with non-vanishing basis function $\phi_{\ba}$ on $K$. In addtion, for each $\ba \in \mathcal{D}_h$
\begin{equation*}
\mathcal{T}_h^{\ba} := \left \{
K \in \mathcal{T}_h \; | \; \ba \in \mathcal{D}_h(K)
\right \}
\end{equation*}
is the set of elements in the support of $\phi_{\ba}$, and we use the short hand notation
$\sharp \ba$ for the cardinal of $\mathcal{T}_h^{\ba}$.


We are now ready to introduce our quasi-interpolation operator.
It is an ``Oswald'' interpolation operator in the spirit of the seminal
contribution~\cite{oswald_1999a}. Our quasi-interpolation operator
$I_h: H^1_{\GD}(\Omega) \to V_h$, is defined by requiring that
\begin{equation*}
I_h(v)(\ba) = \frac{1}{\sharp \ba} \sum_{K \in \mathcal{T}_h^{\ba}} (\Pi_K v)(\ba)
\end{equation*}
for all degree of freedom nodes $\ba \in \mathcal{D}_h$. In fact,
as we already alluded to, our analysis essentially extends the
one in~\cite{ern_guermond_2017a}.

The following shorthand notation will be useful. We introduce the broken projection
$I_h^\flat: H^1_{\GD}(\Omega) \to V_h^\flat$ by setting $I_h^\flat(v)|_K = \Pi_K(v)$ for all
$K \in \mathcal{T}_h$.

\begin{lemma}[Dofs mismatch]
Let $\ba \in \mathcal{D}_h$. Then, for all pairs $K_\pm \in \mathcal{T}_h^{\ba}$ of elements
sharing a face $F = \partial K_+ \cap \partial K_-$, we have
\begin{equation}
\label{eq_mismatch_face}
|(\Pi_{K_+}v)(\ba)-(\Pi_{K_-}v)(\ba)|
\lesssim
h_{K_+}^{1-d/2} |v-\Pi_{K_+}v|_{H^1(K_+)}
+
h_{K_-}^{1-d/2} |v-\Pi_{K_-} v|_{H^1(K_-)}
\end{equation}
for all $v \in H^1_{\GD}(\Omega)$ with hidden constants depending on $M_{K_\pm}$.
Besides, if $K \in \mathcal{T}_h$ and $\ba \in \mathcal{D}_h(K)$, we have
\begin{equation}
\label{eq_mismatch}
|(\Pi_Kv)(\ba)-(\Pi_{K'}v)(\ba)|
\lesssim
h_K^{1-d/2} |v-I_h^\flat(v)|_{H^1(\mathcal{T}_h^K)}
\end{equation}
for all $K' \in \mathcal{T}_h^{\ba}$. Here, the hidden constant
only depends on $M_{\mathcal{T}_h^K}$.
\end{lemma}

\begin{proof}
We first focus on~\eqref{eq_mismatch_face}, and the following notation will be useful.
We let $\widehat{F}_\pm := \mathcal{F}_{K_\pm}^{-1}(F) \in \widehat{\mathcal{F}}$
and denote by $A_\pm$ the bijective affine maps between $\widehat{F}_{d-1}$ and $\widehat{F}_{\pm}$
used in~\eqref{eq_compatible_mappings}. We further write $v_\pm := \Pi_{K_\pm} v \in \mathcal{P}(K_\pm)$,
$\widehat{v}_\pm := v_\pm \circ \mathcal{F}_{K_\pm} \circ A_\pm \in L^2(\widehat{F}_{d-1})$
and $\widehat{\ba} = (\mathcal{F}_{K_\pm} \circ A_\pm)^{-1}(\ba) \in \widehat{F}_{d-1}$.
We further point out that $\widehat{v}_\pm \in \mathcal{P}_p(\widehat{F}_{d-1)}$ since
$A_\pm$ are affine maps, and that the definition of $\widehat{\ba}$ is not ambiguous
due to~\eqref{eq_compatible_mappings}.

We start by writing that
\begin{equation*}
|v_+(\ba)-v_-(\ba)|
=
|\widehat{v}_+(\widehat \ba)-\widehat{v}_-(\widehat \ba)|
\leq
\|\widehat{v}_+-\widehat{v}_-\|_{L^\infty(\widehat{F}_{d-1})}
\lesssim
\|\widehat{v}_+-\widehat{v}_-\|_{L^2(\widehat{F}_{d-1})}
\end{equation*}
where we used a standard inverse inequality on the face $\widehat{F}_{d-1}$,
which is possible since $\widehat{v}_\pm$ belong to the finite-dimensional space
$\mathcal{P}_p(\widehat{F}_{d-1})$. We then introduce
$\widehat{v} := v \circ \mathcal{F}_{K_\pm} \circ A_\pm \in L^2(\widehat{F}_{d-1})$
and we write that
\begin{equation*}
\|\widehat{v}_+-\widehat{v}_-\|_{L^2(\widehat{F}_{d-1})}
=
\|\widehat{v}_+-\widehat{v}+(\widehat{v}-\widehat{v}_-)\|_{L^2(\widehat{F}_{d-1})}
\leq
\|\widehat{v}_+-\widehat{v}\| _{L^2(\widehat{F}_{d-1})}
+
\|\widehat{v}-\widehat{v}_-\|_{L^2(\widehat{F}_{d-1})}.
\end{equation*}
We can now write
\begin{equation*}
\|\widehat{v}-\widehat{v}_\pm\|_{L^2(\widehat{F}_{d-1})}
\lesssim
\|(v-v_\pm) \circ \mathcal{F}_{K_\pm}\|_{L^2(\widehat{F}_\pm)}
\end{equation*}
since the map $A_\pm$ is affine and invertible and only depends on the choice
of reference simplices. A trace inequality on the reference $d$-simplex
then gives that
\begin{equation*}
\|\widehat{v}-\widehat{v}_\pm\|_{L^2(\widehat{F}_{d-1})}
\lesssim
\|(v-v_\pm) \circ \mathcal{F}_{K_\pm}\|_{L^2(\widehat{K})}
+
|(v-v_\pm) \circ \mathcal{F}_{K_\pm}|_{H^1(\widehat{K})},
\end{equation*}
and we conclude with~\eqref{eq_change_of_variable},~\eqref{eq_Wsq_hK_K} and~\eqref{eq_poincare}.

We now prove~\eqref{eq_mismatch}. If $K = K'$, there is nothing to show, and
if $K$ and $K'$ share a face, then~\eqref{eq_mismatch} is a direct consequence
of~\eqref{eq_mismatch_face}. In the general case, however, we might only have
$K \cap K' = \ba$ if $\ba$ is vertex of $\mathcal{T}_h$.
Nevertheless, in this case, there exists
a chain of $n$ elements $K = K_1, \ldots, K_n = K'$ that are all connected by a face,
and~\eqref{eq_mismatch} then follows from the triangular inequality
\begin{equation*}
|(\Pi_K v)(\ba)-(\Pi_{K'}v)(\ba)|
\leq
\sum_{j=1}^{n-1} |(\Pi_{K_{j+1}} v)(\ba)-(\Pi_{K_j}v)(\ba)|
\end{equation*}
by applying~\eqref{eq_mismatch_face} to each summand and observing that
$h_{K_j} \lesssim h_K$ for $j=1,\dots,n$ due to~\eqref{eq_comparable_diameters}
\end{proof}

\begin{lemma}[Basis function scaling]
For all $\ba \in \mathcal{D}_h$ and $K \in \mathcal{T}_h$, we have
\begin{equation}
\label{eq_phia_scaling}
\|\phi_{\ba}\|_{L^r(K)} + h_K|\phi_{\ba}|_{W^{1,r}(K)}
\lesssim
h_K^{d/r}
\end{equation}
where the hidden constant depends on $p$ and $M_K$.
\end{lemma}

\begin{proof}
It is a simple combination of~\eqref{eq_phia_mapping} and the change
of coordinates formulas~\eqref{eq_change_of_variable}
and~\eqref{eq_W1q_K_hK}.
\end{proof}

\begin{theorem}[Error in conformity enforcement]
Let $v \in H^1_{\GD}(\Omega)$. Then, for all $K \in \mathcal{T}_h$, we have
\begin{equation}
\label{eq_Ihb_Ih}
h_K^{-1}\|I_h^\flat(v)-I_h(v)\|_{L^r(K)}+|I_h^\flat(v)-I_h(v)|_{W^{1,r}(K)}
\lesssim
h_K^{d/r-d/2} |v-I_h^\flat(v)|_{H^1(\mathcal{T}_h^K)}
\end{equation}
with a hidden constant solely depending on $M_{\mathcal{T}_h^K}$.
\end{theorem}

\begin{proof}
Let us first obersve that for a fixed $K \in \mathcal{T}_h$, we have
\begin{align*}
\left .\left ( I^\flat(v)-I_h(v) \right )\right |_K
&=
\sum_{\ba \in \mathcal{D}_h(K)}
\left \{
(\Pi_K v)(\ba)
-
\frac{1}{\sharp \ba}
\sum_{K' \in \mathcal{T}_h^{\ba}}
(\Pi_{K'}v)(\ba)
\right \}
\phi_{\ba}|_K
\\
&=
\sum_{\ba \in \mathcal{D}_h(K)}
\frac{1}{\sharp \ba}
\sum_{K' \in \mathcal{T}_h^{\ba}}
\left \{
(\Pi_K v)(\ba)
-
(\Pi_{K'}v)(\ba)
\right \}
\phi_{\ba}|_K,
\end{align*}
so that
\begin{equation*}
\|I_h^\flat(v)-I_h(v)\|_{L^r(K)}
\leq
\sum_{\ba \in \mathcal{D}_h(K)}
\sum_{K' \in \mathcal{T}_h^{\ba}}
|
(\Pi_K v)(\ba)
-
(\Pi_{K'}v)(\ba)
|
\|\phi_{\ba}\|_{L^r(K)}
\end{equation*}
and
\begin{equation*}
|I_h^\flat(v)-I_h(v)|_{W^{1,r}(K)}
\leq
\sum_{\ba \in \mathcal{D}_h(K)}
\sum_{K' \in \mathcal{T}_h^{\ba}}
|
(\Pi_K v)(\ba)
-
(\Pi_{K'}v)(\ba)
|
|\phi_{\ba}|_{W^{1,r}(K)}.
\end{equation*}
It then follows from~\eqref{eq_phia_scaling} that
\begin{multline*}
h_K^{-1}\|I_h^\flat(v)-I_h(v)\|_{L^r(K)} + |I_h^\flat(v)-I_h(v)|_{W^{1,r}(K)}
\lesssim
\\
h_K^{d/r-1}
\sum_{\ba \in \mathcal{D}_h(K)}
\sum_{K' \in \mathcal{T}_h^{\ba}}
|
(\Pi_K v)(\ba)
-
(\Pi_{K'}v)(\ba)
|,
\end{multline*}
and~\eqref{eq_Ihb_Ih} follows from~\eqref{eq_mismatch} and Lemma~\ref{lemma_patch}.
\end{proof}

We are now ready to establish our main result.

\begin{proof}[Proof of Theorem~\ref{theorem_quasi_interpolant}]
We first observe that~\eqref{eq_error_estimate_global} follows from~\eqref{eq_error_estimate}
due to Lemma~\ref{lemma_patch} by observing that
\begin{multline*}
\sum_{K \in \mathcal{T}_h}
|\phi|_{W^{t+1,q}(\mathcal{T}_h^K)}^q
=
\sum_{K \in \mathcal{T}_h}
\sum_{\substack{K' \in \mathcal{T}_h \\ K' \cap K \neq \emptyset}}
|\phi|_{W^{t+1,q}(K')}^q
\\
=
\sum_{K' \in \mathcal{T}_h}
\sum_{\substack{K \in \mathcal{T}_h \\ K \cap K' \neq \emptyset}}
|\phi|_{W^{t+1,q}(K')}^q
\leq
N |\phi|_{W^{t+1,q}(\mathcal{T}_h)}^q
\lesssim
|\phi|_{W^{t+1,q}(\mathcal{T}_h)}^q
\end{multline*}
for all $t \geq 0$, $q \geq 2$ and $\phi \in W^{t+1,q}(\mathcal{T}_h)$.

We therefore fix $K \in \mathcal{T}_h$ and establish~\eqref{eq_error_estimate}.
We start with the triangular inequality
\begin{align*}
h_K^{-1}\|v-I_h(v)\|_{L^r(K)}
+
|v-I_h(v)|_{W^{1,r}(K)}
&\leq
h_K^{-1}\|v-I_h^\flat(v)\|_{L^r(K)}
+
|v-I_h^\flat(v)|_{W^{1,r}(K)}
\\
&+
h_K^{-1}\|I_h^\flat(v)-I_h(v)\|_{L^r(K)}
+
|I_h^\flat(v)-I_h(v)|_{W^{1,r}(K)}.
\end{align*}
Since $v-I_h^\flat(v)|_K = v-\Pi_K v$, we can immediatly
apply~\eqref{eq_bramble_hilbert} for the corresonding terms.
For the other terms, we involve~\eqref{eq_Ihb_Ih}, to write
\begin{equation*}
h_K^{-1}\|I_h^\flat(v)-I_h(v)\|_{L^r(K)}
+
|I_h^\flat(v)-I_h(v)|_{W^{1,r}(K)}
\lesssim
h_K^{d/r-d/2}|v-I_h^\flat(v)|_{H^1(\mathcal{T}_h^K)}.
\end{equation*}
At that point,~\eqref{eq_error_estimate} follows from~\eqref{eq_bramble_hilbert}.
\end{proof}


