\section{Preliminaries and problem definition}

\subsection{Preliminaries}


Let $ G = (V, E)$  be a temporal graph, with $|V|=n$ and $|E|=M$. Each temporal edge $ e \in E $ is defined as a quadruple $ (u, v, t, \lambda )$, with \( u, v \in V \), where  $t$  denotes the \textit{starting time}, $ \lambda$  denotes the \textit{traversal time} needed to travel from $ u$ to $v$ starting at time $t$, and $t + \lambda $ represents the \textit{ending time}. Most of our algorithms receive as input an \emph{edge stream}, containing all edges sorted by ascending $t$-value. This is standard for temporal graphs~\cite{Holme_Temporal_graphs,Lee_edgestream,OettershagenKM23_edgestream,Path_Wu}.


The set of temporal edges from $u$ to $v$ $(u,v \in V)$ is denoted by $E(u,v)$. Let $\pi = \max \limits _{u,v \in V}\{|E(u,v)|\}$ (maximum number of parallel edges) and $m = |\{u,v \in V : |E(u,v)| > 0\}$ (number of connected pairs of vertices).
We denote with $N_{out}(u) = \{v : (u,v,t,\lambda) \in E \}$ the set of out-neighbours of $u \in V$, and with $d_{out}$ the maximum out-degree in $G$. We similarly define $N_{in}(u)$ and $d_{in}$.
Finally, $d_{max}$ denotes the maximum between $d_{out}$ and $d_{in}$.
%\SotirisComment{dout, din are not the sizes of the neighbor sets, they are the degrees (based on temporal edges)}


A \emph{temporal path} $P$ in a temporal graph $G$ is a sequence of vertices $P=\langle v_1,v_2,\dots, v_\ell\rangle$ where $(v_i, v_{i+1},t_i, \lambda_i) \in E$ is the $i$-th temporal edge on $P$ for $1 \leq i \leq \ell$, and $(t_i+\lambda_i) \leq t_{i+1}$ for $1 \leq i < \ell$.
The quantity $(t_\ell + \lambda_\ell)$ is known as the \emph{ending time} of $P$, denoted by $end(P)$, while $t_1$ is the \emph{starting time} of $P$, $start(P)$. 
The \emph{duration} of $P$ is defined as $dura(P)=end(P)-start(P)$. 
Finally, the sum of the traversal time of each temporal edge of $P$ is known as the \emph{distance} of the path, denoted as $dist(P)$.



%\AnnaComment{Maybe we can give the graph transformation here?}








%In some of our algorithms we will assume the removal of a subset of the temporal edges.
%We call these edges \textit{dominated}.

\begin{definition}[\textbf{Dominated edge}]
\label{def:dom_edge}
    We say that a temporal edge $e = (u, v, t, \lambda)$ is \emph{dominated} if there exists another edge $e' = (u, v, t', \lambda')$ such that $t' \ge t$ and $t' + \lambda' \le t + \lambda$, with at least one of the two inequalities being strict. Symmetrically, we say that edge $e'$ \emph{dominates} edge $e$.
\end{definition}

%\textit{Example: }

%Intuitively, in any optimality criterion considered, there would be no benefit in using a temporal edge $e$ as opposed to a temporal edge $e'$ that dominates $e$.
%The edge domination criterion naturally generalizes to paths.

\begin{definition}[\textbf{Dominated paths}]
\label{def:dom_path}
Let $P$ be a temporal $u-v$ path. We say that $P$ is \emph{dominated} if there exists another temporal $u-v$ path $P'$ such that $\text{start}(P') \ge \text{start}(P)$ and $\text{end}(P') \le \text{end}(P)$, with at least one of the inequalities being strict. We say that $P$ is \emph{distance-wise dominated} if there exists a temporal $u-v$ path $P'$ such that $\text{dist}(P') \le \text{dist}(P)$ and $\text{end}(P') \le \text{end}(P)$, with at least one of the inequalities being strict.
\end{definition}


In some of our algorithms we will use a subroutine that computes all\footnote{If there are paths $P,P'$ with $start(P)=start(P')$ and $end(P)=end(P')$, the algorithm only stores one of them, since they can be used interchangeably for any objective. Throughout the paper, when we say "all non-dominated paths", we imply that only one path is kept when there are such ties.} non-dominated paths from one node to all others. This is useful for finding fastest paths, as well as for precomputing certain paths in temporal graphs to answer queries faster. This subroutine consists of part of the fastest-path algorithm of \cite{Path_Wu}. We defer the full algorithm to Appendix~\ref{appendix_omit_algo}.

\begin{algorithm}[H]
\caption{$\texttt{Non-dom\textunderscore paths($G,x,[t_\alpha,t_\omega]$)}$}
\label{alg:non_dominated_paths}
\begin{algorithmic}[1]
\Require{A temporal graph $G = (V, E)$, source vertex $x$, time interval $[t_\alpha, t_\omega]$.}
\Ensure{For $v \in V$, the list $L_v$ of non-dominated $(s, a)$ pairs (from $x$ to $v$) within \([t_{\alpha},t_{\omega}]\).}
\end{algorithmic}
\end{algorithm}


Algorithm~\ref{alg:non_dominated_paths} runs in time $\bigO(n+M \log(c))$, where $c= \min \{d_{in},d_{out}\}$. Note that $c$ is a bound for the amount of non-dominated pairs $(s,a)$ (start, arrival) between any two vertices and, thus, also a bound for the size of each $L_v$. For more details, we defer the reader to~\cite{Path_Wu}.

We will also use a similar subroutine for distance-wise non-dominated paths, which is part of the shortest-path algorithm of~\cite{Path_Wu}. Its full description is deferred to Appendix~\ref{appendix_omit_algo}.


\begin{algorithm}[H]
\caption{$\texttt{Dist\textunderscore non-dom\textunderscore paths($G,x,[t_\alpha,t_\omega]$)}$}
\label{alg:distance_non_dominated_paths}
\begin{algorithmic}[1]
\Require{A temporal graph $G = (V, E)$, source vertex $x$, time interval $[t_\alpha, t_\omega]$.}
\Ensure{For $v \in V$, the list $S_v$ of distance-wise non-dominated $(d, a)$ pairs (from $x$ to $v$) within \([t_{\alpha},t_{\omega}]\).}
\end{algorithmic}
\end{algorithm}

Algorithm~\ref{alg:distance_non_dominated_paths} runs in time $\bigO(n+M \log (d_{in}))$. Observe that $d_{in}$ is a bound for the amount of distance-wise non-dominated pairs $(d,a)$ (distance, arrival) between any two vertices.


\subsection{The temporal beer path problem}

We assume a temporal graph with a set $B = \{b_1, \dots, b_k\} \subseteq V$ of $k$ \emph{beer vertices}. 
For each beer vertex $b \in B$, we are given a set $T_{b}$ of timestamps denoting the time instants in which $b$ is \emph{active}.
We assume that beer vertices can still be traversed in time units in which they are inactive, functioning as regular vertices.
We define $T=\max\limits_{b \in B} \{|T_b|\}$.

Given a temporal graph $G$, vertices $x,y \in  V$ and a time interval $[t_\alpha, t_\omega ]$, we denote the set of temporal beer paths between two vertices $x$ and $y$ starting after $t_\alpha$ and ending before $t_\omega$ as $P_B(x,y,[t_\alpha, t_\omega]) =$ $\{P=\langle x=v_1,v_2,\dots,v_\ell=y\rangle:P$  is a temporal path from $x$ to $y$ such that  $start(P) \geq t_\alpha, \ end(P) \leq t_\omega, \ \exists \ (i \in [\ell], t \in T_{v_i}) : (v_i \in B, \  t \in [t_i + \lambda_i,  t_{i+1}]  ) \}$. Note that a beer path must traverse at least one beer vertex at a time in which it is active. 

%We will focus on a subset of these paths based on the following four optimality criteria.

\begin{definition}[\textbf{EABP}]\label{def:eabp}
    A temporal $x$-$y$ path $P \in {P_B}(x,y,[t_\alpha, t_\omega])$ is an earliest-arrival beer path if $end(P) = \min \{ end(P'): P' \in P_B(x,y,[t_\alpha, t_\omega]) \}$.
\end{definition}

%\textit{Example:} In Figure~\ref{fig:temporal_graph} the $x$-$y$ earliest-arrival beer path is $\langle x, b_1, y \rangle$, ending in $y$ at time instant 11.

\begin{definition}[\textbf{LDBP}]\label{def:ldbp}
    A temporal $x$-$y$ path $P \in {P_B}(x,y,[t_\alpha, t_\omega])$ is a latest-departure beer path if $start(P) = \max \{ start(P'): P' \in P_B(x,y,[t_\alpha, t_\omega]) \}$.
\end{definition}

%\textit{Example:} In Figure~\ref{fig:temporal_graph} the $x$-$y$ latest-departure beer path is $\langle x, b_2, y \rangle$, ending in $y$ at time instant 35.


\begin{definition}[\textbf{FBP}]\label{def:fbp}
    A temporal $x$-$y$ path $P \in {P_B}(x,y,[t_\alpha, t_\omega])$ is a fastest beer path if $dura(P) = \min \{ dura(P'): P' \in P_B(x,y,[t_\alpha, t_\omega]) \}$.
\end{definition}

%\textit{Example:} In Figure~\ref{fig:temporal_graph} the $x$-$y$ fastest beer path is $\langle x, b_3, y \rangle$, whose duration equals 3.


\begin{definition}[\textbf{SBP}]\label{def:sbp}
    A temporal $x$-$y$ path $P \in {P_B}(x,y,[t_\alpha, t_\omega])$ is a shortest beer path if $dist(P) = \min \{ dist(P'): P' \in P_B(x,y,[t_\alpha, t_\omega]) \}$.
\end{definition}

%\textit{Example:} In Figure~\ref{fig:temporal_graph} the $x$-$y$ shortest beer path is $\langle x, b_4, y \rangle$, whose distance is equal to 2.


