\section{Algorithms for temporal beer path problems}\label{sec:algo}

In all our algorithms, we focus on the computation of the objective function (e.g., the earliest arrival time) instead of reporting the corresponding optimal path. This  path can be easily recovered by storing parent information. 

\subsection{Algorithms for earliest-arrival beer path }\label{subsec:earliest_beer}

In this subsection we propose an EABP algorithm (from source $x$ to all nodes), based on the earliest-arrival time algorithm of \cite{Path_Wu} with a modification for calculating \emph{multiple-source} earliest-arrival paths (MSEAP - Def.~\ref{def:multisource}). Our algorithm makes two sequential passes of the graph's edge stream, calculating the earliest arrival times from $x$ to each beer vertex in the first pass. For the second pass, all arrival times are initialized to $\infty$, except those of the beer vertices, which are initialized to the minimum active time greater than or equal to their respective earliest arrival time. We will later prove that this correctly calculates EABP times.

We also present a MSEAP subroutine for graphs containing no dominated edges.\footnote{This is a reasonable assumption for temporal graphs, since dominated edges are not useful for any of the commonly considered objectives.} This algorithm is similar-in-spirit to Dijkstra's algorithm and uses binary search for parallel edges, achieving a running time independent of $M$. Although faster than the previous one, it requires random access to the edges of the graph (through e.g. an adjacency list with temporal logs~\cite{Caro_temporal_logs}), instead of scanning an edge stream in a specific order. 




\subsubsection{An earliest-arrival beer path algorithm in edge stream representation }

%We define Multiple-Source Earliest-Arrival Paths (MSEAPs), which will prove useful as an intermediate step for calculating earliest-arrival beer paths.

\begin{definition}[MSEAP]\label{def:multisource}
    Given a temporal graph $G=(V,E)$ and initial times $init[v]\in \mathbb{R}^+ \cup \{\infty\}$, $v\in V$, we say that a temporal path $x-y$ starting from $x$ no earlier than $init[x]$ is a \emph{multiple-source earliest-arrival path} to $y$ if its arrival time at $y$ is minimum among all temporal paths $v-y$, $v\in V$, starting from $v$ no earlier than $init[v]$. We call this arrival time the \emph{multiple-source earliest-arrival path time} of $y$.
\end{definition}

Intuitively, a MSEAP is a path that can reach a target node in the earliest possible time unit, starting from any node of the graph, with restrictions for the starting time of each node. If some $init[v]$ is $\infty$, we cannot start a path from $v$.
We first show that a generalization of the earliest-arrival path algorithm of \cite{Path_Wu} can compute MSEAPs. 





\begin{algorithm}[H]
\caption{$\texttt{MSEAP$(G,[t_\alpha,t_\omega],init)$}$}
\label{alg:earliest_multisource_stream}
\begin{algorithmic}[1]

\Require{A temporal graph $G$ in its edge stream
 representation, a time window $[t_{\alpha}, t_{\omega}]$ and initial times $init[v]$, such that $t_\alpha \leq init[v] \leq t_\omega$ or $init[v] = \infty$, for all $v \in V$.}
\Ensure{The MSEAP times within $[t_\alpha, t_\omega]$ to every vertex, assuming we can start at time $init[v]$ from each $v \in V$.}


\State $\tau[v] \gets init[v]$ \textbf{for all} $v \in V$

\For{$e=(u,v,t,\lambda)$ in the edge stream}{
    \If{$\tau[u]\leq t$ \textnormal{\textbf{and}} $t+\lambda\leq t_{\omega}$}
       \State $\tau[v] \gets \min\{\tau[v], t+\lambda\}$
    \EndIf
}
\EndFor

\State \Return{$\tau[v]$ for each $v \in V$}
\end{algorithmic}
\end{algorithm}

Algorithm~\ref{alg:earliest_multisource_stream} scans each temporal edge once and thus runs in time $\bigO(n+M)$.

\begin{observation}\label{obs:single_source_earliest}
    With initialization $init[x] = t_\alpha$ for some $x \in V$ and $init[v] = \infty$ for $v \in V \setminus \{x\}$, Algorithm~\ref{alg:earliest_multisource_stream} coincides with the earliest-arrival time algorithm of \cite{Path_Wu} with source node $x$ and calculates single-source earliest arrival paths.
\end{observation}

\begin{lemma}[Wu et al.~\cite{Path_Wu}]\label{lem:earliest_prefix_property}
    For all nodes $x,y \in V$, if there exists some temporal $x-y$ path, then there exists some earliest-arrival $x-y$ path $\langle v_0=x,v_1,v_2,\ldots,v_k=y \rangle$ for which every prefix-subpath $\langle x,v_1,v_2,\ldots,v_i \rangle$ is an earliest-arrival $x-v_i$ path.
\end{lemma}

\begin{observation}
    In temporal graphs, the property described in Lemma~\ref{lem:earliest_prefix_property} only holds for some $x-y$ earliest-arrival path, in contrast to classical graphs, where a similar property holds for all $x-y$ shortest paths.
\end{observation}

The following lemma is analogous to Lemma~\ref{lem:earliest_prefix_property} for MSEAPs.

\begin{lemma}\label{lem:earliest_multisource_prefix_property}
     For $G=(V,E)$ and $init[v]\in \mathbb{R}^+ \cup \{\infty\}$, $v\in V$, it holds that for every $y \in V$ with non-infinite MSEAP time there exists some MSEAP $\langle v_0,v_1,\ldots,v_p=y \rangle$ to $y$ for which every prefix-subpath $\langle v_0,v_1,\ldots,v_i \rangle$ is a MSEAP to $v_i$.
\end{lemma}

\begin{proof}
    Let \(P=\langle u_0,u_1,\dots ,u_p=y\rangle\) be an arbitrary MSEAP to $y$. If the desired property does not hold for \(P\), take the maximum $i \in [p]$ s.t. the prefix-subpath \(R=\langle u_0,\dots ,u_i\rangle\) of $P$ is not a MSEAP to \(u_i\). Let \(Q=\langle w_0,w_1,\dots ,w_j=u_i\rangle\) be a MSEAP to $u_i$. Replace $R$ with \(Q\), keeping the suffix $\langle u_{i+1},\dots ,u_p\rangle$ unchanged.
    Since \(Q\) reaches \(u_i\) no later than $R$ (by definition of MSEAP), the resulting path $P'$ is a valid temporal path and the arrival times of nodes $u_{i+1},\ldots u_p$ through $P'$ remain the same as they were in $P$ (and, thus, the desired property is preserved for those nodes).
    This process can be repeated until every prefix-subpath is a MSEAP.
\end{proof}


\begin{lemma}\label{lem:earliest_multisource_correctness}
    Algorithm~\ref{alg:earliest_multisource_stream} computes the MSEAP times to each vertex, within time window $[t_\alpha, t_\omega]$. If time $\infty$ is returned for some vertex, then that vertex is unreachable from all $v \in V$ (starting no earlier than $init[v]$) within $[t_\alpha, t_\omega]$.
\end{lemma}

\begin{proof}
    For each \(v \in V\) let \(\tau[v]\) be the time calculated by the algorithm and \(\tau^*[v] \) be the respective MSEAP time (within $[t_\alpha, t_\omega]$). Since \(\tau[v]\) is initialized to $init[v]$, any update done by the algorithm calculates the arrival time of a valid temporal path, starting from some node $v$ at time $init[v]$. Thus, at any step of the algorithm it holds that \(\tau[v] \geq \tau^*[v]\), $\forall v \in V$.

    Fix an arbitrary vertex \(y\) with \(\tau^*[y]<\infty\). By Lemma~\ref{lem:earliest_multisource_prefix_property}, there exists a MSEAP $P=\langle v_{0}=x,v_{1},\dots ,v_{p}=y\rangle$ to $y$ s.t. every prefix-subpath $\langle v_0,v_1,v_2,\ldots,v_i \rangle$ of $P$ is a MSEAP to $v_i$. 
    Denote the \(i\)-th edge of $P$ by \(e_i = (v_{i-1},v_{i},t_{i},\lambda_{i}), i=1,2,\dots,p\). Thus, it holds that \(t_{i}\geq \tau^*[v_{i-1}]\) and \(\tau^*[v_{i}]=t_{i}+\lambda_{i}\). 
    We will show by induction on \(i\) that Algorithm \ref{alg:earliest_multisource_stream} computes \( \tau[v_i] = \tau^*[v_i]\) after processing \(e_i\).

    \emph{Base} \((i=0)\). By the prefix-subpath property of $P$, we have \(\tau ^*[x]=init[x]\). By the initialization of the algorithm, $\tau[x] \leq init[x]$. Thus, $\tau[x]=\tau^*[x]$.


    \emph{Inductive step} \((i \geq 1)\). Assume \(\tau[v_{i-1}]=\tau^*[v_{i-1}]\) after \(e_{i-1}\) is processed.
    When Algorithm \ref{alg:earliest_multisource_stream} scans \(e_{i}=(v_{i-1},v_{i},t_{i},\lambda_{i})\), it holds that $t_i \geq \tau[v_{i-1}]=\tau^*[v_{i-1}]$. Thus, \(\tau[v_{i}]\) is updated to \(t_{i}+\lambda_{i}=\tau^*[v_{i}]\) (unless it was already equal to that value). Since it always holds that \(\tau[v] \geq \tau^*[v]\), $\forall v \in V$, $\tau[v_i]$ will never be updated again after this step.

    From the above we infer that $\tau[v]=\infty$ can be returned for some $v\in V$ only if no MSEAP to $v$ exists. This implies that $v$ is unreachable from all $u \in V$ (starting no earlier than $init[u]$) within $[t_\alpha, t_\omega]$.
\end{proof}


We now present an EABP algorithm, which calls Algorithm~\ref{alg:earliest_multisource_stream} twice, calculating earliest-arrival path times in the first phase and EABP times in the second phase.


\begin{algorithm}[H]
\caption{$\texttt{EABP$(G,x,[t_\alpha,t_\omega])$}$}
\begin{algorithmic}[1]

\Require{A temporal graph $G$, source vertex $x$, time window $[t_{\alpha}, t_{\omega}]$, a set of beer vertices $B$ and a list $T_i$ of time units for each of them.}
\Ensure{The EABP time from $x$ to every vertex $v \in V$ within $[t_\alpha, t_\omega]$.}


\State $init[x]\gets t_\alpha,\, init[v] \gets \infty$ \textbf{for all} $v \in V \setminus \{x\}$

\State $\tau[v] \leftarrow \texttt{MSEAP($G,[t_\alpha,t_\omega],init$)}$, for $v \in V$

\State $init'[v] \gets \infty$ \textbf{for all} $v \in V$

\For{{\textbf{all}} $b\in B$}{
    \State $beer\_ time \gets \min\{time \in T_b \mid time \geq \tau[b]\}$ \Comment{$\infty$ if it does not exist}

    \If{$beer\_ time \leq t_{\omega}$}
        \State $init'[b] \gets beer\_ time$
    \EndIf


}
\EndFor    
\State $\tau'[v] \leftarrow \texttt{MSEAP($G,[t_\alpha,t_\omega],init'$)}$, for $v \in V$

\State \Return{$\tau'[v]$ for each $v \in V$}
\end{algorithmic}
\label{alg:earliest_arrival_beer}
\end{algorithm}



\begin{theorem}\label{thrm:earliest_beer_correctness}
    Algorithm~\ref{alg:earliest_arrival_beer} computes the EABP times from $x$ to all $v \in V$ in time $\bigO(n+M+k\log (T))$.
\end{theorem}

\begin{proof}
    Algorithm~\ref{alg:earliest_arrival_beer} scans all edges twice. A binary search is done for each of the $k$ lists $T_b$. Hence, Algorithm~\ref{alg:earliest_arrival_beer} runs in time $\bigO(n+M+k\log (T))$.

    By Observation~\ref{obs:single_source_earliest}, the first call to Algorithm~\ref{alg:earliest_multisource_stream} correctly computes the earliest-arrival path times from $x$ to the beer vertices (within $[t_\alpha,t_\omega]$). Thus, the binary search on $T_b$ computes for each $b \in B$ the earliest departure time from $b$ s.t. $b$ is used as the beer vertex of a beer path from $x$ to any other node (within $[t_\alpha,t_\omega]$). Denote this time as $t[b]$, $b \in B$. Observe that, for any node $v$, the EABP time from $x$ to $v$ is the earliest time in which $v$ is reachable from some $b \in B$, starting from $b$ no earlier than $t[b]$. This coincides with the MSEAP time to $v$ for $init[b]=t[b]$, $b \in B$, and $init[u] = \infty$, $u \in V\setminus B$. Hence, the second call to Algorithm~\ref{alg:earliest_multisource_stream} correctly computes the EABP times from $x$ to all nodes (within $[t_\alpha,t_\omega]$), by Lemma~\ref{lem:earliest_multisource_correctness}.
\end{proof}

\subsubsection{A faster earliest-arrival beer path algorithm with adjacency list representation}



 We present an alternative algorithm to be used as the MSEAP subroutine of Algorithm~\ref{alg:earliest_arrival_beer}, in the place of Algorithm~\ref{alg:earliest_multisource_stream}. Although faster for graphs with no dominated edges, this algorithm requires an adjacency list instead of an edge stream. The algorithm is similar-in-spirit to Dijkstra's algorithm, using a min-priority queue for the nodes and their arrival times.

\begin{algorithm}[H]
\caption{$\texttt{MSEAP\textunderscore alternative$(G,[t_\alpha,t_\omega],init)$}$}
\label{alg:earliest_multisource_dijkstra}
\begin{algorithmic}[1]
\Require{A temporal graph $G$ in adjacency list
 representation, a time window $[t_{\alpha}, t_{\omega}]$ and initial times $init[v]$, such that $t_\alpha \leq init[v] \leq t_\omega$ or $init[v] = \infty$, for all $v \in V$.}
\Ensure{The MSEAP times within $[t_\alpha, t_\omega]$ to every vertex, assuming we can start at time $init[v]$ from each $v \in V$.}


\State $\tau[v] \gets init[v]$ \textbf{for all} $v \in V$

\State $PQ \gets \emptyset$ \Comment{a min-priority queue}
\State $PQ.enqueue (\tau[v],v)$ \textbf{for all} $v \in V$
\Comment{Add $v$ to priority queue with $\tau[v]$ priority}

\While{$PQ \neq \emptyset$}
    \State $(\tau[u],u) \gets PQ.extractMin()$

    \For{$v \in N_{out}(u)$}
        \State Let $(u,v,t,\lambda) \in E(u,v)$ be a temporal edge with minimum $t$ s.t. $t \geq \tau[u]$ 

        %\Comment{binary search on $t$ of all $e \in E(u,v)$ }
        \If{$t + \lambda \leq t_{\omega}$ \textnormal{\textbf{and} $t + \lambda < \tau[v]$}}
            \State $\tau[v] \gets t + \lambda$\;
             \State   $PQ.decreaseKey(v,\tau[v])$
        \EndIf
    \EndFor
\EndWhile

\State \Return{$\tau[v]$ for each $v \in V$}
\end{algorithmic}
\end{algorithm}



\begin{theorem}\label{thrm:earliest_beer_correctness_alternative}
    For graphs with no dominated edges, Algorithm~\ref{alg:earliest_arrival_beer} computes the EABP times from $x$ to all $v \in V$ in time $\bigO(m\log (\pi)+n\log (n) + k \log (T))$, if Algorithm~\ref{alg:earliest_multisource_dijkstra} is used as the MSEAP subroutine.
\end{theorem}

The proof of Theorem~\ref{thrm:earliest_beer_correctness_alternative} is similar-in-spirit to the proofs of Lemma~\ref{lem:earliest_multisource_correctness} and Theorem~\ref{thrm:earliest_beer_correctness} and is deferred to Appendix~\ref{appendix_omit_proof}. The $n\log n$ term in the time complexity stems from the usage of a Fibonacci heap as min-priority queue. The $m\log \pi$ term stems from binary search on parallel edges, which is possible by the assumption that $G$ contains no dominated edges.


\begin{observation}
    For graphs with no dominated edges, Algorithm~\ref{alg:earliest_multisource_dijkstra} is a faster alternative to Algorithm~\ref{alg:earliest_multisource_stream} under reasonable assumptions (albeit requiring an adjacency list as input instead of an edge stream). $M$ is bounded by $m \pi$ and may be arbitrarily larger than $m$, which renders $\bigO(m \log (\pi))$ a significant improvement over $\bigO(M)$.
\end{observation}


\subsection{Algorithms for latest-departure beer path}\label{subsec:latest_beer}

We propose two LDBP algorithms (from all nodes to some node $y$), based on the earliest-arrival algorithms presented in subsection~\ref{subsec:earliest_beer}.
The main idea is to reverse the direction of time, starting from the target node $y$ as late as possible and traversing temporal edges in reverse, while storing the latest time in which we can depart from each node to reach $y$. Due to space constraints, we defer the full descriptions of these algorithms to Appendix~\ref{appendix_omit_algo} and we briefly mention the main differences compared to those of subsection~\ref{subsec:earliest_beer}.

\begin{definition}[MTLDP]\label{def:multitarget}
   Given a temporal graph $G=(V,E)$ and final times $fin[v]\in \mathbb{R}^+ \cup \{-\infty\}$, $v\in V$, we say that a temporal $x-y$ path arriving at $y$ no later than $fin[y]$ is a \emph{multiple-target latest-departure path} from $x$ if its starting time from $x$ is maximum among all temporal paths $x-v$, $v\in V$, arriving at $v$ no later than $fin[v]$. We call this starting time the \emph{multiple-target latest-departure path time} of $x$.
\end{definition}

The main algorithm (analogous to Algorithm~\ref{alg:earliest_arrival_beer}) sets $fin[y]$ to $t_\omega$ and $fin[v]$ to $-\infty$ for all other nodes. A MTLDP subroutine is used to calculate latest-departure times in the first phase and LDBP times in the second phase. A search in each list $T_b$ is done before the second phase, similar to Algorithm~\ref{alg:earliest_arrival_beer}.

We now describe the main differences of the two MTLDP subroutines, compared to Algorithms~\ref{alg:earliest_multisource_stream} and~\ref{alg:earliest_multisource_dijkstra}. In the edge stream algorithm, the stream is scanned in reverse (i.e., by decreasing $t$-value) and each edge $(u,v,t,\lambda)$ updates $\tau [u]$ to $t$ if $\tau [u] < t$ and $t \geq t_a$ and $t+\lambda \leq \tau [v]$. In the adjacency list algorithm, a max-priority queue is used for MTLDP times and the binary search on parallel edges considers their $(t+\lambda)$-value\footnote{Note that non-dominated edges sorted by $t$-value are also sorted by $(t+\lambda)$-value (by definition). Thus, this binary search is possible with no additional precomputation.}. For each node $v$ extracted from the queue we consider its set $N_{in}(v)$ and the updates to the queue are done through \emph{increase-key} operations.
The time complexity of each algorithm is the same as in subsection~\ref{subsec:earliest_beer} and the correctness proofs are analogous.



\subsection{Algorithm for fastest beer path }

A significant difference for FBP compared to EABP/LDBP is that no property similar to Lemma~\ref{lem:earliest_prefix_property} holds. Indeed, computing a fastest path from the source to a beer vertex is unhelpful as an intermediate step for computing FBPs.


\begin{lemma}\label{lem:fastest}
    If there is a temporal $x-y$ beer path within time interval $[t_\alpha, t_\omega]$, then there is an $x-y$ FBP $\langle v_0=x,v_1,\ldots,v_j=b,\ldots,v_p=y\rangle$ within $[t_\alpha, t_\omega]$, traversing $b \in B$ at a time $t \in T_b$, such that its subpaths $\langle v_0=x,v_1,\ldots,v_j=b\rangle$ and $\langle v_j=b,v_{j+1},\ldots,v_p=y\rangle$ are non-dominated paths.
\end{lemma}

The proof of Lemma~\ref{lem:fastest} is deferred to Appendix~\ref{appendix_omit_proof}.
Based on Lemma~\ref{lem:fastest}, we propose a two-phase FBP algorithm (from source $x$ to all nodes), utilizing Algorithm~\ref{alg:non_dominated_paths}. In the first phase, all non-dominated paths from $x$ to each $b \in B$ are calculated. As in subsection~\ref{subsec:earliest_beer}, we find the minimum eligible active time for the respective beer vertex for each of these paths. 
For the second phase, a dummy vertex is used as source, connected with each $b \in B$ by (multiple) dummy edges with starting and traversal times dictated by the values calculated previously for each path. Algorithm~\ref{alg:non_dominated_paths} is then used for the new graph, calculating eligible non-dominated paths from the dummy vertex to all vertices.

\begin{algorithm}[H]
\caption{$\texttt{FBP$(G,x,[t_\alpha,t_\omega])$}$}
\label{alg:fastest_beer}
\begin{algorithmic}[1]
\Require{A temporal graph $G$ in edge stream representation, source vertex $x$, time interval $[t_\alpha, t_\omega]$, a set of beer vertices $B$ and a list $T_i$ of time units for each of them.}
\Ensure{The FBP duration from $x$ to every vertex $v \in V$ within $[t_\alpha, t_\omega]$.}


\State $L_b \leftarrow \texttt{Non-dom\textunderscore paths($G,x,[t_\alpha,t_\omega]$)}$, for $b \in B$
\Comment{calculate non-dom paths with Alg~\ref{alg:non_dominated_paths}}

\For{$b\in B$}
\For{$(s,a) \in L_b$}
    \State $a' \gets \min\{time \in T_b \mid time \geq a\}$  \Comment{$\infty$ if it does not exist}

    \If{$a' \leq t_{\omega}$}
        \State Replace $(s,a)$ with $(s,a')$ in $L_b$

    \Else
        \State Remove $(s,a)$ from $L_b$ \Comment{impossible to get beer}
    \EndIf
    \EndFor
\EndFor
%Remove dominated elements in $L_b$

\State Add dummy node $\epsilon$ to the graph. Add an edge $(\epsilon, b, s, a-s)$ for each $(s,a) \in L_b$ for each $b \in B$; Let $G'=(V',E')$ be the modified graph\;

\State $L_v' \leftarrow \texttt{Non-dom\textunderscore paths($G',\epsilon,[t_\alpha,t_\omega]$)}$, for $v \in V$

\For{$v \in V$}
\State $f[v] \leftarrow s-a$, where $(s,a)\in L_v'$ is the tuple with minimum difference
\EndFor
\State \Return{$f[v]$ for each $v \in V$} 
\end{algorithmic}
\end{algorithm}

Recall that Algorithm~\ref{alg:non_dominated_paths} runs in time $\bigO(n+M \log (c))$, where $c= \min \{d_{in},d_{out}\}$ is a bound for the size of each list $L_v$. The number of temporal edges added to the graph is bounded by $kc$, since there are $k$ lists $L_b,\ b\in B$. Observe that $d_{in}$ can at most double itself after inserting the new edges, so the $c$-value of $G'$ is bounded by $2d_{in}$. Thus, the second call to Algorithm~\ref{alg:non_dominated_paths} runs in time $\bigO(n+(M+kc)\log (d_{in}))$. Taking into account the binary searches for the active beer times, we obtain that Algorithm~\ref{alg:fastest_beer} runs in time $\bigO(n+(M+kc)\log (d_{in})+kc\log (T))$.\footnote{The last for-loop of Alg.~\ref{alg:fastest_beer} can be incorporated into the second call of Alg.~\ref{alg:non_dominated_paths} without increasing its time complexity, by storing the tuples with minimum difference. We only present the pseudocode in this manner to help readability.} The correctness of Algorithm~\ref{alg:fastest_beer} follows from Lemma~\ref{lem:fastest}.

\subsection{Algorithm for shortest beer path}

SBPs are significantly more complicated, in part because, somewhat unexpectedly, Lemma~\ref{lem:fastest} does not hold verbatim for \emph{distance-wise} non-dominated paths. To overcome this, we define the following alternative domination criterion.

\begin{definition}[\textbf{Inverse-distance-wise dominated path}]
\label{def:inverse_dom_path}
Let $P$ be a temporal $u-v$ path. We say that $P$ is \emph{inverse-distance-wise dominated} if there exists another temporal $u-v$ path $P'$ such that $\text{dist}(P') \le \text{dist}(P)$ and $\text{start}(P') \ge \text{start}(P)$, with at least one of the inequalities being strict.
\end{definition}

\begin{lemma}\label{lem:shortest}
    If there is a temporal $x-y$ beer path within time interval $[t_\alpha, t_\omega]$, then there is a $x-y$ SBP $\langle v_0=x,v_1,\ldots,v_j=b,\ldots,v_p=y\rangle$ within $[t_\alpha, t_\omega]$, traversing $b \in B$ at a time $t \in T_b$, s.t. $\langle v_0=x,v_1,\ldots,v_j=b\rangle$ is a distance-wise non-dominated path (within $[t_\alpha, t_\omega]$) and $\langle v_j=b,v_{j+1},\ldots,v_p=y\rangle$ is an inverse-distance-wise non-dominated path (within $[t_\alpha, t_\omega]$).
\end{lemma}

The proof of Lemma~\ref{lem:shortest} is deferred to Appendix~\ref{appendix_omit_proof}.
We propose a modification of Algorithm~\ref{alg:distance_non_dominated_paths} to calculate inverse-distance-wise non-dominated paths from all vertices to some vertex $y$, using a reverse edge stream. Its full description is deferred to Appendix~\ref{appendix_omit_algo}.
\begin{algorithm}[H]
\caption{$\texttt{Inv\textunderscore dist\textunderscore non-dom\textunderscore paths($G,y,[t_\alpha,t_\omega]$)}$}
\label{alg:inverse_distance_non_dominated_paths}
\begin{algorithmic}[1]
\Require{A temporal graph $G = (V, E)$ in reverse edge stream representation, target vertex $y$, time interval $[t_\alpha, t_\omega]$.}
\Ensure{For each $v \in V$, the list $I_v$ of inverse-distance-wise non-dominated $(d, s)$ pairs (from $v$ to $y$) within \([t_{\alpha},t_{\omega}]\).}
\end{algorithmic}
\end{algorithm}
Algorithm~\ref{alg:inverse_distance_non_dominated_paths} runs in time $\bigO(n+M \log (d_{out}))$. Observe that $d_{out}$ is a bound for the amount of inverse-distance-wise non-dominated pairs $(d,s)$ (distance, start) between any two vertices and, thus, also a bound for the size of each list $I_v$. 
\begin{theorem}\label{thrm:inv_dist_correctness}
    Algorithm~\ref{alg:inverse_distance_non_dominated_paths} computes all inverse-distance-wise non-dominated $(d,s)$ pairs from each $v \in V$ to $y$ within $[t_\alpha,t_\omega]$, in time $\bigO(n+M \log (d_{out}))$.
\end{theorem}
The proof of Theorem~\ref{thrm:inv_dist_correctness} is deferred to Appendix~\ref{appendix_omit_proof}.
We propose a SBP algorithm, utilizing Algorithms~\ref{alg:distance_non_dominated_paths} and \ref{alg:inverse_distance_non_dominated_paths}. Unlike most of our algorithms, Algorithm~\ref{alg:shortest_beer} only calculates a path between two nodes; this happens because it uses two different domination criteria (see Lemma~\ref{lem:shortest}), with each one imposing different restrictions via its respective algorithm.

\begin{algorithm}[H]
%\scriptsize
\caption{$\texttt{SBP$(G,x,y,[t_\alpha,t_\omega])$}$}
\label{alg:shortest_beer}
\begin{algorithmic}[1]
\Require{A temporal graph $G = (V, E)$ in edge stream representation (both regular and reverse), source vertex $x$, target vertex $y$, time interval $[t_\alpha, t_\omega]$, a set of beer vertices $B$ and a list $T_i$ of time units for each of them.}
\Ensure{The SBP distance from $x$ to $y$ within $[t_\alpha, t_\omega]$.}

\State $dist \leftarrow \infty$
\State $L_b \leftarrow \texttt{Dist\_Non-dom\_paths($G,x,[t_\alpha,t_\omega]$)}$, for $b \in B$  
\Comment{Alg~\ref{alg:distance_non_dominated_paths} from $x$ to $b\in B$}
\State $I_b \leftarrow \texttt{Inv\textunderscore dist\textunderscore Non-dom\textunderscore paths($G,y,[t_\alpha,t_\omega]$)}$, for $b \in B$ 
\Comment{Alg~\ref{alg:inverse_distance_non_dominated_paths} from $b \in B$ to $y$}


\For{$b\in B$}
    \For{$(d,a) \in L_b$}
        \State $a' \gets \min\{time \in T_b \mid time \geq a\}$ \Comment{$\infty$ if it does not exist}

        \If{$a' \leq t_{\omega}$}
            \State Replace $(d,a)$ with $(d,a')$ in $L_b$

        \Else 
            \State Remove $(d,a)$ from $L_b$
        \Comment{impossible to get beer}
        \EndIf
\EndFor
    \For{$(d,a) \in L_b$}
        \State Find $(d',s)$ in $I_b$ with minimum $s$ such that $s \geq a$
        \Comment{find best fitting path}

        \State $dist \leftarrow \min\{d+d' , dist\}$
    \EndFor
\EndFor
\State \Return{dist}
\end{algorithmic}
\end{algorithm}

Algorithm~\ref{alg:shortest_beer} calls Algorithms~\ref{alg:distance_non_dominated_paths} and \ref{alg:inverse_distance_non_dominated_paths} once each. Recall that the size of each $L_v$ is bounded by $d_{in}$ and the size of each $I_v$ is bounded by $d_{out}$. Hence, Algorithm~\ref{alg:shortest_beer} runs in time $\bigO(n+M \log (d_{max}) + k d_{in} (\log (T) + \log (d_{out})))$.
The correctness of Algorithm~\ref{alg:shortest_beer} follows from Lemma~\ref{lem:shortest} and Theorem~\ref{thrm:inv_dist_correctness}.

