\subsection{Omitted MTLDP and latest-departure beer path algorithms}


\setcounter{algorithm}{8}


\begin{algorithm}[H]
\caption{$\texttt{MTLDP$(G,[t_\alpha,t_\omega],fin)$}$}
\label{alg:latest_multisource_stream}
\begin{algorithmic}[1]

\Require{A temporal graph $G$ in its reverse edge stream
 representation, a time window $[t_{\alpha}, t_{\omega}]$ and final times $fin[v]$, such that $t_\alpha \leq fin[v] \leq t_\omega$ or $fin[v] = -\infty$, for all $v \in V$.}
\Ensure{The MTLDP times within $[t_\alpha, t_\omega]$ to every vertex, assuming we can arrive at time $fin[v]$ at each $v \in V$.}


\State $\tau[v] \gets fin[v]$ \textbf{for all} $v \in V$

\For{$e=(u,v,t,\lambda)$ in the reverse edge stream}{
    \If{$t \geq t_{\alpha}$ \textnormal{\textbf{and}} $t+\lambda\leq \tau[v]$}
       \State $\tau[u] \gets \max\{\tau[u], t\}$
    \EndIf

}
\EndFor

\State \Return{$\tau[v]$ for each $v \in V$}
\end{algorithmic}
\end{algorithm}




\begin{algorithm}[H]
\caption{$\texttt{MTLDP\textunderscore alternative$(G,[t_\alpha,t_\omega],fin)$}$}
\label{alg:latest_multisource_dijkstra}
\begin{algorithmic}[1]
\Require{A temporal graph $G$ in adjacency list
 representation, a time window $[t_{\alpha}, t_{\omega}]$ and final times $fin[v]$, such that $t_\alpha \leq fin[v] \leq t_\omega$ or $fin[v] = -\infty$, for all $v \in V$.}
\Ensure{The MTLDP times within $[t_\alpha, t_\omega]$ to every vertex, assuming we can arrive at time $fin[v]$ at each $v \in V$.}


\State $\tau[v] \gets fin[v]$ \textbf{for all} $v \in V$

\State $PQ \gets \emptyset$ \Comment{a max-priority queue}
\State $PQ.enqueue (\tau[v],v)$ \textbf{for all} $v \in V$
\Comment{Add $v$ to priority queue with $\tau[v]$ priority}

\While{$PQ \neq \emptyset$}
    \State $(\tau[v],v) \gets PQ.extractMax()$

    \For{$u \in N_{in}(v)$}
        \State Let $(u,v,t,\lambda) \in E(u,v)$ be a temporal edge with maximum $t$ s.t. $t + \lambda \leq \tau[v]$ 

        \Comment{binary search on $t+\lambda$ of $e \in E(u,v)$ }
        \If{$t \geq t_\alpha$ \textnormal{\textbf{and} $t > \tau[u]$}}
            \State $\tau[u] \gets t $\;
             \State  $PQ.increaseKey(u,\tau[u])$
        \EndIf  
    \EndFor
\EndWhile

\State \Return{$\tau[v]$ for each $v \in V$}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
\caption{$\texttt{LDBP$(G,x,[t_\alpha,t_\omega])$}$}
\begin{algorithmic}[1]

\Require{A temporal graph $G$, source vertex $x$, a time window $[t_{\alpha}, t_{\omega}]$, a set of beer vertices $B$ and a list $T_i$ of time units for each of them.}
\Ensure{The LDBP time to $y$ from every vertex $v \in V$ within $[t_\alpha, t_\omega]$.}


\State $fin[y]\gets t_\omega,\, init[v] \gets -\infty$ \textbf{for all} $v \in V \setminus \{x\}$

\State $\tau[v] \leftarrow \texttt{MTLDP($G,[t_\alpha,t_\omega],fin$)}$, for $v \in V$

\State $fin'[v] \gets -\infty$ \textbf{for all} $v \in V$

\For{{\textbf{all}} $b\in B$}{
    \State $beer\_ time \gets \max\{time \in T_b \mid time \leq \tau[b]\}$
    \Comment{$-\infty$ if it does not exist}

    \If{$beer\_ time \geq t_{\alpha}$}
        \State $fin'[b] \gets beer\_ time$
    \EndIf


}
\EndFor    
\State $\tau'[v] \leftarrow \texttt{MTLDP($G,[t_\alpha,t_\omega],fin'$)}$, for $v \in V$

\State \Return{$\tau'[v]$ for each $v \in V$}
\end{algorithmic}
\label{alg:latest_departure_beer}
\end{algorithm}







