\setcounter{theorem}{13}

\begin{theorem}
    For graphs with no dominated edges, Algorithm~\ref{alg:earliest_arrival_beer} computes the earliest-arrival beer path times from $x$ to all $v \in V$ in time $\bigO(m\log (\pi)+n\log (n) + k \log (T))$, if Algorithm~\ref{alg:earliest_multisource_dijkstra} is used as the MSEAP subroutine.
\end{theorem}

\begin{proof}
    Algorithm~\ref{alg:earliest_multisource_dijkstra} uses a binary search\footnote{Binary search is possible due to the assumption that there are no dominated edges in the graph.} on each non-empty set $E(u,v)$ $(u,v \in V)$; this requires total time $\bigO(m \log (\pi))$. If a Fibonacci heap is used as priority queue, $\bigO(\log (n))$ time is required for each extract-min operation, while decrease-key operations are done in constant time. Thus, Algorithm~\ref{alg:earliest_multisource_dijkstra} runs in time $\bigO(m\log (\pi)+n\log (n))$. Recall that Algorithm~\ref{alg:earliest_arrival_beer} calls the MSEAP subroutine twice, while also doing $\bigO(k)$ binary searches on lists of size $\bigO(T)$. We infer that Algorithm~\ref{alg:earliest_arrival_beer} runs in time $\bigO(m\log (\pi)+n\log (n) + k \log (T))$, if Algorithm~\ref{alg:earliest_multisource_dijkstra} is used as the MSEAP subroutine.

    We now prove the correctness of Algorithm~\ref{alg:earliest_multisource_dijkstra} by induction. We only describe the induction briefly, since it is similar to the proof of correctness of Dijkstra's classic algorithm. For each \(v \in V\) let \(\tau[v]\) be the time calculated by the algorithm and \(\tau^*[v] \) be the respective MSEAP time within $[t_\alpha, t_\omega]$. By definition of MSEAP, for the node with minimum $init[u]$ it is $\tau^*[u]=init[u]$; thus, the first node extracted from the queue has \(\tau[u]=\tau^*[u]\). For each $v \in N_{out}(u)$, $\tau[v]$ is then updated through the $u-v$ edge that arrives at $v$ at the earliest possible time. Assuming the graph has no dominated edges, this is an edge with minimum $t$ s.t. $t \geq \tau[u]$. Inductively, any $u\in V$ extracted from the queue has \(\tau[u]=\tau^*[u]\). This happens because paths that only use processed nodes have been considered in previous steps and it is impossible to arrive at $u$ earlier than $\tau[u]$ by traversing an unprocessed node $v \in V$ with $\tau[v] \geq \tau[u]$. Regarding the update of $\tau[v]$ for $v \in N_{out}(u)$, the same things hold as in the base of the induction, thus completing the proof.

    The correctness of Algorithm~\ref{alg:earliest_arrival_beer} using Algorithm~\ref{alg:earliest_multisource_dijkstra} as the MSEAP subroutine is then identical to the proof of Theorem~\ref{thrm:earliest_beer_correctness}.
\end{proof}

\setcounter{lemma}{16}

\begin{lemma}
    If there is a temporal $x-y$ beer path within time interval $[t_\alpha, t_\omega]$, then there is an $x-y$ FBP $\langle v_0=x,v_1,\ldots,v_j=b,\ldots,v_p=y\rangle$ within $[t_\alpha, t_\omega]$, traversing $b \in B$ at a time $t \in T_b$, such that its subpaths $\langle v_0=x,v_1,\ldots,v_j=b\rangle$ and $\langle v_j=b,v_{j+1},\ldots,v_p=y\rangle$ are non-dominated paths.
\end{lemma}

\begin{proof}
    Let there be a temporal beer path $P=\langle u_0=x,u_1,\ldots,u_{j'}=b,\ldots,u_{p'}=y\rangle$ within $[t_\alpha, t_\omega]$, traversing $b \in B$ at a time $t \in T_b$. Define the subpaths of $P$: $Q=\langle u_0=x,u_1,\ldots,u_{j'}=b\rangle$, $R=\langle u_{j'}=b,u_{j'+1},\ldots,u_{p'}=y\rangle$. If $Q$ is a dominated path, then there is some other path $Q'=\langle w_0=x,w_1,\ldots,w_f=b\rangle$ such that $start(Q') \geq start(Q)$ and $end(Q') \leq end(Q)$, with at least one of the inequalities being strict. Concatenate $Q'$ with $R$ to obtain a $x-y$ path $P'$. By the first inequality we obtain $dura(P') \leq dura(P)$. By the second inequality we infer that $P'$ also traverses $b$ at time $t$ and that $P'$ is a valid temporal path. Thus, $P'$ is a beer path with smaller or equal duration than $P$ and is also within $[t_\alpha, t_\omega]$. Applying a similar argument for $R$ completes the proof. 
\end{proof}


\setcounter{lemma}{18}

\begin{lemma}
    If there is a temporal $x-y$ beer path within time interval $[t_\alpha, t_\omega]$, then there is a $x-y$ SBP $\langle v_0=x,v_1,\ldots,v_j=b,\ldots,v_p=y\rangle$ within $[t_\alpha, t_\omega]$, traversing $b \in B$ at a time $t \in T_b$, s.t. $\langle v_0=x,v_1,\ldots,v_j=b\rangle$ is a distance-wise non-dominated path (within $[t_\alpha, t_\omega]$) and $\langle v_j=b,v_{j+1},\ldots,v_p=y\rangle$ is an inverse-distance-wise non-dominated path (within $[t_\alpha, t_\omega]$).
\end{lemma}

\begin{proof}
    Let there be a temporal beer path \(P=\langle u_{0}=x,u_{1},\dots ,u_{j'}=b,\dots ,u_{p'}=y\rangle\) within \([t_{\alpha},t_{\omega}]\), traversing \(b\in B\) at some time \(t\in T_{b}\).  
    Define the sub-paths of \(P\):   \(Q=\langle u_{0}=x,u_{1},\dots ,u_{j'}=b\rangle\) and  \(R=\langle u_{j'}=b,u_{j'+1},\dots ,u_{p'}=y\rangle\). If \(Q\) is distance-wise dominated (within \([t_{\alpha},t_{\omega}]\)), there exists a path  
    \(Q'=\langle w_{0}=x,w_{1},\dots ,w_{f}=b\rangle\) (within \([t_{\alpha},t_{\omega}]\)), such that  
    \(\text{dist}(Q')\le \text{dist}(Q)\) and \(\text{end}(Q')\le \text{end}(Q)\), with at least one of the two inequalities strict.  
    Concatenate \(Q'\) with \(R\) to obtain a path \(P'\) from \(x\) to \(y\).  Because of the first inequality we get \(\text{dist}(P') \le \text{dist}(P)\). 
    By the second inequality we infer that \(P'\) also traverses \(b\) at time $t$ and is a valid temporal path. Hence, \(P'\) is a beer path within \([t_{\alpha},t_{\omega}]\) whose total distance is smaller than or equal to that of \(P\). 

    If \(R\) is inverse-distance-wise dominated (within \([t_{\alpha},t_{\omega}]\)), there is a path \(R'=\langle z_{0}=b,z_{1},\dots ,z_{g}=y\rangle\) (within \([t_{\alpha},t_{\omega}]\)) such that  \(\text{dist}(R')\le \text{dist}(R)\) and \(\text{start}(R')\ge \text{start}(R)\), again with at least one inequality being strict. Concatenate \(Q'\) with \(R'\) to obtain a $x-y$ path $P''$. By the first inequality we obtain \(\text{dist}(P'') \le \text{dist}(P')\). By the second inequality, we obtain that $P''$ is a valid temporal beer path. Therefore, \(P''\) is a beer path within \([t_{\alpha},t_{\omega}]\) whose total distance is smaller than or equal to that of \(P'\).
\end{proof}

\begin{theorem}
    Algorithm~\ref{alg:inverse_distance_non_dominated_paths} computes all inverse-distance-wise non-dominated $(d,s)$ pairs from each $v \in V$ to $y$ within $[t_\alpha,t_\omega]$, in time $\bigO(n+M \log (d_{out}))$.
\end{theorem}


