\subsubsection{Problem formulation}
In this work, we design a network traffic prediction model (MetaSTNet) based on a meta-learning framework, which is composed of meta-training and meta-testing stages.

The meta-training phase takes a bi-level optimization procedure\cite{ji2021bilevel}. We assume $\widetilde{\boldsymbol{\omega}}=(\boldsymbol{\omega}_1,...,\boldsymbol{\omega}_N)$, where $\boldsymbol{\omega}_i,i\in \{1,...,N\}$ denotes the task-specific parameters. In the inner-level optimization stage, the base learner of task $\mathcal{T}_i$ seeks $\boldsymbol{\omega}_i$ as the minimizer of its loss on training set $\mathcal{D}_{\mathcal{T}_i}^{\rm{tr}}$ in Eq. (\ref{Eq.3}). And $\widetilde{\boldsymbol{\omega}}^*$ can be optimized over all $N$ tasks in Eq. (\ref{Eq.2}). In the outer-level optimization stage, the meta-learner evaluates the minimizer $\boldsymbol{\omega}^*_i$ on validating set $\mathcal{D}^{\rm{val}}_{\mathcal{T}_i}$, and optimizes $\boldsymbol{\theta}$ over all $N$ tasks in Eq. (\ref{Eq.1}). To be specific, $\boldsymbol{\omega}_i$ is the parameters of the last linear layer of MetaSTNet while $\boldsymbol{\theta}$ corresponds to the parameters of the remaining layers\cite{Ji2020}. Moreover, $g(\boldsymbol{\theta},\widetilde{\boldsymbol{\omega}})$ represents the loss function of inner-level optimization stage and  $f(\boldsymbol{\theta},\widetilde{\boldsymbol{\omega}}^*)$ denotes the objective function of outer-level optimization stage.
\begin{equation}
\min _{\boldsymbol{\theta}} \Psi(\boldsymbol{\theta})= f(\boldsymbol{\theta},\widetilde{\boldsymbol{\omega}}^*)=\frac{1}{N} \sum_{i=1}^{N} \  \frac{1}{\left| \mathcal{D}_{\mathcal{T}_i}^{\rm{val}} \right|} \sum_{\xi \in \mathcal{D}_{\mathcal{T}_i}^{\rm{val}}} \mathcal{L}_i(\boldsymbol{\theta},\boldsymbol{\omega}^*_i;\xi), 
\label{Eq.1}   
\end{equation}
\begin{equation}
\label{Eq.2} 
\rm{s.t.} \ \widetilde{\boldsymbol{\omega}}^* = \arg \min _{\widetilde{\boldsymbol{\omega}}} g(\boldsymbol{\theta},\widetilde{\boldsymbol{\omega}})=\frac{1}{N} \sum_{i=1}^{N}\ \mathcal{L}_{\mathcal{S}_i}(\boldsymbol{\theta},\boldsymbol{\omega}_i),
\end{equation}
\begin{equation}
\label{Eq.3} 
\mathcal{L}_{\mathcal{S}_i}(\boldsymbol{\theta},\boldsymbol{\omega}_i) = \frac{1}{\left| \mathcal{D}_{\mathcal{T}_i}^{\rm{tr}} \right|} \sum_{\xi \in \mathcal{D}_{\mathcal{T}_i}^{\rm{tr}}} \mathcal{L}_i(\boldsymbol{\theta},\boldsymbol{\omega}_i; \xi).
\end{equation}

To solve the problem Eq. (\ref{Eq.1}), we employ the approximate implicit differentiation based approach as it is computationally and memory efficient\cite{ji2021bilevel}. In the inner loop, we can obtain $\omega_{i,j}^{P}$ for each meta-training task $\mathcal{T}_i$ using $P$ steps of gradient decent, where $\widetilde{\boldsymbol{\omega}}_j^{P}=(\boldsymbol{\omega}_{1,j}^{P},...,\boldsymbol{\omega}_{N,j}^{P})$ and $j\in \{1,...,J\}$ denotes the number of epochs. Then, we aim to estimate hypergradient $\hat{\nabla} \Psi (\boldsymbol{\theta}_j)$ in the outer-level optimization stage. To be specific, as shown in \cite{ji2021bilevel}, we first obtain $v^{Q}_j$ by solving $\nabla^2_{\widetilde{\boldsymbol{\omega}}}g(\boldsymbol{\theta}_j,\widetilde{\boldsymbol{\omega}}_j^P)v=\nabla_{\widetilde{\boldsymbol{\omega}}}f(\boldsymbol{\theta}_j,\widetilde{\boldsymbol{\omega}}_j^P)$ with $Q$ steps of conjugate gradient. Then, we can obtain the Jacobian-vector product $\nabla_{\boldsymbol{\theta}}\nabla_{\widetilde{\boldsymbol{\omega}}} g(\boldsymbol{\theta}_j,\widetilde{\boldsymbol{\omega}}_j^{P})v^{Q}_{j}$ with existing automatic differentiation packages. Finally, we can obtain hypergradient estimation with the following equation\cite{ji2021bilevel},
\begin{equation}
\widehat{\nabla}\Psi(\boldsymbol{\theta}_j)=\nabla_{\boldsymbol{\theta}}f(\boldsymbol{\theta}_j,\widetilde{\boldsymbol{\omega}}_j^{P})-\nabla_{\boldsymbol{\theta}}\nabla_{\widetilde{\boldsymbol{\omega}}} g(\boldsymbol{\theta}_j,\widetilde{\boldsymbol{\omega}}_j^{P})v^{Q}_{j}.
\label{Eq.4}
\end{equation}


In the meta-testing phase, we use the training set $\mathcal{D}^{\rm{tr}}$ to fine tune the model parameters, which can be denoted as $\boldsymbol{\theta}^{*}$. Then, we exploit the calibrating set $\mathcal{D}^{\rm{cal}}$ and yield estimate $\boldsymbol{\hat{y}}^{\rm{cal}}$,
\begin{equation}
\boldsymbol{\hat{y}}^{\rm{cal}}=f_{\boldsymbol{\theta} ^{*}}(\boldsymbol{X}^{\rm{tra,cal}},\boldsymbol{X}^{\rm{txt,cal}},\boldsymbol{X}^{\rm{img}}),
\end{equation}
where $\boldsymbol{\hat{y}}^{\rm{cal}}=[\hat{y}^{\rm{cal}}_1,...,\hat{y}^{\rm{cal}}_D]$ and $\hat{y}^{\rm{cal}}_i$ denotes the $i$-th element of $\boldsymbol{\hat{y}}^{\rm{cal}}$.

Suppose there are $L$ number of samples in $\mathcal{D}^{\rm{cal}}$. Then, the nonconformity score $R_i, i\in\{1,...,L\}$ can be calculated via,
\begin{equation}
R_{i}=[\lvert y_1^{\rm{cal}}-\hat{y}_1^{\rm{cal}}\rvert,...,\lvert y_D^{\rm{cal}}-\hat{y}_D^{\rm{cal}}\rvert]^{\top}.
\label{Eq.5}
\end{equation}

We denote the nonconformity scores of $L$ samples as $R\in \mathbb{R}^{L\times D}$. And we use $\boldsymbol{\hat{\epsilon}}=[\hat{\epsilon}_1,...,\hat{\epsilon}_D] \in \mathbb{R}^{D}$ to represent the empirical nonconformity score. For the $i,i\in \{1,...,D\}$-th dimension, all $L$ samples are sorted and the $l,l=\left\lceil {(1-\alpha)(L+1)} \right\rceil$-th smallest volume is chosen as the $i$-th element of the empirical nonconformity score $\hat{\epsilon}_i$\cite{CF-RNN}. 

For a new example in the testing set, we can obtain the prediction of our proposed model with the following formulation,
\begin{equation}
\boldsymbol{\hat{y}}=f_{\boldsymbol{\theta} ^ {*}}(\boldsymbol{X}^{\rm{tra,ts}},\boldsymbol{X}^{\rm{txt,ts}},\boldsymbol{X}^{\rm{img}}),
\label{Eq.6}
\end{equation}
where $\hat{\boldsymbol{y}}=[\hat{y}_1,...,\hat{y}_D]$ and $\hat{y}_i$ denotes the $i$-th element of $\boldsymbol{\hat{y}}$. 

Then, the prediction interval can be obtained by the following equations, 
\begin{align}
\hat{y}_i^{\rm{L}}=\hat{y}_{i}-\hat{\epsilon}_i, \label{Eq.7}\\
\hat{y}_i^{\rm{U}}=\hat{y}_{i}+\hat{\epsilon}_i, \label{Eq.8}
\end{align}
where $\hat{\boldsymbol{y}}^{\rm{L}}=[\hat{y}_1^{\rm{L}},...,\hat{y}_D^{\rm{L}}]$,${\hat{\boldsymbol{y}}}^{\rm{U}}=[\hat{y}_1^{\rm{U}},...,\hat{y}_D^{\rm{U}}]$ denote the lower bound and upper bound of the prediction interval. $\hat{y}_i^{\rm{L}}$ and $\hat{y}_i^{\rm{U}}$ denote the $i$-th element of $\hat{\boldsymbol{y}}^{\rm{L}}$ and $\hat{\boldsymbol{y}}^{\rm{U}}$, respectively.

Finally, when we fix a significance level $\alpha\in (0,1)$, the probability that the true volume falls outside the corresponding prediction interval is at most $\alpha$ \cite{jensen2022ensemble,CQR},
\begin{equation}
\mathbb{P}(y_i \in [\hat{y}_i^{\rm{L}},\hat{y}_i^{\rm{U}}])\geq 1-\alpha.
\label{Eq.9}
\end{equation}

