The control volume of $v_i$ is consisted of its surrounding dashed lines. The discretized forms of Equations (\ref{sW}, \ref{pN}) at $v_i$ are:
\begin{eqnarray}\label{dsW}
        \nonumber
		\frac{\partial\left(\sum_{N \in e_j\cap b_i} \left.\Phi_j \rho_{w}S_{w }\right|_{\mathbf{x}_N} A_{b^j_i}\right)}{\partial t}
		+
		\sum_{M \in e_j\cap \partial b_i} \left.\frac{\rho_w k_{r w} p_c^{'}}{\mu_w}\mathbf{K} \nabla S_w\mathbf{n} \right|_{\mathbf{x}_M}l_M		
		+\sum_{M \in e_j\cap \partial b_i} \left.\rho_w k_{r w}\mathbf{v}_w \mathbf{n} \right|_{\mathbf{x}_M}l_M \\
		=\sum_{N \in e_j\cap b_i} \left.q_{w}\right|_{\mathbf{x}_N} A_{b^j_i}
\end{eqnarray}
\begin{equation}\label{dpN}
	\frac{\partial\left(\sum_{N \in e_j\cap b_i} \left.\Phi_j \rho_{n}\left(1-S_w\right)\right|_{\mathbf{x}_N} A_{b^j_i}\right)}{\partial t}	
	+\sum_{M \in e_j\cap \partial b_i} \left.\rho_n k_{rn}\mathbf{v}_n \mathbf{n} \right|_{\mathbf{x}_M}l_M
	=\sum_{N \in e_j\cap b_i} \left.q_{n}\right|_{\mathbf{x}_N} A_{b^j_i}
\end{equation}

where $\mathbf{x}_N$ is the barycenter of sub-control volume $b^j_i$, $A_{b^j_i}$ is the area of sub-control volume face, $\mathbf{x}_M$ is the midpoint of sub-control volume edge, $l_M$ is the length of sub-control volume edge.
\subsection{Upwind scheme}
Multi-phase problem could be either diffusion or convection-dominated, which depends on parameters. Therefore, a upwind scheme is expected to eliminate numerical oscillation, especially for convection-dominated cases. Different from the upwind scheme where Darcy velocities $\mathbf{u}_\alpha$ are utilized in the upwind criteria, the velocity  $\mathbf{v}_\alpha$ are used in the present upwind scheme. This modification prevents the capillary diffusion part $\frac{ k_{r w} p_c^{'}}{\mu_w}\mathbf{K} \nabla S_w$ from being upwind. The upwind evaluations for the coupled Equations (\ref{dsW}, \ref{dpN}) are as follows:
\begin{eqnarray}\label{dsW}
    \nonumber
	\rho_{w}\frac{\partial\left(\sum_{N \in e_j\cap b_i} \left.\Phi_j S_{w }\right|_{\mathbf{x}_N} A_{b^j_i}\right)}{\partial t}
	+
	\rho_w\sum_{M \in e_j\cap \partial b_i} \left.\frac{ k_{r w} p_c^{'}}{\mu_w}\mathbf{K} \nabla S_w\mathbf{n} \right|_{\mathbf{x}_M}l_M		
	+
	\rho_w\sum_{M \in e_j\cap \partial b_i} \left. \left. k_{rw}\right|_{\mathbf{x}_{up}}\mathbf{v}_w \mathbf{n} \right|_{\mathbf{x}_M}l_M\\
	=\sum_{N \in e_j\cap b_i} \left.q_{w}\right|_{\mathbf{x}_N} A_{b^j_i}
\end{eqnarray}
\begin{equation}\label{dpN}
	\rho_{n}\frac{\partial\left(\sum_{N \in e_j\cap b_i} \left.\Phi_j \left(1-S_w\right)\right|_{\mathbf{x}_N} A_{b^j_i}\right)}{\partial t}	
	+\rho_{n}\sum_{M \in e_j\cap \partial b_i} \left. \left.k_{r n}\right|_{\mathbf{x}_{up}}\mathbf{v}_n \mathbf{n} \right|_{\mathbf{x}_M}l_M
	=\sum_{N \in e_j\cap b_i} \left.q_{n}\right|_{\mathbf{x}_N} A_{b^j_i}
\end{equation}
where $\mathbf{x}_{up}$ is the upwind node, $\left.()\right|_{\mathbf{x}_{up}}$ is evaluated as follows
\begin{equation}\label{up_krw}
	\left. k_{rw}\right|_{\mathbf{x}_{up}}=
	\begin{cases}
		k_{rw}(\left.S_w\right|_{\mathbf{x}_i}) & \left.\mathbf{v}_w \cdot \mathbf{n}\right|_{\mathbf{x}_M} \geq 0 \\
		k_{rw}(\left.S_w\right|_{\mathbf{x}_j}) & \text { else }
	\end{cases}
\end{equation}
\begin{equation}\label{up_krn}
\left.k_{r n}\right|_{\mathbf{x}_{up}}=
\begin{cases}
	k_{rn}(\left.S_w\right|_{\mathbf{x}_i}) & \left.\mathbf{v}_n \cdot \mathbf{n}\right|_{\mathbf{x}_M} \geq 0 \\
	k_{rn}(\left.S_w\right|_{\mathbf{x}_j}) & \text { else }
\end{cases}
\end{equation}


\subsection{heterogeneity}
Based on the extended capillary pressure condition \cite{van1995effect}, the general interface conditions at media discontinuities for vertex-centered finite volume method can be developed by the competition of capillary pressure. The evaluation of saturation at vertex $v_i$ wrt. element $e_j$ depends on $p_{\text {cmin }, i}$, which is defined as following
\begin{equation}\label{pcmin}
	p_{\text {cmin }, i}=\min _{k \in E_i} p_c\left(\mathbf{x}^k\right)
\end{equation}
where $E_i$ are the elements having vertex $v_i$, $\mathbf{x}^k$ is the barycenter of element $e_k$. However, this scheme is not efficient for large scale parallel computing, since the computation of $p_{\text {cmin }, i}$ is expensive. The dynamic update of $p_{\text {cmin }, i}$ is required with the changing of saturation. Moreover, for each update, extra communication between processors is needed if elements $E_i$ are not distributed on the same processor. A more efficient scheme is proposed by Bastian \cite{bastian1999numerical} as following
\begin{equation}\label{pcmin2}
	p_{\text {cmin }, i}=\min _{k \in e_i} p_c\left(\mathbf{x}^k, 1-S_{n, i}\right)
\end{equation}
where $p_c$ is not evaluated at $\mathbf{x}^k$ restrictively, since the saturation of vertex $S_{n, i}$ are used for every evaluate point $\mathbf{x}^k$ in elements $e_i$.\\
In the current framework, a scheme without the calculation of $p_c$ is implemented, which depends on $p_{\text {dmin }}$. The definition of $p_{\text {dmin }, i}$ at vertex $v_i$ is as following
\begin{equation}\label{pdmin}
	p_{\text {dmin }, i}=\min _{N \in e_j\cap b_i} p_{\text {d}}(N)
\end{equation}
where $p_{\text {d}}(N)$ is the entry pressure of element $e_j$, $N \in e_j\cap b_i$. The saturation is evaluated by
\begin{equation}\label{hSw}
	\hat{S}_{w,i,N}=
	\begin{cases}
		S_{w,i} & p_{\text {d}}(N)=p_{\text {dmin }, i} \\
		1-S_{n,r} & p_{\text {d}}(N)\geq p_{\text {dmin }, i}J(S_{w,i}) \\
		S & \text{where} \; S \; \text{solves}\; p_{\text {d}}(N)J(S) = p_{\text {dmin }, i}J(S_{w,i})  \\
	\end{cases}
\end{equation}
where $\hat{S}_{w,i,N}$ is the saturation evaluated in the sub control volume $e_j\cap b_i$, $S_{w,i}$ is the saturation at vertex $v_i$, $J$ is the Leverett-J function \cite{leverett1941capillary} for Brooks-Corey capillary pressure function. Notice that Equation (\ref{hSw}) should be applied in the upwind scheme as well. However, such barrier conditions are only for the non-wetting phase and are not imposed on the convection terms of the wetting phase equations (\ref{dsW}). For instance, the evaluations of the relative permeabilities at $x_{ij}^3$ are illustrated in Figure \ref{fvm2}, where 
\begin{equation} \label{krn_ip}
    k_{rn}|_{\mathbf{x}_{ij,up}^3}= k_{rn}(\hat{S}_{w,up}^3)
\end{equation}
and 
\begin{equation} \label{krw_ip}
    k_{rw}|_{\mathbf{x}_{ij,up}^3} = k_{rw}(S_{w,up})
\end{equation}

