\end{equation}
\begin{equation} \label{r_Lp}
	r_{L^p}=\log_2 \left(\frac{\left\|S_w-S_{w 2 h}\right\|_{L^p}}{\left\|S_w-S_{w h}\right\|_{L^p}}\right)
\end{equation}
